#include "esp_log.h"
static vprintf_like_t g_prevVprintf = nullptr;
static int scanLogVprintf(const char* fmt, va_list ap){
  if(fmt && strstr(fmt, "OVF")) g_scanRec.ovf++;
  char b[200]; va_list cp; va_copy(cp, ap); int n = vsnprintf(b, sizeof b, fmt, cp); va_end(cp);
  if(n > 0) Serial.write((const uint8_t*)b, (size_t)n < sizeof b ? (size_t)n : sizeof b - 1);
  return n;
}
