// 23 Nov 2026 (#57, bench only): "cm lie N [S]" makes the NEXT PSBT scanned claim
// S sats (default 100) less for input N, to prove the coin memory refuses a changed amount.
static int8_t g_cmLieInput = -1;
static uint32_t g_cmLieSats = 100;   // "cm lie N S": S sats less (default 100; must stay below the fee or the PSBT's outputs exceed its inputs)
static void cmBenchSerial(const String& line){   // "cm lie N" / "cm off"; also read in the Bitcoin door menu
  String a = line.substring(3); a.trim();
  if(a == "off") g_cmLieInput = -1;
  else if(a.startsWith("lie ")){
    String r = a.substring(4); r.trim(); int sp = r.indexOf(' ');
    int n = (sp < 0 ? r : r.substring(0, sp)).toInt(); g_cmLieInput = (n >= 0 && n < 8) ? (int8_t)n : -1;
    long sats = sp < 0 ? 100 : r.substring(sp + 1).toInt(); g_cmLieSats = (sats > 0 && sats < 100000000L) ? (uint32_t)sats : 100;
  }
  if(g_cmLieInput >= 0) Serial.printf("[CM-BENCH] next PSBT: input amount lowered by %lu sats\n", (unsigned long)g_cmLieSats);
  else Serial.println("[CM-BENCH] next PSBT: unchanged");
  if(g_cmLieInput >= 0) Serial.printf("[CM-BENCH] input %d. DO NOT BROADCAST anything signed while this is set.\n", g_cmLieInput);
}
#endif
