// ── Idle screen dimmer ──────────────────────────────────────────────────────
// Lighter than goSleep: after ~30s of no button activity (and only when NOT
// charging / USB-plugged), fade the backlight to 0% to save battery. Any
// button instantly fades it back up and is consumed (doesn't trigger an
// action). The session stays unlocked — this is a screen-saver, not a security
// lock; the real key-wiping boundary remains the longer AUTO_SLEEP_MS sleep.
#define DIM_TIMEOUT_MS   30000UL   // idle time before fading out
#define BL_PWM_FREQ      5000      // backlight PWM frequency (Hz)
#define BL_PWM_RES       10        // backlight PWM resolution (bits)
#define DIM_FULL         1023      // hardware maximum backlight PWM duty (2^BL_PWM_RES - 1)
// ── Backlight level (5 Oct 2026) ───────────────────────────────────────────
// User-set brightness, 1..10, persisted in NVS "device"/"bl". Every "full on"
// in the firmware goes through blTargetDuty() so fades, wakes and the idle dim
// all land on the chosen level, never on the hardware maximum. The table is
// perceptual (roughly square-law) so each step looks like an even change.
static uint8_t blLevel = 10;
static const uint16_t BL_DUTY[11] = { 0, 40, 90, 150, 220, 310, 420, 550, 700, 860, 1023 };
int blTargetDuty(){ return BL_DUTY[blLevel > 10 ? 10 : blLevel]; }
void blLoad(){ Preferences p; if(p.begin("device", true, NVSPART_SEC)){ uint8_t v = p.getUChar("bl", 10); if(v >= 1 && v <= 10) blLevel = v; p.end(); } }
void blSave(){ Preferences p; if(p.begin("device", false, NVSPART_SEC)){ p.putUChar("bl", blLevel); p.end(); } }
static bool dimActive=false;       // true while the screen is faded out
static unsigned long dimSuppressUntil=0;  // brief guard after a wake

void loadAutoSleep(){
  Preferences p; p.begin("device", true, NVSPART_SEC);
  // Default 5 minutes (was 0 = disabled). After 5 min with no button press or
  // signing activity the device deep-sleeps to ~3mA (radio + peripherals off),
  // waking on a button. This is the real fix for AP-mode drain: when idle, stop
  // being a ~110mA access point entirely rather than trying to sleep-while-
  // reachable. NOTE: while asleep the device is OFF the network — incoming sign
  // requests are not received until woken by a button. User-adjustable in
  // Settings (0 disables).
  int mins = p.getInt("autosleep",5);
  p.end();
  AUTO_SLEEP_MS = (unsigned long)mins * 60000UL;
}
void saveAutoSleep(int mins){
  Preferences p; p.begin("device", false, NVSPART_SEC);
  p.putInt("autosleep",mins);
  p.end();
  AUTO_SLEEP_MS = (unsigned long)mins * 60000UL;
}
void loadHotspotIdle(){
  Preferences p; p.begin("device", true, NVSPART_SEC);
  int mins = p.getInt("apidle",2);   // default 2 min: well inside the 5 min auto sleep
  p.end();
  HOTSPOT_IDLE_MS = (unsigned long)mins * 60000UL;
}
void saveHotspotIdle(int mins){
  Preferences p; p.begin("device", false, NVSPART_SEC);
  p.putInt("apidle",mins);
  p.end();
  HOTSPOT_IDLE_MS = (unsigned long)mins * 60000UL;
}

// ── Boot to CIPHER (cover mode) ───────────────────────────────────────────
// When enabled the device boots straight into the game and stays there across
// reboots, so a casual observer sees an arcade toy rather than a signer.
//
// SCOPE, stated plainly so this is never oversold: this defeats a thief, a
// nosy guest or a cursory bag search. It does NOT defeat anyone who knows what
// a Favilla KEY is — the case is branded and one search gives the game away.
// Against coercion it is arguably a small negative, since a known game mode is
// something an attacker can simply demand you exit. It is camouflage, not
// duress protection.
//
// The exit therefore lands on the NORMAL boot path, which means the PIN. The
// game is the disguise; the PIN is the security. If exiting dropped straight
// into an unlocked wallet we would have replaced a lock with a secret
// handshake — strictly worse, because handshakes can be watched.
bool BOOT_TO_CIPHER = false;
// TRUE only while the device is actually acting as a cover: set when we boot
// into the game, cleared the moment the exit chord is honoured. BOOT_TO_CIPHER
// is the persistent SETTING and stays true for the next boot, so driving
// behaviour off it directly is wrong — once the user has exited and unlocked,
// opening CIPHER normally from the menu would re-arm the lock-on-chord AND the
// restart-on-death guard, trapping them in the game with no way back.
bool coverModeActive = false;
// 25 Sep 2026: in cover mode a COLD boot must not show SELECT MODE (it names
// the device as surely as the boot animation did). The door choice is
// DEFERRED: the game comes up with no door chosen, and the fork runs after the
// exit chord, before the PIN. Safe because nothing latches until unlock.
bool g_coverDoorPending = false;
void loadBootToCipher(){
  Preferences p; p.begin("device", true, NVSPART_SEC);
  BOOT_TO_CIPHER = p.getBool("bootcipher", false);
  p.end();
}
void saveBootToCipher(bool on){
  Preferences p; p.begin("device", false, NVSPART_SEC);
  p.putBool("bootcipher", on);
  p.end();
  BOOT_TO_CIPHER = on;
}


