// ── Log-safe secret fingerprint (SEC_1 finding 1 remediation) ───────────────
// NEVER log a secret, or even a prefix of one — a prefix shrinks the
// brute-force space. When a log line needs to identify a token/secret
// (e.g. to correlate mint → consume events), log secretFp(s): the first
// 4 hex chars of SHA-256(secret). Identifies without revealing.
// Returns a pointer to a static buffer — valid until the next call, which
// is fine for single-threaded log formatting (one fp per log line).
__attribute__((unused)) static const char* secretFp(const char* secret){
  static char fp[5];
  if(!secret || !secret[0]){ strcpy(fp, "-"); return fp; }
  uint8_t h[32];
  mbedtls_sha256_context ctx; mbedtls_sha256_init(&ctx);
  mbedtls_sha256_starts(&ctx, 0);
  mbedtls_sha256_update(&ctx, (const uint8_t*)secret, strlen(secret));
  mbedtls_sha256_finish(&ctx, h); mbedtls_sha256_free(&ctx);
  snprintf(fp, sizeof(fp), "%02x%02x", h[0], h[1]);
  return fp;
}

// Best-effort in-place wipe of an Arduino String's live buffer (SEC_1
// finding 6: String heap copies of key material). setCharAt writes the
// backing buffer without reallocating, so this scrubs the current copy.
// LIMITATION: cannot reach buffers already freed by earlier reallocations
// (substring/concat) — the real fix is keeping key material out of String
// entirely, which is a V1.x refactor item. This removes the live copy.
__attribute__((unused)) static void wipeString(String& s){
  for(unsigned int i=0;i<s.length();i++) s.setCharAt(i,'\0');
  s = "";
}

// ── Hardware pins ──────────────────────────────────────────────────────────
#define DEFAULT_SLOT  0
#define MAX_JSON_SIZE 2048  // NIP-46/stack-path scratch only — keep small (some of these live on task stacks)
// NIP-46 big-event budget (7 Oct 2026). A standard sign_event carries the WHOLE
// unsigned event inside the NIP-44 payload; a kind:3 contact list is 60-120 KB.
// Every buffer on that path (request params, canonical preimage, signed-event
// output, dedup replay cache, outbox slot) is PSRAM and sized to this, so a
// third-party app can follow/unfollow through the bunker without the KEY
// dropping the relay. NIP-44 itself caps plaintext at 65535 bytes, so 160 KB
// covers anything a spec-compliant client can send (base64 + JSON envelope).
// The WebSocket library's frame cap is raised to match (lib/WebSockets_Generic).
#define NIP46_BIG_SZ (160 * 1024)
#define EVENT_JSON_SZ 16384 // Full-event staging for /api/sign + NIP-46 sign_event (PSRAM, ps_malloc at
                            // boot — same pattern as PENDING_PARAMS_SZ). Lifts the old 2KB MAX_JSON_SIZE
                            // cap that truncated long kind:1 notes/replies. Events larger than this still
                            // sign correctly via the pre_id / sig-only stub path.
// ── Button scheme (V21.1 four-button) ───────────────────────────────────────
//   BTN1 / IO4 = ENTER / ACCEPT   -> drives btn2 engine (confirm/select)
//   BTN2 / IO9 = BACK / DECLINE   -> btn4 engine (unwind menus, decline dialogs)
//   BTN3 / IO1 = SCROLL DOWN      -> drives btn1 engine (next/scroll)
//   BTN4 / IO2 = SCROLL UP        -> btn3 engine (prev/scroll)
// Rationale: the existing UI is a two-button engine (btn1=next, btn2=confirm)
// referenced at ~129 sites. We keep that engine intact and only repoint which
// PHYSICAL pin feeds each, so Enter + Scroll-Down work everywhere with no
// logic change. btn3 (up) and btn4 (back/decline) are layered on top.
#define BTN1_GPIO  4    // V1.1 physical BTN1 = ENTER/ACCEPT
#define TFT_BL_PIN 8    // V1.1 TFT backlight, ESP-controlled (HIGH=on). Global so
                        // the sleep routine can turn it OFF (was a local #define
                        // in setup, out of scope for sleep -> backlight stayed on
                        // through deep sleep = the bulk of the ~7mA standby leak).
#define BTN2_GPIO  9    // V1.1 physical BTN2 = BACK/DECLINE
#define BTN3_GPIO  1    // V1.1 physical BTN3 = SCROLL DOWN (+ CIPHER hold skill)
#define BTN4_GPIO  2    // V1.1 physical BTN4 = SCROLL UP
// Engine aliases: map the two legacy engines onto the physical pins above.
//   btn1 engine (next/scroll)  <- SCROLL DOWN  (BTN3/IO1)
//   btn2 engine (confirm/enter) <- ENTER       (BTN1/IO4)
#define BTN_ENGINE_NEXT_GPIO     BTN3_GPIO   // IO1  -> btn1
#define BTN_ENGINE_CONFIRM_GPIO  BTN1_GPIO   // IO4  -> btn2
#define BTN_ENGINE_UP_GPIO       BTN4_GPIO   // IO2  -> btn3
#define BTN_ENGINE_BACK_GPIO     BTN2_GPIO   // IO9  -> btn4
#define BTN_L BTN1_GPIO
#define BTN_R BTN2_GPIO
#define BTN_ACT BTN3_GPIO
#define BUZZER_PIN 46   // V1.1 piezo PIEZO_EN (was 12); 100R inline, strap-safe
#define BUZZER_CHANNEL 1  // LEDC channel 1 (camera uses 0)
#define BUZZER_TIMER   1  // LEDC timer 1

// ── Buzzer ─────────────────────────────────────────────────────────────────
void buzzerInit(){
  // 10w (9 Nov 2026): the channel does NOT pick the timer in this core - it
  // takes the first free one, which is timer 0 at boot. (The camera does not
  // use an LEDC timer on the S3; see CAM_LEDC_TIMER.) The note below is the
  // 2 Oct belief.
  // 2 Oct 2026: pin the piezo to LEDC channel 4 -> timer 2. Auto-allocation
  // handed it channel 0/timer 0, which the camera driver also programs for its
  // XCLK (it configures LEDC directly, so the Arduino table never knew), and
  // the backlight is on channel 2/timer 1. ledcWriteTone retunes a whole timer,
  // so the piezo must own one.
  ledcAttachChannel(BUZZER_PIN, 2000, 8, 4);
  ledcWrite(BUZZER_PIN, 0);
}
void buzzerTone(uint32_t freq, uint32_t ms){
  if(freq==0){ ledcWrite(BUZZER_PIN,0); delay(ms); return; }
  // 2 Oct 2026 (PM build): the piezo channel is in the LEDC driver's default
  // PAUSE sleep mode, so with light sleep on, every nap during the delay()
  // below stopped the PWM - the tone came out chopped and sounded weaker
  // (Josh noticed clicks/beeps "feel weaker in normal mode"). Hold the chip
  // awake for the tone's duration; a beep is tens of ms, so this costs nothing.
  pmHoldWake();
  ledcWriteTone(BUZZER_PIN, freq);
  ledcWrite(BUZZER_PIN, 200);
  delay(ms);
  ledcWrite(BUZZER_PIN, 0);
  pmReleaseWake();
}
// Raw piezo patterns — used internally by feedback router. The public
// buzzerClick/OK/Fail/Boot functions below route through haptic + piezo
// based on the user's FeedbackMode setting.
void _buzzerClickTone(){ buzzerTone(2400, 12); }
void _buzzerOKTone()   { buzzerTone(2000,60); delay(30); buzzerTone(2800,80); }
void _buzzerFailTone() { buzzerTone(400,150); delay(30); buzzerTone(300,200); }
void _buzzerBootTone() { buzzerTone(1600,40); delay(20); buzzerTone(2000,40); delay(20); buzzerTone(2400,80); }
// Sign request — three short pulses at 1500Hz. Distinct rhythm from
// OK (rising 2-tone) and Fail (descending low). User learns "this means
// something needs my attention" within a couple of uses.
void _buzzerSignRequestTone() {
  buzzerTone(1500, 50); delay(40);
  buzzerTone(1500, 50); delay(40);
  buzzerTone(1500, 50);
}
// ── Haptic (DRV2605L) ──────────────────────────────────────────────────────
// I2C-controlled haptic driver. Drives an LRA via OUT+/OUT- pins.
// EN pin (V1.1: IO3) controls power — held high during use, can be pulled
// low to fully gate the chip during deep sleep. IO3 has a 10k pulldown on
// the V1.1 board (strap-safe at boot).
//
// Defensive init: if the chip doesn't ack on I2C, haptic.ok stays false
// and all play() calls become no-ops. Missing/broken haptic doesn't
// brick the device.
#define HAPTIC_EN_PIN     3     // V1.1 (was 18)
#define HAPTIC_I2C_ADDR   0x5A
// Effect numbers from DRV2605 built-in waveform library
#define HAPTIC_FX_CLICK         24  // Sharp Tick 100% — trackpad-style snap
#define HAPTIC_FX_DOUBLE_CLICK  10  // Double Click 100%
#define HAPTIC_FX_TRANSITION    70  // Transition Hum 1 — pleasant ramp
#define HAPTIC_FX_LONG_DBL_SHARP 56  // Long Double Sharp Click — error
#define HAPTIC_FX_SMOOTH_HUM    84  // Smooth Hum 1 — boot ramp
#define HAPTIC_FX_BUZZ          47  // Buzz 100% — alert
#define HAPTIC_FX_LIGHT_DBL_TAP 27  // Short Double Click Strong 30% — light "done" tap

struct HapticDriver {
  bool ok = false;

  bool _writeReg(uint8_t reg, uint8_t val) {
    Wire.beginTransmission(HAPTIC_I2C_ADDR);
    Wire.write(reg);
    Wire.write(val);
    return Wire.endTransmission() == 0;
  }
  uint8_t _readReg(uint8_t reg) {
    Wire.beginTransmission(HAPTIC_I2C_ADDR);
    Wire.write(reg);
    if (Wire.endTransmission(false) != 0) return 0xFF;
    Wire.requestFrom(HAPTIC_I2C_ADDR, (uint8_t)1);
    if (!Wire.available()) return 0xFF;
    return Wire.read();
  }

  void enablePin(bool en) {
    digitalWrite(HAPTIC_EN_PIN, en ? HIGH : LOW);
  }

  bool init(bool isLRA = true) {
    pinMode(HAPTIC_EN_PIN, OUTPUT);
    enablePin(false);
    delay(10);
    enablePin(true);
    delay(50); // generous settle: datasheet 250µs but be conservative

    // Probe — read status register (0x00). Should return 0xE0 (silicon rev marker)
    uint8_t status = _readReg(0x00);
    if (status == 0xFF || status == 0x00) {
      ok = false;
      enablePin(false); // disable to save power if chip missing
      return false;
    }

    // Exit standby mode (Mode register 0x01 — bit 6 = standby)
    if (!_writeReg(0x01, 0x00)) {
      ok = false;
      return false;
    }

    // Set rated voltage and overdrive based on actuator type.
    // For a 235Hz / 1.8V RMS LRA: rated_voltage register ≈ 0x75
    // (datasheet formula: V_RMS × 255 / (5.336e-6 × √(1 - 0.682)))
    // Overdrive clamp 0xAC allows ~2.5V peak transients for sharp attack
    // without exceeding LRA absolute max (typically 1.6× rated for short
    // pulses).
    if (isLRA) {
      // 30 Sep 2026: corrected from 0x75/0xAC. TI LRA closed-loop formula:
      //   RATED = Vrms / (20.58 mV * sqrt(1 - (4*SAMPLE_TIME + 300us) * f))
      //         = 1.8 / (0.02058 * sqrt(1 - 1.5 ms * 235 Hz)) = 109 -> 0x6D
      // 0x75 was ~1.94 Vrms, above the VG0832013D's 1.85 V max. OD_CLAMP is
      // ~21.2 mV/LSB peak; 0xAC = 3.65 V, twice the motor's rated peak, and
      // auto-cal drives AT the clamp - it failed DIAG with E8 / 0C / 6C.
      // 0x8C = ~3.0 V peak (1.2x rated peak): still snappy, within reason.
      _writeReg(0x16, 0x6D); // rated voltage — 1.8 Vrms at 235 Hz
      _writeReg(0x17, 0x8C); // overdrive clamp — ~3.0 V peak
      // Feedback control reg 0x1A:
      // bit 7 = N_ERM_LRA (1 = LRA mode)
      // bits [6:4] = FB_BRAKE_FACTOR (default 7 = 4x)
      // bits [3:2] = LOOP_GAIN (default 1 = medium)
      // bits [1:0] = BEMF_GAIN (LRA: default 1 = 1.65x)
      // For best LRA snap: set N_ERM_LRA=1, BEMF_GAIN=3 (1.8x) for max sensitivity
      _writeReg(0x1A, 0xB6); // 0b10110110 — LRA + 4x brake + medium loop + 1.65x BEMF
      // Control3 reg 0x1D — clear LRA_OPEN_LOOP (bit 0 = 0 → closed loop)
      // bit 5 = ERM_OPEN_LOOP, bit 0 = LRA_OPEN_LOOP. Both off = closed loop.
      _writeReg(0x1D, 0x80); // 0b10000000 — NG_THRESH disabled, closed loop, LRA drive mode auto
      // Control1 reg 0x1B: bit7 STARTUP_BOOST, bits[4:0] DRIVE_TIME.
      // DRIVE_TIME = (half-period - 0.5 ms) / 0.1 ms. VG0832013D is 235 Hz:
      // half-period 2.128 ms -> 16 = 0x10. The power-on default 0x13 is ~208 Hz,
      // so the drive was slightly off-resonance before auto-cal could pull it in.
      _writeReg(0x1B, 0x90); // STARTUP_BOOST on, DRIVE_TIME 0x10 (235 Hz)
      // Select library 6 (LRA tuned) — register 0x03
      _writeReg(0x03, 6);
      // Reload auto-calibration results (see autoCal()). Without these the
      // closed loop runs on placeholder compensation/BEMF values and the LRA
      // feels mushy and late — TI requires auto-cal for LRA closed loop.
      loadCal();
    } else {
      _writeReg(0x16, 0x90);
      _writeReg(0x17, 0x90);
      _writeReg(0x1A, 0x36); // 0b00110110 — ERM + 4x brake + medium loop + 1.65x BEMF
      _writeReg(0x1D, 0x80);
      _writeReg(0x03, 1); // library 1 = ERM, default
    }

    // Internal trigger mode — register 0x01 = 0x00 (already done above,
    // but explicitly: bits[2:0] = 0 means internal-trigger / GO bit)
    _writeReg(0x01, 0x00);

    ok = true;
    return true;
  }

  // 2 Oct 2026: standby between effects (~2 mA when idle otherwise). Every
  // play path exits standby first; hapticStandbyTick() re-enters it 400 ms
  // after the last play.
  uint32_t lastPlayMs = 0;
  bool inStandby = false;
  // 2 Oct 2026: after leaving standby the DRV2605L needs ~250 us before it can
  // drive properly; a GO inside that window plays weak/truncated. Since the
  // standby tick parks it 400 ms after every play, nearly every click was
  // starting from standby - felt as "weaker". 1 ms settle is inaudible.
  void wakeForPlay() { if (inStandby) { _writeReg(0x01, 0x00); inStandby = false; delay(1); } lastPlayMs = millis(); }
  void standby() { if (!ok || inStandby) return; _writeReg(0x01, 0x40); inStandby = true; }
  void play(uint8_t effect) {
    if (!ok) return;
    wakeForPlay();
    _writeReg(0x04, effect & 0x7F); // Waveform sequencer slot 0
    _writeReg(0x05, 0x00);          // Slot 1 = 0 means stop
    _writeReg(0x0C, 0x01);          // GO bit
  }

  void playSequence(uint8_t e1, uint8_t e2) {
    if (!ok) return;
    wakeForPlay();
    _writeReg(0x04, e1 & 0x7F);
    _writeReg(0x05, e2 & 0x7F);
    _writeReg(0x06, 0x00);          // Slot 2 = stop
    _writeReg(0x0C, 0x01);
  }

  // ── Auto-calibration (30 Sep 2026) ──────────────────────────────────────
  // DRV2605 mode 7 measures the mounted LRA and fills ACAL_COMP (0x18),
  // ACAL_BEMF (0x19) and BEMF_GAIN (0x1A[1:0]). Persisted in NVS "favilla":
  // hcal (1 = valid), hcomp, hbemf, hgain. Must be run with the motor in its
  // final mounting — the bonded mass is part of what gets measured.
  bool calValid = false;
  uint8_t calComp = 0, calBemf = 0, calGain = 0;
  // Open-loop fallback: drives the LRA at a fixed 235 Hz with no BEMF tracking.
  // Needs no calibration and gives a hard, consistent snap; costs a little
  // efficiency. NVS "favilla"/"hol". Toggle on the Haptic cal page.
  bool openLoop = false;
  void applyLoopMode() {
    if (openLoop) {
      _writeReg(0x1D, 0x81);   // LRA_OPEN_LOOP = 1
      _writeReg(0x20, 0x2B);   // OL_LRA_PERIOD: 1/235 Hz = 4255 us / 98.46 us = 43 = 0x2B
    } else {
      _writeReg(0x1D, 0x80);   // closed loop (auto-resonance)
    }
  }
  void setOpenLoop(bool on) {
    openLoop = on;
    Preferences p;
    if (p.begin("favilla", false)) { p.putUChar("hol", on ? 1 : 0); p.end(); }
    applyLoopMode();
  }
  void loadCal() {
    Preferences p;
    if (!p.begin("favilla", true)) return;
    openLoop = p.getUChar("hol", 0) == 1;
    calValid = p.getUChar("hcal", 0) == 1;
    uint8_t c2 = 0xF5;
    if (calValid) {
      calComp = p.getUChar("hcomp", 0);
      calBemf = p.getUChar("hbemf", 0);
      calGain = p.getUChar("hgain", 0) & 0x03;
      c2      = p.getUChar("hc2", 0xF5);
    }
    p.end();
    applyLoopMode();
    if (!calValid) return;
    _writeReg(0x1C, c2);   // the sensing window the passing cal was measured with
    _writeReg(0x18, calComp);
    _writeReg(0x19, calBemf);
    uint8_t fb = _readReg(0x1A);
    if (fb != 0xFF) _writeReg(0x1A, (fb & 0xFC) | calGain);
  }
  // Runs auto-cal (~1 s, the motor buzzes). Returns true and saves on a clean
  // DIAG_RESULT; on failure leaves the previous calibration untouched.
  // Tries three passes (1000 / 500 / 250 ms cal windows) and logs every raw
  // register so a failure can be diagnosed from the serial line. Diag bytes:
  // lastStatus (0x00), lastGo (0x0C after the wait), lastComp/lastBemf/lastFb.
  uint8_t lastStatus = 0, lastGo = 0, lastComp = 0, lastBemf = 0, lastFb = 0;
  bool autoCal() {
    if (!ok) return false;
    // Sweep: cal window {1000,500,250 ms} x Control2 (0x1C) sensing window
    // {default F5, shorter sample+blanking for a fast 235 Hz motor}.
    const uint8_t calTimes[3] = { 0x30, 0x20, 0x10 };
    const uint8_t ctrl2[3]    = { 0xF5, 0xE5, 0xD5 };   // SAMPLE_TIME 3 / 2 / 1
    bool wasOpen = openLoop;
    for (int pass = 0; pass < 9; pass++) {
      uint8_t ct = calTimes[pass % 3], c2 = ctrl2[pass / 3];
      _writeReg(0x1D, 0x80);         // closed loop — required for auto-cal
      _writeReg(0x1C, c2);
      _writeReg(0x1E, ct);           // AUTO_CAL_TIME, ZC_DET_TIME 100 us
      inStandby = false;
      _writeReg(0x01, 0x07);         // mode 7 = auto-calibration
      delay(5);
      _writeReg(0x0C, 0x01);         // GO
      uint32_t t0 = millis();
      lastGo = 0x01;
      while (millis() - t0 < 2500) {
        delay(20);
        uint8_t go = _readReg(0x0C);
        if (go != 0xFF) lastGo = go;
        if (go != 0xFF && (go & 0x01) == 0) break;
      }
      lastStatus = _readReg(0x00);
      lastComp   = _readReg(0x18);
      lastBemf   = _readReg(0x19);
      lastFb     = _readReg(0x1A);
      _writeReg(0x01, 0x00);
      bool good = (lastStatus != 0xFF) && ((lastStatus & 0x08) == 0) && ((lastGo & 0x01) == 0);
      Serial.printf("[HAPTIC] auto-cal pass %d (0x1E=%02X 0x1C=%02X): status %02X go %02X comp %02X bemf %02X fb %02X -> %s\n",
                    pass + 1, ct, c2, lastStatus, lastGo, lastComp, lastBemf, lastFb, good ? "PASS" : "fail");
      if (!good) { delay(150); continue; }
      calComp = lastComp; calBemf = lastBemf; calGain = lastFb & 0x03;
      calValid = true;
      Preferences p;
      if (p.begin("favilla", false)) {
        p.putUChar("hcal", 1);
        p.putUChar("hcomp", calComp);
        p.putUChar("hbemf", calBemf);
        p.putUChar("hgain", calGain);
        p.putUChar("hc2", c2);
        p.end();
      }
      openLoop = wasOpen; applyLoopMode();
      return true;
    }
    _writeReg(0x1C, 0xF5);
    openLoop = wasOpen; applyLoopMode();
    return false;
  }

  void click()       { play(HAPTIC_FX_CLICK); }
  void doubleClick() { play(HAPTIC_FX_DOUBLE_CLICK); }
  void success()     { play(HAPTIC_FX_LIGHT_DBL_TAP); }
  void error()       { play(HAPTIC_FX_LONG_DBL_SHARP); }
  void boot()        { play(HAPTIC_FX_SMOOTH_HUM); }
  void alert()       { play(HAPTIC_FX_BUZZ); }

  // Sign request arriving — distinctive triple-pulse rhythm that's
  // attention-grabbing without feeling like an alarm. Double-click +
  // strong click = "tap-tap-tap" ringtone feel.
  void signRequest() {
    if (!ok) return;
    wakeForPlay();
    _writeReg(0x04, 10);  // Double Click 100% — first two pulses
    _writeReg(0x05, 1);   // Strong Click 100% — third pulse
    _writeReg(0x06, 0x00); // terminator
    _writeReg(0x0C, 0x01); // GO
  }

  // Sleep — drop EN low to fully gate the chip. Saves ~1.5mA.
  void sleep() { enablePin(false); ok = false; }
};

HapticDriver haptic;
void hapticStandbyTick(){
  if(haptic.ok && !haptic.inStandby && millis() - haptic.lastPlayMs > 400) haptic.standby();
}

// ── Feedback router ────────────────────────────────────────────────────────
// Routes feedback events to haptic + piezo based on user preference.
// Default: QUIET (haptic only, no piezo) for premium feel.
// User can change via Settings → Feedback Mode.
// FeedbackMode enum is now defined near the top of the file (above the
// auto-generated prototypes). Only the runtime variable lives here.
FeedbackMode feedbackMode = FEEDBACK_QUIET;
// 30 Sep 2026: per-press haptic tick is now its own switch (NVS "favilla"/
// "keyclick", default ON = unchanged behaviour). The brass buttons already
// have a mechanical click; with this OFF the haptic is reserved for events
// the button itself cannot tell you about (confirm, error, sign request,
// wake, lock). Settings > Device > Key clicks.
bool g_keyClick = true;

void feedbackInit() {
  // Load preference from NVS. Note: the NVS key is "fb_mode2" because the
  // enum values shifted when FEEDBACK_OFF was added at position 0. Using
  // the old "fb_mode" key would have caused users with QUIET (was 0) to
  // suddenly get OFF (now 0) — silent device unexpectedly. Fresh key
  // defaults everyone to QUIET on first boot of this firmware version.
  Preferences prefs;
  if (prefs.begin("favilla", true)) {
    uint8_t m = prefs.getUChar("fb_mode2", FEEDBACK_QUIET);
    if (m <= FEEDBACK_LOUD) feedbackMode = (FeedbackMode)m;
    g_keyClick = prefs.getUChar("keyclick", 1) == 1;
    prefs.end();
  }
}

void feedbackSetMode(FeedbackMode m) {
  feedbackMode = m;
  Preferences prefs;
  if (prefs.begin("favilla", false)) {
    prefs.putUChar("fb_mode2", (uint8_t)m);
    prefs.end();
  }
}

// New unified feedback API. buzzerClick / OK / Fail / Boot are kept as
// the public names because the rest of the codebase already calls them.
// They now route through haptic + (optionally) piezo per FeedbackMode.
void buzzerClick() {
  if (feedbackMode == FEEDBACK_OFF) return;
  if (g_keyClick) haptic.click();
  if (feedbackMode == FEEDBACK_LOUD) _buzzerClickTone();
}
void keyClickSet(bool on) {
  g_keyClick = on;
  Preferences prefs;
  if (prefs.begin("favilla", false)) { prefs.putUChar("keyclick", on ? 1 : 0); prefs.end(); }
}
void buzzerOK() {
  if (feedbackMode == FEEDBACK_OFF) return;
  haptic.success();
  if (feedbackMode >= FEEDBACK_NORMAL) _buzzerOKTone();
}
void buzzerFail() {
  if (feedbackMode == FEEDBACK_OFF) return;
  haptic.error();
  if (feedbackMode >= FEEDBACK_NORMAL) _buzzerFailTone();
}
// 30 Sep 2026: set by wakeHoldGate() (top of setup()) when this boot is a
// deep-sleep wake that passed the 2 s hold. Wake feedback is a crisp
// "beep beep" (DRV2605 Double Click) rather than the cold-boot hum.
bool g_wakeFromSleep = false;
// Plays the wake "beep beep" the moment the hold is satisfied — called from
// setup() right after NVS is up, BEFORE the 500 ms serial settle and the
// display/SE/G0 bring-up, so the haptic lands ~1 s earlier than buzzerBoot().
// Brings the main I2C bus and the DRV2605 up early; the later haptic init in
// setup() is skipped when this already succeeded.
void wakeBeepEarly() {
  feedbackInit();                               // respect FEEDBACK_OFF
  if (feedbackMode == FEEDBACK_OFF) return;
  rtc_gpio_hold_dis((gpio_num_t)6);  rtc_gpio_deinit((gpio_num_t)6);   // SDA
  rtc_gpio_hold_dis((gpio_num_t)5);  rtc_gpio_deinit((gpio_num_t)5);   // SCL
  rtc_gpio_hold_dis((gpio_num_t)HAPTIC_EN_PIN);
  rtc_gpio_deinit((gpio_num_t)HAPTIC_EN_PIN);
  Wire.begin(6,5);
  if (haptic.init(true /* LRA */)) haptic.doubleClick();
}
void buzzerBoot() {
  if (feedbackMode == FEEDBACK_OFF) return;
  if (g_wakeFromSleep) return;                  // wakeBeepEarly() already played it
  haptic.boot();                                // smooth hum — cold boot / restart
  if (feedbackMode >= FEEDBACK_NORMAL) _buzzerBootTone();
}
// Sign request alert — buzzes in NORMAL or LOUD mode. Higher priority
// than success/error since the user needs to take action.
void buzzerSignRequest() {
  if (feedbackMode == FEEDBACK_OFF) return;
  haptic.signRequest();
  if (feedbackMode >= FEEDBACK_NORMAL) _buzzerSignRequestTone();
}

#define C_BG        0x0000   // absolute black
#define C_FG        0xFFFF   // full white
// V22.x: QR light-module brightness — user-adjustable (Settings -> Device ->
// QR brightness). Was a fixed 75% grey (0xC638) chosen to cut glare for phone
// scanning; now a 3..10 level driving the grey (10 = full white). The floor
// at 3 keeps enough light/dark contrast that phone cameras still lock on.
// Persisted in the "favilla" Preferences namespace ("qr_white"); loaded at
// boot by qrWhiteLoad(). C_QR_WHITE stays a drop-in macro, so every existing
// QR draw site (quiet-zone cards + full-bleed UR frames) picks the live value
// up unchanged.
#define QR_WHITE_LVL_MIN 3
#define QR_WHITE_LVL_MAX 10
#define QR_WHITE_LVL_DEF 8    // (8*255)/10 = 204 — visually the old 0xC638
static uint8_t qrWhiteLevel = QR_WHITE_LVL_DEF;
static inline uint16_t qrWhiteColor(){
  int g=(qrWhiteLevel*255)/10;                            // level -> 8-bit grey
  return (uint16_t)(((g&0xF8)<<8)|((g&0xFC)<<3)|(g>>3));  // grey -> RGB565
}
#define C_QR_WHITE  qrWhiteColor()
static void qrWhiteLoad(){
  Preferences p;
  if(p.begin("favilla", true)){
    uint8_t v=p.getUChar("qr_white", QR_WHITE_LVL_DEF);
    if(v>=QR_WHITE_LVL_MIN && v<=QR_WHITE_LVL_MAX) qrWhiteLevel=v;
    p.end();
  }
}
static void qrWhiteSave(){
  Preferences p;
  if(p.begin("favilla", false)){ p.putUChar("qr_white", qrWhiteLevel); p.end(); }
}

// ── WiFi TX power level ─────────────────────────────────────────────────────
// User-adjustable radio power, capped for RF-exposure compliance. Stored as a
// 1..8 UI level in the "favilla" namespace ("wifi_tx"); mapped to the IDF's
// quarter-dBm units at apply time. Loaded at boot by wifiTxLoad().
//
// COMPLIANCE CAP: this device is worn on the body / held in the hand, so the
// >20cm mobile exemption does not apply. WIFI_TX_CAP_Q keeps output under the
// low-power SAR exemption used by ARPANSA RPS S-1 / FCC KDB 447498 / EN 62479.
// DO NOT raise without SAR data. Level 8 == the cap, so the UI cannot exceed
// it by construction.
// 20 Oct 2026: 13 dBm -> 8.5 dBm, per the 13 Oct decision to keep the antenna
// on the inside of the back glass and cap shipping TX power (8.5 dBm WiFi)
// for the SAR exclusion rather than move the antenna or SAR-test. This build
// has no Bluetooth (no BLE stack is started), so there is no BLE power to cap.
// A stored "wifi_tx" level keeps its number and maps to the new, lower table.
#define WIFI_TX_CAP_Q     34   // 34 * 0.25 = 8.5 dBm — hard ceiling, compliance
#define WIFI_TX_LVL_MIN   1
#define WIFI_TX_LVL_MAX   8
#define WIFI_TX_LVL_DEF   8    // ship at the cap; user may reduce
static uint8_t wifiTxLevel = WIFI_TX_LVL_DEF;

// Level -> quarter-dBm. Spread across the driver's usable range up to the cap.
// The IDF quantises to discrete steps, so these are requests, not guarantees;
// esp_wifi_get_max_tx_power() reports what actually landed.
static inline int8_t wifiTxQuarter(uint8_t lvl){
  static const int8_t q[WIFI_TX_LVL_MAX] = { 8, 12, 16, 20, 24, 28, 32, 34 };   // 2 .. 8.5 dBm
  if(lvl < WIFI_TX_LVL_MIN) lvl = WIFI_TX_LVL_MIN;
  if(lvl > WIFI_TX_LVL_MAX) lvl = WIFI_TX_LVL_MAX;
  int8_t v = q[lvl-1];
  return (v > WIFI_TX_CAP_Q) ? WIFI_TX_CAP_Q : v;   // belt and braces
}
static inline float wifiTxDbm(uint8_t lvl){ return wifiTxQuarter(lvl) * 0.25f; }

static void wifiTxLoad(){
  Preferences p;
  if(p.begin("favilla", true)){
    uint8_t v=p.getUChar("wifi_tx", WIFI_TX_LVL_DEF);
    if(v>=WIFI_TX_LVL_MIN && v<=WIFI_TX_LVL_MAX) wifiTxLevel=v;
    p.end();
  }
}
static void wifiTxSave(){
  Preferences p;
  if(p.begin("favilla", false)){ p.putUChar("wifi_tx", wifiTxLevel); p.end(); }
}

// THE choke point. Nothing else in this firmware may call
// esp_wifi_set_max_tx_power() directly — route every change through here so
// the cap cannot be bypassed by a future code path. Safe to call when the
// radio is down (returns the IDF error, no harm). Must be called AFTER
// esp_wifi_start(): the driver resets TX power on start, so every mode change
// and every AP/STA bring-up has to re-apply.
static bool wifiApplyTxPower(){
  int8_t want = wifiTxQuarter(wifiTxLevel);
  esp_err_t e = esp_wifi_set_max_tx_power(want);
  if(e != ESP_OK){
    LOG_NET("[RFDIAG] set_max_tx_power(%d) failed: %d\n", want, (int)e);
    return false;
  }
  int8_t got = 0; esp_wifi_get_max_tx_power(&got);
  LOG_NET("[RFDIAG] TX lvl=%u req=%d (%.2f dBm) got=%d (%.2f dBm) cap=%d\n",
          wifiTxLevel, want, want*0.25f, got, got*0.25f, WIFI_TX_CAP_Q);
  return true;
}

// 20 Oct 2026: apply the cap on EVERY radio start, whatever started it. The
// background boot connect (ANS_BOOT_WAIT), the path a normal boot takes, never
// called wifiApplyTxPower(), so on most boots the radio ran at the driver
// default (about 20 dBm) and the cap only held after a menu change, a hotspot
// start or a fallback reconnect. The driver resets TX power on every start, so
// hooking STA_START / AP_START (before the first scan or association frame)
// and STA_CONNECTED (belt and braces) covers every path, present and future.
static void wifiTxCapEvent(WiFiEvent_t event, WiFiEventInfo_t info){
  (void)event; (void)info;
  wifiApplyTxPower();
}
static void wifiTxCapInstall(){
  static bool done = false;
  if(done) return;
  done = true;
  WiFi.onEvent(wifiTxCapEvent, ARDUINO_EVENT_WIFI_STA_START);
  WiFi.onEvent(wifiTxCapEvent, ARDUINO_EVENT_WIFI_AP_START);
  WiFi.onEvent(wifiTxCapEvent, ARDUINO_EVENT_WIFI_STA_CONNECTED);
}
