//   F_BODY    — Inter Regular 12       — menu items, body text
//   F_SMALL   — Inter Regular 10       — labels, hints, status bar text
//   F_MONO    — JetBrains Mono Reg 12  — hex, npub, IP, sat amounts
//   F_DISPLAY — Archivo Bold 28        — boot splash wordmark "FAVILLA" (4 Oct 2026: was Bebas Neue 32)
//   F_DISPLAY_LT — Archivo Light 28     — boot splash wordmark "KEY" (drawn tracked, in brass)
//
// Inter for human-readable copy. JetBrains Mono for technical readouts.
// Bebas Neue for the brand wordmark — matches the PWA's display font.
// F_HEAD_SM exists because uiHeader's coloured 4px dot reads strong, and
// the surrounding label needs matching weight at the same small size.
#define F_TITLE   0
#define F_HEAD    1
#define F_BODY    2
#define F_SMALL   3
#define F_MONO    4
#define F_HEAD_SM 5
#define F_DISPLAY 6
#define F_DISPLAY_LT 7
#define F_BRAND_B12  8   // Archivo Bold 12  — header lockup "FAVILLA" (5 Oct 2026)
#define F_BRAND_L12  9   // Archivo Light 12 — header lockup "KEY" (tracked)
#define F_BRAND_B14 10   // Archivo Bold 14  — tile / section labels, tracked caps
#define FONT_COUNT 11

// ── Display ────────────────────────────────────────────────────────────────
TFT_eSPI tft = TFT_eSPI();
TFT_eSprite spr = TFT_eSprite(&tft);

static StaticSemaphore_t dispMutexBuf;
static SemaphoreHandle_t dispMutex = NULL;
// DISP_LOCK also holds off automatic light sleep for the duration of the
// display transaction. A light sleep entered mid-pushSprite gates the SPI
// peripheral clock partway through the frame and tears/corrupts the panel —
// the classic PM failure mode alongside camera DMA. Putting the hold in the
// macro (rather than in dispPush) covers ALL ~21 pushSprite sites, including
// the ones that take DISP_LOCK directly and never go through dispPush().
// pmHoldWake/pmReleaseWake are ref-counted and compile to nothing when
// CONFIG_PM_ENABLE is off, so this costs nothing on non-PM builds.
#define DISP_LOCK()   do { pmHoldWake(); if(dispMutex) xSemaphoreTake(dispMutex, portMAX_DELAY); } while(0)
// No-op macro — approval interruption handled via loop condition checks
#define CHECK_APPROVAL() do { } while(0)
#define DISP_UNLOCK() do { if(dispMutex) xSemaphoreGive(dispMutex); pmReleaseWake(); } while(0)

void blHandoffOnPush();   // 10l: below (the door hand-off's fade-in)
void dispPush() {
  // Light-sleep hold is inside DISP_LOCK/DISP_UNLOCK — see the macro comment.
  DISP_LOCK();
  spr.pushSprite(0, 0);
  DISP_UNLOCK();
  blHandoffOnPush();   // 10l: the first screen after a door hand-off fades in
}

// V21.1: blocking sub-menu loops (run*Menu) have their own while(true) and
// don't return to the main loop(), so the periodic battery read + status-bar
// refresh there never runs — the battery % looked frozen until reboot. Call
// this inside those loops to keep the bar live. Throttled internally (battRead
// has its own 30s gate; the bar repaint is cheap but we cap it to ~2s).

// Global sleep gesture: hold BOTH scroll buttons (btn1+btn3) 2.5s to sleep.
// Defined after the Button struct (needs btn.stable); forward-declared here so
// the menu/status loops above can call it. Returns true when it fires.
bool tickSleepGesture();

#ifdef FAVILLA_FIDO_PROBE
static void vpPump();   // defined in the FAVILLA_FIDO_PROBE vault section (15 Nov: the call was unguarded, which broke the plain builds' link)
#endif
void tickStatusBarInMenu(bool paintFooter=true){
  if(tickSleepGesture()) return;   // both-scroll-held-5s → sleep (global)
  battRead();   // 30s-throttled internally; updates battPercent
#ifdef FAVILLA_FIDO_PROBE
  vpPump();     // 11q: vault jobs the phone asked for, inside blocking menus too
#endif
  tickMenuIdleDim();   // idle dimming + wake inside blocking menu sub-loops
  tickAutoNetInMenu(); // keep AUTO-mode network switching alive in blocking menus
  // 28 Sep 2026: keep the STATION POWER-SAVE POLICY alive in blocking menus too.
  // It only ran from loop(), so the radio froze at whatever state it had when a
  // menu was entered: PS_NONE if the app had been talking (stuck at ~125 mA on
  // the Battery page even after the app was closed), MIN_MODEM otherwise. Same
  // 2 s cadence as the loop's status-bar branch.
  { static uint32_t lastPs = 0; if(millis() - lastPs > 2000){ lastPs = millis(); tickWifiIdlePower(); } }
  motionLockTick();    // keep BMA400 motion auto-lock arming/firing inside submenus
  lockChordTick();     // 11bz: the lock shortcut inside submenus too
  remoteLockTick();    // keep PWA lock/unlock screen-sync firing inside submenus
  pairPromoteTick();  // keep Option A pair-promotion reveal firing inside submenus
  sasConfirmTick();   // Option B: SAS code-confirm modal fires inside submenus too
  // Mark that a blocking menu currently owns the screen. autoNetRefreshUI()
  // checks this so an AUTO network switch completing mid-menu refreshes only the
  // status bar instead of repainting the full main menu over the settings UI.
  blockingMenuScreenUntil = millis() + 250;
                       // (defined after tickIdleDim/Button, where its deps are in scope)
  // Footer repaint is opt-out: screens that deliberately have NO footer (e.g.
  // Auto-lock / Motion-Lock) pass paintFooter=false so this background tick
  // doesn't redraw uiFooter() over their clean layout every 2s.
  if(!paintFooter) return;
  // Don't push the sprite while the reconnect-approve screen owns the display —
  // it would flash the stale menu over the top every 2s.
  if(g_rcApprove.active || g_vaultOverlay || fidoPromptActive()) return;
  static unsigned long lastMenuBar = 0;
  if(dimActive) return;   // 11cf (power): no footer pushes into a dark, sleeping panel
  if(millis() - lastMenuBar > 2000 || g_wakeRepaint){
    lastMenuBar = millis(); g_wakeRepaint = false;
    DISP_LOCK();
    uiFooter();
    spr.pushSprite(0,0);
    DISP_UNLOCK();
  }
}

// Push only a region of the sprite to the LCD. Use during animation to
// avoid pushing the full 240×240 (115KB SPI traffic) every frame when only
// a small area changed. Caller is responsible for ensuring the rest of the
// sprite buffer matches what's currently on-screen.
void dispPushRegion(int x, int y, int w, int h) {
  DISP_LOCK();
  spr.pushSprite(x, y, x, y, w, h);
  DISP_UNLOCK();
}

// ── Backlight dissolve helpers ──────────────────────────────────────────────
// Page-transition dissolve (same curve as bunkerConnectedReveal): ramp the
// backlight down fast, let the caller render the next page while dark, then
// ramp back up. Pure PWM — zero sprite/SPI cost.
void blDimOut(){
  for(int d=blTargetDuty(); d>=0; d-=64){ ledcWrite(TFT_BL_PIN, d); delay(6); }
  ledcWrite(TFT_BL_PIN, 0);
}
void blDimIn(){
  for(int d=0; d<=blTargetDuty(); d+=48){ ledcWrite(TFT_BL_PIN, d); delay(6); }
  ledcWrite(TFT_BL_PIN, blTargetDuty());
}
// One-shot ASYNC dim-in for entering CIPHER. runCipherGame() (cipher_game.h)
// blocks and paints its own intro, so main.cpp can't call blDimIn() "after
// the game's first frame" synchronously. This task waits long enough for the
// intro to paint (panel is dark, over a black frame — no stale-menu flash),
// then ramps the backlight up around it. Backlight PWM is its own peripheral,
// so there's no SPI / display-lock contention with the game's rendering.
static void blDimInTask(void*){
  vTaskDelay(pdMS_TO_TICKS(120));           // let the game paint its intro
  for(int d=0; d<=blTargetDuty(); d+=32){ ledcWrite(TFT_BL_PIN, d); vTaskDelay(pdMS_TO_TICKS(6)); }
  ledcWrite(TFT_BL_PIN, blTargetDuty());
  vTaskDelete(NULL);
}
void blDimInAsync(){ xTaskCreate(blDimInTask, "blDimIn", 2048, NULL, 1, NULL); }
// 10j (Josh, 9 Nov 2026: "can we still have a fade out and fade in between
// pages? that looks better and would use some of the time productively").
// The door to PIN hand-off: Select Mode fades out over ~0.35 s on its own task
// while the boot carries on (SE051, G0 door, network), the panel stays dark
// for whatever is left, and the PIN pad fades in over ~0.35 s once drawn
// (loop's state change, blHandoffFadeIn). Smoothstep both ways, like the boot
// splash, so neither end snaps.
static volatile bool g_blFadeOutBusy = false;
bool g_blFadeInPending = false;
bool g_pinPreDrawn = false;   // 10l: the PIN pad went up during the hand-off; loop's state change keeps its presses
// 10l (Josh, 9 Nov 2026: "make the fade out and in faster and just go straight
// to the PIN page and have the rest happen underneath"; and every door fades).
// Out: 8 x 15 ms, on the caller (Select Mode is static, nothing else to draw).
// In: the next frame anyone pushes (dispPush) starts an 8 x 15 ms ramp on its
// own task, so the screen comes up while the boot carries on underneath.
static inline int blEase(int full, int i, int n, bool up){ const float p = (float)i / n, e = p * p * (3.0f - 2.0f * p); return (int)(full * (up ? e : 1.0f - e)); }
void blHandoffFadeOut(){
  const int from = blTargetDuty();
  for(int i = 1; i <= 10; i++){ ledcWrite(TFT_BL_PIN, blEase(from, i, 10, false)); delay(15); }   // 10m: 0.15 s (Josh: 25% longer)
  ledcWrite(TFT_BL_PIN, 0);
  g_blFadeInPending = true;
  // Safety net in every life (the PASSKEY life never runs loop()): a screen
  // that never goes through dispPush must not leave the panel dark.
  xTaskCreate([](void*){ vTaskDelay(pdMS_TO_TICKS(3000));
    if(g_blFadeInPending){ g_blFadeInPending = false; ledcWrite(TFT_BL_PIN, blTargetDuty()); ets_printf("[UI] hand-off fade-in did not come: backlight restored\n"); }
    vTaskDelete(NULL); }, "blGuard", 2048, NULL, 1, NULL);
}
static void blHandoffInTask(void*){
  g_blFadeOutBusy = true;
  const int to = blTargetDuty();
  for(int i = 1; i <= 10; i++){ ledcWrite(TFT_BL_PIN, blEase(to, i, 10, true)); vTaskDelay(pdMS_TO_TICKS(15)); }   // 10m: 0.15 s
  ledcWrite(TFT_BL_PIN, to);
  g_blFadeOutBusy = false; vTaskDelete(NULL);
}
void blHandoffOnPush(){
  if(!g_blFadeInPending) return;
  g_blFadeInPending = false;
  if(xTaskCreate(blHandoffInTask, "blIn", 2048, NULL, 1, NULL) != pdPASS) ledcWrite(TFT_BL_PIN, blTargetDuty());
}

// Spinner location is fixed in dispLoading (cx=120, cy=106, r=28) and
// dispWaiting (cx=120, cy=96, r=26). With dot radius up to 3 the effective
// drawing area is bounded by these constants:
#define SPIN_LOADING_X   84
#define SPIN_LOADING_Y   70
#define SPIN_LOADING_W   72
#define SPIN_LOADING_H   72
#define SPIN_WAITING_X   84
#define SPIN_WAITING_Y   60
#define SPIN_WAITING_W   72
#define SPIN_WAITING_H   72

// Repaint just the spinner ring area for animation ticks. Clears the
// region in the sprite, redraws the dots, pushes only that region.
// Costs ~5KB SPI vs 115KB for a full dispPush() — about 23× cheaper.
void spinnerTickLoading(uint16_t col) {
  spr.fillRect(SPIN_LOADING_X, SPIN_LOADING_Y, SPIN_LOADING_W, SPIN_LOADING_H, C_BG);
  if(col == C_GREEN) drawSpinnerRingGreen(120, 106, 28, 5);
  else               drawSpinnerRing(120, 106, 28, 5);
  dispPushRegion(SPIN_LOADING_X, SPIN_LOADING_Y, SPIN_LOADING_W, SPIN_LOADING_H);
}
#define WAIT_MARK_OY 52
void ebBreatheDraw(int oy);   // defined with the sign screen
void spinnerTickWaiting() {
  ebBreatheDraw(WAIT_MARK_OY);
  dispPushRegion(96, WAIT_MARK_OY, 48, 48);
}

// ── Background spinner task ────────────────────────────────────────────────
// When the main thread is blocked (e.g. webSocket.loop() during a TLS
// handshake), a polled spinner stops animating because spinTick() is
// never called. The fix is to run the spinner repaint on core 1 — the
// idle core on a dual-core ESP32-S3 — so it ticks regardless of what
// core 0 is doing.
//
// Usage:
//   bgSpinnerStart(C_GREEN);   // begin animating
//   ...long-running blocking work on core 0...
//   bgSpinnerStop();           // stops the task and waits for it to exit
//
// Safety: the spinner writes to the shared sprite buffer and pushes
// regions of it via SPI. Both spr operations and SPI access need
// serialization with whatever core 0 is doing. The dispPushRegion path
// already takes DISP_LOCK, so concurrent pushes are safe. We do NOT
// modify the sprite buffer outside the spinner region while bg spinner
// is active — callers must ensure their static UI is painted before
// starting the bg spinner and must not redraw it until after stopping.
static volatile bool bgSpinnerRunning = false;
static volatile uint16_t bgSpinnerCol = C_AMBER;
static volatile bool bgSpinnerEmber = false;   // 5 Oct 2026: animate the ember (sign screen) instead of the ring
static volatile bool g_signWorkingArmed = false; // set by dispSignWorking; the next bgSpinnerStart consumes it
static TaskHandle_t bgSpinnerTask = nullptr;
void ebSignWorkingTick();                      // defined with the sign screen

static void bgSpinnerTaskFn(void* arg){
  while(bgSpinnerRunning){
    if(bgSpinnerEmber){
      ebSignWorkingTick();                     // self-paced (~50 ms noise step)
      vTaskDelay(pdMS_TO_TICKS(25));
      continue;
    }
    // spinTick reads millis() and computes the correct frame for now,
    // so the rotation rate is uniform regardless of how often this task
    // gets scheduled. If core 1 is briefly busy, we'll skip frames on
    // resume rather than fall behind real time.
    if(spinTick()){
      spinnerTickLoading(bgSpinnerCol);
    }
    vTaskDelay(pdMS_TO_TICKS(8));
  }
  bgSpinnerTask = nullptr;
  vTaskDelete(NULL);
}

void bgSpinnerStart(uint16_t col){
  if(bgSpinnerRunning) return;  // already running
  bgSpinnerCol = col;
  bgSpinnerEmber = g_signWorkingArmed; g_signWorkingArmed = false;
  bgSpinnerRunning = true;
  // 4KB stack is plenty — the task only does region pushes
  xTaskCreatePinnedToCore(bgSpinnerTaskFn, "bgSpin", 4096, nullptr, 1,
                          &bgSpinnerTask, 1 /* core 1 */);
}

void bgSpinnerStop(){
  if(!bgSpinnerRunning) return;
  bgSpinnerRunning = false;
  // Wait for the task to actually exit so it's safe for the caller to
  // reuse the spinner region for other drawing.
  while(bgSpinnerTask != nullptr){
    vTaskDelay(pdMS_TO_TICKS(2));
  }
  bgSpinnerEmber = false;
}

// RAII scope-guard for the background spinner. Construct it after painting a
// static loading screen and before a blocking crypto op; it starts the core-1
// spinner and GUARANTEES bgSpinnerStop() runs on every exit path — normal
// return, early error return, break, or exception — so the spinner task can
// never leak and scribble over the next screen. Usage:
//   { BgSpin _spin(C_GREEN);  ...blocking work, returns/breaks ok... }
// The spinner stops automatically when _spin goes out of scope.
struct BgSpin {
  BgSpin(uint16_t col){ bgSpinnerStart(col); }
  ~BgSpin(){ bgSpinnerStop(); }
  // Manual early stop (e.g. just before drawing a success/failure screen
  // inside the same scope). Safe to call more than once.
  void stop(){ bgSpinnerStop(); }
};

// ── Background button polling task ───────────────────────────────────────
// Buttons are polled by Button::poll() which checks digitalRead and
// debounces. Without this task, poll() only runs when core 0's main loop
// reaches it — which doesn't happen for hundreds of ms at a time when
// core 0 is busy with ATECC operations, TLS handshakes, or NIP-46 request
// processing. During those windows the buttons are completely dead.
//
// Solution: dedicate a tiny task on core 1 that calls poll() on both
// buttons every 5ms. Core 1 is otherwise mostly idle. Buttons stay
// responsive regardless of core 0 load.
//
// Note: the existing in-line btn1.poll()/btn2.poll() calls scattered
// throughout the codebase remain harmless — poll() is idempotent
// (digitalRead + state update). They serve as belt-and-braces during
// blocking work where even core 1 might be briefly delayed.
//
// Forward declarations — Button struct and btn1/btn2 instances are
// defined further down. We just need to call .poll() on them, which
// the linker resolves.
struct Button;
extern Button btn1;
extern Button btn2;
extern Button btn3;   // SCROLL UP   (V21.1)
extern Button btn4;   // BACK/DECLINE (V21.1)
static TaskHandle_t btnPollTask = nullptr;
static TaskHandle_t g_prePinTaskH = nullptr;   // 11w: the PIN pad's task in the door hand-off gap (never sleeps the KEY itself)
static void btnPollTaskFn(void* arg);
void btnPollStart(){
  if(btnPollTask) return;
  // 2KB stack is plenty — task only calls digitalRead and updates struct fields.
  xTaskCreatePinnedToCore(btnPollTaskFn, "btnPoll", 2048, nullptr, 2,
                          &btnPollTask, 1 /* core 1 */);
}



// Font load/unload helpers — always pair fSet with fEnd
static int currentFont = -1;

// Font slot pointers/sizes. Now set by fontsPreload() to embedded flash arrays.
// Indices match F_TITLE, F_HEAD, F_BODY, F_SMALL, F_MONO, F_HEAD_SM, F_DISPLAY.
static uint8_t* fontBufs[FONT_COUNT]      = {};
static uint32_t fontBufSizes[FONT_COUNT]  = {};

// Font slots now point directly at const arrays embedded in the signed
// firmware image (see fonts_data.h). No filenames, no filesystem, no RAM copy:
// TFT_eSPI reads the VLW straight from memory-mapped flash. The array for each
// slot, in F_* index order (F_TITLE..F_DISPLAY).
static const uint8_t* const fontData[FONT_COUNT] = {
  FONT_JetBrainsMono_Bold_24,   // F_TITLE
  FONT_Inter_Semibold_16,       // F_HEAD
  FONT_Inter_Regular_12,        // F_BODY
  FONT_Inter_Regular_10,        // F_SMALL
  FONT_JetBrainsMono_Regular_12,// F_MONO
  FONT_Inter_Semibold_10,       // F_HEAD_SM
  FONT_Archivo_Bold_28,         // F_DISPLAY    (fonts_brand.h)
  FONT_Archivo_Light_28,        // F_DISPLAY_LT (fonts_brand.h)
  FONT_Archivo_Bold_12,         // F_BRAND_B12  (fonts_brand.h)
  FONT_Archivo_Light_12,        // F_BRAND_L12  (fonts_brand.h)
  FONT_Archivo_Bold_14          // F_BRAND_B14  (fonts_brand.h)
};
static const uint32_t fontDataLen[FONT_COUNT] = {
  FONT_JetBrainsMono_Bold_24_len,
  FONT_Inter_Semibold_16_len,
  FONT_Inter_Regular_12_len,
  FONT_Inter_Regular_10_len,
  FONT_JetBrainsMono_Regular_12_len,
  FONT_Inter_Semibold_10_len,
  FONT_Archivo_Bold_28_len,
  FONT_Archivo_Light_28_len,
  FONT_Archivo_Bold_12_len,
  FONT_Archivo_Light_12_len,
  FONT_Archivo_Bold_14_len
};

// Point each font slot at its embedded array. No allocation, no I/O; kept as a
// function so the boot sequence and call site are unchanged.
void fontsPreload() {
  for(int i = 0; i < FONT_COUNT; i++){
    fontBufs[i]     = (uint8_t*)fontData[i];   // const cast: TFT_eSPI only reads
    fontBufSizes[i] = fontDataLen[i];
    LOG_BOOT("Font slot %d embedded (%u bytes)\n", i, (unsigned)fontDataLen[i]);
  }
}

void fSet(int font) {
  if(font < 0 || font >= FONT_COUNT) return;  // bounds check — bad token = no-op
  if(currentFont == font) return;
  if(currentFont >= 0) spr.unloadFont();
  if(fontBufs[font] && fontBufSizes[font] > 0)
    spr.loadFont(fontBufs[font]);
  else
    LOG_BOOT("Font %d not loaded\n", font);
  currentFont = font;
}

// Lazy end: keep the font loaded so the next fSet() with the same font
// short-circuits. The previous behaviour unloaded immediately, forcing a
// reload on every text draw. Switching fonts still does the right thing
// because fSet() unloads the previous font before loading the new one.
// Call fEndHard() if you genuinely need to free the font buffer reference
// (e.g. before extended sleep) — currently unused.
void fEnd() {
  // intentional no-op
}
void fEndHard() {
  if(currentFont >= 0) spr.unloadFont();
  currentFont = -1;
}

// Measure string width using current loaded font
int fWidth(const char* s) {
  return spr.textWidth(s);
}

// Draw string centred on x
void fDrawCentre(const char* s, int cx, int y) {
  int w = fWidth(s);
  spr.drawString(s, cx - w/2, y);
}
// 29 Oct 2026: page-language helpers, defined with uiBrandLabel (declared early: the footer uses them)
static void uiTrackLabel(const char* t, int cx, int y, uint16_t col, int track = 3);   // defined with uiBrandLabel
static int  uiTrackWidth(const char* t, int track);
static void uiHoldFooter(const char* action, const char* sub, float p, uint16_t col = C_EB_BRASS);

// Draw string right-aligned
void fDrawRight(const char* s, int rx, int y) {
  int w = fWidth(s);
  spr.drawString(s, rx - w, y);
}

// ── v21 UI helpers ────────────────────────────────────────────────────────
void uiCard(int y, int h, const char* title, const char* desc, bool sel,
            uint16_t accent = C_GREEN);
void uiAsk(const char* question, const char* detail = nullptr);
void uiPill(int x, int y, int w, int h, uint16_t bg, uint16_t textCol,
            const char* label, bool ghost=false, uint16_t borderCol=0) {
  int r = h / 2;
  if (ghost) spr.drawRoundRect(x, y, w, h, r, borderCol ? borderCol : C_BORDER2);
  else       spr.fillRoundRect(x, y, w, h, r, bg);
  fSet(F_BODY); spr.setTextColor(textCol);
  int tw = spr.textWidth(label);
  spr.drawString(label, x + (w - tw) / 2, y + (h - 12) / 2);
  fEnd();
}

// ── uiCard: THE choice card ─────────────────────────────────────────────────
// Same shape as runNostrMenu()'s cards, which is the layout in this product
// that already solves "240x240 with no room to waste": inset rounded panel,
// CAPS title at F_HEAD, one-line description at F_BODY, and NO header or
// footer so the cards own the whole screen.
//
// Selection is shown by the BORDER and the TITLE COLOUR, not by inverting the
// row. That matters: the description stays C_TEXT2 on every card, so the
// option you have NOT selected is still fully readable — you can compare two
// choices without scrolling between them. A dimmed alternative forces the user
// to select something just to read it.
void uiCard(int y, int h, const char* title, const char* desc,
            bool sel, uint16_t accent) {
  const int X = 12, W = 216;
  spr.fillRoundRect(X, y, W, h, 10, sel ? C_PANEL2 : C_PANEL);
  spr.drawRoundRect(X, y, W, h, 10, sel ? accent : C_BORDER2);
  const int textX = X + 16;
  fSet(F_HEAD); spr.setTextColor(sel ? accent : C_FG);
  spr.drawString(title, textX, y + 14); fEnd();
  if (desc && *desc) {
    fSet(F_BODY); spr.setTextColor(C_TEXT2);
    spr.drawString(desc, textX, y + 40); fEnd();
  }
}

// Onboarding question block. Onboarding drops uiHeader AND uiFooter: the
// header's 28px strip plus the footer's mode-glyph/battery row cost ~58px of a
// 240px screen to show a section name and status the user cannot act on during
// setup. The question itself does the header's job and can be twice the size.
// 29 Oct 2026 (page language): the question as tracked caps (Archivo Bold 14,
// or 12 if it is long), the detail in Archivo 13 grey. Same y band as before
// (8..44) so every card layout under it stands.
void uiAsk(const char* question, const char* detail) {
  char up[40]; size_t i = 0;
  for(; question[i] && i + 1 < sizeof up; i++) up[i] = (question[i] >= 'a' && question[i] <= 'z') ? question[i] - 32 : question[i];
  up[i] = 0;
  int w = 0; fSet(F_BRAND_B14);
  for(const char* q = up; *q; q++){ char c[2] = {*q, 0}; w += spr.textWidth(c) + 2; }
  int font = (w - 2 <= 224) ? F_BRAND_B14 : F_BRAND_B12;
  fSet(font); spr.setTextColor(C_EB_INK);
  w = 0; for(const char* q = up; *q; q++){ char c[2] = {*q, 0}; w += spr.textWidth(c) + 2; }
  int x = 120 - (w - 2) / 2;
  for(const char* q = up; *q; q++){ char c[2] = {*q, 0}; spr.drawString(c, x, 10); x += spr.textWidth(c) + 2; }
  if (detail && *detail) {
    fEndHard(); spr.loadFont(FONT_Archivo_Regular_13); spr.setTextColor(C_EB_GREY);
    spr.drawString(detail, 120 - spr.textWidth(detail) / 2, 30);
    fEndHard();
  }
}

void uiPanel(int x, int y, int w, int h,
             uint16_t bg=C_PANEL, uint16_t border=C_BORDER) {
  spr.fillRoundRect(x, y, w, h, 8, bg);
  spr.drawRoundRect(x, y, w, h, 8, border);
}

void uiBadge(const char* label, int x, int y, uint16_t col) {
  fSet(F_SMALL); spr.setTextColor(col);
  int tw = spr.textWidth(label);
  fEnd();
  spr.drawRoundRect(x, y, tw + 14, 15, 4, col);
  fSet(F_SMALL); spr.setTextColor(col);
  spr.drawString(label, x + 7, y + 3);
  fEnd();
}

// Geometric right-pointing chevron `›`. Cleaner than the typographic `>`
// glyph used previously — sharper apex, anti-aliased edges via drawWideLine,
// sized independently of the menu font. Apex at (cx,cy); the back edges
// extend w pixels to the left and h pixels above/below.
//
// Use for "select this" indicators on menu rows. For the standard 38px-row
// menus, w=5 h=7 thickness=2 reads as a balanced, modern caret.
void drawChevronRight(int cx, int cy, int w, int h, int thickness, uint16_t col){
  spr.drawWideLine(cx - w, cy - h, cx, cy, thickness, col);
  spr.drawWideLine(cx, cy, cx - w, cy + h, thickness, col);
}
void drawChevronLeft(int cx, int cy, int w, int h, int thickness, uint16_t col){
  spr.drawWideLine(cx + w, cy - h, cx, cy, thickness, col);
  spr.drawWideLine(cx, cy, cx + w, cy + h, thickness, col);
}

// ── Clean restart ──────────────────────────────────────────────────────────
void cleanRestart() {
  WiFi.persistent(true);       // restore normal WiFi persistence
  WiFi.setAutoReconnect(true); // restore auto-reconnect
  fEnd();
  spr.fillSprite(C_BG);
  DISP_LOCK(); spr.pushSprite(0,0); DISP_UNLOCK();
  tft.fillScreen(TFT_BLACK);
  delay(60);
  ESP.restart();
}

// ── WiFi credentials ───────────────────────────────────────────────────────
// ── Multi-network WiFi storage ─────────────────────────────────────────────
// Stores up to 5 networks as JSON in Preferences.
// On connect, tries each in order, connects to first that responds.

#define WIFI_MAX_NETWORKS 5

struct WifiNetwork { char ssid[64]; char pass[64]; };
WifiNetwork wifiNetworks[WIFI_MAX_NETWORKS];
int wifiNetworkCount = 0;
char wifiSSID[64] = {0}; // currently connected SSID
char wifiPass[64] = {0};
bool wifiProvisioned = false;

void wifiLoadCredentials(){
  Preferences p; p.begin("wifi", true);
  // Try new multi-network format first
  String json = p.getString("networks", "");
  // Fall back to legacy single-network format
  if(json.length() == 0){
    String s = p.getString("ssid", "");
    String pw = p.getString("pass", "");
    p.end();
    if(s.length() > 0){
      strncpy(wifiNetworks[0].ssid, s.c_str(), 63);
      strncpy(wifiNetworks[0].pass, pw.c_str(), 63);
      wifiNetworkCount = 1;
      wifiProvisioned = true;
    }
    return;
  }
  p.end();
  // Parse JSON array: [{"s":"ssid","p":"pass"},...]
  wifiNetworkCount = 0;
  int idx = 0;
  while(wifiNetworkCount < WIFI_MAX_NETWORKS){
    int start = json.indexOf('{', idx);
    if(start < 0) break;
    int end = json.indexOf('}', start);
    if(end < 0) break;
    String entry = json.substring(start+1, end);
    // Extract s and p fields
    int si = entry.indexOf("\"s\":\"");
    int pi = entry.indexOf("\"p\":\"");
    if(si >= 0 && pi >= 0){
      int sstart = si + 5;
      int send = entry.indexOf('"', sstart);
      int pstart = pi + 5;
      int pend = entry.indexOf('"', pstart);
      if(send > sstart && pend > pstart){
        String ssid = entry.substring(sstart, send);
        String pass = entry.substring(pstart, pend);
        strncpy(wifiNetworks[wifiNetworkCount].ssid, ssid.c_str(), 63);
        strncpy(wifiNetworks[wifiNetworkCount].pass, pass.c_str(), 63);
        wifiNetworkCount++;
      }
    }
    idx = end + 1;
  }
  wifiProvisioned = wifiNetworkCount > 0;
}

void wifiSaveNetworks(){
  String json = "[";
  for(int i = 0; i < wifiNetworkCount; i++){
    if(i > 0) json += ",";
    json += "{\"s\":\"";
    json += wifiNetworks[i].ssid;
    json += "\",\"p\":\"";
    json += wifiNetworks[i].pass;
    json += "\"}";
  }
  json += "]";
  Preferences p; p.begin("wifi", false);
  p.putString("networks", json);
  // Clear legacy keys
  p.remove("ssid"); p.remove("pass");
  p.end();
}

void wifiSaveCredentials(const char* ssid, const char* pass){
  // Add network if not already in list, otherwise update password
  for(int i = 0; i < wifiNetworkCount; i++){
    if(strcmp(wifiNetworks[i].ssid, ssid) == 0){
      strncpy(wifiNetworks[i].pass, pass, 63);
      wifiSaveNetworks();
      wifiProvisioned = true;
      return;
    }
  }
  // Add new — shift if at max
  if(wifiNetworkCount >= WIFI_MAX_NETWORKS){
    // Remove oldest (index 0), shift down
    for(int i = 0; i < WIFI_MAX_NETWORKS-1; i++) wifiNetworks[i] = wifiNetworks[i+1];
    wifiNetworkCount = WIFI_MAX_NETWORKS-1;
  }
  strncpy(wifiNetworks[wifiNetworkCount].ssid, ssid, 63);
  strncpy(wifiNetworks[wifiNetworkCount].pass, pass, 63);
  wifiNetworkCount++;
  wifiSaveNetworks();
  wifiProvisioned = true;
}

void wifiRemoveNetwork(int idx){
  if(idx < 0 || idx >= wifiNetworkCount) return;
  for(int i = idx; i < wifiNetworkCount-1; i++) wifiNetworks[i] = wifiNetworks[i+1];
  wifiNetworkCount--;
  wifiSaveNetworks();
  wifiProvisioned = wifiNetworkCount > 0;
}

void wifiClearCredentials(){
  // 19 Oct 2026: forget for real. The ESP32 WiFi stack keeps its own copy of
  // the last network joined (WiFi.persistent is on), so erase that too, and
  // zero the RAM copies of every SSID and password.
  WiFi.disconnect(true, true);          // radio off + erase the stack's stored config
  memset(wifiNetworks, 0, sizeof(wifiNetworks));
  wifiNetworkCount = 0;
  memset(wifiSSID, 0, sizeof(wifiSSID)); memset(wifiPass, 0, sizeof(wifiPass));
  wifiProvisioned = false;
  Preferences p; p.begin("wifi", false);
  p.remove("networks"); p.remove("ssid"); p.remove("pass");
  p.end();
}

// Try each saved network, skipping the failed one first (try it last)
bool wifiConnectBestSkipping(const char* skipSsid, int timeoutPerNetwork){
  for(int i = 0; i < wifiNetworkCount; i++){
    if(strcmp(wifiNetworks[i].ssid, skipSsid)==0) continue;
    LOG_NET("[WiFi] Trying: %s\n", wifiNetworks[i].ssid);
    WiFi.begin(wifiNetworks[i].ssid, wifiNetworks[i].pass);
    unsigned long start = millis();
    while(WiFi.status() != WL_CONNECTED && millis()-start < (unsigned long)timeoutPerNetwork){ esp_task_wdt_reset(); delay(200); }
    if(WiFi.status() == WL_CONNECTED){
      strncpy(wifiSSID, wifiNetworks[i].ssid, 63);
      strncpy(wifiPass, wifiNetworks[i].pass, 63);
      wifiApplyTxPower();   // driver resets TX power on start — re-apply the cap
      return true;
    }
    WiFi.disconnect(true); delay(200);
  }
  // Last resort: retry the network that dropped
  for(int i = 0; i < wifiNetworkCount; i++){
    if(strcmp(wifiNetworks[i].ssid, skipSsid)!=0) continue;
    LOG_NET("[WiFi] Retrying: %s\n", wifiNetworks[i].ssid);
    WiFi.begin(wifiNetworks[i].ssid, wifiNetworks[i].pass);
    unsigned long start = millis();
    while(WiFi.status() != WL_CONNECTED && millis()-start < (unsigned long)timeoutPerNetwork){ esp_task_wdt_reset(); delay(200); }
    if(WiFi.status() == WL_CONNECTED){
      strncpy(wifiSSID, wifiNetworks[i].ssid, 63);
      strncpy(wifiPass, wifiNetworks[i].pass, 63);
      wifiApplyTxPower();   // driver resets TX power on start — re-apply the cap
      return true;
    }
    WiFi.disconnect(true); delay(200);
  }
  return false;
}

// Try each saved network in order, return true if connected
bool wifiConnectBest(int timeoutPerNetwork){
  for(int i = 0; i < wifiNetworkCount; i++){
    LOG_NET("[WiFi] Trying: %s\n", wifiNetworks[i].ssid);
    WiFi.begin(wifiNetworks[i].ssid, wifiNetworks[i].pass);
    unsigned long start = millis();
    while(WiFi.status() != WL_CONNECTED && millis()-start < (unsigned long)timeoutPerNetwork){
      esp_task_wdt_reset();   // V21.1: blocking wait was tripping the task WDT on slow association
      delay(200);
    }
    if(WiFi.status() == WL_CONNECTED){
      strncpy(wifiSSID, wifiNetworks[i].ssid, 63);
      strncpy(wifiPass, wifiNetworks[i].pass, 63);
      // Re-apply the capped user level: the driver resets TX power on start,
      // so association is the point at which it has to be set again.
      wifiApplyTxPower();
      int8_t txq=0; esp_wifi_get_max_tx_power(&txq);
      LOG_NET("[RFDIAG] connected: RSSI %d dBm, max_tx_power %d (%.2f dBm)\n",
        WiFi.RSSI(), txq, txq*0.25f);
      return true;
    }
    WiFi.disconnect(true); delay(200);
  }
  return false;
}

// Force-connect to a specific saved network by index. Disconnects first
// to clear any in-progress connection. Returns true on success.
// Use for manual network switching from the WIFI submenu.
bool wifiConnectSpecific(int idx, int timeoutMs){
  if(idx < 0 || idx >= wifiNetworkCount) return false;
  WiFi.disconnect(true); delay(200);
  LOG_NET("[WiFi] Switching to: %s\n", wifiNetworks[idx].ssid);
  WiFi.begin(wifiNetworks[idx].ssid, wifiNetworks[idx].pass);
  unsigned long start = millis();
  while(WiFi.status() != WL_CONNECTED && millis()-start < (unsigned long)timeoutMs){ esp_task_wdt_reset(); delay(200); }
  if(WiFi.status() == WL_CONNECTED){
    strncpy(wifiSSID, wifiNetworks[idx].ssid, 63);
    strncpy(wifiPass, wifiNetworks[idx].pass, 63);
    return true;
  }
  return false;
}

// ── Runtime mode transitions (Auto mode only) ─────────────────────────────
// These are called from the main loop when the environment changes, NOT
// from the boot dispatcher (which has its own one-shot setup logic).
// Both update effectiveMode at the end so all runtime gates that key off
// effectiveMode (status bar, bunker availability, captive probe handler,
// reconnect logic) flip automatically.

// ── nostrconnect session ───────────────────────────────────────────────────
struct NostrConnectSession {
  char clientPubkey[65]=""; char secret[64]="";
  char relay1[128]=""; char relay2[128]=""; char relay3[128]="";
  bool active=false;
} ncSession;

// ── Camera pins (V1.1 — OV2640) ─────────────────────────────────────────────
// Rail EN, RES and PWDN are NOT on the ESP32 — they hang off a TCA9554 I2C
// expander on the MAIN bus (P0=CAM_RES active-low, P1=CAM_PWRDN active-high,
// P2=CAM_EN rail active-high). The camera SCCB is its OWN bus (SIOD=10/SIOC=11)
// with 2.8V pull-ups.
#define CAM_PIN_PWDN  -1   // via TCA9554 P1 (see cameraPowerUp)
#define CAM_PIN_RESET -1   // via TCA9554 P0 (see cameraPowerUp)
#define CAM_PIN_XCLK  21
#define CAM_PIN_SIOD  10
#define CAM_PIN_SIOC  11
#define CAM_PIN_D7    14   // Y9
#define CAM_PIN_D6    47   // Y8
#define CAM_PIN_D5    48   // Y7
#define CAM_PIN_D4    38   // Y6
#define CAM_PIN_D3    40   // Y5
#define CAM_PIN_D2    42   // Y4
#define CAM_PIN_D1    41   // Y3
#define CAM_PIN_D0    39   // Y2
#define CAM_PIN_VSYNC 12
#define CAM_PIN_HREF  13
#define CAM_PIN_PCLK  45
// V21.1 camera XCLK — TUNABLE. Sensor is OV2640 (same family that ran fine at
// 20MHz in v20), so 20MHz is the proven value — do NOT lower it without reason;
// the earlier "OV3660 / 16MHz" comments in this file were wrong. Kept as a
// single constant only so it can be swept on hardware if ever needed.
// 11c: the camera's one big internal-RAM need is its DMA buffer, which is
// CONFIG_CAMERA_DMA_BUFFER_SIZE_MAX (32 KB in the standard core; 16 KB in the
// light-sleep builds, which build the driver themselves since 10z). The gates
// were a fixed 34,000; in a Bluetooth life the largest block after Bluetooth
// stops came back at 32,756 and the scan was refused ("start blocked").
#ifdef CONFIG_CAMERA_DMA_BUFFER_SIZE_MAX
#define CAM_CONTIG_NEED ((size_t)CONFIG_CAMERA_DMA_BUFFER_SIZE_MAX + 1232)
#else
#define CAM_CONTIG_NEED ((size_t)34000)
#endif
#define CAM_LEDC_TIMER LEDC_TIMER_3   // 10w: unused by the S3 camera driver (LCD_CAM makes the sensor clock); kept off the piezo's timer 0
#define CAM_XCLK_HZ  20000000   // 20MHz: bumped from 8M to test capture margin at
                                // full pixel clock. WARNING (from this board's own
                                // history): 20M previously produced continuous
                                // EV-VSYNC-OVF -> cam_task stack overflow / ROM
                                // memcpy double-exception on fresh-boot scans. The
                                // suspected root is electrical (DVP PCLK signal
                                // integrity), which no XCLK value fully fixes. If
                                // fresh-boot scan tears/crashes at 20M, step DOWN:
                                // 20M -> 16M -> 12M -> 8M. The highest value that
                                // boots-and-scans cleanly is this board's ceiling.
                                // Higher XCLK = higher frame rate = more capture
                                // attempts/sec at the coordinator's QR — the win we
                                // want — but only if frames don't tear.
                                 // on this board (continuous EV-VSYNC-OVF -> cam_task
                                 // stack overflow at 20M). Lower pixel clock = more
                                 // timing margin on a marginal DVP path. If this runs
                                 // clean, the 20M flood was a signal-integrity issue.
                                 // Tradeoff: ~half the frame rate (slower animated-QR
                                 // capture). Restore to 20000000 if the board's DVP is good.

// V22.4: preview rotation for swapped OV2640 modules. Some OV2640 modules
// mount the sensor die rotated 180° relative to others, so the live preview
// comes out upside-down (decode is unaffected — quirc is rotation-tolerant).
// Set to 1 for the new modules (image was upside-down on the bench), 0 for the
// original. Only affects dispAirgapPreviewFrameRaw's on-screen draw, NOT the
// buffer quirc decodes — so flipping this never changes scan reliability.
// favilla board: preview came out rotated 180° both ways (motion in from top
// showed at bottom, in from right showed at left) -> set 0 to un-rotate.
#ifndef CAM_PREVIEW_ROT180
#define CAM_PREVIEW_ROT180 0
#endif

// V22.4: horizontal preview alignment for swapped OV2640 modules. The new
// modules' active image starts at a different column than the original, so
// a strip of one side wraps to the other. This shifts the sampled column to
// re-centre the image. Positive values shift the visible image one way,
// negative the other — start at 0, then nudge by ±10 until the wrapped strip
// disappears. Preview-only; never affects the decoded buffer.
// NOTE: the -64 value was tuned for CAM_PREVIEW_ROT180=1. With ROT180 now 0 the
// horizontal sampling direction is reversed, so that offset no longer applies —
// reset to 0 and re-tune on the bench for this orientation.
#ifndef CAM_PREVIEW_X_OFF
#define CAM_PREVIEW_X_OFF 0
#endif

// V22.x: VERTICAL preview alignment. The preview draws the sensor TRANSPOSED
// (display-y samples sensor COLUMNS, display-x samples sensor ROWS — the
// module is mounted rotated 90°). The display's 196 visible rows therefore
// sample a 196-wide band out of the sensor's 320 columns, and the original
// mapping pinned that band at one end (columns 22..217): its midpoint is
// column ~120, but the lens optical centre is column ~160 — so the true aim
// point rendered in the UPPER part of the preview. +40 centres the band
// (columns 62..257) for BOTH ROT180 settings. Nudge by ±10 from there if the
// enclosure window wants a slightly different framing; values that push the
// band past the 0/319 edge show a wrapped strip (same behaviour as X_OFF).
// Preview-only; never affects the buffer quirc decodes.
#ifndef CAM_PREVIEW_Y_OFF
#define CAM_PREVIEW_Y_OFF 40
#endif

// ── TCA9554 I2C GPIO expander ───────────────────────────────────────────────
// On the main I2C bus. Owns the camera power rail + reset/power-down lines.
//
// NEW BOARD REV ("favilla"): the camera now has a DEDICATED POWER RAIL gated by
// the expander (P2=CAM_EN). Previously (V1.1) the OV2640 was always powered and
// only its RES/PWDN pins were expander-controlled. RES/PWDN keep their pins;
// the rail switch is added on P2:
//   P0 = CAM_RES   (OV2640 RESETB, active-low : drive HIGH to run)
//   P1 = CAM_PWRDN (OV2640 PWDN,   active-high: drive LOW  to wake)
//   P2 = CAM_EN    (camera rail enable,        active-high: drive HIGH to power)
// Ordering matters: the rail must come up (and settle) BEFORE PWDN is released,
// and RESETB must be released AFTER the rail is stable and PWDN is low — see
// cameraPowerUp() for the full OV2640 sequence.
#define TCA9554_ADDR        0x20
#define TCA9554_REG_OUTPUT  0x01
#define TCA9554_REG_CONFIG  0x03   // 1=input (default), 0=output
#define TCA_P0_CAM_RES     (1 << 0)  // OV2640 RESETB: drive HIGH to run
#define TCA_P1_CAM_PWRDN   (1 << 1)  // OV2640 PWDN:   drive LOW  to wake
#define TCA_P2_CAM_EN      (1 << 2)  // camera rail:   drive HIGH to power on
// All three camera lines are outputs; everything else on the expander stays an
// input (config bit 1). Used everywhere we (re)assert the camera pin config.
#define TCA_CAM_OUTPUTS    (TCA_P0_CAM_RES | TCA_P1_CAM_PWRDN | TCA_P2_CAM_EN)
#define TCA_CFG_CAM_OUT    ((uint8_t)(0xFF & ~TCA_CAM_OUTPUTS))  // 0=output for P0/P1/P2

// ── Buffers ────────────────────────────────────────────────────────────────
// 2 Nov 2026: internal RAM ran out in WiFi modes on the FIDO build (5 KB free
// after network bring-up: phones could not connect, SCAN starved). Large
// buffers that hold nothing secret and are never touched by DMA or an ISR now
// live in PSRAM, taken once during start-up (PSRAM is on the heap before the
// global constructors run). Internal RAM is the fallback, so nothing breaks
// if PSRAM ever fails.
static void* psBootCalloc(size_t n){
  void* p = heap_caps_calloc(1, n, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT);
  return p ? p : calloc(1, n);
}
// 3 Nov 2026 (bench): internal RAM was down to 6-12 KB in NOSTR mode and the PWA
// (850 KB) and the 194-entry vault list timed out on send. EXT_RAM_BSS_ATTR is
// a no-op on this prebuilt core (CONFIG_SPIRAM_ALLOW_BSS_SEG_EXTERNAL_MEMORY is
// off), so the buffers marked with it were still in internal RAM. PS_ARRAY makes
// a reference to an array taken from PSRAM once, so name[i] and sizeof(name)
// work exactly as before. Same rule: nothing secret, no DMA, no ISR.
#define PS_ARRAY(T, name, N) T (&name)[N] = *reinterpret_cast<T(*)[N]>(psBootCalloc(sizeof(T) * (N)))
char* json_buf         = (char*)psBootCalloc(MAX_JSON_SIZE);
char* signedJsonBuffer = (char*)psBootCalloc(MAX_JSON_SIZE);
#define QRCODE_DATA_SZ 4096
static uint8_t* globalQrcodeData = nullptr;   // QR-gen module bitmap (PSRAM, ps_malloc at boot; CPU-only)
// V22: airgap Bitcoin UR (crypto-psbt) accumulator. ~10.6KB (frag buffer).
// V21_2: held via a PSRAM pointer, NOT a static global — as .bss it consumed
// ~10.6KB of scarce INTERNAL RAM in every mode at boot, which pushed NETWORK
// mode over its internal-RAM budget and aborted boot at configTime. It's only
// used in offline/airgap, so we ps_malloc it on airgap entry and free on exit;
// WiFi modes never pay for it. One airgap scan at a time.
static ur_decoder_t* urAirgapDec=nullptr;
static bool         urAirgapActive=false;
// Lazily allocate the UR decoder in PSRAM. Returns false if allocation fails.
static bool urAirgapEnsure(){
  if(!urAirgapDec){
    urAirgapDec=(ur_decoder_t*)ps_malloc(sizeof(ur_decoder_t));
    if(!urAirgapDec){ urAirgapDec=(ur_decoder_t*)malloc(sizeof(ur_decoder_t)); }
    if(urAirgapDec) ur_decoder_reset(urAirgapDec);
  }
  return urAirgapDec!=nullptr;
}
static void urAirgapFree(){
  if(urAirgapDec){ free(urAirgapDec); urAirgapDec=nullptr; }
  urAirgapActive=false;
}

// ── WebSocket globals ──────────────────────────────────────────────────────
WebSocketsClient webSocket, webSocket2;
bool wifiConnected=false, wsInitialised=false, ws2Initialised=false;

// ── Single-active-relay failover (memory fix) ──────────────────────────────
// Holding TWO simultaneous TLS WebSocket sessions in bunker mode consumed
// ~88KB of internal SRAM, leaving only ~27KB free — too little for the SE051
// transport to allocate its buffers during a decrypt, which produced
// `SW ReadNostr = 6D00` failures and eventual out-of-memory reboots. We now
// hold ONE TLS session at a time and fail over to the next relay when the
// active one drops. webSocket2 is left defined (many refs) but is NOT brought
// up in bunker mode anymore.
// ── Relay list — ONE list, used everywhere ────────────────────────────────
// Previously there were FOUR independent relay lists (the r1/r2 outbox
// toggles, a hardcoded BUNKER_RELAY_POOL, hardcoded relay= params in the
// bunker:// URI builders, and CIPHER_SHARE_RELAYS). Adding a relay to one did
// nothing for the others, which is exactly how our own relay ended up being
// listened on but never advertised. This is now the single source of truth:
// the device listens on the ENABLED entries, advertises the ENABLED entries in
// the bunker URI, and publishes through the ENABLED entries. Editable from the
// PWA, toggleable on the device.
#define RELAY_MAX      8
#define RELAY_URL_MAX  64
struct RelayEntry {
  char url[RELAY_URL_MAX];   // host only, no scheme — "relay.favillakey.io"
  bool enabled;
};
RelayEntry relayList[RELAY_MAX];
int        relayCount = 0;

// Seed order matters: ours first (we control it, it has no purge policy), then
// public relays by observed reliability as failover. Bunker mode holds ONE TLS
// session at a time, so this is a failover order, never parallel.
static const char* RELAY_DEFAULTS[] = {
  "relay.favillakey.io", "relay.primal.net", "nos.lol", "relay.nsec.app"
};
static const int RELAY_DEFAULTS_N = 4;

// Enabled entries only, in list order. idx is an index into the ENABLED subset.
const char* relayEnabledAt(int idx){
  int seen = 0;
  for(int i=0;i<relayCount;i++){
    if(!relayList[i].enabled) continue;
    if(seen == idx) return relayList[i].url;
    seen++;
  }
  return nullptr;
}
int relayEnabledCount(){
  int n=0;
  for(int i=0;i<relayCount;i++) if(relayList[i].enabled) n++;
  return n;
}
int activeRelayIdx = 0;               // index into the active pool
unsigned long _relayConnectedAt = 0;  // millis when the active relay last connected
int _relayReconnectFails = 0;         // consecutive failed (re)connects on the active relay
// After this many consecutive reconnect failures on the active relay, fail
// over to the next relay in the pool (skipping circuit-broken ones).
const int RELAY_FAILOVER_AFTER = 2;
// Heap floors. NIP46_HARD_FLOOR is crash-prevention: below it we refuse ANY
// NIP-46 request (incl. signs) because the transport decrypt itself would fail
// / OOM. NIP46_HEAP_FLOOR is the higher, decrypt-CLASS budget: below it we shed
// decrypt floods (but still allow rare, important sign_event/connect).
//
// The old ~27KB crash baseline / 32000 floor came from parsing full events into
// INTERNAL-heap JsonDocuments (a kind:3 list hit 100KB+ internal). Those docs
// now allocate from PSRAM (see PsramJsonAllocator), so processing a request no
// longer needs a large internal reserve — the remaining internal use is the
// bounded NIP-44 decrypt (~2KB typical, ~13KB worst-case for a 4KB event) plus
// response assembly. The floor can therefore come down, which is what lets the
// bunker sign again when a live relay TLS session leaves only ~28KB internal
// free. 24000 keeps a comfortable margin over the (now much lower) real need.
// BENCH-CHECK: sign a large kind:3 follow list over the bunker and confirm no OOM.
// 20 Oct 2026: 24000 -> 16000. Two things moved since 24000 was set: mbedTLS
// now allocates in PSRAM (CONFIG_MBEDTLS_EXTERNAL_MEM_ALLOC), so the TLS
// session no longer takes internal RAM mid-request, and processNip46Request
// runs under Nip46PsramScope (every malloc >= 256 B goes to PSRAM), so the
// envelope decrypt + reply cost ~1-2 KB internal. Bench 20 Oct: with the LAN
// PWA signing at the same time, steady internal free was 29-31 KB and the
// 24000 floor refused 6 of 13 Nostrich DMs at free=21-23 KB.
const uint32_t NIP46_HARD_FLOOR = 16000;   // was 24000 (pre mbedTLS-in-PSRAM)
const uint32_t NIP46_HEAP_FLOOR = 32000;   // was 40000
// True when at least one relay has acknowledged our REQ subscription with
// EOSE — this is the real "ready to handle bunker traffic" signal. Just
// having TCP up (wsInitialised) means the connection's open but the relay
// hasn't necessarily processed our subscribe yet. Showing "Bunker active"
// before this is misleading, and during the gap the second relay's TLS
// handshake jams the UI.
bool signerEoseReceived=false;
// millis() of last successful response to any NIP-46 client request.
// Used by the B indicator: green when we've talked to a client in the
// last 30s (truly ready / actively connected), amber otherwise. Captures
// both first-time connects AND silent reconnects (when a returning client
// skips 'connect' and just sends get_public_key to verify the bunker is
// alive). Goes back to amber if the device has been silent for 30s+,
// which is itself a useful "something's wrong" signal.
unsigned long bunkerLastClientResponseMs = 0;

// Activity counters for the bunker status screen. Reset on activate.
volatile uint32_t bunkerRequestCount = 0;  // every NIP-46 request received
volatile uint32_t bunkerSignedCount = 0;   // sign_event approvals (not auth)
int bunkerStatusSel = 0;                    // bunker status screen: 0 = Phone QR card, 1 = App QR card
// Transient banner shown on the bunker status screen when a remote pairing
// event occurs (slave minted, slave revoked) — so a physical holder always SEES
// remote control-plane actions. Set by the NIP-46 handlers; rendered + expired
// by dispBunkerStatus(). Not a PIN overlay, just an informational strip.
char     bunkerBannerText[40] = {0};
volatile unsigned long bunkerBannerUntilMs = 0;
void bunkerSetBanner(const char* msg){
  strncpy(bunkerBannerText, msg, sizeof(bunkerBannerText)-1);
  bunkerBannerText[sizeof(bunkerBannerText)-1]=0;
  bunkerBannerUntilMs = millis() + 4000;   // visible ~4s
}
char currentIP[20] = {0}; // our own IP string — only set when we know it's valid
char currentMdnsName[32] = {0}; // registered mDNS hostname
bool reconnecting = false; // true while cycling through saved networks after dropout
bool wsStarted=false, bootstrapDone=false;
int32_t nwcBalanceSats=-1; // -1 = unknown, >=0 = fetched
unsigned long nwcBalanceLastFetch=0;

// ── Outbox ─────────────────────────────────────────────────────────────────
#define OUTBOX_SIZE 4
// Was 1024, which SILENTLY TRUNCATED any larger relay message and sent broken
// JSON — strfry answered "bad msg: ...:1:1024: invalid unescaped character" and
// the KEY retried forever. A measured nip44_decrypt response is ~1456 bytes and
// signed events run larger, so 1024 was never enough for the DM path.
// 4 slots x 3072 = 12KB of static RAM, against ~107KB free at idle.
#define OUTBOX_MSG_MAX 3072          // baseline slot size (most relay messages)
#define OUTBOX_MSG_HARD_MAX (NIP46_BIG_SZ + 4096)   // a slot grows (PSRAM) up to this for a big signed event reply
#define OUTBOX_ID_MAX 72
struct OutboxEntry {
  // msg lives in PSRAM, not internal RAM. At 3072 bytes x 4 slots this would
  // be 12KB of BSS, and internal contiguous RAM is the scarce resource on this
  // board — the camera DMA needs ~34KB contiguous and measures 31-49KB free.
  // These are plain strings handed to sendTXT, never DMA targets, so PSRAM is
  // the correct home and costs nothing internal. Allocated once in
  // outboxInit(); falls back to internal RAM only if PSRAM is unavailable.
  char* msg = nullptr;
  size_t cap = 0;              // bytes allocated behind msg (7 Oct 2026: slots grow for big NIP-46 replies)
  char eventId[OUTBOX_ID_MAX];
  bool ws1ok=false, ws2ok=false, active=false;
  uint8_t retries=0;
  unsigned long lastSent=0;
  OutboxEntry(){ eventId[0]=0; }
};
OutboxEntry outbox[OUTBOX_SIZE];

// Must run once before any outboxAdd(). Safe to call twice.
void outboxInit(){
  for(int i=0;i<OUTBOX_SIZE;i++){
    if(outbox[i].msg) continue;
    outbox[i].msg = (char*)ps_malloc(OUTBOX_MSG_MAX);
    if(!outbox[i].msg) outbox[i].msg = (char*)malloc(OUTBOX_MSG_MAX);  // last resort
    if(outbox[i].msg){ outbox[i].msg[0] = 0; outbox[i].cap = OUTBOX_MSG_MAX; }
  }
  LOG_BOOT("[OUTBOX] %d slots x %u bytes\n", OUTBOX_SIZE, (unsigned)OUTBOX_MSG_MAX);
}
// Make slot i able to hold `need` bytes. Grows in PSRAM only (a big reply
// must never carve internal RAM); shrinks back to the baseline when a slot is
// reused for a small message so one 100 KB follow doesn't pin 100 KB forever.
static bool outboxFit(int i, size_t need){
  if(need <= OUTBOX_MSG_MAX){
    if(outbox[i].cap > OUTBOX_MSG_MAX){
      char* p = (char*)ps_malloc(OUTBOX_MSG_MAX);
      if(p){ free(outbox[i].msg); outbox[i].msg = p; outbox[i].cap = OUTBOX_MSG_MAX; }
    }
    return outbox[i].msg != nullptr;
  }
  if(outbox[i].cap >= need) return true;
  char* p = (char*)ps_malloc(need);
  if(!p){ LOG_NIP46("[OUTBOX] PSRAM alloc %u failed — message dropped\n", (unsigned)need); return false; }
  free(outbox[i].msg); outbox[i].msg = p; outbox[i].cap = need; p[0] = 0;
  return true;
}

void outboxAdd(const String& relay_msg, const String& event_id, bool skipRelay1 = false, bool skipRelay2 = false) {
  // NEVER queue a message we cannot hold whole. strncpy would cut it mid-token
  // and we would publish invalid JSON, which the relay rejects and we retry —
  // a silent loop that looks like a network fault. Fail loudly instead.
  outboxInit();   // idempotent; guarantees the buffers exist
  if(relay_msg.length() >= OUTBOX_MSG_HARD_MAX){
    LOG_NIP46("[OUTBOX] DROPPED oversized msg: %u bytes (max %u) id=%.16s\n",
              (unsigned)relay_msg.length(), (unsigned)OUTBOX_MSG_HARD_MAX, event_id.c_str());
    return;
  }
  // Find empty slot
  for(int i=0;i<OUTBOX_SIZE;i++){
    if(!outbox[i].active){
      if(!outboxFit(i, relay_msg.length()+1)) return;   // PSRAM exhausted — logged
      strlcpy(outbox[i].msg, relay_msg.c_str(), outbox[i].cap);
      strncpy(outbox[i].eventId, event_id.c_str(), OUTBOX_ID_MAX-1);
      outbox[i].eventId[OUTBOX_ID_MAX-1]=0;
      // Pre-mark "ok" for relays we shouldn't retry to. This is how
      // the outbox respects per-event relay routing — e.g. kind 10002
      // shouldn't go to nsec.app which only accepts 24133/24135.
      outbox[i].ws1ok=skipRelay1; outbox[i].ws2ok=skipRelay2;
      outbox[i].active=true; outbox[i].retries=0;
      outbox[i].lastSent=millis(); return;
    }
  }
  // No empty slot — shift and overwrite oldest. NOTE: entries own a heap
  // pointer now, so a plain struct copy would alias two slots onto the same
  // buffer and leak the other. Swap the pointers as we shift.
  for(int i=0;i<OUTBOX_SIZE-1;i++){
    char* keep = outbox[i].msg; size_t keepCap = outbox[i].cap;
    outbox[i] = outbox[i+1];      // copies the scalar fields (and the pointer + cap)
    outbox[i+1].msg = keep; outbox[i+1].cap = keepCap;   // hand the older buffer forward for reuse
  }
  if(!outboxFit(OUTBOX_SIZE-1, relay_msg.length()+1)) return;
  strlcpy(outbox[OUTBOX_SIZE-1].msg, relay_msg.c_str(), outbox[OUTBOX_SIZE-1].cap);
  strncpy(outbox[OUTBOX_SIZE-1].eventId, event_id.c_str(), OUTBOX_ID_MAX-1);
  outbox[OUTBOX_SIZE-1].eventId[OUTBOX_ID_MAX-1]=0;
  outbox[OUTBOX_SIZE-1].ws1ok=skipRelay1; outbox[OUTBOX_SIZE-1].ws2ok=skipRelay2;
  outbox[OUTBOX_SIZE-1].active=true; outbox[OUTBOX_SIZE-1].retries=0;
  outbox[OUTBOX_SIZE-1].lastSent=millis();
}
void outboxConfirm(const String& event_id, bool isWS2) {
  for(int i=0;i<OUTBOX_SIZE;i++){
    if(outbox[i].active && strcmp(outbox[i].eventId, event_id.c_str())==0){
      if(isWS2) outbox[i].ws2ok=true; else outbox[i].ws1ok=true;
      if(outbox[i].ws1ok||outbox[i].ws2ok) outbox[i].active=false;
      return;
    }
  }
}

// ── Relay state ────────────────────────────────────────────────────────────
// Retained only so any stray reference still compiles — the relay list above
// is the source of truth. Do not add new uses.
bool relay1Enabled=true, relay2Enabled=true;
int relaySelIdx=0;
Preferences relayPrefs;
// NVS layout: "n" = count, "u0".."u7" = host strings, "en" = enabled bitmask.
// A bitmask rather than per-entry bools keeps this to one extra key and makes
// the whole enabled-set a single atomic write.
void saveRelayPrefs(){
  relayPrefs.begin("relays",false);
  relayPrefs.putInt("n", relayCount);
  uint32_t mask = 0;
  char key[4];
  for(int i=0;i<relayCount;i++){
    snprintf(key,sizeof(key),"u%d",i);
    relayPrefs.putString(key, relayList[i].url);
    if(relayList[i].enabled) mask |= (1UL<<i);
  }
  relayPrefs.putUInt("en", mask);
  relayPrefs.end();
  LOG_BOOT("[RELAY] saved %d entries, mask=0x%02X\n", relayCount, (unsigned)mask);
}

void relaySeedDefaults(){
  relayCount = 0;
  for(int i=0;i<RELAY_DEFAULTS_N && i<RELAY_MAX;i++){
    strncpy(relayList[i].url, RELAY_DEFAULTS[i], RELAY_URL_MAX-1);
    relayList[i].url[RELAY_URL_MAX-1] = 0;
    relayList[i].enabled = true;
    relayCount++;
  }
}

void loadRelayPrefs(){
  relayPrefs.begin("relays",true);
  int n = relayPrefs.getInt("n", -1);
  if(n <= 0){
    // First boot on this scheme. Seed defaults, then carry over the OLD r1/r2
    // booleans if they exist so an upgrading device keeps whatever the user
    // had toggled rather than silently re-enabling everything.
    bool oldR1 = relayPrefs.getBool("r1", true);
    bool oldR2 = relayPrefs.getBool("r2", true);
    relayPrefs.end();
    relaySeedDefaults();
    if(relayCount > 0) relayList[0].enabled = oldR1;
    if(relayCount > 1) relayList[1].enabled = oldR2;
    saveRelayPrefs();
    LOG_BOOT("[RELAY] seeded %d defaults (migrated r1=%d r2=%d)\n",
             relayCount, oldR1, oldR2);
    return;
  }
  if(n > RELAY_MAX) n = RELAY_MAX;
  uint32_t mask = relayPrefs.getUInt("en", 0xFFFFFFFFUL);
  char key[4];
  relayCount = 0;
  for(int i=0;i<n;i++){
    snprintf(key,sizeof(key),"u%d",i);
    String u = relayPrefs.getString(key, "");
    if(u.length() == 0) continue;
    strncpy(relayList[relayCount].url, u.c_str(), RELAY_URL_MAX-1);
    relayList[relayCount].url[RELAY_URL_MAX-1] = 0;
    relayList[relayCount].enabled = (mask >> i) & 1UL;
    relayCount++;
  }
  relayPrefs.end();
  // Never leave the device with nothing to talk to.
  if(relayCount == 0){ relaySeedDefaults(); saveRelayPrefs(); }
  LOG_BOOT("[RELAY] loaded %d entries, %d enabled\n", relayCount, relayEnabledCount());
}
void outboxTick() {
  if(!wsInitialised&&!ws2Initialised) return;
  unsigned long now=millis();
  for(int i=0;i<OUTBOX_SIZE;i++){
    if(!outbox[i].active) continue;
    if(now-outbox[i].lastSent<5000) continue;
    if(outbox[i].retries>=5){outbox[i].active=false;continue;}
    // ws1 is the active bunker relay, ws2 the share/publish link. Both are
    // drawn from the enabled list now, so there is no per-socket toggle — if
    // nothing is enabled there is nowhere to send and we mark done rather
    // than retrying forever against a list the user emptied.
    bool anyEnabled = relayEnabledCount() > 0;
    if(!outbox[i].ws1ok && wsInitialised && anyEnabled) webSocket.sendTXT(outbox[i].msg);
    else if(!outbox[i].ws1ok && !anyEnabled) outbox[i].ws1ok=true;
    if(!outbox[i].ws2ok && ws2Initialised && anyEnabled) webSocket2.sendTXT(outbox[i].msg);
    else if(!outbox[i].ws2ok && !anyEnabled) outbox[i].ws2ok=true;
    outbox[i].lastSent=now; outbox[i].retries++;
  }
}

// ── Buttons ────────────────────────────────────────────────────────────────
// INPUT GATE (25 Sep 2026). The poll task latches a press the instant the
// button goes down, so a press landing while a screen is changing sits in
// `pending` and the NEXT screen consumes it ("spam ENTER on the menu and the
// page you land on also gets an ENTER"). clearButtonPending() only empties
// the queue at the moment it runs. So every screen change also opens a short
// gate: any press whose down-edge is earlier than g_inputGateUntil is dropped
// inside isPressed() itself, and no screen has to remember to do it.
static volatile unsigned long g_inputGateUntil = 0;
#define INPUT_GATE_MS 250
// And a press-following gate: once a press is DELIVERED, press-edges for the
// next INPUT_REPEAT_MS are dropped device-wide. Screens that change without
// calling clear/drain (the onboarding cards) are covered by this one, because
// the press that caused the change also opens the gate. 6 presses/s still
// get through, which is faster than anyone taps a menu on purpose; holds are
// untouched (they read pressStart, not pending).
#define INPUT_REPEAT_MS 160
static inline void inputDelivered(){ unsigned long t = millis() + INPUT_REPEAT_MS; if(t > g_inputGateUntil) g_inputGateUntil = t; }
struct Button;
static void backHoldTick(Button* b);   // global hold-BACK-2s -> sleep (defined after the button instances)
// 31 Oct 2026: the watchdog restarts the KEY when the main loop is STUCK, not
// when it is WAITING. Every screen that waits for the owner polls the buttons,
// so a button poll on the main loop counts as alive. A loop blocked on a lock,
// the I2C bus or a peripheral never gets here, and the watchdog fires
// (the 31 Oct freeze: blocked on the I2C lock, dark until a power cycle).
static TaskHandle_t g_wdtLoopTask = nullptr;   // set where loopTask joins the watchdog (setup)
static inline void wdtFeedIfLoop(){
  if(g_wdtLoopTask && xTaskGetCurrentTaskHandle() == g_wdtLoopTask) esp_task_wdt_reset();   // other tasks are not subscribed
}
struct Button {
  int pin;
  int lastRaw=HIGH, stable=HIGH;
  unsigned long lastDB=0, pressStart=0;
  unsigned long pressEdge=0;   // set ONLY at the down-edge; resetHold() moves pressStart, never this
  bool pending=false;
  // ── Press bleed-through guard ────────────────────────────────────────────
  // A single physical press was firing on TWO screens: it triggers the
  // transition, and the button is still physically DOWN when the next screen
  // starts, so its release bounce lands there as a fresh press. Classic case:
  // NEXT opens the camera and the same press immediately closes it.
  // clearButtonPending() alone can't fix that — it clears the flag at the
  // moment of transition, before the offending edge even exists.
  //
  // So a button must be SEEN RELEASED before it can fire again. armDisarm()
  // is called on every screen change; poll() re-arms only when the pin reads
  // HIGH. A press that arrives while disarmed is discarded, not queued —
  // queuing it would just delay the same bug by one screen.
  bool armed=true;
  // disarm() clears any queued press but must NOT un-arm a button: the old
  // version set armed=(stable==HIGH), so a disarm() that landed while the
  // button was still physically DOWN (ENTER causes most screen changes, so it
  // is usually still held at the transition) forced armed=false — and if the
  // release edge was then missed, the button stayed disarmed and swallowed
  // every later press (the intermittent-ENTER/BTN1 bug; pull-up + GPIO4 fine).
  // Now disarm() only drops pending; re-arming is owned solely by poll() on a
  // confirmed release, which a transition cannot undo.
  void disarm(){ pending=false; }
  void poll() {
    wdtFeedIfLoop();
    int r=digitalRead(pin);
    if(r!=lastRaw){lastDB=millis();lastRaw=r;}
    if((millis()-lastDB)>20){
      if(r==LOW&&stable==HIGH){stable=LOW;pressStart=millis();pressEdge=pressStart;pending=armed;}
      if(r==HIGH&&stable==LOW){ stable=HIGH; armed=true; }   // released → armed
    }
    // Watchdog self-heal: pin read a clean released HIGH for >200ms forces
    // armed, so a missed release edge or stray disarm() can never leave a
    // button permanently dead. Double-fire guard intact (a press while
    // stable==LOW cannot re-fire).
    if(stable==HIGH && (millis()-lastDB)>200) armed=true;
    backHoldTick(this);
  }
  bool gated(){ wdtFeedIfLoop(); backHoldTick(nullptr); if(pending && pressEdge < g_inputGateUntil){ pending=false; return true; } return false; }   // stale press: drop it
  bool isPressed(){if(gated())return false;if(pending){pending=false;inputDelivered();buzzerClick();return true;}return false;}
  // Race-proof gate for high-stakes screens (e.g. SIGN confirm): only honor a
  // press that actually occurred AFTER the screen appeared. A press latched
  // during a prior blocking op (scan/sign) has an older pressStart, so it can
  // never auto-trigger the action — regardless of background-poll timing.
  bool isPressedFresh(unsigned long since){
    if(gated()) return false;
    if(pending && pressStart>=since){ pending=false; inputDelivered(); buzzerClick(); return true; }
    return false;
  }
  // Same as isPressed but skips the auto-click haptic. Use for high-stakes
  // actions where the action's own feedback (success/fail) is the canonical
  // signal — chaining click+OK feels stuttery.
  bool isPressedSilent(){if(gated())return false;if(pending){pending=false;inputDelivered();return true;}return false;}
  void resetHold(){pressStart=millis();}
  float holdProgress(unsigned long threshold=2500){
    if(stable!=LOW) return 0.0f;
    float p=(float)(millis()-pressStart)/(float)threshold;
    return p>1.0f?1.0f:p;
  }
};
// btn1 = NEXT/scroll-down engine (physical BTN3/IO1)
// btn2 = CONFIRM/enter engine    (physical BTN1/IO4)
// btn3 = SCROLL UP               (physical BTN4/IO2)  — V21.1
// btn4 = BACK/DECLINE            (physical BTN2/IO9)  — V21.1
Button btn1={BTN_ENGINE_NEXT_GPIO}, btn2={BTN_ENGINE_CONFIRM_GPIO};
Button btn3={BTN_ENGINE_UP_GPIO},   btn4={BTN_ENGINE_BACK_GPIO};
static float holdSince(Button& b, unsigned long since, unsigned long ms){
  if(b.stable != LOW || b.pressStart < since) return 0.0f;
  return b.holdProgress(ms);
}

// ── Global hold-BACK-for-2s sleep (7 Oct 2026) ──────────────────────────────
// Holding BACK on ANY screen — onboarding, PIN, Bitcoin, menus — for 2 s shows
// the ember sleep page and sleeps the device (goSleep wipes keys first).
// Hooked into Button::poll() because every blocking loop in the firmware polls
// its buttons; the background poll task only tracks the hold (it must never
// run goSleep itself). Not a chord: BACK held with ENTER (verify / CIPHER exit)
// or either scroll button is ignored for the whole hold. The 2 s counts from the
// physical press, so holding BACK through a page that BACK closes still sleeps.
static bool g_backHoldTaint = false;
static void backHoldTick(Button* b){
  if(b && b->pin != BTN_ENGINE_BACK_GPIO) return;
  if(btn4.stable != LOW){ g_backHoldTaint = false; return; }
  if(btn2.stable == LOW || btn1.stable == LOW || btn3.stable == LOW){ g_backHoldTaint = true; return; }
  if(g_backHoldTaint || dimActive) return;
  if(b && xTaskGetCurrentTaskHandle() == btnPollTask) return;   // main context only
  if(!b && xTaskGetCurrentTaskHandle() == btnPollTask) return;
  if(g_prePinTaskH && xTaskGetCurrentTaskHandle() == g_prePinTaskH) return;   // 11w: the real pad owns the sleep hold
  if(millis() - btn4.pressEdge < 2000) return;
  g_backHoldTaint = true;                                       // one shot
  btn4.pending = false;
  LOG_BOOT("[SLEEP] BACK held 2 s -> sleep\n");
  goSleep(false);                                               // ember sleep page, then deep sleep
}

// ── Global sleep gesture ───────────────────────────────────────────────────
// Hold BOTH scroll buttons (btn1 + btn3) together for 1.2 s to sleep, from any
// screen (30 Sep 2026: was 2.5 s — too long, people let go thinking it had
// not taken; now paired with the 1 s hold-to-wake). Tracks when the pair first
// became held simultaneously (their individual pressStart differ, so we need
// our own timer). The animation IS the backlight: the screen fades smoothly to
// black over the hold; at 0 it sleeps. Releasing early snaps the backlight
// back to full. A single scroll press never triggers it (fade only begins
// after ~200 ms of holding both).
// Returns true if it fired (goSleep doesn't return until wake). Forward-declared
// up near tickStatusBarInMenu so the menu loops can call it.
static unsigned long g_sleepGestureStart = 0;
static bool          g_sleepGestureDimming = false;
bool tickSleepGesture(){
  const unsigned long SLEEP_HOLD_MS = 1200;
  bool both = (btn1.stable == LOW && btn3.stable == LOW);
  if(both){
    // (The btnPollTask already swallows btn1/btn3 press edges while both are
    // held, so the menu underneath never registers a scroll bounce.)
    if(g_sleepGestureStart == 0) g_sleepGestureStart = millis();
    unsigned long held = millis() - g_sleepGestureStart;
    float pct = (float)held / (float)SLEEP_HOLD_MS;
    if(pct > 1.0f) pct = 1.0f;
    // Animation IS the backlight: fade the screen toward black as the hold
    // progresses. Start the fade only after ~200ms so a quick accidental
    // double-scroll-press doesn't visibly flicker the brightness.
    if(held > 200){
      int duty = (int)(blTargetDuty() * (1.0f - pct));   // 1023 → 0 over the hold
      if(duty < 0) duty = 0;
      ledcWrite(TFT_BL_PIN, duty);
      g_sleepGestureDimming = true;
    }
    if(held >= SLEEP_HOLD_MS){
      g_sleepGestureStart = 0; g_sleepGestureDimming = false;
      ledcWrite(TFT_BL_PIN, 0);                     // ensure fully dark
      btn1.resetHold(); btn3.resetHold();
      goSleep(true);                                // already faded — skip moon
      return true;
    }
  } else {
    // Released before sleep — snap the backlight back to full and reset.
    if(g_sleepGestureStart != 0){
      g_sleepGestureStart = 0;
      if(g_sleepGestureDimming){ ledcWrite(TFT_BL_PIN, blTargetDuty()); g_sleepGestureDimming = false; }
    }
  }
  return false;
}

// Drain any pending button events after a menu transition. Without this,
// holding BTN2 a fraction too long when navigating between menus can
// cause the press to leak into the new menu's input loop and register
// as a spurious tap — e.g. cursor jumps from "Show URL" to "Deactivate"
// when entering the bunker mini-menu.
//
// Waits up to maxWaitMs for both buttons to be observed HIGH continuously
// for stableMs, then drains pending flags. If user is still holding a
// button at the end of the wait window, drains anyway and returns —
// better to lose one held press than to hang the UI.
//
// Call after returning from any submenu, or after any state-machine
// transition where the user might still be touching a button.
// V21_2: lightweight, non-blocking pending-press clear. Discards any latched
// 'pending' edge on all four buttons WITHOUT waiting for settle or firing the
// click haptic (unlike drainButtonsAfterTransition). Call on every state
// transition so a press queued/leaked during the change isn't consumed as a
// spurious tap by the next screen. Does NOT touch 'stable', so a button the
// user is genuinely still holding will re-register a fresh edge only on its
// next HIGH->LOW, not from the stale latch.
void clearButtonPending(){
  // Disarm rather than merely clearing: a button still held from the previous
  // screen must be released before it counts again. Any button already up is
  // left armed, so a genuine new press on the next screen is never swallowed.
  btn1.disarm(); btn2.disarm(); btn3.disarm(); btn4.disarm();
  g_inputGateUntil = millis() + INPUT_GATE_MS;   // and presses arriving during the paint are dropped too
}


// Held ENTER+BACK for 3s inside the game returns to the real device. Chosen
// because no game reason exists to hold both, the duration makes an accidental
// trigger essentially impossible, and it does not collide with the sleep chord
// (btn1+btn3). Deliberately NOT surfaced anywhere in the game UI — a visible
// "Exit" would defeat the entire point.
#define CIPHER_EXIT_HOLD_MS 3000
unsigned long cipherExitHoldStart = 0;
bool cipherExitRequested = false;
// Call from the game's input tick. Returns true when the chord completes.
bool cipherCheckExitChord(){
  if(btn2.stable==LOW && btn4.stable==LOW){
    if(cipherExitHoldStart==0) cipherExitHoldStart = millis();
    if(millis()-cipherExitHoldStart >= CIPHER_EXIT_HOLD_MS){
      cipherExitHoldStart = 0;
      cipherExitRequested = true;
      LOG_BOOT("[CIPHER] exit chord held - leaving cover mode\n");
      return true;
    }
  } else {
    cipherExitHoldStart = 0;   // must be a continuous hold
  }
  return false;
}


// ── Vertical pill selector ──────────────────────────────────────────────────
// Reusable single-choice menu matching the onboarding/verify UX:
//   • scroll UP (btn3) / DOWN (btn1) move the highlight (wraps)
//   • ENTER (btn2) chooses the highlighted pill
//   • BACK (btn4) returns -1 (caller treats as "go back")
// The highlighted pill is filled in `accent`; the rest are ghost outlines.
// Renders title (with accent dot via uiHeader) + optional subtitle, then up to
// 4 pills evenly placed in the content band. Returns the chosen index, or -1.
int uiPillSelect(const char* title, const char* subtitle, uint16_t accent,
                 const char* const* labels, int count, bool allowBack=true){
  if(count<1) return -1;
  if(count>4) count=4;
  int sel=0;
  clearButtonPending();   // don't let a leaked press auto-pick
  // Vertical layout: pills sized/spaced to fill the band under the subtitle.
  const int top = subtitle ? 84 : 70;
  const int avail = 210 - top;            // up to status bar zone
  const int gap = 12;
  int ph = (avail - gap*(count-1)) / count;
  if(ph>44) ph=44; if(ph<32) ph=32;
  while(true){
    spr.fillSprite(C_BG);
    uiHeader(title, accent);
    if(subtitle){
      fSet(F_BODY); spr.setTextColor(C_MUTED);
      fDrawCentre(subtitle,120,52); fEnd();
    }
    int totalH = ph*count + gap*(count-1);
    int y0 = top + ( (210-top) - totalH )/2;
    for(int i=0;i<count;i++){
      int py = y0 + i*(ph+gap);
      if(i==sel) uiPill(16,py,208,ph,accent,C_BG,labels[i]);
      else       uiPill(16,py,208,ph,C_BG,C_DIM,labels[i],true,C_BORDER2);
    }
    uiFooter(); dispPush();
    bool acted=false;
    while(!acted){
      btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
      esp_task_wdt_reset();
      if(btn3.isPressed()){ sel=(sel-1+count)%count; acted=true; }   // up
      else if(btn1.isPressed()){ sel=(sel+1)%count; acted=true; }    // down
      else if(btn2.isPressed()){ return sel; }                       // enter
      else if(allowBack && btn4.isPressed()){ return -1; }           // back
      delay(20);
    }
  }
}

void drainButtonsAfterTransition(unsigned long stableMs = 80,
                                 unsigned long maxWaitMs = 400){
  unsigned long start = millis();
  unsigned long allHighSince = 0;
  while(millis() - start < maxWaitMs){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();   // V21.1 all four
    if(btn1.stable == HIGH && btn2.stable == HIGH &&
       btn3.stable == HIGH && btn4.stable == HIGH){
      if(allHighSince == 0) allHighSince = millis();
      if(millis() - allHighSince >= stableMs) break;
    } else {
      allHighSince = 0;
    }
    delay(5);
  }
  // Drain whatever's pending — leaked bounces from entry, or the genuine
  // press that brought us here, or both. None of it should be treated
  // as fresh input by the next caller of isPressed().
  // Consume what is queued WITHOUT the click a real press makes, and open the
  // gate so anything that lands during the new screen's paint is dropped too.
  btn1.disarm(); btn2.disarm(); btn3.disarm(); btn4.disarm();
  g_inputGateUntil = millis() + INPUT_GATE_MS;
}

// ── Verify-device chord on the PIN screens (7 Oct 2026) ─────────────────────
// ENTER + BACK held together (the two non-scroll buttons; the scroll pair is
// the sleep chord) opens the attestation flow BEFORE the PIN is typed: scan the
// verify page's challenge, the SE signs it, the reply QR is shown. The point is
// to prove the device is genuine before trusting it with a PIN.
// Wired into: the NOSTR unlock/PIN-setup screen (ST_PIN_ENTRY) and the three
// BTC PIN loops. It signs nothing of the user's: the attestation key is the
// device identity, challenges are domain-separated, and no PIN or seed is read.
void runAttestFlow();                    // defined in attest_flow.inc (included far below)
static unsigned long g_vChordT0 = 0;
// Call once per pass of a PIN-entry loop BEFORE the normal button handling.
// true = the chord ran and returned; the caller redraws its screen and skips
// the rest of this pass.
static bool pinVerifyChord(){
  const unsigned long HOLD_MS = 250;     // deliberate, not a fumbled double press
  if(btn2.stable == LOW && btn4.stable == LOW){
    btn2.pending = false; btn4.pending = false;       // neither press is a digit action
    if(!g_vChordT0) g_vChordT0 = millis();
    if(millis() - g_vChordT0 < HOLD_MS) return false;
    g_vChordT0 = 0;
    unsigned long w = millis();          // wait for release so the lifting fingers can't act as ENTER/BACK
    while((btn2.stable == LOW || btn4.stable == LOW) && millis() - w < 3000){
      btn2.poll(); btn4.poll(); esp_task_wdt_reset(); delay(10);
    }
    clearButtonPending();
    LOG_BOOT("[PIN] verify-device chord -> attestation flow\n");
    runAttestFlow();
    clearButtonPending();
    drainButtonsAfterTransition();
    return true;
  }
  g_vChordT0 = 0;
  return false;
}
// A lone ENTER/BACK press is held back for 70 ms so a slightly-early finger of
// the chord cannot trigger a digit action first. true = defer this pass.
static bool pinChordDefer(){
  const unsigned long WIN = 70;
  if(btn2.pending && btn4.stable == HIGH && millis() - btn2.pressEdge < WIN) return true;
  if(btn4.pending && btn2.stable == HIGH && millis() - btn4.pressEdge < WIN) return true;
  return false;
}

// btnPollTaskFn body — start function and forward decl up near bgSpinner.
static void btnPollTaskFn(void* arg){
  for(;;){
    btn1.poll();
    btn2.poll();
    btn3.poll();   // SCROLL UP
    btn4.poll();   // BACK/DECLINE
    // Sleep-chord guard: when BOTH scroll buttons are held (the hold-to-sleep
    // gesture), swallow their press edges here — in the 5ms poll task, which
    // runs far faster than any menu loop — so neither leaks to the menu as a
    // scroll. This kills the selection "bounce" at the start of the gesture
    // even when the two presses land a poll-cycle apart.
    if(btn1.stable==LOW && btn3.stable==LOW){
      btn1.pending=false; btn3.pending=false;
    }
    // Adaptive cadence: poll fast (5ms) normally so taps are never missed, but
    // when the screen is dimmed (confirmed deep-idle) stretch to 40ms so the
    // core gets longer light-sleep windows. The dim WAKE itself is handled at
    // the top of loop() via raw digitalRead, so a slow poll here can't miss the
    // wake press — and once awake we're back to 5ms before any real input.
#if CONFIG_PM_ENABLE
    // 10a (census, 9 Nov 2026: 37 timer wakes a second while dark): dark, 1 s.
    // Every loop that runs while the screen is dark polls the buttons itself
    // (loop() reads the pins raw at its top; the PASSKEY home loop polls all four
    // each pass), so this task adds nothing then but a wake every 100 ms.
    vTaskDelay(pdMS_TO_TICKS(dimActive ? 1000 : 30));  // PM: every poll is a wake; 30 ms is still instant to a thumb
#else
    vTaskDelay(pdMS_TO_TICKS(dimActive ? 40 : 5));
#endif
  }
}



// ── State machine ──────────────────────────────────────────────────────────
enum DeviceState {
  ST_MENU, ST_SCANNING, ST_CONFIRM_EVENT, ST_SHOW_SIGNED_QR,
  ST_SHOW_BUNKER_QR, ST_PIN_ENTRY,
  ST_WAITING_CORACLE, ST_APPROVAL, ST_RELAYS, ST_AIRGAP_SIGN,
  ST_WIFI_PROVISION, ST_CIPHER, ST_BUNKER_STATUS, ST_ONBOARD,
  ST_PAIR_CONFIRM
};
DeviceState currentState=(DeviceState)99, nextState=ST_MENU, lastState=(DeviceState)99;

// ── Rule 4 predicate: states where the security UX owns the device ─────────
// Game NVS flushes are deferred while any of these is active. Read directly
// from currentState each flush tick, so no transition can be missed. Covers
// PIN entry, event/PSBT confirm + approval, airgap signing, QR scan (part of
// the signing pipeline, camera+decode timing-critical), signed-QR display
// (animated, timing-sensitive), pairing screens, and onboarding (seed entry).
static inline bool stateIsSecurityUx(DeviceState s){
  switch(s){
    case ST_PIN_ENTRY: case ST_CONFIRM_EVENT: case ST_APPROVAL:
    case ST_AIRGAP_SIGN: case ST_SCANNING: case ST_SHOW_SIGNED_QR:
    case ST_SHOW_BUNKER_QR: case ST_PAIR_CONFIRM: case ST_ONBOARD:
      return true;
    default: return false;
  }
}

// Scan router scope. SCAN_UNIVERSAL (top-level Scan) accepts ALL supported QR
// types and routes by content. The scoped modes (entered from a sub-menu)
// restrict what a decoded QR is allowed to do, so e.g. a Bitcoin-scoped scan
// won't silently act on a Nostr key. Set before transitioning to ST_SCANNING.
enum ScanRouterMode { SCAN_UNIVERSAL, SCAN_BTC_ONLY, SCAN_NOSTR_ONLY };
ScanRouterMode scanRouterMode = SCAN_UNIVERSAL;
// True while a USER-initiated scan (top-level Scan / scoped sub-menu scan) is
// running in ST_SCANNING. Distinguishes it from a PWA remote scan
// (scanApiPending). The loop's "force-stop if not an API scan" safety guard
// must NOT kick a user scan back to the menu, so it checks this too.
bool userScanActive = false;

// ── QR pairing (scan-router based) state ────────────────────────────────────
// Filled by the FK1 branch of the scan router; consumed by ST_PAIR_CONFIRM.
volatile bool g_pairScanReady = false;
uint8_t  g_pairScanPhonePub[32] = {0};   // phone static pubkey to enrol on Confirm
uint8_t  g_pairScanPid[8] = {0};         // pair_id (also embedded in FK2)
