// ── Device mode ────────────────────────────────────────────────────────────
// User-facing modes — saved in NVS as the user's preference.
#define MODE_OFFLINE  0
#define MODE_HOTSPOT  1
#define MODE_NETWORK  2
#define MODE_AUTO     3
#define MODE_BLUETOOTH 4   // 9p: a Change mode answer only (the NOSTR Bluetooth life, sys/nbt); never saved as deviceMode
#define MODE_UNSET   -1
int deviceMode=MODE_UNSET;
// Runtime mode — what we're ACTUALLY running as right now. For OFFLINE,
// HOTSPOT, NETWORK this matches deviceMode. For AUTO, this gets resolved
// at boot to either NETWORK (saved WiFi reachable) or HOTSPOT (not). All
// the runtime "what mode am I in?" gates check this rather than
// deviceMode, so AUTO behaves transparently as whichever real mode it
// resolved to. Bunker gating, status bar IP display, mDNS hostname,
// etc all work without special-casing AUTO.
int effectiveMode=MODE_UNSET;

// ── Two-door key mode (NOSTR / BTC) ─────────────────────────────────────────
// Independent of deviceMode (which is CONNECTIVITY: offline/hotspot/network).
// This is WHICH KEY WORLD the device is in for this power-on life, enforced by
// MODE_PCR in the SE (see TWO_DOOR_MODE_SPEC). The boot Select-Mode screen sets
// g_doorChoice; entering the matching PIN commits MODE_PCR. BTC forces offline.
#define DOOR_NONE   0
#define DOOR_NOSTR  1
#define DOOR_BTC    2
#define DOOR_PASSKEY 3   // 30 Oct 2026 (step 3b): FAVILLA_PASSKEY_DOOR builds only
#define DOOR_NOSTR_BT 4  // 9k: the Select Mode answer only; the life is DOOR_NOSTR with g_nostrBtLife (the G0 door is NOSTR)
#if defined(FAVILLA_PASSKEY_DOOR) && !defined(FAVILLA_FIDO_PROBE)
#error "FAVILLA_PASSKEY_DOOR needs the FIDO env (FAVILLA_FIDO_PROBE)"
#endif
int g_doorChoice = DOOR_NONE;   // chosen at the Select-Mode screen this boot
// ── Passkey life (30 Oct 2026, step 3b) ────────────────────────────────────
// A power-on life the G0 holds as PASSKEY. Radios are never initialised
// (deviceMode forced OFFLINE, as in a Bitcoin session), the normal menu never
// runs: setup() hands over to passkeyLifeRun(), which never returns. The
// passkey PIN is entered once on the KEY at the door and held in RAM for the
// life (spec v1.0 section 6, PIN-once); it is wiped on auto-lock and on sleep.
bool g_passkeyLife = false;
// 4 Nov 2026 (Josh: "true air-gap, nothing to turn on"): an onboarded NOSTR
// life that booted OFFLINE is an AIR-GAP LIFE, latched until power-off like
// the Bitcoin and PASSKEY lives: the WiFi driver is never initialised, every
// radio bring-up is refused by g0DoorRadioGuard, and the loop() tripwire checks
// esp_wifi is NOT_INIT every 2 s. Going online = a mode change, which already
// restarts across the offline boundary (applyModeChange, crossesOffline).
bool g_airgapLife = false;
// 4 Nov 2026 (Vault phase 6): a PASSKEY life that started with the Bluetooth
// keyboard setting on. Set once (blekLifeDecide), never cleared; the only way
// esp_bt_controller_init is let through (see __wrap_esp_bt_controller_init).
bool g_btLife = false;
// 9k (7 Nov 2026, issue #7): the NOSTR Bluetooth life, chosen at Select Mode.
// A NOSTR life (NOSTR PIN, the G0 door NOSTR) with no Wi-Fi at all (it is an
// air-gap life: esp_wifi_init is refused) and Bluetooth on: the iPhone app runs
// the KEY's PWA and reaches its /api handlers over the app channel (API 0x3A).
bool g_nostrBtLife = false;
#if defined(FAVILLA_RF_TEST) && defined(FAVILLA_BLE_KBD)
// 15 Nov 2026 (EMC lab build only): the RF test and EMC pages may start
// Bluetooth in a NOSTR Wi-Fi life. Its memory is normally released before
// setup() (btInUse) in such a life, so the page sets "rfbt" in favbt and
// restarts once; that boot keeps the memory and lets the controller start.
// The flag is used up at that boot, so a power cycle is a plain life again.
bool g_rfBtKept = false;
static bool rfBtFlag(){ nvs_handle_t h; uint8_t v = 0; if(nvs_open("favbt", NVS_READONLY, &h) == ESP_OK){ nvs_get_u8(h, "rfbt", &v); nvs_close(h); } return v == 1; }
static void rfBtFlagSet(bool on){ nvs_handle_t h; if(nvs_open("favbt", NVS_READWRITE, &h) == ESP_OK){ if(on) nvs_set_u8(h, "rfbt", 1); else nvs_erase_key(h, "rfbt"); nvs_commit(h); nvs_close(h); } }
#endif
static void nbtSave(bool on){ Preferences p; if(p.begin("sys", false)){ p.putUChar("nbt", on ? 1 : 0); p.end(); } }
static bool nbtLoad(){ Preferences p; if(!p.begin("sys", true)) return false; const bool on = p.getUChar("nbt", 0) == 1; p.end(); return on; }
// 9p: the footer's Bluetooth glyph: a confirmed phone on an encrypted link.
#ifdef FAVILLA_BLE_KBD
bool blekPhoneLinked(){ return blek::s_up && blek::s_conn && blek::s_secure; }
#else
bool blekPhoneLinked(){ return false; }
#endif
static bool s_bootKeyPresent = false;   // set at the early probe: onboarded (onboarding and SE faults are not air-gap lives)
#ifdef FAVILLA_PASSKEY_DOOR
static char g_pkPin[9] = {0};
static volatile bool g_pkPinHeld = false;
// The passkey PIN's wrong-entry count belongs to the wallet: cleared when a
// new passkey PIN is made and on every wallet wipe (review, 30 Oct 2026).
static void pkFailsClear(){ Preferences p; if(p.begin("pkdoor", false, NVSPART_SEC)){ p.clear(); p.end(); } }
#endif
static bool g_netKickPending = false;   // 24 Sep 2026: boot STA kick deferred until the G0 door is committed
// The door is a property of the POWER-ON LIFE, not of one boot. A soft reset
// (rejected PSBT, ceremony exit, crash) must not forget it: if the BTC door was
// chosen and the next boot's daily unlock committed NOSTR, the latch would be
// slammed for the rest of the power cycle and only a battery pull could reopen
// BTC (seen on silicon 11 Sep 2026: "[MODEPCR] BTC refused: latch not neutral").
// Persisted in NVS "sys"/"door"; overwritten at every cold-boot selection.
// UX only — the SE latch is the real gate, an RCE forging this gains nothing.
static void doorSave(int d){
  Preferences p; p.begin("sys", false); p.putUChar("door",(uint8_t)d); p.end();
}
static int doorLoad(){
  Preferences p; p.begin("sys", true); int d=p.getUChar("door",DOOR_NONE); p.end();
#ifdef FAVILLA_PASSKEY_DOOR
  if(d==DOOR_PASSKEY) return d;
#endif
  return (d==DOOR_NOSTR||d==DOOR_BTC)?d:DOOR_NONE;
}
// True only on a genuine power-on reset (cold boot). A soft/SW reset is NOT a
// fresh mode choice — MODE_PCR persists, so we keep the current door. Uses the
// ESP32 reset-reason register (see esp_reset_reason); an RCE can fake this, but
// it is UX only — actually changing the door still needs a PIN (SE-enforced).
bool g_coldBoot = false;

// ── Bitcoin session ("ceremony" in the code; airgap-only TX doctrine) ──────
// A PSBT is signed ONLY in a Bitcoin session - a power-on life in which the
// WiFi/BT drivers are never initialised (the loop() tripwire verifies
// esp_wifi is NOT_INIT every 2 s). Entered one of two ways:
//   * the door: BITCOIN at the Select Mode screen, IN PLACE - the boot is
//     already fresh and pre-radio, so ceremonyEnterInPlace() just sets the
//     flag and forces OFFLINE (7 Oct 2026; previously a restart - see the
//     note on ceremonyEnterInPlace);
//   * ceremonyRequest(): one-shot NVS flag + restart, consumed at NVS mount
//     before any radio decision. Used by the PSBT-rescan offer inside a BTC
//     life, where a clean restart after a reject/crash is still worth having.
// The session ends via ceremonyFinish(): the card, then deep sleep. A Nostr
// life can NEVER become a Bitcoin life (the G0/SE latch is per power-on), and
// the seed is never on this processor in either life - the G0 signs.
bool g_ceremonyBoot = false;              // this power-on is a Bitcoin session
bool g_ceremonyEntered = false;           // first ST_MENU -> the door; later arrivals -> the door menu again
unsigned long g_ceremonyStart = 0;
static const unsigned long CEREMONY_TIMEOUT_MS = 15UL*60UL*1000UL;   // idle ceiling; the door menu refreshes g_ceremonyStart on every press
void ceremonyRequest();                   // persist flag + reboot (never returns)
void ceremonyFinish(const char* msg);     // "Bitcoin / SLEEPING" card + deep sleep (never returns)
void ceremonyOffer(const char* why);      // interstitial; reboots on accept, returns on decline
void ceremonyExplainNostrMode(const char* header = "BITCOIN TX DETECTED");  // Bitcoin asked for in a NOSTR life: explain the power cycle
bool prefer24Words=false;
char lastMnemonic[300]={0};
bool restoringKey=false;
// Bench 2 Nov 2026: the onboarding restore branch clears restoringKey as its
// first step (before the SE provisioning), so pkrPendingStore() always saw
// false and "relay restore pending" was never set after a restore from the
// words. This keeps the fact for that one store.
static bool g_obWasRestore = false;
static uint8_t pendingRestoreKey[32]={0};
// Holds the 64-byte BIP-39 seed between runRestoreFlow (where the seed is
// derived from the user's typed-in words) and the ST_PIN_ENTRY save step
// (where the new PIN is finally available to encrypt it). Parallel to
// pendingRestoreKey, same lifetime, same zeroise-on-abort discipline.
// Used only when restoringKey is true and the source was a BIP-39
// mnemonic — nsec imports leave this zero (no seed exists for an nsec).
static uint8_t pendingRestoreSeed[64]={0};
static bool    pendingRestoreSeedValid=false;
// v4 (24 Sep 2026): per-session passphrase restore — the ENTROPY is what gets
// sealed (mode 2), never a derived seed. Wiped wherever pendingRestoreSeed is.
static uint8_t pendingRestoreMode=0;          // 0 none, 1 baked in, 2 each session (PP_MODE_*)
static uint8_t pendingRestoreEntropy[32]={0};
static int     pendingRestoreWc=0;
#ifdef FAVILLA_PK_RESTORABLE
#define PKR_OB_WIPE() pkrPendingClear()
#else
#define PKR_OB_WIPE() do{}while(0)
#endif
#ifdef FAVILLA_PK_RESTORABLE
// 30 Oct 2026, restorable passkeys (spec v0.8). S_pk = HMAC-SHA256(BIP-39 seed
// WITHOUT passphrase, "FAVILLA-PASSKEY-MASTER-v1"), made here in the offline
// onboarding step that already holds the words. The G0 seals it (PKMASTER,
// seal window only) before the seed store closes that window; the sealed bytes
// are stored on the SE once the daily wrap key exists. Same lifetime and
// wipe discipline as pendingRestoreSeed.
#include "mbedtls/md.h"
extern int8_t g_pkrMasterSeen;   // FIDO backend's cache of "master on the SE" (defined with the FIDO glue)
static uint8_t g_pkrSpk[32]; static bool g_pkrSpkValid=false;
static uint8_t g_pkrSealed[G0_PKM_LEN]; static bool g_pkrSealedValid=false;   // v19: inner || tag
// Phase 3 (2 Nov 2026): the vault backup publishing key's public half and the
// check value, made here while S_pk is in RAM, so a restore from the words can
// find the backup before any PASSKEY login. Public data.
static uint8_t g_vbPub[32], g_vbChk[8]; static bool g_vbKeysValid=false;
static void pkrPendingClear(){
  mbedtls_platform_zeroize(g_pkrSpk,32); mbedtls_platform_zeroize(g_pkrSealed,sizeof g_pkrSealed);
  g_pkrSpkValid=false; g_pkrSealedValid=false;
  memset(g_vbPub,0,32); memset(g_vbChk,0,8); g_vbKeysValid=false;
  g_obWasRestore=false;   // review 2 Nov 2026: a failed restore must not mark a later new wallet "relay restore pending"
}
static void pkrPendingFromSeed(const uint8_t seedNoPass[64]){
  MbedSecretScope _mbedSecret;   // 2 Nov 2026: seed-keyed HMAC and vb_derive stay on-chip (mbed_secret.h)
  static const char lab[]="FAVILLA-PASSKEY-MASTER-v1";
  g_pkrSpkValid = mbedtls_md_hmac(mbedtls_md_info_from_type(MBEDTLS_MD_SHA256), seedNoPass, 64,
                                  (const uint8_t*)lab, sizeof(lab)-1, g_pkrSpk) == 0;
  g_pkrSealedValid=false;
  g_vbKeysValid = g_pkrSpkValid && favilla::vb_derive(g_pkrSpk, g_vbPub, g_vbChk);   // phase 3
}
// After se_provision_g0_identity (G0 keys set, seal window open), BEFORE the
// seed store (which closes the window). Non-fatal: a wallet without restorable
// passkeys still onboards.
static void pkrPendingSeal(){
  if(!g_pkrSpkValid) return;
  g_pkrSealedValid = g0_pk_master(g_pkrSpk, g_pkrSealed);
  mbedtls_platform_zeroize(g_pkrSpk,32); g_pkrSpkValid=false;
  if(!g_pkrSealedValid) LOG_BOOT("[onboard] WARN: G0 passkey master seal failed (restorable passkeys unavailable)\n");
}
// 2 Nov 2026 (Vault phase 2b, rulings S3 + S4 = A): onboarding no longer
// stores the master under the daily key. It creates K_PK and keeps the
// G0-sealed inner layer with its tag (v19: 64 bytes, AES under K_G0 and an HMAC
// under K_G0, useless without the G0) in nvs_sec until the first PASSKEY login
// writes the PASSKEY copy inside a V_3 window.
static const char* PK2B_NS = "pk2b";
static bool pk2bPendingLoad(uint8_t pkm[G0_PKM_LEN]){
  Preferences p; bool ok = false;
  if(p.begin(PK2B_NS, true, NVSPART_SEC)){
    ok = p.getBytesLength("inner") == G0_PKM_LEN && p.getBytes("inner", pkm, G0_PKM_LEN) == G0_PKM_LEN;
    p.end();
  }
  return ok;
}
// v19: k_pub sealed under K_G0 (PUBSEAL in the PASSKEY life), kept until the next
// NOSTR unlock wraps it under the daily key into SE_OBJ_VPUB. Ciphertext only.
static bool vpubSealSave(const uint8_t sealed32[32]){
  Preferences p; bool ok = false; if(p.begin(PK2B_NS, false, NVSPART_SEC)){ ok = p.putBytes("vseal", sealed32, 32) == 32; p.end(); } return ok;
}
static bool vpubSealLoad(uint8_t sealed32[32]){
  Preferences p; bool ok = false; if(p.begin(PK2B_NS, true, NVSPART_SEC)){ ok = p.getBytesLength("vseal") == 32 && p.getBytes("vseal", sealed32, 32) == 32; p.end(); } return ok;
}
static bool vpubSealPending(){ uint8_t t[32]; bool ok = vpubSealLoad(t); mbedtls_platform_zeroize(t, 32); return ok; }
static void vpubSealErase(){ Preferences p; if(p.begin(PK2B_NS, false, NVSPART_SEC)){ p.remove("vseal"); p.end(); } }
static void pk2bPendingErase(){
  Preferences p; if(p.begin(PK2B_NS, false, NVSPART_SEC)){ p.remove("inner"); p.end(); }
}
static void pk2bWipeAll(){
  Preferences p; if(p.begin(PK2B_NS, false, NVSPART_SEC)){ p.clear(); p.end(); }
}
// Phase 3 (2 Nov 2026): vault backup state, in the same namespace (a wipe
// clears it with the rest): "vpub" x-only publishing key, "vchk" check value,
// "rpend" a restore from the words still has to fetch the relay backup,
// "vlast"/"vlastn" the last backup a relay accepted (time, records).
static bool vbKeysLoad(uint8_t pub[32], uint8_t chk[8]){
  Preferences p; bool ok = false;
  if(p.begin(PK2B_NS, true, NVSPART_SEC)){ ok = p.getBytesLength("vpub") == 32 && p.getBytesLength("vchk") == 8 && p.getBytes("vpub", pub, 32) == 32 && p.getBytes("vchk", chk, 8) == 8; p.end(); }
  return ok;
}
static void vbKeysSave(const uint8_t pub[32], const uint8_t chk[8]){
  Preferences p; if(p.begin(PK2B_NS, false, NVSPART_SEC)){ p.putBytes("vpub", pub, 32); p.putBytes("vchk", chk, 8); p.end(); }
}
// "vfix": a backup signature did not verify against the stored key; the next
// PASSKEY login re-makes the SE copy and the stored key (review 2 Nov 2026).
static bool vbFixPending(){ Preferences p; uint8_t v = 0; if(p.begin(PK2B_NS, true, NVSPART_SEC)){ v = p.getUChar("vfix", 0); p.end(); } return v != 0; }
static void vbFixSet(bool on){ Preferences p; if(p.begin(PK2B_NS, false, NVSPART_SEC)){ if(on) p.putUChar("vfix", 1); else p.remove("vfix"); p.end(); } }
static bool vbRestorePending(){ Preferences p; uint8_t v = 0; if(p.begin(PK2B_NS, true, NVSPART_SEC)){ v = p.getUChar("rpend", 0); p.end(); } return v != 0; }
static void vbRestorePendingSet(bool on){ Preferences p; if(p.begin(PK2B_NS, false, NVSPART_SEC)){ if(on) p.putUChar("rpend", 1); else p.remove("rpend"); p.end(); } }
static void vbLastSave(uint32_t t, uint16_t n){ Preferences p; if(p.begin(PK2B_NS, false, NVSPART_SEC)){ p.putULong("vlast", t); p.putUShort("vlastn", n); p.end(); } }
static bool vbLastLoad(uint32_t* t, uint16_t* n){ Preferences p; bool ok = false; if(p.begin(PK2B_NS, true, NVSPART_SEC)){ *t = p.getULong("vlast", 0); *n = p.getUShort("vlastn", 0); ok = *t != 0; p.end(); } return ok; }
static void pkrPendingStore(){
  if(g_pkrSealedValid){
    bool ok = g0_doorpin_present() && favilla::se_pk2b_create_keys();   // v19: only with a G0 that returns inner || tag and reads PKM_IN
    if(ok){ Preferences p; if(p.begin(PK2B_NS, false, NVSPART_SEC)){ p.clear(); ok = p.putBytes("inner", g_pkrSealed, G0_PKM_LEN) == G0_PKM_LEN; p.end(); } else ok = false; }
    g_pkrMasterSeen = -1;   // look again (the FIDO backend caches it)
    if(g_vbKeysValid){   // phase 3: after the clear() above
      vbKeysSave(g_vbPub, g_vbChk);
      bool wasRestore = restoringKey || g_obWasRestore;
      if(wasRestore) vbRestorePendingSet(true);   // fetch the relay backup at the first NOSTR unlock with Wi-Fi
      LOG_BOOT("[onboard] vault backup key: %02x%02x%02x%02x... stored%s\n", g_vbPub[0], g_vbPub[1], g_vbPub[2], g_vbPub[3], wasRestore ? ", relay restore pending" : "");
    }
    g_obWasRestore = false;
    if(!ok) LOG_BOOT("[onboard] WARN: passkey keys not created (restorable passkeys unavailable)\n");
    else LOG_BOOT("[onboard] restorable passkeys: K_PK created; the PASSKEY copy is written at the first PASSKEY login\n");
  }
  pkrPendingClear();
}
#endif
