void loadDeviceMode(){Preferences p;p.begin("device", true, NVSPART_SEC);deviceMode=p.getInt("mode",MODE_UNSET);p.end();}
void saveDeviceMode(int m){Preferences p;p.begin("device", false, NVSPART_SEC);p.putInt("mode",m);p.end();deviceMode=m;}
