// ── Profile name: REMOVED 19 Oct 2026 ─────────────────────────────────────
// The PWA used to push the owner's Nostr display name here for the menu
// header. The header stopped showing it in a redesign, and a name on the
// screen tells whoever finds a lost KEY whose it is and which account it
// signs for. Removed: the store, the /api/profile-name endpoint and the PWA
// push. This only erases a name left by older firmware, once per boot.
void eraseLegacyProfileName() {
  Preferences p;
  if (p.begin("favilla", false)) {
    if (p.isKey("profileName")) { p.remove("profileName"); LOG_BOOT("[BOOT] removed a stored profile name (feature retired)\n"); }
    p.end();
  }
}

uint16_t modeColor(int m){
  if(m==MODE_BLUETOOTH) return C_PURPLE;   // 9p: the colour the NOSTR BT door had
  if(m==MODE_OFFLINE) return C_GREEN;
  if(m==MODE_HOTSPOT) return C_AMBER;
  if(m==MODE_AUTO)    return C_CYAN;
  return C_BLUE;
}
const char* modeName(int m){
  if(m==MODE_BLUETOOTH) return "Bluetooth";
  if(m==MODE_OFFLINE) return "Offline";
  if(m==MODE_HOTSPOT) return "Hotspot";
  if(m==MODE_AUTO)    return "Auto";
  return "Network";
}
const char* modeDesc(int m){
  if(m==MODE_BLUETOOTH) return "Phone app only. No Wi-Fi.";
  if(m==MODE_OFFLINE) return "Air-gapped. QR signing only.";
  if(m==MODE_HOTSPOT) return "Device is AP. Phone uses cell.";
  if(m==MODE_AUTO)    return "Network at home, AP on the go.";
  return "Join existing WiFi network.";
}
const char* modeSecurity(int m){
  if(m==MODE_OFFLINE) return "MAX SECURITY";
  if(m==MODE_HOTSPOT) return "Moderate";
  if(m==MODE_AUTO)    return "Adaptive";
  return "Connected";
}

unsigned long scanStart=0;

// ── PIN entry ──────────────────────────────────────────────────────────────
char pinBuf[9]="000000";
int pinDigit=0;
// 6-digit PINs (V1.x): pinTargetLen is the length the current entry expects.
// All PINs (daily + spend, set + unlock) are fixed at PIN_NEW_LEN (6). A
// pre-existing wallet is wiped on the OLD firmware before flashing this build,
// so the new build never needs to accept a non-6-digit PIN. PIN_MIN_LEN /
// PIN_MAX_LEN are retained only to document the SE's variable-length support
// and to size pinBuf; the on-device entry UI does not use them.
constexpr int PIN_NEW_LEN = 6;   // length of every PIN set/entered on-device
constexpr int PIN_MIN_LEN = 4;   // SE accepts down to this; UI does not use it
constexpr int PIN_MAX_LEN = 8;   // SE accepts up to this; pinBuf is sized to it
int pinTargetLen = PIN_NEW_LEN;  // set on each PIN-entry (see ST_PIN_ENTRY)

// ── PIN attempt counter + escalating lockout (UI/UX guard) ──────────────────
// The SE051 enforces the REAL backstop: 10 wrong PINs in a row wipes the device
// in silicon. This software layer mirrors that count so the user can SEE where
// they are, and imposes an escalating delay between attempts so a child mashing
// buttons (or a casual thief) can't burn through all 10 quickly. It is NOT a
// security boundary — the SE wipe is. Persisted to NVS so a power-cycle doesn't
// reset the count or skip a lockout (a reboot during a lockout restarts the
// wait from full — rebooting never helps an attacker).
constexpr int PIN_ATTEMPT_MAX = 10;   // the SE's own counter on the PIN object (PIN_MAX_ATTEMPTS)
// 24 Sep 2026 — BRICK GUARD. The SE locks the daily PIN object for good at its
// tenth wrong verify, and a locked daily PIN cannot be deleted (its policy is
// self-only), so the chip can never be re-onboarded: that is a brick, not a
// wipe. Honest firmware must therefore NEVER send the tenth attempt. Budgets:
//   remote (/api/unlock, a paired phone)   PIN_REMOTE_MAX = 3, then the API is
//                                          refused until an on-device unlock
//   total sent to the SE, any path         PIN_SEND_MAX   = 9, then the PIN
//                                          screen closes: restore from words
// A remote attacker can spend at most 3 of the SE's 10; the owner keeps the
// rest, and one attempt always stays in reserve on the SE.
constexpr int PIN_SEND_MAX   = 9;
constexpr int PIN_REMOTE_MAX = 3;
// Delay (seconds) imposed AFTER each consecutive failure, indexed by failCount.
// failCount 1..3 → instant; 4 → 1min; 5 → 5min; 6 → 10min; 7 → 30min; 8 → 1hr;
// 9 → 6hr; (10 → SE wipes, no delay needed). Index 0 unused.
static const uint32_t PIN_LOCKOUT_SECS[PIN_ATTEMPT_MAX+1] = {
  0, 0, 0, 0, 60, 300, 600, 1800, 3600, 86400, 0
};
int      pinFailCount   = 0;     // wrong attempts SENT to the SE since the last success, any path
int      pinRemoteFails = 0;     // of those, how many came over the API
uint32_t pinLockoutSecs = 0;     // current lockout duration (s); 0 = none
uint32_t pinLockoutStart= 0;     // millis() when this boot's countdown baseline was set
bool     pinLockoutActive = false;

// Load/save the consecutive-fail count + lockout REMAINING seconds across
// reboots. Stored in the "device" namespace. We persist the seconds STILL TO
// WAIT (not the original duration), and resume the countdown from there on
// boot — so a power blip mid-lockout doesn't restart the full wait, but also
// doesn't credit offline time (no RTC to measure it). Rebooting therefore
// never helps an attacker: the remaining time only ever resumes where it was.
static void pinLoadFailState(){
  Preferences p;
  if(p.begin("device", true, NVSPART_SEC)){
    pinFailCount   = p.getInt("pinFails", 0);
    pinRemoteFails = p.getInt("pinRFails", 0);
    pinLockoutSecs = p.getUInt("pinLockS", 0);   // remaining seconds at last save
    p.end();
  }
  if(pinFailCount < 0) pinFailCount = 0;
  if(pinFailCount > PIN_ATTEMPT_MAX) pinFailCount = PIN_ATTEMPT_MAX;
  if(pinRemoteFails < 0) pinRemoteFails = 0;
  if(pinRemoteFails > pinFailCount) pinRemoteFails = pinFailCount;
  // Resume the countdown from the persisted remaining value (baseline = now).
  if(pinLockoutSecs > 0){
    pinLockoutActive = true;
    pinLockoutStart  = millis();
  }
}
static void pinSaveFailState(){
  Preferences p;
  if(p.begin("device", false, NVSPART_SEC)){
    p.putInt("pinFails", pinFailCount);
    p.putInt("pinRFails", pinRemoteFails);
    p.putUInt("pinLockS", pinLockoutSecs);
    p.end();
  }
}
// Seconds remaining in the current lockout (0 if none / elapsed). Computed as
// the stored baseline minus the time elapsed since the baseline was set.
static uint32_t pinLockoutRemaining(){
  if(!pinLockoutActive || pinLockoutSecs == 0) return 0;
  uint32_t el = (millis() - pinLockoutStart) / 1000UL;
  if(el >= pinLockoutSecs) return 0;
  return pinLockoutSecs - el;
}
// Persist the CURRENT remaining time as the new baseline, so a reboot resumes
// from here. Called periodically while counting down. Re-anchors start = now.
static void pinPersistRemaining(){
  uint32_t r = pinLockoutRemaining();
  pinLockoutSecs  = r;
  pinLockoutStart = millis();
  pinSaveFailState();
}
// Clear lockout + counter on a successful unlock.
static void pinResetFailState(){
  pinFailCount = 0; pinRemoteFails = 0; pinLockoutSecs = 0; pinLockoutActive = false; pinLockoutStart = 0;
  pinSaveFailState();
}
// True once honest firmware must stop sending PINs to the SE (see PIN_SEND_MAX).
static bool pinSendBudgetSpent(){ return pinFailCount >= PIN_SEND_MAX; }
// 31 Oct 2026: COUNT BEFORE SEND (as the passkey PIN already does). The
// attempt is counted, its lockout tier armed and both saved BEFORE the PIN
// reaches the SE. Counted after, a power cut between the SE's decrement and
// our save left the SE an attempt ahead of the brick guard, and skipped the
// lockout: rebooting helped. A right PIN clears it all again straight away
// (pinResetFailState). The only cost: a power cut during a RIGHT PIN's check
// leaves one counted attempt and its wait, which the next right PIN clears.
static void pinCountBeforeSend(bool remote){
  if(pinFailCount < PIN_ATTEMPT_MAX) pinFailCount++;
  if(remote) pinRemoteFails++;
  uint32_t lk = PIN_LOCKOUT_SECS[pinFailCount];
  if(lk > 0){ pinLockoutSecs = lk; pinLockoutActive = true; pinLockoutStart = millis(); }
  pinSaveFailState();
  LOG_BOOT("[PIN] daily PIN attempt counted and saved before the SE check: %d of %d%s\n",
           pinFailCount, PIN_SEND_MAX, remote ? " (remote)" : "");
}
// The SE refused it: the attempt is already counted; the wait runs from now.
static void pinRefusedAfterCount(){
  if(pinLockoutActive && pinLockoutSecs > 0) pinLockoutStart = millis();
  pinSaveFailState();
  LOG_BOOT("[PIN] daily PIN refused by the SE: %d of %d used, wait %lu s\n",
           pinFailCount, PIN_SEND_MAX, (unsigned long)pinLockoutRemaining());
}

