static void signHistAdd(int kind, bool manual){
  for(int i = (g_signHistN < SIGN_HIST_N ? g_signHistN : SIGN_HIST_N - 1); i > 0; i--) g_signHist[i] = g_signHist[i-1];
  g_signHist[0] = { millis(), kind, manual };
  if(g_signHistN < SIGN_HIST_N) g_signHistN++;
}
static void fmtAgo(char* out, size_t n, uint32_t atMs){
  unsigned long ago = millis() - atMs;
  if(ago < 2000)         snprintf(out, n, "now");
  else if(ago < 60000)   snprintf(out, n, "%lus", ago/1000);
  else if(ago < 3600000) snprintf(out, n, "%lum", ago/60000);
  else                   snprintf(out, n, "%luh", ago/3600000);
}
