static StaticSemaphore_t signMutexBuf, i2cMutexBuf;
static SemaphoreHandle_t signMutex=NULL, i2cMutex=NULL;
#define SIGN_LOCK()   do{if(signMutex)xSemaphoreTake(signMutex,portMAX_DELAY);}while(0)
#define SIGN_UNLOCK() do{if(signMutex)xSemaphoreGive(signMutex);}while(0)
// i2cMutex is RECURSIVE: the SE051 driver now self-locks every APDU exchange
// (se_set_bus_lock), and several call sites ALSO wrap SE calls in I2C_LOCK().
// A non-recursive mutex would deadlock when the same task takes it twice; a
// recursive one lets the same task re-enter safely (each take needs a give).
// 11k (9 Nov 2026): the main I2C bus died twice with the G0 in Stop mode (every
// device silent, the 9-pulse clear useless; with the G0 kept awake, 11j, it
// did not happen). In Stop the G0's I2C block wakes on any START on the bus
// and stretches SCL while its clock comes up; a frame for ANOTHER device
// (the gauge, the accelerometer) arriving in that state is what we think
// wedged it. So: every bus user wakes the G0 first, with a frame addressed to
// it (the one wake the G0 is designed for), through the lock macros below.
static volatile bool g_i2cWaking = false;
static volatile bool g_g0QuietWoke = false;   // 11cq: a dark-time bus user woke the G0 just for its own frame
static inline void i2cWakeG0First(){
  if(g_i2cWaking || !g0_is_asleep()) return;
  g_i2cWaking = true; g0_wake_quiet(); g_i2cWaking = false;   // 11cf: counted, not logged (g0DimSleepTick puts it back)
  if(dimActive) g_g0QuietWoke = true;
}
// 11cq (dark census 22 Nov, Wi-Fi: Signer "Stop 71%", 686 wakes in 8 min 40 s):
// the accelerometer drain (1 a second) and the gauge read woke the G0, and it
// went back to Stop only on the next g0DimSleepTick, up to 200 ms later on the
// Battery page. Now the bus user that woke it puts it back as it lets go of
// the bus, if nothing used the G0 meanwhile. Only on the OUTERMOST release:
// putting the G0 to sleep while this task still holds the bus for another
// device is the Stop-mode wedge 11k guards against.
static inline void i2cUnlock(){
  if(i2cMutex) xSemaphoreGiveRecursive(i2cMutex);
  if(g_g0QuietWoke && dimActive && (!i2cMutex || xSemaphoreGetMutexHolder(i2cMutex) != xTaskGetCurrentTaskHandle())){
    g_g0QuietWoke = false;
#if FAVILLA_G0_STOP_ON_DIM
    g0_resleep_if_untouched();
#endif
  }
}
#define I2C_LOCK()    do{if(i2cMutex)xSemaphoreTakeRecursive(i2cMutex,portMAX_DELAY); i2cWakeG0First();}while(0)
#define I2C_UNLOCK()  i2cUnlock()
// 20 Oct 2026: for the main loop's per-tick sensor reads (accelerometer,
// gauge). A G0 operation holds the bus for 0.5-0.8 s; blocking the UI loop
// on it is what froze the screen during PWA/bunker crypto. Skip the read
// instead. Returns false if the bus is busy.
static inline bool i2cTryLock(uint32_t ms){
  if(i2cMutex && xSemaphoreTakeRecursive(i2cMutex, pdMS_TO_TICKS(ms)) != pdTRUE) return false;
  i2cWakeG0First();   // 11k
  return true;
}
#define I2C_TRYLOCK(ms) i2cTryLock(ms)

// ── Boot-time I2C bus scanner (diagnostic) ──────────────────────────────────
// Lists every device that ACKs on the main bus (SDA=6/SCL=5), then probes the
// BMA400's two possible addresses 10x each. The hit rate is the tell:
//   10/10 -> present & solid    0/10 -> fully open joint / dead / unpowered
//   1..9/10 -> INTERMITTENT (cracked LGA joint) — a reflow would very likely fix it
// Set I2C_BOOT_SCAN 0 to remove from production builds.
#ifndef I2C_BOOT_SCAN
#define I2C_BOOT_SCAN 1
#endif
#if I2C_BOOT_SCAN
static void i2cBusScan(){
  I2C_LOCK();
  LOG_BOOT("[I2CSCAN] main bus (SDA=6 SCL=5):\n");
  int found=0;
  for(uint8_t a=0x08; a<=0x77; a++){
    Wire.beginTransmission(a);
    if(Wire.endTransmission()==0){
      const char* name="?";
      switch(a){
        case 0x14: case 0x15: name="BMA400 (accel)"; break;
        case 0x20: name="TCA9554"; break;
        case 0x36: name="MAX17048 (batt)"; break;
        case 0x40: name="INA232 (batt V/I)"; break;
        case 0x18: case 0x19: name="LIS2DW12 (accel)"; break;
        case 0x5A: name="DRV2605L (haptic)"; break;
      }
      LOG_BOOT("[I2CSCAN]   0x%02X ACK  %s\n", a, name);
      found++;
    }
    // 10h: no 1 ms pause per address (112 ms a boot); an empty address NACKs at once
  }
  // 10h (Josh, 9 Nov 2026: "BMA400 is gone, we only use LIS2DW12"): the
  // 20-try BMA400 joint check is gone with it (about 60 ms a boot).
  LOG_BOOT("[I2CSCAN] %d device(s) total\n", found);
  I2C_UNLOCK();
}
#endif

