// NETWORK — WiFi fan. Tinted by mode colour; dim if not actually connected.
void drawModeWifi(int x, int y, int level, uint16_t col){
  // level 1..4 signal strength. The full fan is drawn dim as a "track", then
  // the lit portion is overlaid in colour: L1=dot/dim only, L2=+inner arc,
  // L3=+middle arc, L4=full fan. All variants share one bbox so they align.
  int cx = x + FAN_FULL_W/2, cy = y + FAN_FULL_H/2;
  if(level < 1) level = 1; if(level > 4) level = 4;
  // Dim full-fan track underneath.
  blitA4(FAN_FULL_A4, FAN_FULL_W, FAN_FULL_H, FAN_FULL_ROWBYTES, cx, cy, C_VDIM, C_BG);
  // Lit portion in colour on top.
  if(level >= 4)      blitA4(FAN_FULL_A4, FAN_FULL_W, FAN_FULL_H, FAN_FULL_ROWBYTES, cx, cy, col, C_BG);
  else if(level == 3) blitA4(FAN2_A4,     FAN2_W,     FAN2_H,     FAN2_ROWBYTES,     cx, cy, col, C_BG);
  else if(level == 2) blitA4(FAN1_A4,     FAN1_W,     FAN1_H,     FAN1_ROWBYTES,     cx, cy, col, C_BG);
  // level 1: only the dim track shows (weakest) — but light the dot so it reads
  // as connected. FAN1 includes the dot; draw just that in colour faintly.
  else                blitA4(FAN1_A4,     FAN1_W,     FAN1_H,     FAN1_ROWBYTES,     cx, cy, blend565(col, C_BG, 150), C_BG);
}

// HOTSPOT — concentric broadcast rings (the device IS the access point).
void drawModeHotspot(int x, int y, uint16_t col){
  blitA4(MODE_HOTSPOT_A4, MODE_HOTSPOT_W, MODE_HOTSPOT_H, MODE_HOTSPOT_ROWBYTES, x + MODE_HOTSPOT_W/2, y + MODE_HOTSPOT_H/2, col, C_BG);
}

// 9p: NOSTR over Bluetooth: the Bluetooth rune, in the Wi-Fi fan's 24x20 box
// (centred, 10 x 18), 2 px strokes like the air-gap slash.
void drawModeBluetooth(int x, int y, uint16_t col){
  const int cx = x + FAN_FULL_W/2 - 1, top = y + 1, bot = y + FAN_FULL_H - 1, mid = y + FAN_FULL_H/2;
  const int r = cx + 5, l = cx - 5, q = (mid - top) / 2;
  spr.drawWideLine(cx, top, cx, bot, 2, col);              // the spine
  spr.drawWideLine(cx, top, r, top + q, 2, col);           // upper arrow
  spr.drawWideLine(r, top + q, l, mid + q, 2, col);
  spr.drawWideLine(cx, bot, r, bot - q, 2, col);           // lower arrow
  spr.drawWideLine(r, bot - q, l, mid - q, 2, col);
}

// OFFLINE / AIRGAPPED — the WiFi glyph, dimmed, with a thin red slash.
void drawModeAirgap(int x, int y, uint16_t col){
  (void)col;
  int cx = x + FAN_FULL_W/2, cy = y + FAN_FULL_H/2;
  blitA4(FAN_FULL_A4, FAN_FULL_W, FAN_FULL_H, FAN_FULL_ROWBYTES, cx, cy, C_VDIM, C_BG);
  // Thin (2px) red diagonal slash — clear but not heavy.
  spr.drawWideLine(x + 1, y + 1, x + FAN_FULL_W - 1, y + FAN_FULL_H - 1, 2, C_RED);
}


void uiStatusBar(){
  spr.fillRect(0,218,240,22,C_BG);
  spr.drawFastHLine(0,218,240,C_BORDER);

  // Layout zones (x ranges):
  //   [0..168]   left:  mode dot + IP/state text + relay marker
  //   [170..184] middle: NWC balance text (right-aligned to 184)
  //   [186..234] right:  battery icon + percentage
  // NWC balance is hidden when wider than the middle slot rather than
  // colliding with adjacent zones. Status text is truncated similarly.

  bool scanning = reconnecting;
  bool netBooting = netBootConnecting();   // boot-time STA connect in flight
  bool netSearching = netBootFailed();     // boot connect failed, retrying
  bool conn=wifiConnected&&currentIP[0]!=0&&!scanning;
  bool relay=wsInitialised||ws2Initialised;
  uint16_t dotCol=(effectiveMode==MODE_OFFLINE)?C_MUTED:
                  g_apParked?C_VDIM:
                  (scanning||netBooting||netSearching)?C_AMBER:
                  (conn&&relay?C_GREEN:C_AMBER);
  spr.fillCircle(12,228,4,dotCol);
  fSet(F_SMALL);

  // Left zone: mode label / IP. Truncate to fit before relay indicator.
  const int LEFT_TEXT_X = 22;
  const int LEFT_TEXT_MAX_W = 130; // 22..152 — leaves room for relay marker
  auto drawTruncated = [&](const char* s){
    String t = s;
    while(t.length() > 0 && spr.textWidth(t.c_str()) > LEFT_TEXT_MAX_W){
      t.remove(t.length()-1);
    }
    spr.drawString(t.c_str(), LEFT_TEXT_X, 222);
  };
  if(effectiveMode==MODE_OFFLINE){
    spr.setTextColor(C_MUTED); drawTruncated("air-gapped");
  } else if(scanning){
    spr.setTextColor(C_DIM); drawTruncated(currentIP);
  } else if(netBooting){
    // Background boot connect not yet established — show progress, not a
    // stale/empty IP. The menu is already up; this just tracks connectivity.
    spr.setTextColor(C_DIM); drawTruncated("connecting...");
  } else if(netSearching){
    spr.setTextColor(C_DIM); drawTruncated("searching...");
  } else if(conn){
    spr.setTextColor(C_MUTED); drawTruncated(currentIP);
  } else if(g_apParked){
    spr.setTextColor(C_VDIM); drawTruncated("hotspot off");
  } else if(wifiConnected && effectiveMode==MODE_HOTSPOT){
    spr.setTextColor(C_MUTED); drawTruncated("connecting...");
  }

  // Middle zone: NWC balance. Hide if it would overflow the slot.
  if(nwcBalanceSats >= 0){
    String balStr = String(nwcBalanceSats);
    int balW = spr.textWidth(balStr.c_str()) + 9; // +9 for zap glyph
    const int NWC_MAX_W = 56;       // 184 - 128 (after relay zone)
    const int NWC_RIGHT = 184;
    if(balW <= NWC_MAX_W){
      int bx = NWC_RIGHT - balW;
      int by = 222;
      spr.setTextColor(C_AMBER);
      spr.drawString(balStr.c_str(), bx+9, by);
      spr.drawLine(bx+5,222, bx+2,227, C_AMBER);
      spr.drawLine(bx+2,227, bx+7,226, C_AMBER);
      spr.drawLine(bx+7,226, bx+4,232, C_AMBER);
    }
  }

  // Right zone: battery (icon at 192, percentage to its right).
  battDraw(192, 221);

  // Motion auto-lock ARMED indicator. When armed, show red "ARMED" in the
  // left zone — a security-armed state outranks the IP/mode text there.
  if(accel.ok && accel.mState == AccelDrv::MS_ARMED){
    spr.fillRect(0,218,160,22,C_BG);        // clear left+middle zones
    spr.fillCircle(12,228,4,C_RED);
    fSet(F_SMALL); spr.setTextColor(C_RED);
    spr.drawString("ARMED", 22, 222); fEnd();
  }
  fEnd();
}

// ── New home-screen footer ──────────────────────────────────────────────────
// Slim footer matching the main menu / lock screen: a mode glyph on the left
// (WiFi signal fan in NETWORK, broadcast in HOTSPOT, slashed bars in OFFLINE)
// and the inline battery on the right. No IP, no NWC balance, no status dot,
// no divider line — deliberately quieter than uiStatusBar(). This is the
// canonical footer; uiStatusBar() is retained only where the richer status
// readout (IP/relay/NWC) is actually wanted.
void uiFooter(){
  const int footY = 220;
  int rm = (effectiveMode == MODE_UNSET) ? deviceMode : effectiveMode;
  uint16_t mcol = C_EB_BRASS;   // 5 Oct 2026: one accent; the glyph shape says which mode
  if(rm == MODE_NETWORK){
    // Map RSSI to a 1..4 signal level for the fan icon.
    int level = 1;
    if(wifiConnected){
      long r = WiFi.RSSI();
      level = (r >= -55) ? 4 : (r >= -67) ? 3 : (r >= -78) ? 2 : 1;
    }
    drawModeWifi(12, footY, level, wifiConnected ? mcol : C_VDIM);
  } else if(rm == MODE_HOTSPOT){
    drawModeHotspot(12, footY, g_apParked ? C_VDIM : mcol);   // dim while idle-off has the AP parked
  } else if(g_nostrBtLife){
    drawModeBluetooth(12, footY, blekPhoneLinked() ? mcol : C_VDIM);   // 9p: brass with the phone on, dim while it is away
  } else {
    drawModeAirgap(12, footY, mcol);
  }
  // Which door this power-on life is in (5 Oct 2026): mono grey, after the
  // mode glyph. The cipher-hold scramble overdraws this strip and dispMenu
  // repaints it on release, so the two never fight.
  if(g_doorChoice == DOOR_NOSTR || g_doorChoice == DOOR_BTC){
    // 29 Oct 2026: Archivo tracked caps like the rest of the footer (was mono).
    { const char* d = g_doorChoice == DOOR_BTC ? "BTC" : "NOSTR";
      uiTrackLabel(d, 44 + uiTrackWidth(d, 2) / 2, footY + 2, C_EB_GREY, 2); }
  }
  // Motion auto-lock ARMED: red label centred in the footer.
  if(accel.ok && accel.mState == AccelDrv::MS_ARMED){
    uiTrackLabel("ARMED", 120, footY + 2, C_RED, 2);
  }
#ifdef FAVILLA_EMBERWILL
  emwFooter(footY);   // Emberwill: ember + ALIVE/SILENT + days to the window, only while the G0 holds a plan
#endif
  battDrawInline(190, footY);
}
