// Hold progress bar
static float lastBarPct=-1.0f;
void drawHoldBar(float pct, const char* label){
  if(fabsf(pct-lastBarPct)<0.02f) return;
  lastBarPct=pct;
  spr.fillRect(0, 200, 240, 22, C_BG);
  if(pct>0.0f){
    fSet(F_SMALL); spr.setTextColor(C_EB_BRASS);   // 5 Oct 2026: brass (non-destructive holds only)
    spr.drawString(label, 10, 203);
    fEnd();
    spr.drawRect(10, 213, 220, 6, C_EB_BRASS);
    int fw=(int)(pct*218);
    if(fw>0) spr.fillRect(11, 214, fw, 4, C_EB_BRASS);
  }
  DISP_LOCK(); spr.pushSprite(0,0); DISP_UNLOCK();
}

// ── CIPHER hold reveal (hidden BACK-hold shortcut) ─────────────────────────
// Replaces the generic amber hold bar for the BACK-hold easter egg into the
// CIPHER game. The word "CIPHER" appears in the FOOTER strip as churning
// random hex glyphs (dim grey, reshuffled every ~80ms) and decrypts one
// letter at a time, left→right, into green as the hold progresses — a cipher
// literally being broken. Each letter locking in plays a rising piezo note.
// Early release repaints the whole menu (footer included) via dispMenu(), so
// no explicit restore pass is needed — just call cipherHoldReset().
static int      cipherHoldResolved  = -1;  // letters locked so far (-1 = idle)
static uint32_t cipherHoldShuffleAt = 0;   // next glyph reshuffle time
void cipherHoldReset(){ cipherHoldResolved = -1; cipherHoldShuffleAt = 0; }
void drawCipherHold(float pct){
  static const char WORD[7] = "CIPHER";
  static const char HEXG[17] = "0123456789ABCDEF";
  int resolved = (int)(pct * 6.0f);
  if(resolved > 6) resolved = 6;
  uint32_t now = millis();
  // Repaint only when a letter locks in or the scramble reshuffles (~80ms) —
  // same spirit as drawHoldBar's 2% delta gate, keeps SPI traffic light.
  if(resolved == cipherHoldResolved && now < cipherHoldShuffleAt) return;
  if(resolved > cipherHoldResolved && cipherHoldResolved >= 0){
    // Progressive decrypt ladder — each letter locking in plays one step
    // higher; the 6th (full word) lands the top note. Piezo only, no haptic:
    // the rising pitch IS the progress feedback. Respects feedback mode.
    static const uint16_t kDecryptHz[6] = {1200, 1450, 1750, 2100, 2500, 3000};
    if(feedbackMode >= FEEDBACK_NORMAL) buzzerTone(kDecryptHz[resolved-1], 18);
  }
  cipherHoldResolved  = resolved;
  cipherHoldShuffleAt = now + 80;

  // Overdraw only the CENTRE of the footer strip, between the mode glyph
  // (left, ends ~x=32) and the battery (right, starts x=190). Both icons stay
  // resident — tickStatusBarInMenu's 2s uiFooter repaint redraws them in
  // place without ever touching the scramble, so the two painters coexist.
  spr.fillRect(40, 210, 145, 30, C_BG);
  fSet(F_MONO);
  char g[2] = {0, 0};
  const int cw = spr.textWidth("0") + 4;     // mono advance + letterspacing
  int x = 120 - (6*cw - 4)/2;
  for(int i = 0; i < 6; i++){
    if(i < resolved){ g[0] = WORD[i]; spr.setTextColor(C_GREEN); }
    else            { g[0] = HEXG[random(16)]; spr.setTextColor(C_DIM); }
    spr.drawString(g, x + i*cw, 218);
  }
  fEnd();
  dispPushRegion(40, 210, 145, 30);          // centre strip only — light SPI
}

// Error screen
// Centred word wrap in the CURRENTLY LOADED font. Returns the y after the last
// line. Words longer than maxW are drawn as they are (rare: hex, URLs).
static int uiWrapCentre(const char* t, int y, int maxW, int lineH, int maxLines){
  char line[64]; int n = 0, lines = 0; const char* p = t;
  while(*p && lines < maxLines){
    n = 0; const char* lastBreak = nullptr; int lastN = 0; const char* q = p;
    while(*q && n < (int)sizeof(line) - 1){
      line[n] = *q; line[n+1] = 0;
      if(spr.textWidth(line) > maxW && n > 0){ break; }
      if(*q == ' '){ lastBreak = q; lastN = n; }
      n++; q++;
    }
    if(*q && lastBreak){ n = lastN; q = lastBreak + 1; }
    line[n] = 0;
    spr.drawString(line, 120 - spr.textWidth(line) / 2, y);
    y += lineH; lines++; p = q;
    while(*p == ' ') p++;
  }
  return y;
}
// The dead ember: the 13-cell diamond gone dark, red at its core (errors).
static void uiDeadEmber(int x, int y, int cell, int gap, uint16_t core){
  for(int r = 0; r < 5; r++) for(int c = 0; c < 5; c++){
    int d = abs(r-2) + abs(c-2); if(d > 2) continue;
    spr.fillRect(x + c*(cell+gap), y + r*(cell+gap), cell, cell, d == 0 ? core : (uint16_t)0x2104);
  }
}
// 29 Oct 2026 (Emberwill page language): red tracked label, the dead ember,
// the message large if it fits one line, else wrapped (it used to run off its
// red panel), and how to dismiss. No status footer: errors are modal.
void dispError(const char* msg){
  buzzerFail();
  fEnd();
  if(bgSpinnerRunning) bgSpinnerStop();
  spr.fillSprite(C_BG);
  uiTrackLabel("ERROR", 120, 14, C_RED);
  uiDeadEmber(101, 40, 6, 2, C_RED);
  if(!msg) msg = "";
  fEndHard(); spr.loadFont(FONT_Archivo_Bold_28_full);
  spr.setTextColor(C_EB_INK);
  if(spr.textWidth(msg) <= 216){
    spr.drawString(msg, 120 - spr.textWidth(msg) / 2, 100);
  } else {
    fEndHard(); spr.loadFont(FONT_Archivo_Regular_13);
    spr.setTextColor(C_EB_INK);
    uiWrapCentre(msg, 96, 210, 18, 5);
  }
  fEndHard();
  uiTrackLabel("ENTER TO CONTINUE", 120, 206, C_EB_GREY);
  dispPush();
}

