// ── Animated key splash (boot) ────────────────────────────────────────────
// Mirrors the PWA's key-mark animation: bow circle, shaft, two teeth and
// hole each draw themselves in on a staggered timeline. Same visual
// language across web and device.
//
// PWA viewport is 110×50; device version scales 1.3× and centers around
// (120, 168) below the wordmark. Total animation ~1.15s; the function
// blocks for that duration.
// ── Boot splash fade-out (non-blocking) ─────────────────────────────────────
// The draw-on animation (dispBootKeyAnimation) runs blocking in setup() for
// ~1.14s — short and intentional. The old 6s "idle pulse" that followed it
// blocked setup() and, post background-network-refactor, became pure dead time
// (the WiFi connect it used to mask now runs in the background). Replaced with
// this non-blocking fade: setup() returns immediately after the draw-on, and
// loop() fades the fully-drawn key out over the BG before the first real screen
// (PIN entry / menu) paints. Net: ~1.8s of splash instead of 7.14s, key
// dissolves cleanly into the first screen.
//
// The fade runs BEFORE any real screen has drawn, so there's no overlay/
// concurrency hazard — paintBootKeyFrame() owns the whole sprite each frame,
// and the state dispatch in loop() is gated until the fade completes.
// ── Entropy Ember boot (4 Oct 2026) ──────────────────────────────────────────
// The skeleton-key draw-on is retired. The boot is now the brand mark from the
// favillakey.io kit: a 5x5 grid of cells (lifted from the entropy visualiser)
// that starts as noise, locks outside-in to the ember, flashes, then the
// wordmark fades in beneath it. Same lifecycle as before: this blocks for the
// draw-on, then tickBootSplashFade() in loop() holds and dissolves it while
// the rest of setup() (WiFi, NVS) proceeds.
//
// Geometry for the 240x240 panel: cell 24 px, gap 6 px -> 144 px square at
// (48,30). Wordmark baseline area y=186: FAVILLA (Archivo 700 28 px, ink) +
// KEY (Archivo 300 28 px, brass, tracked EB_KEY_TRACK px). Version in F_SMALL,
// grey, centred at y=223.
static const int EB_CELL = 24, EB_GAP = 6, EB_OX = 48, EB_OY = 30;
static const int EB_WORDMARK_Y = 186, EB_VERSION_Y = 223;
static const int EB_WORD_GAP = 9;        // 0.32 em between FAVILLA and KEY
static const int EB_KEY_TRACK = 5;       // 0.18 em letter-spacing on KEY
// (Entropy Ember palette C_EB_* now lives with the other colour tokens near C_AMBER — 5 Oct 2026)
// Noise palette the unlocked cells flicker through (same list as ember.js)
static const uint16_t EB_NOISE[8] = { 0x0841 /*0A0A0A*/, 0x10A2 /*141414*/, 0x18E3 /*1C1C1C*/, 0x2124 /*262626*/,
                                      0x3164 /*2E2A22*/, 0x41A3 /*3A3020*/, 0x4A04 /*4C4020*/, 0x7AE5 /*7A5C2A*/ };

// Blend two RGB565 colours, t255 = 0 -> a, 255 -> b.
static inline uint16_t ebMix(uint16_t a, uint16_t b, uint8_t t255){
  uint8_t ar=(a>>11)&0x1F, ag=(a>>5)&0x3F, ab=a&0x1F;
  uint8_t br=(b>>11)&0x1F, bg=(b>>5)&0x3F, bb=b&0x1F;
  uint8_t r=(ar*(255-t255)+br*t255)/255;
  uint8_t g=(ag*(255-t255)+bg*t255)/255;
  uint8_t bl=(ab*(255-t255)+bb*t255)/255;
  return (r<<11)|(g<<5)|bl;
}
// The ember: Manhattan distance from the centre picks the colour.
static inline uint16_t ebTarget(int r, int c){
  int d = abs(r-2) + abs(c-2);
  if(d == 0) return C_EB_INK;
  if(d == 1) return C_EB_BRASS;
  if(d == 2) return (r != 2 && c != 2) ? C_EB_BRASS2 : C_EB_BRASS3;
  return C_EB_CHAR;
}
static inline void ebCell(int r, int c, uint16_t col){
  spr.fillRect(EB_OX + c*(EB_CELL+EB_GAP), EB_OY + r*(EB_CELL+EB_GAP), EB_CELL, EB_CELL, col);
}
// The ember at any size: 5x5 cells of `cell` px with `gap` px between, top-left
// at (x,y). Used by the header lockup (cell 3, gap 1 -> 19 px).
static void ebMarkSmall(int x, int y, int cell, int gap){
  for(int r = 0; r < 5; r++) for(int c = 0; c < 5; c++){
    uint16_t col = ebTarget(r, c);
    if(col == C_EB_CHAR) continue;   // corners stay panel-black at this size
    spr.fillRect(x + c*(cell+gap), y + r*(cell+gap), cell, cell, col);
  }
}
// The ember going out, cell by cell, for a destructive hold (DELETE KEY).
// 13 lit cells die outside-in - the reverse of the boot draw-on - so the mark
// is extinguished from its edges and the ink core is the last thing left.
// pct 0..1 of the hold. Returns how many cells are out, so the caller can tick
// once per cell. Geometry matches the PIN mark (cell 8, gap 2, 48 px).
static int ebMarkExtinguish(int ox, int oy, float pct){
  // outside-in order: d=2 ring (8 cells) clockwise, then d=1 (4), then centre
  static const int8_t order[EB_HOLD_CELLS][2] = {
    {0,2},{1,3},{2,4},{3,3},{4,2},{3,1},{2,0},{1,1},   // d == 2
    {1,2},{2,3},{3,2},{2,1},                            // d == 1
    {2,2} };                                            // core
  int out = (int)(pct * EB_HOLD_CELLS + 0.0001f); if(out > EB_HOLD_CELLS) out = EB_HOLD_CELLS;
  bool dead[5][5] = {};
  for(int i = 0; i < out; i++) dead[order[i][0]][order[i][1]] = true;
  for(int r = 0; r < 5; r++) for(int c = 0; c < 5; c++){
    uint16_t col = ebTarget(r, c);
    if(dead[r][c]) col = C_EB_CHAR;
    spr.fillRect(ox + c*10, oy + r*10, 8, 8, col);
  }
  return out;
}
// ── Brand header (5 Oct 2026) ────────────────────────────────────────────────
// 28 px strip: small ember (19 px) + "FAVILLA" (Archivo 700 12, ink) + "KEY"
// (Archivo 300 12, brass, tracked 2 px) on the left; an optional right-aligned
// mono label (the door: NOSTR / BTC) in grey; charcoal rule under it. Replaces
// the coloured-dot uiHeader on the main menu first; other screens follow.
static void uiBrandHeader(const char* right){
  spr.fillRect(0, 0, 240, HEADER_H, C_BG);   // no rule: spacing separates, lines are noise on 240 px
  ebMarkSmall(10, 4, 3, 1);
  int x = 36;
  fSet(F_BRAND_B12); spr.setTextColor(C_EB_INK);
  spr.drawString("FAVILLA", x, 8);
  x += spr.textWidth("FAVILLA") + 4;
  fSet(F_BRAND_L12); spr.setTextColor(C_EB_BRASS);
  for(const char* q = "KEY"; *q; q++){ char ch[2] = {*q, 0}; spr.drawString(ch, x, 8); x += spr.textWidth(ch) + 2; }
  if(right && *right){
    fSet(F_MONO); spr.setTextColor(C_EB_GREY);
    int w = spr.textWidth(right);
    spr.drawString(right, 230 - w, 8);
  }
  fEnd();
}
// Tracked caps label, centred on cx (Archivo 700 14, +1 px tracking).
// ── Page-language helpers (29 Oct 2026) ─────────────────────────────────────
// The Emberwill pages' vocabulary, shared by the rest of the device:
//   uiTrackLabel  tracked caps (Archivo Bold 12, +3 px), centred on cx
//   uiHoldFooter  the "HOLD ENTER TO ..." band at the bottom of an action
//                 screen: tracked label, a progress underline that fills while
//                 ENTER is held, and one grey line saying how to decline.
//                 Draws y 196..239; push it alone with dispPushRegion(0,196,240,44).
//   holdSince     hold progress that ignores a press begun before `since`, so
//                 a press carried in from the previous screen can't act.
static int uiTrackWidth(const char* t, int track){
  fSet(F_BRAND_B12); int w = 0;
  for(const char* q = t; *q; q++){ char c[2] = {*q, 0}; w += spr.textWidth(c) + track; }
  return w > 0 ? w - track : 0;
}
// 11cv (Josh, 22 Nov 2026): "less is more". A consent screen's two answers sit
// in the bottom corners over their buttons: BACK is bottom-left, ENTER
// bottom-right. Decline grey, accept brass, tracked caps, nothing else.
static void uiCornerAnswers(const char* decline, const char* accept){
  fSet(F_BRAND_B12);
  int x = 12;
  spr.setTextColor(C_EB_GREY);
  if(decline) for(const char* q = decline; *q; q++){ char c[2] = {*q, 0}; spr.drawString(c, x, 216); x += spr.textWidth(c) + 3; }
  int w = 0; for(const char* q = accept; *q; q++){ char c[2] = {*q, 0}; w += spr.textWidth(c) + 3; } w -= 3;
  x = 228 - w; spr.setTextColor(C_EB_BRASS);
  for(const char* q = accept; *q; q++){ char c[2] = {*q, 0}; spr.drawString(c, x, 216); x += spr.textWidth(c) + 3; }
  fEnd();
}
// 11er (Josh, 25 Nov 2026): the top buttons' words, in their corners (UP top-left,
// DOWN top-right), grey, on the same 12 px margin as the bottom ones. Either may be null.
static void uiCornerTop(const char* left, const char* right){
  fSet(F_BRAND_B12); spr.setTextColor(C_EB_GREY);
  if(left){ int x = 12; for(const char* q = left; *q; q++){ char c[2] = {*q, 0}; spr.drawString(c, x, 16); x += spr.textWidth(c) + 3; } }
  if(right){ int w = 0; for(const char* q = right; *q; q++){ char c[2] = {*q, 0}; w += spr.textWidth(c) + 3; } w -= 3;
    int x = 228 - w; for(const char* q = right; *q; q++){ char c[2] = {*q, 0}; spr.drawString(c, x, 16); x += spr.textWidth(c) + 3; } }
  fEnd();
}
static void uiTrackLabel(const char* t, int cx, int y, uint16_t col, int track){
  // 11cz (Josh, 22 Nov 2026: "so many places not doing the button text thing"):
  // the old two-line footers become corner words everywhere, at the source.
  // A centred "ENTER TO X" / "ENTER FOR X" / "ENTER: X" / "HOLD ENTER TO X" on
  // the footer line (y 190-199) draws as X (HOLD TO X) in ENTER's corner,
  // bottom-right; a "BACK TO X" / "BACK: X" on the bottom line (y 210-220) as X
  // in BACK's corner, bottom-left. Colours as the caller gave them.
  if(cx == 120){
    char b[40]; const char* r = nullptr; const char* l = nullptr;
    if(y >= 190 && y <= 199){
      if(!strncmp(t, "ENTER TO ", 9)) r = t + 9;
      else if(!strncmp(t, "ENTER FOR ", 10)) r = t + 10;
      else if(!strncmp(t, "ENTER: ", 7)) r = t + 7;
      else if(!strncmp(t, "HOLD ENTER TO ", 14)){ snprintf(b, sizeof b, "HOLD TO %s", t + 14); r = b; }
    } else if(y >= 210 && y <= 220){
      if(!strncmp(t, "BACK TO ", 8)) l = t + 8;
      else if(!strncmp(t, "BACK: ", 6)) l = t + 6;
      if(l){ snprintf(b, sizeof b, "%s", l); size_t L = strlen(b);
        if(L > 3 && !strcmp(b + L - 3, " IT")) b[L - 3] = 0; else if(L > 5 && !strcmp(b + L - 5, " THEM")) b[L - 5] = 0;   // KEEP IT / KEEP THEM -> KEEP
        l = b; }
    }
    if(r || l){
      fSet(F_BRAND_B12); spr.setTextColor(col);
      const char* s = r ? r : l; int w = 0;
      for(const char* q = s; *q; q++){ char c[2] = {*q, 0}; w += spr.textWidth(c) + 3; } w -= 3;
      int x = r ? 228 - w : 12;
      for(const char* q = s; *q; q++){ char c[2] = {*q, 0}; spr.drawString(c, x, 216); x += spr.textWidth(c) + 3; }
      return;
    }
  }
  int x = cx - uiTrackWidth(t, track) / 2;
  fSet(F_BRAND_B12); spr.setTextColor(col);
  for(const char* q = t; *q; q++){ char c[2] = {*q, 0}; spr.drawString(c, x, y); x += spr.textWidth(c) + track; }
}
static void uiHoldFooter(const char* action, const char* sub, float p, uint16_t col){
  spr.fillRect(0, 196, 240, 44, C_BG);
  uiTrackLabel(action, 120, 202, col);
  int w = uiTrackWidth(action, 3), x0 = 120 - w / 2;
  if(p < 0) p = 0;
  if(p > 1) p = 1;
  spr.fillRect(x0, 218, w, 2, C_EB_LINE);
  if(p > 0) spr.fillRect(x0, 218, (int)(w * p), 2, col);
  if(sub && *sub){ fSet(F_SMALL); spr.setTextColor(C_EB_GREY); fDrawCentre(sub, 120, 225); }
}
static void uiBrandLabel(const char* s, int cx, int y, uint16_t col){
  fSet(F_BRAND_B14); spr.setTextColor(col);
  int w = 0;
  for(const char* q = s; *q; q++){ char ch[2] = {*q, 0}; w += spr.textWidth(ch) + 1; }
  int x = cx - (w - 1) / 2;
  for(const char* q = s; *q; q++){ char ch[2] = {*q, 0}; spr.drawString(ch, x, y); x += spr.textWidth(ch) + 1; }
  fEnd();
}
// One 2x2 grid tile, the way every grid on the device draws it (main menu,
// Settings): black, hairline frame; the SELECTED tile carries its accent as
// frame + a low-alpha wash + ink label, idle tiles grey. Returns the fill so
// the caller can blend its icon against it; icon centre is (*icx,*icy).
static uint16_t uiGridTile(int x, int y, int w, int h, bool sel, uint16_t accent, const char* label, int* icx, int* icy){
  uint16_t bg = sel ? ebMix(C_BG, accent, 28) : C_BG;
  spr.fillRoundRect(x, y, w, h, 8, bg);
  spr.drawRoundRect(x, y, w, h, 8, sel ? accent : C_EB_LINE);
  *icx = x + w/2; *icy = y + h/2 - 12;
  uiBrandLabel(label, *icx, y + h - 26, sel ? C_EB_INK : C_EB_GREY);
  return bg;
}
// Entropy Ember LIST card (7 Oct 2026): the runNostrMenu row, made shared so
// every stacked-choice screen (onboarding, passphrase, Bitcoin door) is the
// same object. Black card, 8 px radius, hairline C_EB_LINE; the selected row
// gets the accent frame + a 28 % wash; name in tracked caps (ink / grey),
// description in F_BODY (muted / grey). Icons are the caller's: draw them at
// the left in `sel ? accent : C_EB_GREY` on the returned background.
// nameCol overrides the name colour (explainer cards that are all "selected").
// Card names are tracked caps; settings pickers hand over mixed-case names.
static const char* uiUpper(const char* s, char* buf, size_t n){
  size_t i = 0; for(; s[i] && i + 1 < n; i++) buf[i] = (s[i] >= 'a' && s[i] <= 'z') ? s[i] - 32 : s[i];
  buf[i] = 0; return buf;
}
static uint16_t uiListCard(int x, int y, int w, int h, bool sel, uint16_t accent,
                           const char* name, const char* desc, int textX, uint16_t nameCol = 0){
  // 11cz: drawn as a row (the plain-rows language): no box, no fill; the
  // selected row a brass bar at its left edge, a hairline under every row.
  const uint16_t bg = C_BG;
  spr.fillRect(x, y, w, h, C_BG);
  if(sel) spr.fillRect(x, y + 6, 2, h - 12, accent);
  spr.drawFastHLine(x + 10, y + h + 1, w - 10, C_EB_LINE);
  bool hasDesc = desc && *desc;
  // Name (14 px caps) + 10 px gap + desc (12 px) = 36 px block, centred in the card.
  int nameY = hasDesc ? y + (h - 37) / 2 : y + h/2 - 7;
  fSet(F_BRAND_B14); spr.setTextColor(nameCol ? nameCol : (sel ? C_EB_INK : C_EB_GREY));
  { int tx = textX; for(const char* q = name; *q; q++){ char cs[2] = {*q, 0}; spr.drawString(cs, tx, nameY); tx += spr.textWidth(cs) + 1; } }
  fEnd();
  if(hasDesc){ fSet(F_BODY); spr.setTextColor(sel ? C_MUTED : C_EB_GREY); spr.drawString(desc, textX, nameY + 21); fEnd(); }
  return bg;
}
// ── 11cy (Josh, 22 Nov 2026: "do 3"): plain rows ────────────────────────────
// Every menu as rows instead of cards: up to five at a time, the name on the
// left (Archivo Bold 14, a space 5 px), the status on the right (Archivo 13)
// when it fits beside the name, hairlines between rows. The selected row: a
// brass bar at the left edge, the name in ink, its status in brass; when its
// status is too long for the row it shows as one line under the list instead.
// The answers sit in the corners (BACK bottom-left, ENTER bottom-right).
// off is the caller's scroll position (kept between draws).
static const char* g_rowsYes = "OPEN";   // ebCardChoice says CHOOSE
static void uiRows(const char* title, const char* const* names, const char* const* vals, int n, int sel, int& off,
                   const char* no = "LEAVE", int checkIdx = -1, int dangerIdx = -1, bool titleDone = false){
  // 11db (Josh, 22 Nov 2026: "the double line looks best, the hint in the
  // second line, do that for everything"): two-line rows, the name and its
  // line under it, three in view (uiListCard's row form), the corners below.
  if(!titleDone){ spr.fillSprite(C_BG); uiTrackLabel(title, 120, 14, C_EB_BRASS); }
  const int VIS = 3, Y0 = 44, PITCH = 48, CH = 44;
  if(n <= VIS) off = 0;
  else { if(sel < off) off = sel; if(sel >= off + VIS) off = sel - VIS + 1; if(off > n - VIS) off = n - VIS; if(off < 0) off = 0; }
  for(int r = 0; r < VIS && off + r < n; r++){
    const int i = off + r, y = Y0 + r * PITCH; const bool a = (i == sel), danger = (i == dangerIdx);
    uiListCard(12, y, 216, CH, a, danger ? C_RED : C_EB_BRASS, names[i], vals ? vals[i] : nullptr, 24,
               danger ? (a ? C_RED : ebMix(C_BG, C_RED, 150)) : 0);
    if(i == checkIdx){ const uint16_t cc = a ? C_EB_BRASS : C_EB_GREY; const int cx = 210, cy = y + CH / 2;
      spr.drawWideLine(cx - 5, cy - 1, cx - 1, cy + 4, 3, cc); spr.drawWideLine(cx - 1, cy + 4, cx + 7, cy - 7, 3, cc); }
  }
  if(n > VIS){ const int TX = 236, TY = Y0 + 2, TH = VIS * PITCH - 6; int thumb = TH * VIS / n; if(thumb < 8) thumb = 8;
    int ty = TY + (TH - thumb) * off / (n - VIS); spr.drawFastVLine(TX, TY, TH, C_EB_LINE); spr.fillRect(TX - 1, ty, 3, thumb, C_EB_BRASS); }
  uiCornerAnswers(no, g_rowsYes);
}
// Title header for sub-screens (5 Oct 2026): small ember + tracked caps title
// in the section's accent. Replaces the coloured-dot uiHeader where adopted.
static void uiTitleHeader(const char* title, uint16_t accent){ uiHeader(title, accent); }   // same thing now
// Wordmark + version at a given alpha (255 = full). FAVILLA in F_DISPLAY
// (Archivo Bold), KEY in F_DISPLAY_LT (Archivo Light) drawn glyph by glyph so
// it carries the brand's 0.18 em tracking (TFT_eSPI has no letter-spacing).
// Draw the brand wordmark centred at y, returns its total width. Used by the
// boot splash, dispBoot() and the first-run welcome so there is one wordmark.
static int ebDrawWordmark(int y, uint8_t alpha){
  static const char* KEY = "KEY";
  fSet(F_DISPLAY);
  int wF = spr.textWidth("FAVILLA");
  fSet(F_DISPLAY_LT);
  int wK = 0;
  for(const char* p = KEY; *p; p++){ char ch[2] = {*p, 0}; wK += spr.textWidth(ch); if(p[1]) wK += EB_KEY_TRACK; }
  int total = wF + EB_WORD_GAP + wK;
  if(alpha == 0){ fEnd(); return total; }
  int x = (240 - total) / 2;
  fSet(F_DISPLAY);
  spr.setTextColor(ebMix(C_BG, C_EB_INK, alpha));
  spr.drawString("FAVILLA", x, y);
  x += wF + EB_WORD_GAP;
  fSet(F_DISPLAY_LT);
  spr.setTextColor(ebMix(C_BG, C_EB_BRASS, alpha));
  for(const char* p = KEY; *p; p++){ char ch[2] = {*p, 0}; spr.drawString(ch, x, y); x += spr.textWidth(ch) + EB_KEY_TRACK; }
  fEnd();
  return total;
}
// v19 (13 Nov 2026, docs/DOOR_KEY_RULE.md section 5): the G0's readout lock, from
// SELFTEST byte 26 (0 = an older G0 that does not say). A production KEY is
// locked at RDP level 2 on the Forge; anything else is a development or audit unit.
static uint8_t g_g0Rdp = 0;
static const char* const DEV_UNIT_BANNER = "DEV UNIT: G0 UNLOCKED";
static bool devUnitUnlocked(){ return g_g0Rdp != 0 && g_g0Rdp != 0xCC; }
static void ebWordmark(uint8_t alpha){
  if(alpha == 0) return;
  ebDrawWordmark(EB_WORDMARK_Y, alpha);
  fSet(F_SMALL); spr.setTextColor(ebMix(C_BG, C_EB_GREY, alpha));
  fDrawCentre(FAVILLA_BENCH_DROP, 120, EB_VERSION_Y);   // 7 Nov 2026 (Josh): the boot animation shows the drop flashed
  if(devUnitUnlocked()){ spr.setTextColor(ebMix(C_BG, C_RED, alpha)); fDrawCentre(DEV_UNIT_BANNER, 120, 8); }   // v19
  fEnd();
}

// Splash-fade lifecycle. bootSplashActive is set true by dispBootKeyAnimation()
// when it finishes the draw-on (so the fade takes over in loop()); cleared once
// the fade completes. bootSplashFadeStart delays the fade start so the finished
// mark sits for a beat before dissolving.
bool bootSplashActive = false;
static unsigned long bootSplashFadeStart = 0;
static const unsigned long BK_HOLD_MS = 400;   // beat on the finished mark
static const unsigned long BK_FADE_MS = 700;   // dissolve duration
void tickBootSplashFade();

// Paint the COMPLETED ember + wordmark at a given alpha (255 = full, 0 = gone).
// Owns the whole sprite. Name kept from the key era: tickBootSplashFade() and
// the draw-on hand-off both call it.
static void paintBootKeyFrame(uint8_t alpha){
  spr.fillSprite(C_BG);
  for(int r = 0; r < 5; r++) for(int c = 0; c < 5; c++) ebCell(r, c, ebMix(C_BG, ebTarget(r, c), alpha));
  ebWordmark(alpha);
}

// Non-blocking fade tick, called from the top of loop() while bootSplashActive.
// Holds the finished ember for BK_HOLD_MS, then fades it to BG over BK_FADE_MS.
// Returns with bootSplashActive=false once done; loop() then proceeds to paint
// the first real screen.
void tickBootSplashFade(){
  if(!bootSplashActive) return;
  unsigned long now = millis();
  if(bootSplashFadeStart == 0){
    bootSplashFadeStart = now;            // first tick — start the hold timer
  }
  unsigned long elapsed = now - bootSplashFadeStart;
  if(elapsed < BK_HOLD_MS){
    return;                               // holding on the finished key
  }
  unsigned long fadeT = elapsed - BK_HOLD_MS;
  if(fadeT >= BK_FADE_MS){
    // Done — clear to BG so the first real screen paints onto black.
    spr.fillSprite(C_BG);
    DISP_LOCK(); spr.pushSprite(0,0); DISP_UNLOCK();
    bootSplashActive = false;
    return;
  }
  // Smoothstep alpha 255→0 across the fade.
  float p = (float)fadeT / (float)BK_FADE_MS;
  float eased = p * p * (3.0f - 2.0f * p);
  uint8_t alpha = (uint8_t)((1.0f - eased) * 255.0f);
  paintBootKeyFrame(alpha);
  DISP_LOCK(); spr.pushSprite(0,0); DISP_UNLOCK();
}

void dispBootKeyAnimation(){
  // ── Entropy Ember draw-on ──
  // Timeline (ms). Cold boot runs the full sequence (~1.8 s, then the
  // 400 ms hold + 700 ms fade in loop()). A wake from deep sleep runs the
  // short form (~1.3 s): same shape, the flash lands where the wake
  // "beep beep" already played, and the user is back on the menu quickly.
  // 11dt (Josh, 23 Nov 2026): cold boot tightened from 2.9 s to 1.8 s. It
  // blocks start-up (the SE and G0 checks wait behind it), so it was 1.1 s of
  // dead time on every power-on. Same sequence, same proportions.
  const bool  shortForm = g_wakeFromSleep;
  const uint32_t T_NOISE      = shortForm ?  250 :  500;   // pure noise until here
  const uint32_t T_SETTLE_END = shortForm ?  700 : 1100;   // last outer cell locks by here
  const uint32_t T_CENTRE     = shortForm ?  750 : 1150;   // centre cell lights
  const uint32_t T_FLASH      = shortForm ?  850 : 1300;   // white wave starts
  const uint32_t T_FLASH_DUR  = shortForm ?  400 :  450;
  const uint32_t T_WM         = shortForm ?  900 : 1350;   // wordmark fade-in
  const uint32_t T_WM_END     = shortForm ? 1200 : 1750;
  const uint32_t T_END        = shortForm ? 1300 : 1800;

  // Per-cell lock time: outer ring first, inner later, with jitter so no two
  // boots look alike (esp_random, hardware RNG). Centre is fixed.
  uint32_t lockAt[5][5];
  uint16_t cur[5][5];
  const uint32_t settleSpan = T_SETTLE_END - T_NOISE;
  for(int r = 0; r < 5; r++) for(int c = 0; c < 5; c++){
    int d = abs(r-2) + abs(c-2);
    if(d == 0) lockAt[r][c] = T_CENTRE;
    else       lockAt[r][c] = T_NOISE + (uint32_t)((4 - d) * (settleSpan / 4)) + (esp_random() % (settleSpan / 3 + 1));
    cur[r][c] = EB_NOISE[esp_random() & 7];
  }

  uint32_t start = millis(), lastFlicker = 0;
  while(true){
    uint32_t t = millis() - start;
    if(t > T_END) break;
    bool flickerStep = (t - lastFlicker) >= 50; if(flickerStep) lastFlicker = t;
    // noise slows as the settle progresses: probability of a cell changing
    // per 50 ms step falls from 100% to 30%
    float slow = (t <= T_NOISE) ? 0.0f : (t >= T_SETTLE_END ? 1.0f : (float)(t - T_NOISE) / (float)settleSpan);
    uint32_t keepPct = (uint32_t)(70.0f * slow);          // 0..70 % chance to KEEP the old colour

    spr.fillSprite(C_BG);
    for(int r = 0; r < 5; r++) for(int c = 0; c < 5; c++){
      uint16_t col;
      if(t >= lockAt[r][c]){
        col = ebTarget(r, c);
        if(t >= T_FLASH && t < T_FLASH + T_FLASH_DUR){
          // white wave rolling outward from the centre, fading as it goes
          float ft   = (float)(t - T_FLASH) / (float)T_FLASH_DUR;
          float wave = ft * 3.2f;
          float dd   = sqrtf((float)((r-2)*(r-2) + (c-2)*(c-2)));
          float g    = expf(-((dd - wave) * (dd - wave)) / 0.35f);
          float k    = 0.85f * g * (1.0f - 0.35f * ft);
          if(k > 0.004f) col = ebMix(col, C_EB_INK, (uint8_t)(k * 255.0f));
        }
      } else {
        if(flickerStep && (esp_random() % 100) >= keepPct)
          cur[r][c] = ((esp_random() % 100) < 4) ? C_EB_BRASS : EB_NOISE[esp_random() & 7];
        col = cur[r][c];
      }
      ebCell(r, c, col);
    }
    // wordmark fades in under the mark
    uint8_t wm = 0;
    if(t >= T_WM_END) wm = 255;
    else if(t > T_WM)  wm = (uint8_t)(255UL * (t - T_WM) / (T_WM_END - T_WM));
    ebWordmark(wm);

    dispPush();
    esp_task_wdt_reset();
    delay(16);
  }

  // ── Hand off to the non-blocking hold + fade in loop() (unchanged) ──
  paintBootKeyFrame(255);          // clean completed frame
  dispPush();
  bootSplashActive = true;
  bootSplashFadeStart = 0;          // tickBootSplashFade arms its timer on first call
}

// ── Mode splash ────────────────────────────────────────────────────────────
void showModeSplash(int mode, const char* subtitle){
  spr.fillSprite(C_BG);
  uint16_t col=modeColor(mode);
  // Header with the mode's accent dot — no full-height left bar.
  uiHeader("MODE", col);
  // Mode name as the hero, centred and large in its colour.
  fSet(F_TITLE); spr.setTextColor(col);
  fDrawCentre(modeName(mode), 120, 70); fEnd();
  // One-line description.
  fSet(F_BODY); spr.setTextColor(C_MUTED);
  fDrawCentre(modeDesc(mode), 120, 106); fEnd();
  // Divider, then the status subtitle ("Starting...", etc.).
  uiRule(140, C_VDIM);
  fSet(F_BODY); spr.setTextColor(col);
  fDrawCentre(subtitle, 120, 156); fEnd();
  dispPush();
}

// ── Mode selection ─────────────────────────────────────────────────────────
// Returns one of MODE_AUTO / MODE_NETWORK / MODE_HOTSPOT / MODE_OFFLINE.
// Display order: Auto first (recommended default), then Network, Hotspot,
// Offline. Returned value is mapped from screen-position index to the
// actual MODE_* constant before returning so the caller doesn't need to
// know the layout order.
// allowBack: when true, BTN4 cancels and returns -1 (caller treats as "no
// change"). Defaults false for the mandatory first-boot / post-WiFi-setup
// callers, where a mode MUST be committed and there's nothing to go back to.
// ── Two-door Select-Mode screen ─────────────────────────────────────────────
// Cold-boot fork: NOSTR (online, Nostr identity + watch-only BTC) or BTC
// (offline air-gapped spending). Returns DOOR_NOSTR or DOOR_BTC. Mirrors
// runModeSelection's button model (btn1 down, btn3 up, btn2 enter). No BACK —
// on a cold boot with a wallet, a door MUST be chosen to proceed.
// The logo blitters are defined further down (baked A4 masks); declared here
// so the select-mode cards can use the SAME artwork as the main-menu tiles.
void drawNostrLogo(int cx, int cy, uint16_t col, uint16_t bg);
void drawBtcLogo(int cx, int cy, uint16_t col, uint16_t bg);
