int runDoorSelection(bool offerPasskey = true){
  // 30 Oct 2026: PASSKEY is offered only on a FAVILLA_PASSKEY_DOOR build, only
  // where the caller can enter that life (not the cover-mode exit, which is
  // already an online Nostr life), and only on a unit onboarded with a passkey
  // PIN (otherwise the G0 would commit a door that can never sign).
#if defined(FAVILLA_PASSKEY_DOOR) && defined(FAVILLA_BLE_KBD)
  // 9p (Josh, 8 Nov 2026): one NOSTR door. Wi-Fi or Bluetooth is a lasting
  // choice in Network > Change mode; the NOSTR card says which one it opens.
  const bool nostrBt = offerPasskey && blek::settingOn() && nbtLoad();
#else
  const bool nostrBt = false;
#endif
#ifdef FAVILLA_PASSKEY_DOOR
  if(offerPasskey){ I2C_LOCK(); offerPasskey = favilla::se_passkey_ready(); I2C_UNLOCK(); }
#else
  (void)offerPasskey;
#endif
  // The doors offered, in order: NOSTR, BITCOIN, PASSKEY
  int doors[4]; int NDOOR = 0;
  doors[NDOOR++] = DOOR_NOSTR;
  doors[NDOOR++] = DOOR_BTC;
#ifdef FAVILLA_PASSKEY_DOOR
  if(offerPasskey) doors[NDOOR++] = DOOR_PASSKEY;
#endif
  int sel = 0;                      // NOSTR (default)
  clearButtonPending();
  auto draw=[&](){
    spr.fillSprite(C_BG);
    uiHeader("SELECT MODE", C_CYAN);
    // 23 Sep 2026 (mockup A): the Nostr-menu card pattern — icon block on the
    // left at X+34, caps title, one-line description bright on BOTH cards.
    // Selection is carried by the border + title colour only; the unselected
    // card stays fully readable. Icons are the baked main-menu masks, tinted
    // the accent when selected and C_DIM otherwise. Accents match the main
    // menu tiles: NOSTR purple, BITCOIN amber. Two 86px cards at y=44 / 140.
    // 5 Oct 2026 (Entropy Ember): same grid chrome as every other card on the
    // device - black, hairline; the selected door carries its accent on the
    // frame, wash and icon, with the NAME in ink and the description muted.
    // The unselected door is grey throughout until it is selected.
    // 30 Oct 2026: with the PASSKEY door the same card, three high: 58 px
    // cards (the 44 px icons keep a 7 px margin), 6 px apart, y = 40 / 104 /
    // 168. Same title and description fonts, same left edge.
    // 9k: a fourth door (NOSTR BT) shows the three-high cards, three in view,
    // scrolling with the selection, and the scroll bar the lists use.
    struct DD { const char* name; const char* desc; uint16_t col; };
    auto dd = [nostrBt](int door) -> DD {
      switch(door){
        case DOOR_NOSTR:    return { "NOSTR",   nostrBt ? "Over Bluetooth" : "Online identity", C_PURPLE };
        case DOOR_BTC:      return { "BITCOIN", "Offline signing", C_AMBER };   // Bitcoin orange (C_BTC_ACCENT is defined later, in bitcoin_menu.inc)
        case DOOR_PASSKEY:  return { "VAULT",   "Passkeys and passwords", C_CYAN };    // the header's accent; no radio in this life either
        default:            return { "NOSTR",   "Online identity", C_PURPLE };
      }
    };
    const int VIS = NDOOR > 3 ? 3 : NDOOR;
    const int X = 12, W = 216, H = (VIS == 3) ? 58 : 86;
    const int Y0 = (VIS == 3) ? 40 : 44, PITCH = (VIS == 3) ? 64 : 96;
    int off = 0; if(NDOOR > VIS){ off = sel - 1; if(off < 0) off = 0; if(off > NDOOR - VIS) off = NDOOR - VIS; }
    if(NDOOR > VIS){ const int TX = 235, TY = Y0 + 2, TH = VIS * PITCH - 10; const int thumb = TH * VIS / NDOOR; const int ty = TY + (TH - thumb) * off / (NDOOR - VIS);
      spr.drawFastVLine(TX, TY, TH, C_EB_LINE); spr.fillRect(TX - 1, ty, 3, thumb, C_EB_BRASS); }
    for(int r=0;r<VIS;r++){
      const int i = off + r;
      int y = Y0 + r*PITCH;
      bool active=(i==sel);
      const DD Di = dd(doors[i]);
      uint16_t col=Di.col;
      uint16_t cardBg = active ? ebMix(C_BG, col, 28) : C_BG;
      spr.fillRoundRect(X,y,W,H,8,cardBg);
      spr.drawRoundRect(X,y,W,H,8, active ? col : C_EB_LINE);
      int icx = X + 34, icy = y + H/2;
      uint16_t icol = active ? col : C_EB_GREY;
      if(doors[i]==DOOR_NOSTR || doors[i]==DOOR_NOSTR_BT) drawNostrLogo(icx, icy, icol, cardBg);
      else if(doors[i]==DOOR_BTC) drawBtcLogo  (icx, icy, icol, cardBg);
      else          drawPasskeyGlyph(icx, icy, icol, cardBg);
      fSet(F_BRAND_B14); spr.setTextColor(active ? C_EB_INK : C_EB_GREY);
      { int x = X+62; for(const char* q = Di.name; *q; q++){ char cs[2] = {*q, 0}; spr.drawString(cs, x, y+H/2-20); x += spr.textWidth(cs) + 1; } }
      fEnd();
      fSet(F_BODY);
      spr.setTextColor(active ? C_MUTED : C_EB_GREY);
      spr.drawString(Di.desc, X+62, y+H/2+6);
      fEnd();
    }
    dispPush();
  };
  draw();
  while(true){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    esp_task_wdt_reset(); delay(5);
    if(btn1.isPressed()){ sel=(sel+1)%NDOOR; draw(); }
    else if(btn3.isPressed()){ sel=(sel+NDOOR-1)%NDOOR; draw(); }
    else if(btn2.isPressed()) return doors[sel];
    delay(10);
  }
}

int runModeSelection(bool allowBack=false, bool offerBt=false){
  // Display order: index into this array gives the MODE_* constant. 9p: Bluetooth
  // (the NOSTR Bluetooth life) last, only from Network > Change mode and only
  // where Bluetooth can start (a Bluetooth build with the setting on).
  int modeOrder[5] = { MODE_AUTO, MODE_NETWORK, MODE_HOTSPOT, MODE_OFFLINE, MODE_BLUETOOTH };
  const int N = offerBt ? 5 : 4, VIS = 4;
  // The mode in use: in the Bluetooth life deviceMode reads Offline (Wi-Fi never
  // starts), so the mark goes on Bluetooth instead.
  const int inUse = g_nostrBtLife ? MODE_BLUETOOTH : deviceMode;
  int sel = 0;  // start on Auto (index 0), the recommended default
  clearButtonPending();
  // Local checkmark (square-capped) — marks the currently-active mode, matching
  // the Signing/Feedback screens. Defined here since fbkDrawCheck is later.
  auto modeCheck=[&](int cx,int cy,uint16_t col){
    spr.drawWideLine(cx-5, cy-1, cx-1, cy+4, 3, col);
    spr.drawWideLine(cx-1, cy+4, cx+7, cy-7, 3, col);
  };
  auto draw=[&](){
    spr.fillSprite(C_BG);
    uiHeader("SELECT MODE", C_CYAN);
    // 4 cards, 46 px on a 49 px pitch from y=40 (bottom 232). 7 Oct 2026 (Entropy
    // Ember): the shared list card, each in its mode colour. 9p: a fifth card
    // (Bluetooth) scrolls, four in view, with the scroll bar the door screen uses.
    int off = 0; if(N > VIS){ off = sel - (VIS - 1); if(off < 0) off = 0; }
    if(N > VIS){ const int TX = 235, TY = 42, TH = VIS * 49 - 7; const int thumb = TH * VIS / N; const int ty = TY + (TH - thumb) * off / (N - VIS);
      spr.drawFastVLine(TX, TY, TH, C_EB_LINE); spr.fillRect(TX - 1, ty, 3, thumb, C_EB_BRASS); }
    for(int r=0;r<VIS && off + r < N;r++){
      const int i = off + r;
      int y=40+r*49;
      bool active=(i==sel);
      int m=modeOrder[i];
      bool current=(m==inUse);   // the mode currently in use
      uint16_t col=modeColor(m);
      char nm[16];
      uiListCard(12, y, 216, 46, active, col, uiUpper(modeName(m), nm, sizeof nm), modeDesc(m), 24);
      // Checkmark on the currently-active mode (in its colour).
      if(current) modeCheck(210, y+23, active ? col : C_EB_GREY);
    }
    dispPush();
  };
  draw();
  while(true){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    esp_task_wdt_reset(); if(wsStarted){webSocket.loop();webSocket2.loop();nip46ReplyPump();} delay(5);
    tickAutoSignSubMenu(); if(subMenuShouldYieldForApi()){ nextState=ST_MENU; break; } if(pendingApproval){ nextState=ST_APPROVAL; dispApproval(); break; }
    if(btn1.isPressed()){ sel=(sel+1)%N; draw(); }        // scroll down
    else if(btn3.isPressed()){ sel=(sel+N-1)%N; draw(); } // scroll up
    else if(btn2.isPressed()) return modeOrder[sel];      // enter
    else if(allowBack && btn4.isPressed()) return -1;     // BACK → cancel
    delay(10);
  }
  return allowBack ? -1 : modeOrder[sel];   // left for the API or an approval: no change
}

// 9p: switching between the NOSTR Wi-Fi life and the NOSTR Bluetooth life is a
// restart (Bluetooth or Wi-Fi is decided once, at boot: the controller choke
// point and the "no Wi-Fi" guarantee are per boot). The door stays NOSTR across
// the soft reset (doorSave, and the G0 holds it). ENTER restarts, BACK cancels.
static bool nostrRadioRestartAsk(bool toBt){
  spr.fillSprite(C_BG);
  uiHeader("CHANGE MODE", C_EB_BRASS);
  fSet(F_BODY);
  spr.setTextColor(C_EB_INK); fDrawCentre(toBt ? "Restart in Bluetooth mode?" : "Restart in Wi-Fi mode?", 120, 92);
  spr.setTextColor(C_MUTED);  fDrawCentre(toBt ? "Wi-Fi stays off. The Favilla" : "Bluetooth stays off until", 120, 120);
                              fDrawCentre(toBt ? "app reaches the KEY instead." : "you switch back.", 120, 140);
  fEnd();
  uiCornerAnswers("CANCEL", "RESTART");   // 11cw: the answers in the corners
  dispPush(); clearButtonPending();
  while(true){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    esp_task_wdt_reset(); delay(10);
    if(btn4.isPressed()) return false;
    if(btn2.isPressed()) return true;
  }
}

