// Returns false if the function exited because of a pending API event
// (pairing PIN, pair-confirmed splash) that runStateMachine needs to
// render. Callers should propagate the false return — repainting their
// own menu over the top would clobber the PIN overlay.
bool dispNpub(){
  if(!wallet.exists||!wallet.unlocked){ dispError("Unlock device first");errorPause(); return true; }
  char npubStr[70]={0};
  bech32Encode("npub",wallet.pub,32,npubStr);
  LOG_BOOT("[NPUB] %s\n", npubStr);

  spr.fillSprite(C_BG);

  QRCode qrN; uint8_t qrNBuf[qrcode_getBufferSize(5)];
  if(qrcode_initText(&qrN,qrNBuf,4,ECC_LOW,npubStr)==0){
    int dim=qrN.size;
    // Full-bleed: no header/footer, so the QR can use most of the 240×240
    // screen. Target ~200px and centre it.
    int sc=200/dim;
    if(sc<1) sc=1;
    int px=dim*sc;
    int ox=(240-px)/2;
    int oy=(240-px)/2;
    spr.fillRoundRect(ox-8,oy-8,px+16,px+16,8,C_QR_WHITE);
    for(int y=0;y<dim;y++) for(int x=0;x<dim;x++)
      if(qrcode_getModule(&qrN,x,y))
        spr.fillRect(ox+x*sc,oy+y*sc,sc,sc,C_BG);
  }

  dispPush();

  while(true){
    btn1.poll(); btn2.poll(); btn4.poll();
    if(btn2.isPressed() || btn4.isPressed()) return true;   // ENTER or BACK → back to Nostr cards
    // Yield to pairing PIN / pair-confirmed splash. Returning false signals
    // the caller that we exited because of a pending API event — the caller
    // must NOT repaint over the top, or the PIN overlay drawn by
    // runStateMachine on the next loop iteration will be clobbered.
    if(pendingDisplayMsg || pendingReturnToMenu) return false;
    delay(10);
  }
}

