// Generic 4-bit AA blitter: blend `col` over `bg` by each pixel's coverage.
static void blitA4(const uint8_t* bits, int W, int H, int rowBytes,
                   int cx, int cy, uint16_t col, uint16_t bg){
  int ox = cx - W/2, oy = cy - H/2;
  for(int y=0;y<H;y++){
    const uint8_t* row = &bits[y*rowBytes];
    for(int x=0;x<W;x++){
      uint8_t nib = (x&1) ? (row[x>>1] & 0x0F) : (row[x>>1] >> 4);
      if(!nib) continue;
      uint8_t a = (uint8_t)(nib*17);          // 0..15 → 0..255
      uint16_t px = (a>=255) ? col : blend565(col, bg, a);
      spr.drawPixel(ox+x, oy+y, px);
    }
  }
}

// Half-scale blit of the same 4-bit masks (44 px logos -> 22 px card icons),
// averaging each 2x2 block's alpha so the anti-aliasing survives. Used so the
// small card icons are the SAME artwork as the home tiles (25 Sep 2026).
static void blitA4Half(const uint8_t* bits, int W, int H, int rowBytes,
                       int cx, int cy, uint16_t col, uint16_t bg){
  int w = W/2, h = H/2, ox = cx - w/2, oy = cy - h/2;
  auto nib = [&](int x, int y)->int{ const uint8_t* row = &bits[y*rowBytes]; return (x&1) ? (row[x>>1] & 0x0F) : (row[x>>1] >> 4); };
  for(int y=0;y<h;y++) for(int x=0;x<w;x++){
    int sum = nib(2*x,2*y) + nib(2*x+1,2*y) + nib(2*x,2*y+1) + nib(2*x+1,2*y+1);   // 0..60
    if(!sum) continue;
    uint8_t a = (uint8_t)((sum*255)/60);
    spr.drawPixel(ox+x, oy+y, (a>=255) ? col : blend565(col, bg, a));
  }
}
void drawScanLogoSmall(int cx, int cy, uint16_t col, uint16_t bg);   // defined after SCAN_LOGO_A4

// Nostr logo, anti-aliased. `bg` is the colour behind the icon (card fill) so
// edge blending is correct in both selected/unselected states.
void drawNostrLogo(int cx, int cy, uint16_t col, uint16_t bg){
  blitA4(NOSTR_LOGO_A4, NOSTR_LOGO_W, NOSTR_LOGO_H, NOSTR_LOGO_ROWBYTES, cx, cy, col, bg);
}

