// CIPHER — the game's snake as a block-grid glyph: nine 8px cells with 1px
// gaps snaking left-to-right, down, right-to-left, down, tail at bottom-left.
// The head carries a 2px "eye" in the card background. Same footprint as the
// other baked tiles (35 x 35) so the 2x2 grid stays balanced. 23 Sep 2026.
void drawCipherLogo(int cx, int cy, uint16_t col, uint16_t bg){
  const int C = 8, G = 1, N = 4;                  // cell, gap, grid
  const int W = N*C + (N-1)*G;                    // 35
  int ox = cx - W/2, oy = cy - W/2;
  // path (col,row): head at (3,0) end, tail at (0,3)
  static const uint8_t path[][2] = { {0,3},{1,3},{2,3},{3,3},{3,2},{2,2},{1,2},{0,2},{0,1},{1,1},{2,1},{3,1},{3,0},{2,0},{1,0},{0,0} };
  const int len = 11;                             // draw 11 cells: tail (0,3) … head (2,1)
  for(int i=0;i<len;i++){
    int x = ox + path[i][0]*(C+G), y = oy + path[i][1]*(C+G);
    spr.fillRoundRect(x, y, C, C, 2, col);
  }
  // eye on the head cell (last drawn)
  { int hx = ox + path[len-1][0]*(C+G), hy = oy + path[len-1][1]*(C+G);
    spr.fillRect(hx + 5, hy + 2, 2, 2, bg); }
}

void drawIconPhone(int cx, int cy, uint16_t col){
  const int w = 26, h = 40, r = 6;
  int x = cx - w/2, y = cy - h/2;
  // Body outline (2px ring: outer fill in col, inner fill in bg leaves a stroke)
  spr.fillRoundRect(x, y, w, h, r, col);
  spr.fillRoundRect(x+2, y+2, w-4, h-4, r-2, C_BG);
  // Speaker slot near the top — short horizontal rounded bar
  spr.fillRoundRect(cx-5, y+6, 10, 3, 1, col);
  // Home button — small smooth dot near the bottom
  spr.fillSmoothCircle(cx, y+h-7, 3, col, C_BG);
}

// Native REMOTE icon — a broadcast / radiating signal. Centre dot with two
// mirrored arc "waves" on each side at increasing radius. Uses drawSmoothArc
// (degrees, 0 = top/12 o'clock, clockwise) so the waves are anti-aliased, not
// faceted. rOuter-rInner sets the stroke thickness.
//   cx,cy = centre of the icon. col = stroke/fill colour.
void drawIconBroadcast(int cx, int cy, uint16_t col){
  // Centre emitter dot
  spr.fillSmoothCircle(cx, cy, 4, col, C_BG);
  // Right-side waves: arcs centred at the dot, opening to the right.
  // 0deg = top, clockwise — a right-opening arc spans ~45..135deg.
  spr.drawSmoothArc(cx, cy, 12, 10, 45, 135, col, C_BG);
  spr.drawSmoothArc(cx, cy, 20, 18, 45, 135, col, C_BG);
  // Left-side waves: mirror — a left-opening arc spans ~225..315deg.
  spr.drawSmoothArc(cx, cy, 12, 10, 225, 315, col, C_BG);
  spr.drawSmoothArc(cx, cy, 20, 18, 225, 315, col, C_BG);
}

