void drawIconBust(int cx, int cy, uint16_t col){
  blitA4(BUST_ICON_A4, BUST_ICON_W, BUST_ICON_H, BUST_ICON_ROWBYTES, cx, cy, col, C_BG);
}
void drawIconQrGlyph(int cx, int cy, uint16_t col){
  const int r = 16;                 // layout radius from centre
  const int node = 5;               // node circle radius
  // Node positions (a wide "<" opening right): hub on the left, two on right.
  int hubX = cx - r,        hubY = cy;            // left hub
  int trX  = cx + r,        trY  = cy - r;        // top-right
  int brX  = cx + r,        brY  = cy + r;        // bottom-right
  // Connecting lines first (so nodes sit on top).
  spr.drawWideLine(hubX, hubY, trX, trY, 3, col);
  spr.drawWideLine(hubX, hubY, brX, brY, 3, col);
  // Three nodes.
  spr.fillSmoothCircle(hubX, hubY, node, col, C_BG);
  spr.fillSmoothCircle(trX,  trY,  node, col, C_BG);
  spr.fillSmoothCircle(brX,  brY,  node, col, C_BG);
}

// ── Main-menu grid icons ───────────────────────────────────────────────────
// All centred at (cx,cy); col = stroke/fill. Sized to read at ~36px in a grid
// cell. Outline style to match the phone/share glyphs.

// SCAN — a camera/viewfinder: rounded body with corner brackets + lens.
// ── Icon drawing kit ───────────────────────────────────────────────────────
// A small set of stroke-based helpers so every icon shares one weight and the
// set reads as a coherent family. The win over fill-and-mask: consistent,
// anti-aliased edges and rounded line caps via drawWideLine / drawSmoothArc.
#define ICON_STROKE 3   // unified stroke weight for the menu icon family

// Stroked (outline) rounded rectangle at the family weight. Drawn as nested
// drawRoundRect rings so the line has thickness without filling the centre.
static void strokeRoundRect(int x, int y, int w, int h, int r, int t, uint16_t col){
  for(int k=0;k<t;k++) spr.drawRoundRect(x+k, y+k, w-2*k, h-2*k, r-k > 0 ? r-k : 0, col);
}
// Stroked full circle (ring) at a given thickness, anti-aliased.
static void strokeCircle(int cx, int cy, int r, int t, uint16_t col){
  spr.drawSmoothArc(cx, cy, r, r - t, 0, 359, col, C_BG);
}

// SCAN — a viewfinder: four bold corner brackets + a centre lens dot. The
// brackets (not a full box) are what make it read as "scan / capture".
void drawIconScan(int cx, int cy, uint16_t col){
  const int s = 34;                  // viewfinder box size
  const int arm = 9;                 // bracket arm length
  const int t = ICON_STROKE;
  int L = cx - s/2, T = cy - s/2, R = cx + s/2, B = cy + s/2;
  // Each corner = two wide lines meeting at a right angle (rounded caps).
  // Top-left
  spr.drawWideLine(L, T, L+arm, T, t, col);  spr.drawWideLine(L, T, L, T+arm, t, col);
  // Top-right
  spr.drawWideLine(R, T, R-arm, T, t, col);  spr.drawWideLine(R, T, R, T+arm, t, col);
  // Bottom-left
  spr.drawWideLine(L, B, L+arm, B, t, col);  spr.drawWideLine(L, B, L, B-arm, t, col);
  // Bottom-right
  spr.drawWideLine(R, B, R-arm, B, t, col);  spr.drawWideLine(R, B, R, B-arm, t, col);
  // Centre lens — a small filled dot.
  spr.fillSmoothCircle(cx, cy, 4, col, C_BG);
}

// BTC — the Bitcoin "₿": vertical spine, two stacked bowls (upper smaller),
// and the two serif ticks top & bottom. Bowls use drawSmoothArc so the curves
// are clean rather than blocky.
void drawIconBtc(int cx, int cy, uint16_t col){
  const int t = ICON_STROKE;
  const int h = 30;
  int top = cy - h/2, bot = cy + h/2, mid = cy;
  int spineX = cx - 7;
  // Vertical spine.
  spr.drawWideLine(spineX, top, spineX, bot, t, col);
  // Top & bottom horizontal bars of the B, plus the middle bar.
  int barR = cx + 5;
  spr.drawWideLine(spineX, top, barR-3, top, t, col);   // top bar
  spr.drawWideLine(spineX, mid, barR-1, mid, t, col);   // middle bar
  spr.drawWideLine(spineX, bot, barR-3, bot, t, col);   // bottom bar
  // Two bowls: right-opening half-rings (arc spans ~0..180 through the right).
  // Upper bowl centred between top and mid; lower between mid and bot.
  int upCy = (top + mid)/2, loCy = (mid + bot)/2;
  int bowlR = (mid - top)/2;
  // 0deg=top, clockwise: a right-opening "D" spans 0..180.
  spr.drawSmoothArc(barR-3, upCy, bowlR, bowlR - t, 0, 180, col, C_BG);
  spr.drawSmoothArc(barR-3, loCy, bowlR, bowlR - t, 0, 180, col, C_BG);
  // Serif ticks above and below the spine.
  spr.drawWideLine(cx - 3, top - 5, cx - 3, top, t-1 > 1 ? t-1 : 1, col);
  spr.drawWideLine(cx + 1, top - 5, cx + 1, top, t-1 > 1 ? t-1 : 1, col);
  spr.drawWideLine(cx - 3, bot, cx - 3, bot + 5, t-1 > 1 ? t-1 : 1, col);
  spr.drawWideLine(cx + 1, bot, cx + 1, bot + 5, t-1 > 1 ? t-1 : 1, col);
}

// SETTINGS — a cog: a stroked hub ring with eight teeth radiating out, plus a
// small centre hole. Teeth are wide lines from just inside the ring to the tip.
void drawIconCog(int cx, int cy, uint16_t col){
  const int rTip  = 18;      // tooth tip radius
  const int rRing = 12;      // gear body ring radius
  const int t = ICON_STROKE;
  // Eight teeth at 45° steps (rounded caps from drawWideLine).
  for(int k=0;k<8;k++){
    float a = (float)k * 0.7853981634f;
    int x1 = cx + (int)(cosf(a) * (rRing - 1));
    int y1 = cy + (int)(sinf(a) * (rRing - 1));
    int x2 = cx + (int)(cosf(a) * rTip);
    int y2 = cy + (int)(sinf(a) * rTip);
    spr.drawWideLine(x1, y1, x2, y2, t + 2, col);   // teeth a touch fatter than the ring
  }
  // Gear body ring (stroked, not filled).
  strokeCircle(cx, cy, rRing, t, col);
  // Centre hole — a small stroked ring reads better than a filled dot.
  strokeCircle(cx, cy, 4, 2, col);
}

// Non-blocking bunker activation. Kicks off the relay WebSocket connection and
// returns immediately — the actual TCP/TLS/subscribe handshake then advances in
// the background via webSocket.loop() (driven each iteration by the main state
// machine). The bunker status screen reflects progress live in its top bubble
// ("Connecting" with a small spinner → "Connected" once EOSE confirms), so
// there's no separate full-screen spinner page anymore. Returns true if
// activation started (WiFi present), false if there's no WiFi.
bool bunkerActivateNonBlocking(){
  bunkerActive=true;
  bunkerLastClientResponseMs = 0;  // fresh activation
  LOG_WS("[BUNKER] Activating (non-blocking)...\n");
  LOG_WS("[BUNKER] WiFi: %s, wsStarted: %d\n", wifiConnected?"yes":"no", wsStarted);
  LOG_WS("[BUNKER] pre-TLS heap: free8=%u internalFree=%u internalLargest=%u dmaFree=%u dmaLargest=%u\n",
    (unsigned)heap_caps_get_free_size(MALLOC_CAP_8BIT),
    (unsigned)heap_caps_get_free_size(MALLOC_CAP_INTERNAL),
    (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL),
    (unsigned)heap_caps_get_free_size(MALLOC_CAP_DMA),
    (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_DMA));
  if(!wifiConnected){
    LOG_WS("[BUNKER] No WiFi!\n");
    bunkerActive=false;
    return false;
  }
  // RAM barrier: the camera and TLS can't share contiguous internal RAM. Stop
  // the camera (if resident) and verify the block came back before we try the
  // relay TLS handshake. If it can't be reclaimed, refuse — otherwise every
  // relay connection would fail the handshake and cycle forever.
  if(!ensureContigForTLS()){
    LOG_WS("[BUNKER] insufficient contiguous RAM for TLS — activation refused\n");
    bunkerActive=false;
    return false;
  }
  wsStarted=false; wsInitialised=false; ws2Initialised=false;
  signerEoseReceived=false;  // reset: must re-confirm with relay
  initWS();                  // begins the relay connection; advances in bg
  LOG_WS("[BUNKER] initWS called\n");
  bunkerRequestCount = 0;
  bunkerSignedCount = 0;
  esp_task_wdt_reset();
  return true;
}

// Two-card Nostr menu (Braun-style). Replaces the old three-item list
// (Airgap sign / Connect / Bunker). Airgap is REMOVED here — the top-level
// Scan already routes to airgap signing (SCAN_UNIVERSAL -> ST_AIRGAP_SIGN).
//
//   LOCAL  (blue, phone icon)     — "Use this KEY, paired directly to your
//                                    phone". Action = the old Connect flow
//                                    (PWA / device-IP pairing screen). LOCAL
//                                    over LAN gives FULL device control.
//   REMOTE (amber, broadcast icon — "Connect this KEY to another Nostr app,
//           + on/off pill)          anywhere". Action = instantly start bunker
//                                    activation, then land on the bunker status
//                                    screen. REMOTE over relays is signing-only.
void runNostrMenu(){
  int idx=0;  // 0 = LOCAL, 1 = REMOTE, 2 = IDENTITY
  const int N = 3;

  // Full-bleed three-card layout (no header/footer) so all three fit on the
  // 240×240 screen. top 10 + 3×68 + 2×8 gap = 230, leaving a small bottom margin.
  const int CARD_X = 12, CARD_W = 216;
  const int CARD_H = 68;
  const int CARD_TOP = 10, CARD_GAP = 8;
  auto cardY = [&](int i){ return CARD_TOP + i*(CARD_H + CARD_GAP); };

  // 5 Oct 2026 (Entropy Ember): black rows on the grid chrome - hairline,
  // accent (frame + wash + icon) only on the selected row, tracked caps name,
  // grey description. No on/off pill: REMOTE can only be entered from here
  // (BACK from the status page reboots), so the state is never "on" on this
  // screen.
  auto drawCard = [&](int i){
    int y = cardY(i);
    bool sel = (idx==i);
    uint16_t accent = (i==0) ? C_BLUE : (i==1) ? C_EB_BRASS : C_GREEN;
    uint16_t bg = sel ? ebMix(C_BG, accent, 28) : C_BG;
    spr.fillRoundRect(CARD_X, y, CARD_W, CARD_H, 8, bg);
    spr.drawRoundRect(CARD_X, y, CARD_W, CARD_H, 8, sel ? accent : C_EB_LINE);

    int iconCx = CARD_X + 34, iconCy = y + CARD_H/2;
    uint16_t iconCol = sel ? accent : C_EB_GREY;
    if(i==0)      drawIconPhone(iconCx, iconCy, iconCol);
    else if(i==1) drawIconBroadcast(iconCx, iconCy, iconCol);
    else          drawIconBust(iconCx, iconCy, iconCol);

    const int textX = CARD_X + 64;
    const char* name = i==0 ? "LOCAL" : i==1 ? "REMOTE" : "IDENTITY";
    fSet(F_BRAND_B14); spr.setTextColor(sel ? C_EB_INK : C_EB_GREY);
    { int x = textX; for(const char* q = name; *q; q++){ char cs[2] = {*q, 0}; spr.drawString(cs, x, y + 14); x += spr.textWidth(cs) + 1; } }
    fEnd();
    fSet(F_BODY); spr.setTextColor(sel ? C_MUTED : C_EB_GREY);
    spr.drawString(i==0 ? "Pair this KEY to a phone"
                 : i==1 ? "Link this KEY to an app"
                        : "Show your npub QR", textX, y + 38);
    fEnd();
  };

  auto drawMenu = [&](){
    spr.fillSprite(C_BG);
    drawCard(0);
    drawCard(1);
    drawCard(2);
    dispPush();
  };

  drawMenu();
  while(true){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    tickStatusBarInMenu(false);   // keep status live; no footer on this full-bleed screen
    esp_task_wdt_reset(); if(wsStarted){webSocket.loop();webSocket2.loop();nip46ReplyPump();} delay(5);
    tickAutoSignSubMenu(); if(subMenuShouldYieldForApi()){ nextState=ST_MENU; break; } if(pendingApproval){ nextState=ST_APPROVAL; dispApproval(); break; }
    if(btn1.isPressed()){            // SCROLL DOWN
      idx=(idx+1)%N; drawMenu();
    }
    if(btn3.isPressed()){            // SCROLL UP
      idx=(idx-1+N)%N; drawMenu();
    }
    if(btn4.isPressed()){            // BACK
      nextState=ST_MENU; return;
    }
    if(btn2.isPressed()){
      if(idx==0){
        // ── LOCAL: guided phone pairing ────────────────────────────────────
        // Three steps, driven by the phone rather than by guesswork:
        //   1. show the URL QR and wait for the PWA to announce itself
        //   2. tell them to add to the Home Screen (guidance, not a gate)
        //   3. open the camera to scan the phone's FK1 pairing QR
        // Only hellos that arrive AFTER this screen opens count — a stale
        // timestamp from an earlier visit must not skip step 1.
        const uint32_t helloBefore = pwaHelloAt;
        // Hotspot (17 Sep 2026): if no phone has joined the AP yet, open on the
        // WiFi-join QR (scan = join, no typing) and flip to the URL QR once a
        // station appears. UP/DOWN toggles the two by hand at any time.
        bool showJoin = (effectiveMode==MODE_HOTSPOT && WiFi.softAPgetStationNum()==0);
        if(showJoin) dispApJoinQr(); else dispIPScreen();
        clearButtonPending();   // the press that chose LOCAL may still be down
        bool advanced = false;

        // Step 1 — waiting for the phone to open the page.
        while(true){
          pumpInputs(); btn4.poll();
          if(btn4.isPressed()) break;                 // BACK → Nostr cards
          if(btn2.isPressed()) { advanced = true; break; }  // let them skip ahead
          if(effectiveMode==MODE_HOTSPOT){
            if(btn1.isPressed() || btn3.isPressed()){ showJoin = !showJoin; if(showJoin) dispApJoinQr(); else dispIPScreen(); }
            else if(showJoin && WiFi.softAPgetStationNum()>0){ showJoin = false; dispIPScreen(); buzzerOK(); }
          }
          // The existing /api/pair path still wins if the phone uses it:
          // returning lets runStateMachine paint the PIN overlay.
          if(pendingDisplayMsg || pendingReturnToMenu){ nextState = ST_MENU; return; }
          if(pwaHelloAt != helloBefore){              // the PWA said hello
            buzzerOK();
            advanced = true;
            break;
          }
          delay(10);
        }

        // Step 2 — Add to Home Screen. NEXT always advances; a second hello
        // (the installed app relaunching) must not skip this or bounce us on.
        if(advanced){
          const bool alreadyPaired = pwaHelloPaired;
          dispPairAddHome();
          clearButtonPending();   // don't let the press that got us here advance again
          while(true){
            pumpInputs(); btn4.poll();
            if(btn4.isPressed()){ advanced = false; break; }   // BACK → cards
            if(btn2.isPressed()) break;                        // NEXT → camera
            if(pendingDisplayMsg || pendingReturnToMenu){ nextState = ST_MENU; return; }
            delay(10);
          }
          // Step 3 — scan the phone's FK1 QR. Skip if it told us it is already
          // paired: there would be nothing to enrol and the camera is a cost.
          if(advanced && !alreadyPaired){
            // Claim the scan. Without userScanActive the safety net in loop()
            // ("stale ST_SCANNING with no owner") fires on the very next tick
            // and shuts the camera immediately — which looked exactly like the
            // NEXT press closing it, but is nothing to do with buttons.
            autoNetCancel();
            scanRouterMode  = SCAN_UNIVERSAL;   // FK1 is handled by the universal router
            userScanActive  = true;
            lastHotspotRecheck = millis();
            clearButtonPending();               // NEXT may still be physically held
            scanStart = millis();
            nextState = ST_SCANNING;
            return;
          }
        }
        drawMenu();
      } else if(idx==1) {
        // ── REMOTE: instantly start bunker activation ──
        if(effectiveMode!=MODE_NETWORK){
          dispError("Network mode only"); errorPause();
          drawMenu();
        } else if(!wallet.exists||!wallet.unlocked){
          dispError("Unlock keys first"); errorPause();
          drawMenu();
        } else if(bunkerActive){
          // Already on — go straight to the status screen. Transition eagerly
          // (same as the fresh-activate path) so no ST_MENU repaint can sneak in.
          bunkerStatusSel = 0;
          currentState = ST_BUNKER_STATUS;
          nextState    = ST_BUNKER_STATUS;
          btn1.resetHold(); btn2.resetHold();
          dispBunkerStatus();
          return;
        } else {
          // Non-blocking: kick off the relay connection and go STRAIGHT to the
          // status page. The top bubble shows "Connecting" + spinner until the
          // background handshake reaches EOSE, then flips to "Connected". No
          // separate full-screen spinner page.
          //
          // Transition EAGERLY: set currentState + paint the bunker page BEFORE
          // initWS() starts the relay, so the connection's background network
          // events (which can repaint based on currentState) never see
          // currentState==ST_MENU and flash the home grid during connect.
          bunkerStatusSel = 0;
          currentState = ST_BUNKER_STATUS;
          nextState    = ST_BUNKER_STATUS;
          bunkerActive = true;            // paint shows "Connecting" immediately
          btn1.resetHold(); btn2.resetHold();  // (mirror the ST_BUNKER_STATUS entry resets)
          dispBunkerStatus();
          bool ok = bunkerActivateNonBlocking();
          if(ok){ return; }
          // Activation failed (no WiFi) — undo the eager transition.
          bunkerActive = false;
          currentState = ST_MENU; nextState = ST_MENU;
          dispError("No WiFi"); errorPause();
          drawMenu();  // no-wifi — back to the cards
        }
      } else {
        // ── IDENTITY: show the npub QR (full-screen, blocks until BACK/ENTER) ──
        if(!dispNpub()){
          // dispNpub returned false → a pairing PIN / splash is pending; let
          // runStateMachine paint it (don't repaint our menu over the top).
          nextState = ST_MENU;
          return;
        }
        drawMenu();   // returned normally → back to the three cards
      }
    }
    delay(10);
  }
}


// ── WIFI sub-menu ──────────────────────────────────────────────────────────
// Lists all saved networks, lets the user switch to any of them, and
// includes "+ ADD NEW" (triggers captive portal) and "Back" rows.
//
// Controls:
//   BTN1 (tap)          — cycle selection
//   BTN2 (tap)          — activate selected row
//   BTN2 (hold ≥1000ms) — delete selected network (with hold-bar feedback)
//
// ── Bunker mini-menu ──────────────────────────────────────────────────────
// Opened by BTN2 from ST_BUNKER_STATUS. Three items only — kept minimal
// so it stays navigable even during NIP-46 bursts. No relays, WiFi,
// settings — those require bunker to be off.
BunkerMiniAction runBunkerMiniMenu(){
  const char* items[] = {"Show URL", "Deactivate", "Back"};
  const int N = 3;
  int sel = 0;

  auto draw = [&](){
    spr.fillSprite(C_BG);
    uiHeader("BUNKER", C_BLUE);

    int yStart = HEADER_H + 24;
    int rowH = 36;
    for(int i = 0; i < N; i++){
      int y = yStart + i * rowH;
      bool s = (i == sel);
      // Selection bar on the left
      if(s) spr.fillRect(0, y - 2, 3, rowH - 4, C_BLUE);
      fSet(F_HEAD);
      uint16_t col = s ? C_FG : C_DIM;
      if(i == 1) col = s ? C_RED : C_DIM;  // deactivate hint
      spr.setTextColor(col);
      spr.drawString(items[i], 16, y + 5);
      fEnd();
    }

    spr.drawFastHLine(0, 212, 240, C_BORDER);

    uiFooter();
    dispPush();
  };

  draw();

  // Wait for entry button release. Subtle issue: a single tap-and-release
  // of BTN2 can produce multiple "pending" events if the button bounces,
  // and the existing isPressed() consume only handles one of them. So we
  // wait for BTN2 to be observably HIGH for a sustained window, then
  // drain any pending events accumulated during entry, only THEN start
  // accepting input. This stops the "press BTN2 to enter, cursor jumps
  // from Show URL to Deactivate" symptom.
  unsigned long releaseStableSince = 0;
  bool entryReleased = false;
  while(true){
    btn1.poll(); btn2.poll();
    pumpInputs();

    if(!entryReleased){
      if(btn2.stable == HIGH){
        if(releaseStableSince == 0) releaseStableSince = millis();
        if(millis() - releaseStableSince > 80){
          // Drain any pending events that accumulated from bounce
          // during the entry press. Both buttons just to be safe.
          btn1.isPressed();
          btn2.isPressed();
          entryReleased = true;
        }
      } else {
        releaseStableSince = 0;
      }
      delay(10);
      continue;
    }

    if(btn1.isPressed()){            // SCROLL DOWN
      sel = (sel + 1) % N;
      draw();
    }
    if(btn3.isPressed()){            // SCROLL UP (V21.1)
      sel = (sel - 1 + N) % N;
      draw();
    }
    if(btn4.isPressed()){            // BACK (V21.1)
      return BMA_BACK;
    }
    if(btn2.isPressed()){
      switch(sel){
        case 0: return BMA_SHOW_URL;
        case 1: return BMA_DEACTIVATE;
        case 2: return BMA_BACK;
      }
    }
    // Yield to pairing PIN / pair-confirmed splash. Without this the PIN
    // would render but immediately get repainted by the menu redraw loop.
    // Returning BMA_NONE lets the caller treat this as a soft cancel and
    // fall back to the bunker status screen, where the state-machine's
    // own pendingDisplayMsg handler can render the PIN.
    if(pendingDisplayMsg || pendingReturnToMenu) return BMA_NONE;
    delay(10);
  }
}


// Press semantics: short tap fires on RELEASE (not press-down) so that a
// long-press to delete doesn't also trigger the short-tap action.
// Returns true if the caller should re-enter (e.g. after a delete left us
// with a stale visible item count), false if the user navigated away
// (BACK, ADD NEW, or successful connect).
// ── Entropy Ember card list + choice (7 Oct 2026) ──────────────────────────
// One scrolling list of black cards (4 visible, 46 px, 3 px gap) used by the
// Security / Network / Device / WiFi pages. names/descs are parallel arrays;
// upper=true tracks-caps the names (menu items), false leaves them as typed
// (SSIDs). checkIdx marks the item in use with a tick; dangerIdx is red.
static void dispCardList(const char* title, const char* const* names, const char* const* descs,
                         int count, int sel, uint16_t accent, bool upper = true,
                         int checkIdx = -1, int dangerIdx = -1){
  spr.fillSprite(C_BG);
  if(devUnitUnlocked() && !strcmp(title, "Device")) uiTrackLabel(DEV_UNIT_BANNER, 120, 14, C_RED, uiTrackWidth(DEV_UNIT_BANNER, 3) <= 228 ? 3 : 1);   // v19: Settings > Device
  else { char up[28]; uiTrackLabel(uiUpper(title, up, sizeof up), 120, 14, C_EB_BRASS); }   // 11cy: centred, no ember
  static const void* lastKey = nullptr; static int off = 0;
  if(lastKey != (const void*)title){ lastKey = (const void*)title; off = 0; }
  // 11cy: plain rows (uiRows) instead of cards; the names as given (no caps)
  (void)upper; (void)accent;
  uiRows(title, names, descs, count, sel, off, "LEAVE", checkIdx, dangerIdx, true);
  dispPush();
  return;
  const int VISIBLE = 4, CH = 46, PITCH = 49, Y0 = 40;
  if(count <= VISIBLE) off = 0;
  else {
    if(sel < off) off = sel;
    if(sel >= off + VISIBLE) off = sel - VISIBLE + 1;
    if(off > count - VISIBLE) off = count - VISIBLE;
    if(off < 0) off = 0;
  }
  for(int r = 0; r < VISIBLE && off + r < count; r++){
    int i = off + r, y = Y0 + r * PITCH;
    bool a = (i == sel), danger = (i == dangerIdx);
    char nm[28];
    const char* shown = upper ? uiUpper(names[i], nm, sizeof nm) : names[i];
    uint16_t col = danger ? C_RED : accent;
    uiListCard(12, y, 216, CH, a, col, shown, descs ? descs[i] : nullptr, 24,
               danger ? (a ? C_RED : ebMix(C_BG, C_RED, 150)) : 0);
    if(i == checkIdx){
      uint16_t cc = a ? col : C_EB_GREY; int cx = 208, cy = y + CH / 2;
      spr.drawWideLine(cx - 5, cy - 1, cx - 1, cy + 4, 3, cc);
      spr.drawWideLine(cx - 1, cy + 4, cx + 7, cy - 7, 3, cc);
    }
  }
  if(count > VISIBLE){
    const int TX = 237, TY = Y0 + 2, TH = VISIBLE * PITCH - 8;
    int thumb = TH * VISIBLE / count; if(thumb < 8) thumb = 8;
    int ty = TY + (TH - thumb) * off / (count - VISIBLE);
    spr.drawFastVLine(TX, TY, TH, C_EB_LINE);
    spr.fillRect(TX - 1, ty, 3, thumb, accent);
  }
  dispPush();
}
// Blocking 2..4 option chooser on the same cards. Returns the index, or -1 on BACK.
static int ebCardChoice(const char* title, const char* const* names, const char* const* descs,
                        int n, uint16_t accent, int dangerIdx = -1){
  int sel = 0;
  clearButtonPending();
  while(btn2.stable == LOW){ btn2.poll(); delay(5); }
  btn2.isPressed(); clearButtonPending();
  g_rowsYes = "CHOOSE";   // 11cy
  struct R { ~R(){ g_rowsYes = "OPEN"; } } rr;
  dispCardList(title, names, descs, n, sel, accent, true, -1, dangerIdx);
  while(true){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    tickStatusBarInMenu(false);
    esp_task_wdt_reset(); if(wsStarted){ webSocket.loop(); webSocket2.loop(); nip46ReplyPump();} delay(5);
    if(btn1.isPressed()){ sel = (sel + 1) % n; dispCardList(title, names, descs, n, sel, accent, true, -1, dangerIdx); }
    if(btn3.isPressed()){ sel = (sel + n - 1) % n; dispCardList(title, names, descs, n, sel, accent, true, -1, dangerIdx); }
    if(btn4.isPressed()) return -1;
    if(btn2.isPressed()) return sel;
    delay(10);
  }
}
// Hero value page (the Brightness grammar): ember swatch, big value, up to three
// grey lines, and a tracked-caps hint that flips to SAVED after a save.
static void ebHeroPage(const char* title, const char* val, const char* l1, const char* l2, const char* l3, bool saved){
  spr.fillSprite(C_BG);
  uiHeader(title, C_EB_BRASS);
  ebMarkSmall(96, 42, 8, 2);
  fSet(F_TITLE); spr.setTextColor(C_EB_INK); fDrawCentre(val, 120, 108); fEnd();
  fSet(F_BODY); spr.setTextColor(C_EB_GREY);
  if(l1) fDrawCentre(l1, 120, 146);
  if(l2) fDrawCentre(l2, 120, 163);
  if(l3) fDrawCentre(l3, 120, 180);
  fEnd();
  pinDrawLabel(saved ? "SAVED" : "ENTER TO SAVE", 208, saved ? C_EB_BRASS : C_EB_GREY);
  dispPush();
}
static void secToggleDraw(const char* title, int sel, const char* offDesc, const char* onDesc,
                          const char* n1, const char* n2, const char* n3);

#define WIFI_UI_MAX 14   // saved networks + Add + Back shown in the list
bool runWifiNetworksMenu(){
  if(g_airgapLife){   // 7b (4 Nov 2026, Josh's bench: offline still joined a network from this menu)
    dispError("Air-gap mode has no Wi-Fi. Change the mode to go online.");
    errorPause();
    return false;
  }
  // Disable autoreconnect while the user is browsing the network list.
  // Without this, transient WiFi drops (sometimes triggered by heavy
  // display SPI activity) cause the system to silently rejoin the
  // last network — which looks like "I went into the menu and it
  // auto-connected without me asking." Restored on exit.
  WiFi.setAutoReconnect(false);

  // Items: [0..wifiNetworkCount-1]=saved networks, then ADD NEW, FORGET ALL, BACK
  // (19 Oct 2026: Forget all - a Delete Key keeps the networks, so this is the
  // step before handing a KEY on.)
  const int ADD_IDX    = wifiNetworkCount;
  const int FORGET_IDX = wifiNetworkCount + 1;
  const int BACK_IDX   = wifiNetworkCount + 2;
  const int totalItems = wifiNetworkCount + 3;

  int selIdx = 0;
  // If currently connected, start selection on the active network
  if(wifiConnected && wifiSSID[0]){
    for(int i=0; i<wifiNetworkCount; i++){
      if(strcmp(wifiNetworks[i].ssid, wifiSSID)==0){ selIdx = i; break; }
    }
  }

  auto isCurrent = [&](int i){
    return wifiConnected && wifiSSID[0] && i < wifiNetworkCount &&
           strcmp(wifiNetworks[i].ssid, wifiSSID)==0;
  };

  auto draw = [&](){
    const char* nm[WIFI_UI_MAX];
    const char* ds[WIFI_UI_MAX];
    static char ssidBuf[WIFI_UI_MAX][24];
    int n = totalItems; if(n > WIFI_UI_MAX) n = WIFI_UI_MAX;
    int cur = -1;
    for(int i = 0; i < n; i++){
      if(i < wifiNetworkCount){
        strncpy(ssidBuf[i], wifiNetworks[i].ssid, 23); ssidBuf[i][23] = 0;
        nm[i] = ssidBuf[i];
        bool c = isCurrent(i); if(c) cur = i;
        ds[i] = c ? "Connected" : "Saved network";
      } else if(i == ADD_IDX){ nm[i] = "Add new"; ds[i] = "Set up another network"; }
      else if(i == FORGET_IDX){ nm[i] = "Forget all"; ds[i] = "Remove every saved network"; }
      else { nm[i] = "Back"; ds[i] = nullptr; }
    }
    // SSIDs stay as typed; the two action rows are caps like every menu.
    spr.fillSprite(C_BG);
    dispCardList("WIFI", nm, ds, n, selIdx, C_EB_BRASS, false, cur);
  };

  // Connect to networks[idx] with the animated spinner. Returns true on
  // success. Factored out of the old tap path unchanged.
  auto connectTo = [&](int idx) -> bool {
    char target[64];
    strncpy(target, wifiNetworks[idx].ssid, 63); target[63]=0;

    WiFi.disconnect(true); delay(100);
    LOG_NET("[WiFi] Switching to: %s\n", target);
    WiFi.begin(wifiNetworks[idx].ssid, wifiNetworks[idx].pass);

    unsigned long connStart = millis();
    bool ok = false;

    // Ember noise (flickering random squares) while we wait; on success
    // dispSuccessFor() resolves that same noise into the lit ember.
    dispEmberWorking("Connecting", "CONNECTING", target);
    {
      BgSpin _spin(C_EB_BRASS);
      while(millis() - connStart < 8000){
        if(WiFi.status() == WL_CONNECTED){ ok = true; break; }
        esp_task_wdt_reset();
        delay(8);
      }
    }

    if(ok){
      strncpy(wifiSSID, wifiNetworks[idx].ssid, 63);
      strncpy(wifiPass, wifiNetworks[idx].pass, 63);
      wifiConnected = true;
      IPAddress ip = WiFi.localIP();
      snprintf(currentIP, sizeof(currentIP), "%d.%d.%d.%d", ip[0],ip[1],ip[2],ip[3]);
      wsInitialised = false; ws2Initialised = false;
      wsStarted = false;
      // Full ring sweep-in + animated tick (continuous with the spinner above).
      dispSuccessFor("Connected", target, C_GREEN);
    } else {
      WiFi.disconnect(true);
      dispError("Connect failed");
      errorPause();
    }
    return ok;
  };

  // Delete networks[idx]. Returns true if the menu should re-enter (list
  // changed but not empty), false if it should exit (list now empty).
  auto deleteAt = [&](int idx) -> bool {
    char delName[64];
    strncpy(delName, wifiNetworks[idx].ssid, 63); delName[63]=0;

    bool wasActive = isCurrent(idx);
    wifiRemoveNetwork(idx);
    if(wasActive){
      WiFi.disconnect(true);
      wifiConnected = false;
      wifiSSID[0] = 0;
      currentIP[0] = 0;
      wsInitialised = false; ws2Initialised = false;
    }

    spr.fillSprite(C_BG);
    uiHeader("DELETED", C_RED);
    fSet(F_BODY); spr.setTextColor(C_DIM);
    char buf[80]; snprintf(buf, 80, "%s removed", delName);
    fDrawCentre(buf, 120, 110);
    fEnd();
    uiFooter();
    dispPush();
    buzzerOK();
    delay(800);

    return (wifiNetworkCount > 0);
  };

  draw();

  // Drain the menu-entry press (BTN2 is what opened this screen — wait for the
  // finger to lift before treating any press as a fresh action, so the leaked
  // press-down doesn't auto-fire on the highlighted row).
  while(btn2.stable == LOW){ btn2.poll(); delay(5); }
  btn2.isPressed();   // consume the leaked event
  clearButtonPending();

  while(true){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    pumpInputs(); // wdt + WS pump (signing requests can interrupt)

    tickAutoSignSubMenu();
    if(subMenuShouldYieldForApi()){
      nextState=ST_MENU; return false;
    }
    if(pendingApproval){
      WiFi.setAutoReconnect(true);
      nextState=ST_APPROVAL; dispApproval(); return false;
    }

    // BTN4: hardware BACK — exit to Network menu.
    if(btn4.isPressed()){
      WiFi.setAutoReconnect(true);
      return false;
    }

    // BTN1 / BTN3: cycle selection (down / up)
    if(btn1.isPressed()){ selIdx = (selIdx + 1) % totalItems; draw(); }
    if(btn3.isPressed()){ selIdx = (selIdx - 1 + totalItems) % totalItems; draw(); }

    // BTN2: enter the highlighted row.
    if(btn2.isPressed()){
      if(selIdx < wifiNetworkCount){
        // Saved network → Select / Delete choice.
        char ssid[24];
        strncpy(ssid, wifiNetworks[selIdx].ssid, 23); ssid[23]=0;
        static const char* opts[] = { "Select", "Delete" };
        static const char* optDesc[] = { "Connect to this network", "Remove it from the Key" };
        int choice = ebCardChoice(ssid, opts, optDesc, 2, C_EB_BRASS, 1);
        if(choice == 0){
          // SELECT → connect
          connectTo(selIdx);
          draw();
        } else if(choice == 1){
          // DELETE → remove, then re-enter (or exit if list now empty)
          if(deleteAt(selIdx)){
            return true;   // re-enter so the menu rebuilds with the new list
          } else {
            WiFi.setAutoReconnect(true);
            return false;  // list empty — back to Network menu
          }
        } else {
          // BACK from the choice → just repaint the list
          draw();
        }
      } else if(selIdx == ADD_IDX){
        // + Add new → captive portal (reboots into WiFi setup)
        WiFi.setAutoReconnect(true);
        { Preferences p; p.begin("device", false, NVSPART_SEC); p.putBool("provision",true); p.end(); }
        spr.fillSprite(C_BG);
        uiHeader("WIFI SETUP",C_EB_BRASS);
        fSet(F_BODY); spr.setTextColor(C_MUTED); fDrawCentre("Opening WiFi setup...",120,116); fEnd();
        dispPush();
        delay(800);
        cleanRestart();
        return false;
      } else if(selIdx == FORGET_IDX){
        static const char* fOpts[] = { "Keep", "Forget all" };
        static const char* fDesc[] = { "Leave the saved networks", "Passwords too. Cannot be undone" };
        int c = ebCardChoice("FORGET ALL?", fOpts, fDesc, 2, C_EB_BRASS, 1);
        if(c == 1){
          int n = wifiNetworkCount;
          wifiConnected = false; currentIP[0] = 0;
          wsInitialised = false; ws2Initialised = false;
          wifiClearCredentials();
          LOG_NET("[WiFi] forgot all %d saved networks\n", n);
          spr.fillSprite(C_BG);
          uiHeader("FORGOTTEN", C_RED);
          fSet(F_BODY); spr.setTextColor(C_DIM);
          fDrawCentre("All networks removed", 120, 110);
          fEnd(); uiFooter(); dispPush();
          buzzerOK(); delay(900);
          WiFi.setAutoReconnect(true);
          return false;   // list is empty: back to the Network menu
        }
        draw();
      } else {
        // Back row
        WiFi.setAutoReconnect(true);
        return false;
      }
    }

    delay(10);
  }
}


// ── NETWORK sub-menu ───────────────────────────────────────────────────────
#if defined(FAVILLA_PASSKEY_DOOR) && defined(FAVILLA_BLE_KBD)
static void btPairScreen(uint32_t& lp);   // passkey_life.inc: PAIR A PHONE (the bond, then the app)
static void btForgetScreen(uint32_t& lp);   // 11aj: FORGET PHONES
#endif
void runNetworkMenu(){
#if defined(FAVILLA_PASSKEY_DOOR) && defined(FAVILLA_BLE_KBD)
  if(g_nostrBtLife){   // 9k: no Wi-Fi in this life; Network is the phone link. 9p: and the way back to Wi-Fi
    // 11aj (12 Nov 2026, Josh): Forget phones here too, not only in VAULT mode
    static const char* it[] = {"Pair a phone", "Forget phones", "Change mode"};
    static const char* de[] = {"The iPhone and the Favilla app", "This KEY forgets every phone", "Wi-Fi, offline or Bluetooth"};
    const int N = 3; int ix = 0;
    dispCardList("Network", it, de, N, ix, C_EB_BRASS);
    while(true){
      btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
      esp_task_wdt_reset(); delay(5);
      tickAutoSignSubMenu(); if(subMenuShouldYieldForApi()){ nextState=ST_MENU; return; } if(pendingApproval){ nextState=ST_APPROVAL; dispApproval(); return; }
      if(btn4.isPressed()) return;
      if(btn1.isPressed()){ ix = (ix + 1) % N; dispCardList("Network", it, de, N, ix, C_EB_BRASS); }
      else if(btn3.isPressed()){ ix = (ix + N - 1) % N; dispCardList("Network", it, de, N, ix, C_EB_BRASS); }
      if(btn2.isPressed()){
        if(ix == 0){ uint32_t lp = millis(); btPairScreen(lp); }
        else if(ix == 1){ uint32_t lp = millis(); btForgetScreen(lp); }
        else {
          const int chosen = runModeSelection(true, true);
          if(chosen >= 0 && chosen != MODE_BLUETOOTH && nostrRadioRestartAsk(false)){
            saveDeviceMode(chosen); nbtSave(false);
            LOG_BOOT("[MODE] NOSTR Bluetooth -> %s: restarting (Bluetooth stays off)\n", modeName(chosen));
            delay(120); cleanRestart(); return;
          }
        }
        drainButtonsAfterTransition(); dispCardList("Network", it, de, N, ix, C_EB_BRASS);
      }
      delay(10);
    }
  }
#endif
  int idx=0;
  int sz=3; // WIFI NETWORKS / RELAYS / CHANGE MODE / BACK
  dispCardList("Network", settingsItemsNet, settingsDescNet, sz, idx, C_EB_BRASS);
  while(true){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    tickStatusBarInMenu(false);   // no footer on the card lists
    esp_task_wdt_reset(); if(wsStarted){webSocket.loop();webSocket2.loop();nip46ReplyPump();} delay(5);
    tickAutoSignSubMenu(); if(subMenuShouldYieldForApi()){ nextState=ST_MENU; break; } if(pendingApproval){ nextState=ST_APPROVAL; dispApproval(); break; }
    if(btn1.isPressed()){            // SCROLL DOWN
      idx=(idx+1)%sz;
      dispCardList("Network", settingsItemsNet, settingsDescNet, sz, idx, C_EB_BRASS);
    }
    if(btn3.isPressed()){            // SCROLL UP (V21.1)
      idx=(idx-1+sz)%sz;
      dispCardList("Network", settingsItemsNet, settingsDescNet, sz, idx, C_EB_BRASS);
    }
    if(btn4.isPressed()){            // BACK (V21.1)
      return;
    }
    if(btn2.isPressed()){
      switch(idx){
        case 0: // WIFI — manage and switch saved networks
          if(wifiNetworkCount == 0){
            // No saved networks yet — go straight to captive portal
            { Preferences p; p.begin("device", false, NVSPART_SEC); p.putBool("provision",true); p.end(); }
            spr.fillSprite(C_BG);
            uiHeader("WIFI SETUP",C_EB_BRASS);
            fSet(F_BODY); spr.setTextColor(C_MUTED); fDrawCentre("Opening WiFi setup...",120,116); fEnd();
            dispPush();
            delay(800);
            cleanRestart(); return;
          }
          // Re-enter after a delete so the user can keep tidying up the list
          while(runWifiNetworksMenu()){
            if(wifiNetworkCount == 0) break; // last network deleted — exit
          }
          drainButtonsAfterTransition();
          dispCardList("Network", settingsItemsNet, settingsDescNet, sz, idx, C_EB_BRASS);
          break;
        case 1: // RELAYS
          relaySelIdx=0; nextState=ST_RELAYS; return;
        case 2: // CHANGE MODE
          {
#if defined(FAVILLA_PASSKEY_DOOR) && defined(FAVILLA_BLE_KBD)
            const bool offerBt = blek::settingOn() && g_doorChoice == DOOR_NOSTR;   // 9p: the NOSTR Bluetooth life, where Bluetooth can start
#else
            const bool offerBt = false;
#endif
            int chosen = runModeSelection(true, offerBt);   // BACK cancels
            if(chosen == MODE_BLUETOOTH){
              if(nostrRadioRestartAsk(true)){
                nbtSave(true);   // the Wi-Fi mode stays saved for the way back
                LOG_BOOT("[MODE] %s -> NOSTR Bluetooth: restarting (Wi-Fi stays off)\n", modeName(deviceMode));
                delay(120); cleanRestart(); return;
              }
              drainButtonsAfterTransition();
              dispCardList("Network", settingsItemsNet, settingsDescNet, sz, idx, C_EB_BRASS);
              break;
            }
            if(chosen < 0 || chosen == deviceMode){
              // Cancelled (BACK) or same mode picked — no-op. Just redraw the
              // network menu without going through teardown/setup.
              dispCardList("Network", settingsItemsNet, settingsDescNet, sz, idx, C_EB_BRASS);
              break;
            }
            applyModeChange(chosen);
            // After live mode change we return to the network menu so the
            // user can keep configuring. The status bar reflects the new
            // mode immediately on next redraw.
            dispCardList("Network", settingsItemsNet, settingsDescNet, sz, idx, C_EB_BRASS);
          }
          break;
        case 3: return; // BACK
      }
    }
    delay(10);
  }
}

// ── DEVICE sub-menu ────────────────────────────────────────────────────────
void runAutoSleepMenu(){
  Preferences p; p.begin("device", true, NVSPART_SEC);
  int mins = p.getInt("autosleep",0);
  p.end();

  unsigned long savedFlashUntil = 0; // show "Saved" briefly after a save

  auto draw = [&](){
    char buf[16];
    if(mins==0) snprintf(buf,sizeof buf,"Never"); else snprintf(buf,sizeof buf,"%d min",mins);
    ebHeroPage("AUTO SLEEP", buf, "Sleeps after inactivity", nullptr, nullptr, millis() < savedFlashUntil);
  };

  draw();
  while(true){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    tickStatusBarInMenu(false);   // no footer on this screen
    esp_task_wdt_reset(); if(wsStarted){webSocket.loop();webSocket2.loop();nip46ReplyPump();} delay(5);
    // Clear the "Saved" flash when it expires.
    if(savedFlashUntil && millis() >= savedFlashUntil){ savedFlashUntil = 0; draw(); }
    if(btn1.isPressed()){            // DOWN = increment (wraps at 30->0)
      mins = (mins >= 30) ? 0 : mins + 1;
      draw();
    }
    if(btn3.isPressed()){            // UP = decrement (wraps 0->30)
      mins = (mins <= 0) ? 30 : mins - 1;
      draw();
    }
    if(btn4.isPressed()){            // BACK
      return;
    }
    if(btn2.isPressed()){            // SAVE — stay in menu, flash confirmation
      saveAutoSleep(mins);
      buzzerOK();
      savedFlashUntil = millis() + 1200;
      draw();
    }
    delay(10);
  }
}

// ── Device menu -> Hotspot idle ─────────────────────────────────────────────
// Same controls as Auto sleep: DOWN +1, UP -1, ENTER saves, BACK leaves.
void runHotspotIdleMenu(){
  Preferences p; p.begin("device", true, NVSPART_SEC);
  int mins = p.getInt("apidle",2);
  p.end();
  unsigned long savedFlashUntil = 0;
  auto draw = [&](){
    char buf[16];
    if(mins==0) snprintf(buf,sizeof buf,"Never"); else snprintf(buf,sizeof buf,"%d min",mins);
    ebHeroPage("HOTSPOT IDLE", buf, "Hotspot off after inactivity", "Any button turns it back on", "Session stays unlocked", millis() < savedFlashUntil);
  };

  draw();
  while(true){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    tickStatusBarInMenu(false);
    esp_task_wdt_reset(); if(wsStarted){webSocket.loop();webSocket2.loop();nip46ReplyPump();} delay(5);
    if(savedFlashUntil && millis() >= savedFlashUntil){ savedFlashUntil = 0; draw(); }
    if(btn1.isPressed()){ mins = (mins >= 30) ? 0 : mins + 1; draw(); }
    if(btn3.isPressed()){ mins = (mins <= 0) ? 30 : mins - 1; draw(); }
    if(btn4.isPressed()) return;
    if(btn2.isPressed()){
      saveHotspotIdle(mins);
      buzzerOK();
      savedFlashUntil = millis() + 1200;
      draw();
    }
    delay(10);
  }
}

// ── Key clicks toggle (30 Sep 2026) ───────────────────────────────────────
void runKeyClickMenu(){
  int sel = g_keyClick ? 1 : 0;
  while(true){
    secToggleDraw("KEY CLICKS", sel, "Events only", "Haptic tick on every press",
                  "Events: confirm, error,", "sign and wake.", nullptr);
    while(true){
      btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
      tickStatusBarInMenu(false);
      esp_task_wdt_reset(); if(wsStarted){webSocket.loop();webSocket2.loop();nip46ReplyPump();} delay(5);
      if(btn4.isPressed()) return;
      if(btn1.isPressed() || btn3.isPressed()){ sel ^= 1; break; }
      if(btn2.isPressed()){
        keyClickSet(sel == 1);
        dispSuccessFor(sel == 1 ? "Key clicks on" : "Key clicks off", "Saved", C_EB_BRASS);
        return;
      }
      delay(10);
    }
  }
}

// ── Haptic auto-calibration page (30 Sep 2026) ────────────────────────────
// Runs DRV2605 auto-cal on ENTER and shows the stored values. Do it with the
// KEY fully assembled — the case mass is part of what is measured.
void runHapticCalPage(){
  int lastResult = -1;   // -1 none, 0 fail, 1 ok
  auto draw = [&](){
    spr.fillSprite(C_BG);
    uiHeader("HAPTIC CAL",C_EB_BRASS);
    char buf[40];
    fSet(F_BODY);
    if(!haptic.ok){
      spr.setTextColor(C_RED); fDrawCentre("Driver not detected",120,90); fEnd();
    } else {
      spr.setTextColor(haptic.calValid ? C_EB_BRASS : C_EB_GREY);
      fDrawCentre(haptic.calValid ? "Calibrated" : "Not calibrated",120,78); fEnd();
      fSet(F_BODY); spr.setTextColor(C_EB_GREY);
      if(haptic.calValid){
        snprintf(buf,sizeof buf,"comp %02X  bemf %02X  gain %d",haptic.calComp,haptic.calBemf,haptic.calGain);
        fDrawCentre(buf,120,104);
      }
      fDrawCentre("ENTER = calibrate (buzzes)",120,126);
      fEnd();
      fSet(F_BODY); spr.setTextColor(haptic.openLoop ? C_EB_BRASS : C_EB_GREY);
      fDrawCentre(haptic.openLoop ? "Open loop: ON (no cal needed)" : "Open loop: off  (scroll = toggle)",120,150);
      fEnd();
      if(lastResult==1){ fSet(F_BODY); spr.setTextColor(C_EB_BRASS); fDrawCentre("Saved",120,178); fEnd(); }
      if(lastResult==0){
        fSet(F_BODY); spr.setTextColor(C_RED); fDrawCentre("Failed - check mounting",120,178); fEnd();
        snprintf(buf,sizeof buf,"st %02X go %02X c %02X b %02X",haptic.lastStatus,haptic.lastGo,haptic.lastComp,haptic.lastBemf);
        fSet(F_BODY); spr.setTextColor(C_EB_GREY); fDrawCentre(buf,120,198); fEnd();
      }
    }
    dispPush();
  };
  draw();
  while(true){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    tickStatusBarInMenu(false);
    esp_task_wdt_reset(); if(wsStarted){webSocket.loop();webSocket2.loop();nip46ReplyPump();} delay(5);
    if(btn4.isPressedSilent()) return;
    if((btn1.isPressedSilent() || btn3.isPressedSilent()) && haptic.ok){
      I2C_LOCK(); haptic.setOpenLoop(!haptic.openLoop); I2C_UNLOCK();
      delay(50); haptic.click();
      draw();
    }
    if(btn2.isPressedSilent() && haptic.ok){
      spr.fillSprite(C_BG); uiHeader("HAPTIC CAL",C_EB_BRASS);
      fSet(F_BODY); spr.setTextColor(C_EB_GREY); fDrawCentre("Calibrating...",120,110); fEnd(); dispPush();
      bool okc;
      { I2C_LOCK(); okc = haptic.autoCal(); I2C_UNLOCK(); }
      lastResult = okc ? 1 : 0;
      delay(150);
      if(okc) haptic.success(); else haptic.error();
      draw();
    }
    delay(10);
  }
}

