#ifdef FAVILLA_BLE_KBD
// F and G: Bluetooth up (one restart the first time, see rfBtEnsure), the
// KEY's own advertising (the production set, connectable, "Favilla KEY") at
// 20 to 30 ms and held there.
static bool emcBleAdvStart(){
  if(!rfBtEnsure()) return false;
  ble_gap_dtm_stop();
  blek::rfHoldFast(true);
  blek::advFast();
  LOG_NET("[EMC] BLE advertising held at 20-30 ms, %+d dBm\n", blek::rfPowerDbm());
  return true;
}
static void emcBleAdvStop(){
  blek::rfHoldFast(false);
  BLEDevice::getAdvertising()->stop();
  LOG_NET("[EMC] BLE advertising stopped\n");
}
static void emcBleAdvertising(){
  if(!emcBleAdvStart()) return;
  pmHoldWake();
  uint32_t t0 = millis(), lastHud = 0;
  while(true){
    btn4.poll(); btn2.poll();
    esp_task_wdt_reset();
    if(btn4.isPressed()) break;
    if(millis() - lastHud > 500){
      lastHud = millis();
      if(!blek::s_conn && !BLEDevice::getAdvertising()->isAdvertising()) blek::advFast();   // a phone that connected and left: back on air
      spr.fillSprite(C_BG); uiHeader("EMC  F", C_EB_BRASS);
      fSet(F_HEAD); spr.setTextColor(C_FG); fDrawCentre("BLE advertising", 120, 70); fEnd();
      char b[40];
      fSet(F_BODY); spr.setTextColor(C_TEXT2);
      snprintf(b, sizeof b, "20 to 30 ms  %+d dBm", blek::rfPowerDbm()); fDrawCentre(b, 120, 104);
      snprintf(b, sizeof b, "37 / 38 / 39   %lu s", (unsigned long)((millis() - t0) / 1000)); fDrawCentre(b, 120, 124);
      if(blek::s_conn){ spr.setTextColor(C_AMBER); fDrawCentre("A phone connected", 120, 150); }
      spr.setTextColor(C_EB_GREY); fDrawCentre("BACK to stop", 120, 200); fEnd();
      dispPush();
    }
    delay(10);
  }
  emcBleAdvStop();
  pmReleaseWake();
}
#endif

// B: every pixel changes every frame, backlight at full. SPI and PWM at their
// busiest, which is the display's worst case for emissions.
static void emcDisplayStress(){
  pmHoldWake();
  ledcWrite(TFT_BL_PIN, 1023);
  uint32_t x = 0xA5A5F00D, frames = 0, t0 = millis(), lastHud = 0;
  while(true){
    btn4.poll(); btn2.poll();
    esp_task_wdt_reset();
    if(btn4.isPressed()) break;
    for(int y = 0; y < 240; y += 8){
      for(int xx = 0; xx < 240; xx += 8){
        x ^= x << 13; x ^= x >> 17; x ^= x << 5;
        spr.fillRect(xx, y, 8, 8, (uint16_t)x);
      }
    }
    frames++;
    if(millis() - lastHud > 500){
      lastHud = millis();
      char b[32]; snprintf(b, sizeof b, "B  %lu fps", (unsigned long)(frames * 1000UL / (millis() - t0 + 1)));
      spr.fillRect(60, 110, 120, 22, C_BG); fSet(F_HEAD); spr.setTextColor(C_FG); fDrawCentre(b, 120, 113); fEnd();
    }
    dispPush();
  }
  ledcWrite(TFT_BL_PIN, blTargetDuty());
  pmReleaseWake();
}
// C: the scan preview, kept up until BACK.
static void emcCameraLive(){
  pmHoldWake();
  cameraStart();
  while(true){
    btn4.poll(); btn2.poll();
    esp_task_wdt_reset();
    if(btn4.isPressed()) break;
    dispPreview(false);
    delay(5);
  }
  cameraStop();
  pmReleaseWake();
}
// D: 1200-byte UDP broadcasts through the normal stack on whatever interface is
// up (station, or the hotspot which transmits broadcast frames with no client
// attached). Brings the hotspot up if nothing is.
static void emcRadioTraffic(bool withBle = false){
#ifdef FAVILLA_BLE_KBD
  if(withBle && !emcBleAdvStart()) return;
#else
  (void)withBle;
#endif
  pmHoldWake();
  if(WiFi.status() != WL_CONNECTED && !(WiFi.getMode() & WIFI_MODE_AP)){
    g0DoorRadioGuard();
    apBringUp();
    delay(800);
  }
  bool viaAp = !(WiFi.status() == WL_CONNECTED);
  IPAddress bc = viaAp ? IPAddress(192,168,4,255) : WiFi.broadcastIP();
  static uint8_t buf[1200];
  uint32_t x = 0x1234ABCD; for(size_t i = 0; i < sizeof buf; i++){ x ^= x << 13; x ^= x >> 17; x ^= x << 5; buf[i] = (uint8_t)x; }
  WiFiUDP udp; udp.begin(4747);
  uint32_t sent = 0, fail = 0, lastHud = 0;
  LOG_NET("[EMC] %s radio traffic via %s to %s\n", withBle ? "G" : "D", viaAp ? "hotspot" : "station", bc.toString().c_str());
  while(true){
    btn4.poll(); btn2.poll();
    esp_task_wdt_reset();
    if(btn4.isPressed()) break;
    for(int i = 0; i < 10; i++){
      if(udp.beginPacket(bc, 4747) && udp.write(buf, sizeof buf) == sizeof buf && udp.endPacket()) sent++; else fail++;
      delay(2);
    }
    if(millis() - lastHud > 500){
      lastHud = millis();
      spr.fillSprite(C_BG); uiHeader(withBle ? "EMC  G" : "EMC  D", C_EB_BRASS);
      fSet(F_HEAD); spr.setTextColor(C_FG); fDrawCentre(viaAp ? "Hotspot broadcast" : "WiFi broadcast", 120, 70); fEnd();
      char b[40];
      snprintf(b, sizeof b, "%lu packets  %lu failed", (unsigned long)sent, (unsigned long)fail);
      fSet(F_BODY); spr.setTextColor(C_TEXT2); fDrawCentre(b, 120, 104);
      snprintf(b, sizeof b, "1200 B each, 8.5 dBm cap");
      fDrawCentre(b, 120, 124);
#ifdef FAVILLA_BLE_KBD
      if(withBle){
        if(!blek::s_conn && !BLEDevice::getAdvertising()->isAdvertising()) blek::advFast();
        snprintf(b, sizeof b, "+ BLE adv 20-30 ms  %+d dBm", blek::rfPowerDbm()); fDrawCentre(b, 120, 144);
      }
#endif
      spr.setTextColor(C_EB_GREY); fDrawCentre("BACK to stop", 120, 200); fEnd();
      dispPush();
    }
  }
  udp.stop();
#ifdef FAVILLA_BLE_KBD
  if(withBle) emcBleAdvStop();
#endif
  pmReleaseWake();
}
void runEmcTests(){
  int sel = 0;
  emcDrawList(sel);
  clearButtonPending();
  while(true){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    tickStatusBarInMenu(false);
    esp_task_wdt_reset(); if(wsStarted){webSocket.loop();webSocket2.loop();nip46ReplyPump();}
    if(btn1.isPressed()){ sel = (sel + 1) % EMC_N; emcDrawList(sel); }
    if(btn3.isPressed()){ sel = (sel + EMC_N - 1) % EMC_N; emcDrawList(sel); }
    if(btn4.isPressed()) return;
    if(btn2.isPressed()){
      switch(sel){
        case 0: g_emcHold = !g_emcHold; lastActivity = millis();
                LOG_NET("[EMC] A hold %s\n", g_emcHold ? "ON" : "off"); break;
        case 1: LOG_NET("[EMC] B display stress\n"); emcDisplayStress(); break;
        case 2: LOG_NET("[EMC] C camera live\n");    emcCameraLive();    break;
        case 3: emcRadioTraffic(); break;
        case 4: LOG_NET("[EMC] E charging page\n");  runBatteryPage();   break;
#ifdef FAVILLA_BLE_KBD
        case 5: LOG_NET("[EMC] F BLE advertising\n"); emcBleAdvertising(); break;
        case 6: LOG_NET("[EMC] G BLE + Wi-Fi\n");     emcRadioTraffic(true); break;
#endif
      }
      drainButtonsAfterTransition();
      emcDrawList(sel);
    }
    delay(10);
  }
}
