// Cover mode toggle. Enabling it is a deliberate two-step: the gesture is
// shown and must be acknowledged, because someone who enables this and then
// forgets how to get out has a game console instead of a signer. The gesture
// is identical on every unit so support can always tell someone what it is.
// Shared by the two on/off pages under Security: header, an OFF card and an ON
// card (selected one framed in brass), then up to three note lines beneath.
static void secToggleDraw(const char* title, int sel, const char* offDesc, const char* onDesc,
                          const char* n1, const char* n2, const char* n3){
  fEnd();
  spr.fillSprite(C_BG);
  uiHeader(title, C_EB_BRASS);
  uiListCard(12, 40, 216, 46, sel == 0, C_EB_BRASS, "OFF", offDesc, 24);
  uiListCard(12, 90, 216, 46, sel == 1, C_EB_BRASS, "ON",  onDesc,  24);
  fSet(F_BODY);
  if(n1){ spr.setTextColor(C_EB_BRASS); fDrawCentre(n1, 120, 150); }
  spr.setTextColor(C_EB_GREY);
  if(n2) fDrawCentre(n2, 120, 170);
  if(n3) fDrawCentre(n3, 120, 188);
  fEnd();
  dispPush();
}

// Cover mode toggle. Enabling it is a deliberate two-step: the gesture is
// shown and must be acknowledged, because someone who enables this and then
// forgets how to get out has a game console instead of a signer. The gesture
// is identical on every unit so support can always tell someone what it is.
void runCoverModeMenu(){
  int sel = BOOT_TO_CIPHER ? 1 : 0;
  while(true){
    secToggleDraw("COVER MODE", sel, "Normal boot", "Boot into the CIPHER game",
                  "Leave it: hold ENTER + BACK 3s",
                  "Hides the device from a glance.",
                  "Your PIN is still the security.");
    while(true){
      pumpInputs(); btn4.poll();
      if(btn4.isPressed()) return;                       // BACK, no change
      if(btn1.isPressed() || btn3.isPressed()){ sel ^= 1; break; }
      if(btn2.isPressed()){
        saveBootToCipher(sel==1);
        dispSuccessFor(sel==1 ? "Cover mode on" : "Cover mode off",
                       sel==1 ? "Restart to take effect" : "Normal boot restored", C_EB_BRASS);
        return;
      }
      delay(10);
    }
  }
}

