// ── Security menu → Motion auto-lock ────────────────────────────────────────
// Rebuilt from the retired Fast/Balanced/Paranoid cache-policy screen. Three
// rows: Enable (on/off), Arm delay (preset cycle), Sensitivity (0–10 bar).
//   btn1 = scroll down   btn3 = scroll up   btn2 = adjust/toggle selected row
//   btn4 = back & save   hold btn1 = back & save
// Adjusting any row takes effect live; everything is saved on exit.

// Arm-delay presets (ms). btn2 on the delay row cycles through these.
static const uint32_t ML_DELAY_PRESETS[] = {
  10000UL, 30000UL, 60000UL, 120000UL, 300000UL, 600000UL
};
static const char* ML_DELAY_LABELS[] = {
  "10 sec", "30 sec", "1 min", "2 min", "5 min", "10 min"
};
static const int ML_DELAY_N = 6;

static int mlDelayIndexFor(uint32_t ms){
  int best = 3; uint32_t bestErr = 0xFFFFFFFF;  // default 2 min
  for(int i=0;i<ML_DELAY_N;i++){
    uint32_t e = ms > ML_DELAY_PRESETS[i] ? ms-ML_DELAY_PRESETS[i] : ML_DELAY_PRESETS[i]-ms;
    if(e<bestErr){bestErr=e;best=i;}
  }
  return best;
}

void dispSecuritySettings(int sel) {
  // 7 Oct 2026 (Entropy Ember): three list cards, brass accent; the value sits
  // top-right of each card, the sensitivity bar fills the description line.
  spr.fillSprite(C_BG);
  uiHeader("MOTION-LOCK", C_EB_BRASS);
  const int CH = 48, PITCH = 52, Y0 = 42;
  const char* names[3] = { "ENABLE", "ARM DELAY", "SENSITIVITY" };
  const char* descs[3] = {
    accel.ok ? "Lock on movement once armed" : "Sensor not detected",
    "Stillness before it arms",
    " " };
  for(int i = 0; i < 3; i++){
    int y = Y0 + i * PITCH; bool a = (sel == i);
    uiListCard(12, y, 216, CH, a, C_EB_BRASS, names[i], descs[i], 24);
    char vb[12]; const char* val; uint16_t vc;
    if(i == 0){ val = accel.featureEnabled ? "ON" : "OFF"; vc = accel.featureEnabled ? C_EB_BRASS : C_EB_GREY; }
    else if(i == 1){ val = ML_DELAY_LABELS[mlDelayIndexFor(accel.armDelayMs)]; vc = a ? C_EB_INK : C_EB_GREY; }
    else { snprintf(vb, sizeof vb, "%u", accel.sensitivity); val = vb; vc = a ? C_EB_INK : C_EB_GREY; }
    fSet(F_BODY); spr.setTextColor(vc); fDrawRight(val, 216, y + 6); fEnd();
    if(i == 2){
      const int seg = 16, gap = 2, bx = 24, by = y + 31;
      for(int k = 0; k < 10; k++){
        bool on = (k < accel.sensitivity);
        spr.fillRoundRect(bx + k * (seg + gap), by, seg, 7, 2, on ? (a ? C_EB_BRASS : C_EB_GREY) : C_EB_LINE);
      }
    }
  }
  dispPush();
}

void runSecuritySettings() {
  int sel = 0;
  dispSecuritySettings(sel);

  bool dirty = false;   // any change made → save on exit

  while (true) {
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    tickStatusBarInMenu(false);   // no footer on this screen — don't repaint it

    if (btn1.isPressed()) {            // SCROLL DOWN
      sel = (sel + 1) % 3;
      dispSecuritySettings(sel);
    }
    if (btn3.isPressed()) {            // SCROLL UP
      sel = (sel - 1 + 3) % 3;
      dispSecuritySettings(sel);
    }

    if (btn2.isPressed()) {            // ADJUST selected row
      if (sel == 0) {
        accel.featureEnabled = !accel.featureEnabled;
        // Re-enter / leave the state machine live so the change is honest.
        if (accel.featureEnabled && wallet.unlocked) accel.motionOnUnlock();
        else accel.motionOnLock();
      } else if (sel == 1) {
        int di = mlDelayIndexFor(accel.armDelayMs);
        di = (di + 1) % ML_DELAY_N;
        accel.armDelayMs = ML_DELAY_PRESETS[di];
        if (accel.featureEnabled && wallet.unlocked) accel.motionOnUnlock(); // restart settling
      } else { // sel == 2 — sensitivity, wraps 0..10
        accel.sensitivity = (accel.sensitivity >= 10) ? 0 : accel.sensitivity + 1;
        accel.applySensitivity();
      }
      dirty = true;
      dispSecuritySettings(sel);
    }

    if (btn4.isPressed()) {            // BACK (save if changed)
      if (dirty) saveMotionLock();
      return;
    }

    delay(10);
  }
}

// ── Settings 2×2 grid ───────────────────────────────────────────────────────
// Mirrors the home-screen grid (dispMenu): same geometry, same clockwise ring
// index, same slim footer. Four cells: Network · Security · Signing · Device.
//
// Each cell's glyph is drawn by one of the four wrappers below. They exist as
// single-call seams so a glyph can be swapped for a final/baked icon later by
// editing exactly one function — the grid renderer never draws glyph geometry
// inline.

// drawSignIcon is defined static later (success-frame helper); forward-declare
// it so the Signing glyph wrapper below can reuse it.
