static void drawSettingsDevIcon(int cx, int cy, uint16_t col, uint16_t bg){
  // blitA4 centres DEVICE_ICON at (cx,cy); col tints, bg is the blend backdrop
  // (pass the real card fill so the anti-aliased edge blends correctly in both
  // selected/unselected states, rather than hardcoding C_BG like the padlock).
  blitA4(DEVICE_ICON_A4, DEVICE_ICON_W, DEVICE_ICON_H, DEVICE_ICON_ROWBYTES, cx, cy, col, bg);
}

// Settings grid labels/accents. Order is the clockwise ring:
//   0 = top-left, 1 = top-right, 2 = bottom-right, 3 = bottom-left.
static const char*    kSetLabel[4] = { "NETWORK", "SECURITY", "SIGNING", "DEVICE" };
// 5 Oct 2026: Security was red - red is reserved for danger (the Delete key
// row keeps it); a section header is not a warning. Signing is purple (Nostr).
static const uint16_t kSetAccent[4] = { C_BLUE, C_EB_BRASS, C_PURPLE, C_GREEN };

void dispSettingsGrid(int sel){
  spr.fillSprite(C_BG);

  // ── 2×2 icon grid — identical geometry and chrome to dispMenu() (5 Oct 2026)
  {
    const int gap = 8;
    const int MXg = 12;
    const int gridTop = 12;
    const int gridBot = 208;                       // sit above the slim footer
    const int cw  = (240 - MXg*2 - gap) / 2;
    const int chh = (gridBot - gridTop - gap) / 2;

    const int cCol[4] = {0, 1, 1, 0};
    const int cRow[4] = {0, 0, 1, 1};

    for(int i=0;i<4;i++){
      int cx0 = MXg + cCol[i] * (cw + gap);
      int cy0 = gridTop + cRow[i] * (chh + gap);
      bool gsel = (sel == i);
      uint16_t accent = kSetAccent[i];
      int icx, icy;
      uint16_t cardBg = uiGridTile(cx0, cy0, cw, chh, gsel, accent, kSetLabel[i], &icx, &icy);
      uint16_t icol = gsel ? accent : C_EB_GREY;
      switch(i){
        case 0: drawSettingsNetIcon (icx, icy, icol, cardBg); break;
        case 1: drawSettingsSecIcon (icx, icy, icol, cardBg); break;
        case 2: drawSettingsSignIcon(icx, icy, icol, cardBg); break;
        case 3: drawSettingsDevIcon (icx, icy, icol, cardBg); break;
      }
    }
  }

  uiFooter();
  dispPush();
}

// ── Security submenu ────────────────────────────────────────────────────────
// Two items: Auto-lock (the motion-arm settings screen) and Delete key (the
// single destructive action, relocated here from the retired Key menu). Kept
// as a small list so the wipe stays visually separated under a red header.
// 11bz: Lock shortcut joins the list; four cards fit the screen, so the list
// scrolls (Delete key stays last, alone in red).
static const char* securityItems[] = { "Motion-lock", "Lock shortcut", "Cover mode", "Reconnect confirm", "Delete key" };
static void runLockChordMenu();
void runSecurityMenu(){
  int idx = 0;
  const int sz = 5, DEL = 4, ROWS = 4;
  // 7 Oct 2026 (Entropy Ember): list cards with a one-line description each;
  // the one destructive row carries red.
  static const char* secDesc[5] = { "Lock when it is moved", "ENTER + DOWN together lock", "Boot into the CIPHER game", "Approve each new phone", "Erase the key for good" };
  auto drawSec = [&](){
    spr.fillSprite(C_BG);
    uiHeader("SECURITY", C_EB_BRASS);
    const int top = idx < ROWS ? 0 : idx - ROWS + 1;
    for(int i = top; i < sz && i < top + ROWS; i++){
      int y = 40 + (i - top) * 49; char nm[24];
      uiListCard(12, y, 216, 46, i == idx, i == DEL ? C_RED : C_EB_BRASS, uiUpper(securityItems[i], nm, sizeof nm), secDesc[i], 24,
                 (i == DEL) ? (i == idx ? C_RED : ebMix(C_BG, C_RED, 150)) : 0);
    }
    dispPush();
  };
  drawSec();
  while(true){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    tickStatusBarInMenu(false);   // no footer on this page: don't let the 2 s tick repaint one
    esp_task_wdt_reset(); if(wsStarted){webSocket.loop();webSocket2.loop();nip46ReplyPump();} delay(5);
    tickAutoSignSubMenu(); if(subMenuShouldYieldForApi()){ nextState=ST_MENU; return; } if(pendingApproval){ nextState=ST_APPROVAL; dispApproval(); return; }
    if(btn1.isPressed()){ idx=(idx+1)%sz; drawSec(); }
    if(btn3.isPressed()){ idx=(idx-1+sz)%sz; drawSec(); }
    if(btn4.isPressed()){ return; }   // BACK → settings grid
    if(btn2.isPressed()){
      switch(idx){
        case 0: // AUTO-LOCK
          runSecuritySettings();
          drainButtonsAfterTransition();
          drawSec();
          break;
        case 1: // LOCK SHORTCUT (11bz)
          runLockChordMenu();
          drainButtonsAfterTransition();
          drawSec();
          break;
        case 2: // COVER MODE
          runCoverModeMenu();
          drainButtonsAfterTransition();
          drawSec();
          break;
        case 3: // RECONNECT CONFIRM (single-session approval)
          runReconnectConfirmMenu();
          drainButtonsAfterTransition();
          drawSec();
          break;
        case 4: { // DELETE KEY (relocated from runKeyMenu)
          // ── Screen 1: confirm ──────────────────────────────────────────
          // No footer (this is a serious page), no divider. Warning in F_HEAD
          // (bolder + larger). Cancel = BACK (btn4, the natural decline),
          // Delete = ENTER (btn2). This matches the device's button language;
          // the old mapping put Cancel on btn1 which fought muscle memory.
          spr.fillSprite(C_BG); uiHeader("DELETE KEY",C_RED);
          fSet(F_HEAD); spr.setTextColor(C_EB_INK);
          fDrawCentre("Permanently",120,50); fDrawCentre("erase key?",120,72); fEnd();
          fSet(F_BODY); spr.setTextColor(C_RED);
          fDrawCentre("This cannot be undone.",120,104); fEnd();
          uiListCard(12, 134, 216, 46, false, C_EB_BRASS, "CANCEL", "Press BACK", 24);
          uiListCard(12, 184, 216, 46, true,  C_RED,      "DELETE", "Press ENTER, then hold", 24, C_RED);
          dispPush();

          bool proceed=false, cancelled=false;
          clearButtonPending();
          while(!proceed && !cancelled){
            btn2.poll(); btn4.poll();
            tickStatusBarInMenu(false);   // no footer on this screen
            if(btn4.isPressed()) cancelled=true;   // BACK = Cancel
            if(btn2.isPressed()) proceed=true;     // ENTER = Delete → hold step
            delay(10);
          }
          if(cancelled){ drawSec(); break; }

          // ── Screen 2: hold-to-erase (5s) ───────────────────────────────
          // Deliberate, abortable: hold ENTER (btn2) for 5s. Releasing or BACK
          // aborts. 5 Oct 2026: the progress IS the ember - it goes out one
          // cell per ~385 ms, outside-in, with a falling tick for each; let go
          // and it relights. When the core dies the key is gone.
          const int EB_HOLD_OX = 96, EB_HOLD_OY = 48;
          auto drawHoldScreen = [&](float pct){
            spr.fillSprite(C_BG); uiHeader("DELETE KEY",C_RED);
            int out = ebMarkExtinguish(EB_HOLD_OX, EB_HOLD_OY, pct);
            pinDrawLabel(out ? "ERASING" : "HOLD TO ERASE", 112, out ? C_RED : C_EB_GREY);
            fSet(F_BODY); spr.setTextColor(C_MUTED);
            fDrawCentre("Release to cancel", 120, 140); fEnd();
            dispPush();
            return out;
          };
          drawHoldScreen(0.0f);

          const unsigned long HOLD_MS = 5000;
          unsigned long holdStart = 0;
          bool committed=false;
          int lastOut = 0;
          clearButtonPending();
          while(true){
            btn2.poll(); btn4.poll();
            tickStatusBarInMenu(false);
            if(btn4.isPressed()){ break; }                 // BACK aborts
            bool down = (btn2.stable == LOW);
            if(down){
              if(holdStart==0) holdStart = millis();
              float pct = (float)(millis()-holdStart)/(float)HOLD_MS;
              if(pct>1.0f) pct=1.0f;
              int out = (int)(pct * EB_HOLD_CELLS + 0.0001f); if(out > EB_HOLD_CELLS) out = EB_HOLD_CELLS;
              if(out != lastOut){
                lastOut = out;
                drawHoldScreen(pct);
                // falling ladder: 1800 Hz down to ~600 Hz across the 13 cells
                if(feedbackMode >= FEEDBACK_NORMAL) buzzerTone(1800 - (uint32_t)(out * 92), 18);
              }
              if(millis()-holdStart >= HOLD_MS){ committed=true; break; }
            } else {
              if(holdStart!=0){   // released early — relight the ember
                holdStart=0; lastOut=0;
                drawHoldScreen(0.0f);
              }
            }
            delay(10);
          }

          if(!committed){ drawSec(); break; }
          delay(400);   // let the dead ember sit for a beat before the wipe screen

          // ── Commit ─────────────────────────────────────────────────────
          deleteSlot(0);
          // 23 Sep 2026: no soft restart after a wipe — onboarding needs the
          // G0's physical-boot one-shot, so the user must power cycle. See
          // dispRestartForever.
          LOG_BOOT("[wipe] key deleted - holding the restart screen (power cycle before onboarding)\n");
          dispRestartForever("KEY DELETED", "The key has been wiped.", "Restart before setting up again.");   // never returns
          break;
        }
      }
    }
    delay(10);
  }
}

void runSettingsMenu(){
  int sel = 0;
  clearButtonPending();
  dispSettingsGrid(sel);
  while(true){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    tickStatusBarInMenu();   // keep battery/footer live in blocking menu
    esp_task_wdt_reset(); if(wsStarted){webSocket.loop();webSocket2.loop();nip46ReplyPump();} delay(5);
    tickAutoSignSubMenu(); if(subMenuShouldYieldForApi()){ nextState=ST_MENU; return; } if(pendingApproval){ nextState=ST_APPROVAL; dispApproval(); return; }

    if(btn1.isPressed()){            // CLOCKWISE
      sel=(sel+1)%4;
      dispSettingsGrid(sel);
    }
    else if(btn3.isPressed()){       // ANTICLOCKWISE
      sel=(sel+3)%4;
      dispSettingsGrid(sel);
    }
    else if(btn4.isPressed()){       // BACK → home menu
      nextState=ST_MENU; return;
    }
    else if(btn2.isPressed()){       // ENTER
      switch(sel){
        case 0: // NETWORK
          runNetworkMenu();
          if(nextState==ST_RELAYS) return;
          drainButtonsAfterTransition();
          dispSettingsGrid(sel); break;
        case 1: // SECURITY (Motion-lock + Delete key)
          {
            // A plain BACK out of Security must return to THIS grid, not escape
            // to the home menu. Only escape if the Security menu actively set an
            // escape state (API yield → ST_MENU, or approval → ST_APPROVAL) —
            // detect that by snapshotting nextState before the call: a plain
            // BACK leaves it unchanged (still ST_MENU), so we stay in the grid.
            DeviceState beforeSec = nextState;
            runSecurityMenu();
            if(nextState != beforeSec) return;   // Security requested a real escape
            drainButtonsAfterTransition();
            dispSettingsGrid(sel);
          }
          break;
        case 2: // SIGNING
          runSigningSettings();
          drainButtonsAfterTransition();
          dispSettingsGrid(sel); break;
        case 3: // DEVICE
          runDeviceMenu();
          drainButtonsAfterTransition();
          dispSettingsGrid(sel); break;
      }
    }
    delay(10);
  }
}


// ── Main menu ──────────────────────────────────────────────────────────────
void dispMenu(){
  updateMenuForMode();
  spr.fillSprite(C_BG);

  // ── Entropy Ember main menu (5 Oct 2026) ─────────────────────────────────
  // Full-bleed: no header, no rule - the grid owns the screen and the brand is
  // on the enclosure and the boot. The door we are in sits in the footer next
  // to the mode glyph. Colour: each tile keeps its function accent (Josh's
  // call, 5 Oct 2026), shown only on the SELECTED tile - frame, icon and a
  // low-alpha fill of the same hue, ink label. Idle tiles are charcoal-framed
  // with grey icon and label, so colour still means "this one". The footer
  // stays brass.

  // menuIndex is a CLOCKWISE ring index: 0=top-left, 1=top-right, 2=bottom-
  // right, 3=bottom-left. BTN1 clockwise, BTN3 anticlockwise (see ST_MENU).
  // Cipher is hidden behind a long-press of BACK (BTN4).
  {
    const int gap = 8;
    const int MXg = 12;
    const int gridTop = 12;
    const int gridBot = 208;                       // sit above the slim footer
    const int cw  = (240 - MXg*2 - gap) / 2;       // 104
    const int chh = (gridBot - gridTop - gap) / 2; // 94

    const int    cCol[4]   = {0, 1, 1, 0};
    const int    cRow[4]   = {0, 0, 1, 1};
    const char*  cLabel[4] = {"SCAN", "NOSTR", "CIPHER", "SETTINGS"};   // 23 Sep 2026: BTC tile retired — Bitcoin lives behind its own door
    const uint16_t cAcc[4] = {C_GREEN, C_PURPLE, C_EB_BRASS, C_BLUE};   // function accents (cipher = brass, the game is the brand's)

    for(int i=0;i<4;i++){
      int cx0 = MXg + cCol[i] * (cw + gap);
      int cy0 = gridTop + cRow[i] * (chh + gap);
      bool sel = (menuIndex == i);
      uint16_t accent = cAcc[i];
      int icx, icy;
      uint16_t cardBg = uiGridTile(cx0, cy0, cw, chh, sel, accent, cLabel[i], &icx, &icy);
      uint16_t icol = sel ? accent : C_EB_GREY;
      switch(i){
        case 0: drawScanLogo(icx, icy, icol, cardBg); break;
        case 1: drawNostrLogo(icx, icy, icol, cardBg); break;
        case 2: drawCipherLogo(icx, icy, icol, cardBg); break;
        case 3: drawSettingsLogo(icx, icy, icol, cardBg); break;
      }
    }
  }

  // ── Slim footer: mode glyph (left) + battery (right) ───────────────────────
  uiFooter();

  dispPush();
}

// ── PIN entry ──────────────────────────────────────────────────────────────
// ── PIN screen chrome (Entropy Ember rebrand, 5 Oct 2026) ───────────────────
// Shared by dispPin() (entry), ufDrawChrome() (unlock animation) and the
// wrong-PIN shake. Layout, top to bottom, on the 240x240 panel:
//   y 32..80   ember mark (5x5, cell 8 px, gap 2 -> 48 px square, centred);
//              it is the lock-state element and animates (see g_pinMark)
//   y 96       label, grey, tracked caps ("ENTER PIN" / "NOSTR PIN" / ...)
//   y 124      PIN position squares (10 px, 21 px pitch, re-centred for length)
//   y 178      hero digit centre (PIN_INK_CY); the ready/unlocking/failed
//              labels sit at y 170 in this zone, attempts-left at 196.
//   No chevrons, no hint line, no menu footer: the lock screen is a gate,
//   not a page — matches the Wake board.
// Squares, not dots: the kit's cells are square and the entered state is a
// filled brass cell, the active position a brass frame with a core, the empty
// positions a brass-2 frame.
#define PIN_INK_CY   178
#define PIN_SQ       10
#define PIN_SQ_PITCH 21
#define PIN_SQ_Y     124
// ── The mark's state. The ember above the label is the lock-state element:
// it resolves, bursts, goes out and shakes. Callers set this before drawing
// the chrome; dispPin() resets it to the resting state.
//   lockP  0..1  cells start as noise and lock outside-in as lockP rises
//                (1.0 = complete ember) — the boot draw-on grammar.
//   flashP 0..1  white wave rolling out from the centre (unlock burst);
//                0 or >=1 = none.
//   alpha  0..255 brightness.
//   fail   cells pulled to red, centre extinguished (charcoal): the ember is out.
//   xoff   horizontal shake offset, px (mark only; label/squares stay put).
struct PinMarkState { float lockP; float flashP; uint8_t alpha; bool fail; int xoff; };
static int  g_ebMarkOX = 96, g_ebMarkOY = 32;   // where ebMarkDraw paints (PIN screen default; sign screen moves it)
static bool g_ebMarkWhite = false;              // every lit cell ink-white (the zap strobe)
static PinMarkState g_pinMark = { 1.0f, 0.0f, 255, false, 0 };
#define PIN_MARK_OX g_ebMarkOX
#define PIN_MARK_OY g_ebMarkOY
static void ebMarkDraw(const PinMarkState& m){
  static uint16_t cur[5][5];
  static uint32_t lastStep = 0;
  static bool seeded = false;
  uint32_t now = millis();
  bool step = (now - lastStep) >= 50;
  if(step) lastStep = now;
  for(int r = 0; r < 5; r++) for(int c = 0; c < 5; c++){
    int d = abs(r-2) + abs(c-2);
    if(!seeded || (step && m.lockP < 1.0f && (esp_random() % 100) >= (uint32_t)(70.0f * m.lockP)))
      cur[r][c] = ((esp_random() % 100) < 4) ? C_EB_BRASS : EB_NOISE[esp_random() & 7];
    float thr = (d == 0) ? 0.95f : 0.05f + (float)(4 - d) * 0.22f;   // corners first, centre last
    uint16_t col;
    if(m.lockP >= thr){
      col = ebTarget(r, c);
      if(g_ebMarkWhite && col != C_EB_CHAR) col = C_EB_INK;
      if(m.fail){ col = (d == 0) ? C_EB_CHAR : ebMix(col, C_RED, 170); }
      if(m.flashP > 0.0f && m.flashP < 1.0f){
        float wave = m.flashP * 3.2f;
        float dd   = sqrtf((float)((r-2)*(r-2) + (c-2)*(c-2)));
        float g    = expf(-((dd - wave) * (dd - wave)) / 0.35f);
        float k    = 0.85f * g * (1.0f - 0.35f * m.flashP);
        if(k > 0.004f) col = ebMix(col, C_EB_INK, (uint8_t)(k * 255.0f));
      }
    } else {
      col = cur[r][c];
    }
    if(m.alpha < 255) col = ebMix(C_BG, col, m.alpha);
    spr.fillRect(PIN_MARK_OX + m.xoff + c*10, PIN_MARK_OY + r*10, 8, 8, col);   // cell 8, gap 2
  }
  seeded = true;
}
// Caps label drawn glyph-by-glyph with +1 px tracking (TFT_eSPI has none).
static void pinDrawLabel(const char* s, int y, uint16_t col){
  fSet(F_HEAD_SM); spr.setTextColor(col);
  int w = 0;
  for(const char* p = s; *p; p++){ char ch[2] = {*p, 0}; w += spr.textWidth(ch) + 1; }
  int x = 120 - (w - 1) / 2;
  for(const char* p = s; *p; p++){ char ch[2] = {*p, 0}; spr.drawString(ch, x, y); x += spr.textWidth(ch) + 1; }
  fEnd();
}
// filled : number of entered positions (pinTargetLen = all)
// active : index of the position being edited (-1 = none)
// accent : colour of the filled/active cells (brass on unlock, green on setup,
//          red on failure)
static void pinDrawChrome(const char* label, uint16_t accent, int filled, int active, int len = -1){
  if(len < 0) len = pinTargetLen;
  if(bgSpinnerRunning) bgSpinnerStop();   // a full PIN-screen paint owns the mark cell again
  spr.fillSprite(C_BG);
  ebMarkDraw(g_pinMark);
  pinDrawLabel(uiHeaderCaps(label), 96, C_EB_GREY);
  const int x0 = 120 - (PIN_SQ_PITCH * (len - 1)) / 2;
  for(int i = 0; i < len; i++){
    int cx = x0 + i * PIN_SQ_PITCH, l = cx - PIN_SQ/2, t = PIN_SQ_Y - PIN_SQ/2;
    if(i < filled){
      spr.fillRect(l, t, PIN_SQ, PIN_SQ, accent);
    } else if(i == active){
      spr.drawRect(l, t, PIN_SQ, PIN_SQ, accent);
      spr.drawRect(l+1, t+1, PIN_SQ-2, PIN_SQ-2, accent);
      spr.fillRect(cx-2, PIN_SQ_Y-2, 4, 4, accent);
    } else {
      spr.drawRect(l, t, PIN_SQ, PIN_SQ, C_EB_BRASS2);
    }
  }
}


void dispPin(){
  // Leaving the lock screen: once the unlock has succeeded and nextState has
  // moved on, nothing may repaint PIN entry (the silent network-mode repaint
  // and the mode-change path both call dispPin() while currentState is still
  // ST_PIN_ENTRY, which flashed a fresh "0" entry frame between UNLOCKED and
  // the menu — seen on video 5 Oct 2026). The lock paths that ARRIVE here set
  // nextState=ST_PIN_ENTRY before calling, so they still draw.
  if(currentState == ST_PIN_ENTRY && nextState != ST_PIN_ENTRY) return;
  const uint16_t accentCol  = C_EB_BRASS;   // 29 Oct 2026: setup was green; brass everywhere, the label names the phase

  // Two-door: during new-PIN setup the label names which PIN + entry/confirm.
  // The unlock screen is always the NOSTR door (a BTC life never shows it:
  // the ceremony boot routes straight to the door, which asks for the BTC
  // PIN on its own screen — psbtDrawSpendPin, same chrome, "BTC PIN").
  const char* hdr = "Nostr PIN";
  if(pinModeNew){
    switch(pinPhase){
      case PINPHASE_DAILY_SET:     hdr="Nostr PIN";        break;
      case PINPHASE_DAILY_CONFIRM: hdr="Confirm Nostr";    break;
      case PINPHASE_SPEND_SET:     hdr="BTC PIN";          break;
      case PINPHASE_SPEND_CONFIRM: hdr="Confirm BTC";      break;
      case PINPHASE_PASSKEY_SET:     hdr="Passkey PIN";    break;   // 30 Oct 2026
      case PINPHASE_PASSKEY_CONFIRM: hdr="Confirm passkey"; break;
      default:                     hdr="New Key";          break;
    }
  }
  // Mini ember + label + position squares + footer (shared with the unlock
  // animation so the entry screen resolves into it without a layout jump).
  if(!pinConfirm) g_pinMark = { 1.0f, 0.0f, 255, false, 0 };   // resting: complete ember
  else            g_pinMark = { 1.0f, 0.0f, 150, false, 0 };   // armed: dimmed, waiting for the press
  pinDrawChrome(hdr, accentCol, pinConfirm ? pinTargetLen : pinDigit, pinConfirm ? -1 : pinDigit);

  // ── Hero digit (editing) or confirm prompt ──────────────────────────────
  // Editing path centres the digit's visible ink on INK_CY (defined in that
  // branch) with chevrons placed symmetrically about the same centre; confirm
  // path shows a centred prompt + pill.
  if(pinConfirm){
    // All digits entered — ready to act. The dots above already show the
    // fully-entered state. dispPin() has drawn the header + dots + footer; we
    // only draw the centre element here, centred on the same INK_CY the digit
    // used so entering the last digit resolves into this element.
    const int RDY_CY = PIN_INK_CY;
    if(!pinModeNew){
      // UNLOCK ready: a CLOSED padlock (not yet verified, so not yet open) with
      // a dim track ring around it. The unlock submit handler animates this
      // through the working arc → tick after the button press (see
      // dispUnlockFrame). Label is the action, no separate "PIN ready" head.
      (void)RDY_CY;
      uiTrackLabel("ENTER TO UNLOCK", 120, 172, accentCol);   // 29 Oct 2026: tracked caps, names the button
    } else {
      // SETUP save — same padlock-in-ring element as unlock (V23 unification),
      // worded for the act. Green accent (pinModeNew) already distinguishes
      // setup from the amber unlock; the header names the exact phase.
      uiTrackLabel("ENTER TO SAVE", 120, 172, accentCol);
    }
  } else {
    // Editing — live digit, vertically centred in the zone between the dot row
    // and the footer. fDrawCentre's y is the glyph-box TOP (TFT_eSPI top-left
    // datum), so the box top is derived from INK_CY minus the ink's offset
    // within the box (DIGIT_IN_BOX).
    // ── Vertical layout: one source of truth ─────────────────────────────
    // INK_CY is where the digit's VISIBLE centre should land (midway between
    // the dot row at y≈58 and the footer at y≈220 → ~138). Everything else is
    // derived from it, so the digit and both chevrons stay locked together.
    //
    // Tuning on hardware (only two numbers):
    //   • INK_CY        — move the whole digit+chevron group up/down together.
    //   • DIGIT_IN_BOX  — ink-centre offset below the drawString y. DERIVED
    //                     from the actual .vlw metrics (not guessed):
    //                       JetBrainsMono-Bold-24: ascent=24, digit dY=18,
    //                       digit height=18 (no descender → ink bottom on
    //                       baseline). TFT_eSPI top-left datum puts the
    //                       baseline at y+ascent, so ink spans (y+6 .. y+24)
    //                       and its centre is y+15. Hence DIGIT_IN_BOX=15
    //                       lands the ink centre exactly on INK_CY.
    //                     Increase → digit moves UP; decrease → digit moves DOWN.
    const int INK_CY       = PIN_INK_CY;
    const int DIGIT_IN_BOX = 15;            // = (24 + (24-18))/2, from .vlw metrics
    const int DIGIT_TOP_Y  = INK_CY - DIGIT_IN_BOX;   // top-left y for drawString
    const int CHEV_X       = 120;

    // ── Commit pulse (effect C) ──────────────────────────────────────────
    // Subtle: the glyph ramps accent→near-white then back over the window.
    // No expanding box — just the white flash on the digit itself.
    uint16_t digitCol = C_EB_INK;      // ink digit; the commit pulse flashes it to the accent
    bool fxActive = (pinFxMs != 0);
    uint32_t fxEl = fxActive ? (millis() - pinFxMs) : 0;
    float lit = 0.0f, p = 0.0f;
    if(fxActive && fxEl < PIN_FX_DUR){
      p   = (float)fxEl / (float)PIN_FX_DUR;
      lit = (p < 0.30f) ? (p / 0.30f) : (1.0f - (p - 0.30f) / 0.70f);
      if(lit < 0) lit = 0;
      digitCol = blend565(accentCol, C_EB_INK, (uint8_t)(lit * 255.0f));
    } else if(fxActive){
      pinFxMs = 0;   // window elapsed — next redraw is clean
    }

    fSet(F_TITLE); spr.setTextColor(digitCol);
    char ch[2] = { pinBuf[pinDigit], 0 };
    fDrawCentre(ch, CHEV_X, DIGIT_TOP_Y);
    fEnd();

    // No chevrons, no hint (5 Oct 2026): the digit alone in the centre zone.
  }

  dispPush();
}

// ── 11w (11 Nov 2026, Josh: "the 3 doors to the pin page feels so clunky
// because it pauses before you can enter pins") ──────────────────────────────
// After Select Mode each door's PIN pad goes up at once (10l/10m), but the
// boot carries on underneath it for seconds (SE051, G0 door, nvs_vault mount,
// Bluetooth) and nothing polls the buttons until the real pad loop starts, so
// presses made on the pad in that time were lost. Now a small task owns the
// pad for that gap: it polls the buttons, keeps the digits (same grammar as
// every pad: UP +1, DOWN -1, ENTER next, BACK back, ENTER again submits) and
// redraws through the door's own draw function. The real pad adopts the state
// when it starts (prePinStop); a PIN fully entered and submitted in the gap is
// checked straight away. The task never touches the I2C bus except a click
// when the bus is free (a haptic write under the SE's T=1 frame would break
// it); the door's draw function pushes under DISP_LOCK itself. Cancel and the
// sleep chord are left to the real pad.
struct PrePin { volatile bool on, running; char pin[9]; int digit; bool armed, submitted; void (*draw)(const char* pin, int digit, bool armed); };
static PrePin g_prePin = {};
static void prePinClick(){ if(!i2cMutex || xSemaphoreTakeRecursive(i2cMutex, 0) != pdTRUE) return; buzzerClick(); xSemaphoreGiveRecursive(i2cMutex); }
static void prePinTask(void*){
  PrePin& P = g_prePin;
  while(P.on){
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    bool redraw = false;
    if(!P.submitted){
      if(btn3.isPressedSilent()){ if(!P.armed){ P.pin[P.digit] = ((P.pin[P.digit]-'0'+1)%10)+'0'; redraw = true; } }
      else if(btn1.isPressedSilent()){ if(!P.armed){ P.pin[P.digit] = ((P.pin[P.digit]-'0'+9)%10)+'0'; redraw = true; } }
      else if(btn4.isPressedSilent()){ if(P.armed){ P.armed = false; P.digit = PIN_NEW_LEN-1; redraw = true; } else if(P.digit > 0){ P.digit--; redraw = true; } }
      else if(btn2.isPressedSilent()){
        if(!P.armed){ if(++P.digit == PIN_NEW_LEN){ P.digit = PIN_NEW_LEN-1; P.armed = true; } redraw = true; }
        else P.submitted = true;   // the real pad checks it the moment it starts
      }
    }
    // The draw functions push through dispPush, which takes DISP_LOCK itself (a
    // plain mutex, not re-entrant): taking it here as well deadlocked the task
    // on the first press and froze every door's pad (bench, 11 Nov 2026).
    if(redraw){ lastActivity = millis(); if(P.draw) P.draw(P.pin, P.digit, P.armed); prePinClick(); }
    vTaskDelay(pdMS_TO_TICKS(10));
  }
  P.running = false;
  g_prePinTaskH = nullptr;
  vTaskDelete(nullptr);
}
static void prePinStart(void (*draw)(const char*, int, bool)){
  PrePin& P = g_prePin;
  if(P.on) return;
  memset(&P, 0, sizeof P);
  for(int i = 0; i < PIN_NEW_LEN; i++) P.pin[i] = '0'; P.pin[PIN_NEW_LEN] = 0;
  P.draw = draw; P.on = true; P.running = true;
  clearButtonPending();
  if(xTaskCreatePinnedToCore(prePinTask, "prepin", 3072, nullptr, 2, &g_prePinTaskH, 1) != pdPASS){ P.on = false; P.running = false; g_prePinTaskH = nullptr; }
}
// Ends the gap. true when the pad was touched: pin, digit, armed and submitted
// are the user's; false when nothing was pressed (start clean as before).
static bool prePinStop(char pin[9], int* digit, bool* armed, bool* submitted){
  PrePin& P = g_prePin;
  if(!P.on && !P.running) return false;
  P.on = false;
  const uint32_t t0 = millis(); while(P.running && millis() - t0 < 200) vTaskDelay(1);
  bool touched = P.digit != 0 || P.armed || P.submitted;
  for(int i = 0; !touched && i < PIN_NEW_LEN; i++) if(P.pin[i] != '0') touched = true;
  if(touched){ memcpy(pin, P.pin, 9); *digit = P.digit; *armed = P.armed; *submitted = P.submitted; }
  mbedtls_platform_zeroize(&P, sizeof P);
  return touched;
}
// the three doors' draw functions for the gap
static void prePinDrawNostr(const char* pin, int digit, bool armed){
  memcpy(pinBuf, pin, PIN_NEW_LEN); pinBuf[PIN_NEW_LEN] = 0; pinDigit = digit; pinConfirm = armed; pinFxMs = 0;
  dispPin();
}
static void prePinDrawBtc(const char* pin, int digit, bool armed);   // bitcoin_menu.inc
#ifdef FAVILLA_PASSKEY_DOOR
static void prePinDrawVault(const char* pin, int digit, bool armed);   // passkey_life.inc
#endif

// ── Motion auto-lock tick (shared by loop() and blocking submenus) ──────────
// Edge-detects the unlock state (covers all unlock/lock paths) and advances
// the BMA400 motion state machine. On a motion-triggered lock it wipes key
// material and navigates to the PIN entry screen — identical to the on-device
// lock flow. Called from loop() every iteration AND from tickStatusBarInMenu()
// so the SM keeps arming/firing while the user sits in a submenu.
void motionLockTick(){
#ifdef FAVILLA_BOARD_V4
  accel.stepTick();   // software pedometer: runs whenever the loop runs (awake), like the BMA400 engine did
#endif
  static bool prevUnlocked = false;
  if(!accel.ok) return;

  if(wallet.unlocked && !prevUnlocked)      accel.motionOnUnlock();
  else if(!wallet.unlocked && prevUnlocked) accel.motionOnLock();
  prevUnlocked = wallet.unlocked;

  if(wallet.unlocked && accel.tickMotion()){
    clearKeyCache();
    memset(wallet.seed,0,64);
    wallet.hasSeed=false;
    wallet.unlocked=false;
    UV_FORGET();
    memset(pinBuf,0,sizeof(pinBuf));
    for(int _i=0;_i<6;_i++) pinBuf[_i]='0'; pinBuf[6]=0;  // displayable '0's (not null)
    pinDigit=0; pinConfirm=false; pinModeNew=false; restoringKey=false;
    prevUnlocked=false;
    clearButtonPending();
    buzzerSignRequest();
    nextState=ST_PIN_ENTRY; dispPin();
    motionLockFired=true;   // make any blocking submenu break out to PIN entry
    LOG_BOOT("[BMA400] motion auto-lock complete → PIN entry\n");
  }
}

// ── 11bz: the lock shortcut ─────────────────────────────────────────────────
// ENTER + SCROLL DOWN (the two right-hand buttons; the scroll pair is the sleep
// chord, ENTER + BACK the verify chord on the PIN screens) pressed together
// while unlocked locks at once (11ca: instant, was a 1 s hold), exactly as motion-lock does: key cache and seed
// wiped, the SE signer locked, PIN entry. Runs where motion-lock runs (loop()
// and every blocking menu). Not on a signing approval, where ENTER means
// approve. Settings > Security > Lock shortcut, on by default.
void lockChordTick(){
  static uint32_t t0 = 0;
  if(!g_lockChordOn || !wallet.unlocked || pendingApproval || currentState == ST_APPROVAL || currentState == ST_PIN_ENTRY){ t0 = 0; return; }
  if(!(btn1.stable == LOW && btn2.stable == LOW)){ t0 = 0; return; }
  btn1.pending = false; btn2.pending = false;   // neither finger is a scroll or a select
  (void)t0;   // 11ca: instant (Josh): locks as soon as both are down, no hold
  unsigned long w = millis();   // wait for release so the lifting fingers act on nothing
  while((btn1.stable == LOW || btn2.stable == LOW) && millis() - w < 3000){ esp_task_wdt_reset(); delay(10); }
  clearKeyCache();
  memset(wallet.seed,0,64);
  wallet.hasSeed=false;
  wallet.unlocked=false;
  UV_FORGET();
  memset(pinBuf,0,sizeof(pinBuf));
  for(int _i=0;_i<6;_i++) pinBuf[_i]='0'; pinBuf[6]=0;
  pinDigit=0; pinConfirm=false; pinModeNew=false; restoringKey=false;
  clearButtonPending();
  buzzerSignRequest();
  nextState=ST_PIN_ENTRY; dispPin();
  motionLockFired=true;   // blocking submenus break out to PIN entry, as for motion-lock
  LOG_BOOT("[LOCK] lock shortcut (ENTER + DOWN) -> PIN entry\n");
}

// ── Remote (PWA) lock/unlock screen sync ────────────────────────────────────
// The /api/unlock and /api/lock handlers run in the web-server task (Core 0)
// and flip wallet.unlocked, but they cannot safely touch the TFT (it's owned
// by the main loop on Core 1). They set g_remoteLockDirty; this tick — called
// from loop() every iteration AND from tickStatusBarInMenu() so it fires even
// while the user sits in a blocking submenu — observes the flag and drives the
// on-device screen to match. The transitions mirror the on-device paths:
//   locked → unlocked  ⇒  ST_MENU      (same as on-device PIN unlock)
//   unlocked → locked  ⇒  ST_PIN_ENTRY (same as motion auto-lock)
void remoteLockTick(){
  if(!g_remoteLockDirty) return;
  g_remoteLockDirty=false;

  if(wallet.unlocked){
    // Remote UNLOCK: go to the unlocked home screen. Don't clobber a more
    // specific screen the user may already be on while unlocked (e.g. an
    // approval) — only redraw if we're currently on the lock screen.
    if(currentState==ST_PIN_ENTRY || nextState==ST_PIN_ENTRY){
      pinDigit=0; pinConfirm=false; pinModeNew=false; restoringKey=false;
      clearButtonPending();
      buzzerOK();
      nextState=ST_MENU; dispMenu();
      LOG_BOOT("[API] remote unlock → ST_MENU\n");
    }
  } else {
    // Remote LOCK: drop to the PIN entry (lock) screen. Mirror the motion-lock
    // reset so PIN entry starts clean and any open submenu breaks out.
    pinDigit=0; pinConfirm=false; pinModeNew=false; restoringKey=false;
    memset(pinBuf,0,sizeof(pinBuf));
    for(int _i=0;_i<6;_i++) pinBuf[_i]='0'; pinBuf[6]=0;  // displayable '0's (not null)
    clearButtonPending();
    buzzerSignRequest();
    nextState=ST_PIN_ENTRY; dispPin();
    remoteLockFired=true;   // make any blocking submenu break out to PIN entry
    LOG_BOOT("[API] remote lock → ST_PIN_ENTRY\n");
  }
}

// Option A pairing: handleApiSession() (web-server task, Core 0) promotes a
// pending pubkey to trusted once the sealed handshake proves possession, and
// sets fsec::g_pairPromoted. It can't touch the TFT, so this tick — called from
// loop() and from tickStatusBarInMenu() like remoteLockTick() — observes the
// flag on Core 1 and shows the canonical "Paired ✓" reveal. This is the moment
// the user's confirmation is bound to the cryptographic proof, not to the raw
// scan they approved a few seconds earlier.
void pairPromoteTick(){
  if(!fsec::g_pairPromoted) return;
  fsec::g_pairPromoted=false;
  // 9 Oct 2026: the ember resolve + burst (the burst carries the success beep),
  // matching the reconnect approve. Safe from any non-signing screen; if the
  // user has since navigated elsewhere it briefly overlays then returns to menu.
  dispEmberResolve("Paired", "PAIRED", "Phone connected", true);
  nextState=ST_MENU; dispMenu();
  LOG_BOOT("[PAIR] pending → trusted promoted; success shown\n");
}


// ── Relays ─────────────────────────────────────────────────────────────────
void dispRelays(){
  spr.fillSprite(C_BG);
  uiHeader("RELAYS", C_EB_BRASS);
  fSet(F_BODY); spr.setTextColor(C_MUTED);
  { char sub[40];
    snprintf(sub,sizeof(sub),"%d of %d enabled", relayEnabledCount(), relayCount);
    spr.drawString(sub, 14, 36); }
  fEnd();

  if(relayCount == 0){
    fSet(F_BODY); spr.setTextColor(C_TEXT2);
    fDrawCentre("No relays", 120, 110);
    fDrawCentre("Add them from the app", 120, 132);
    fEnd(); uiFooter(); dispPush(); return;
  }

  // Scrolling window — the list can hold up to RELAY_MAX and the screen fits
  // four rows, so keep the selection in view rather than paging.
  const int ROWS = 4, RH = 38;
  int first = relaySelIdx - (ROWS-1);
  if(first < 0) first = 0;
  if(first > relayCount-ROWS) first = relayCount-ROWS;
  if(first < 0) first = 0;

  for(int r=0; r<ROWS && (first+r)<relayCount; r++){
    int i = first + r;
    int y = 54 + r*RH;
    bool sel = (relaySelIdx == i);
    bool en  = relayList[i].enabled;

    // Entropy Ember: black card, brass frame + wash when selected; the state
    // is a pill (ON = filled brass, OFF = hollow grey), centred on the card.
    const int CHh = RH - 6;
    spr.fillRoundRect(12,y,216,CHh,8, sel ? ebMix(C_BG, C_EB_BRASS, 28) : C_BG);
    spr.drawRoundRect(12,y,216,CHh,8, sel ? C_EB_BRASS : C_EB_LINE);
    const int PW = 38, PH = 16, PX = 228 - 10 - PW, PY = y + (CHh - PH) / 2;
    if(en) spr.fillRoundRect(PX, PY, PW, PH, 8, C_EB_BRASS);
    else   spr.drawRoundRect(PX, PY, PW, PH, 8, C_EB_GREY);
    fSet(F_BODY); spr.setTextColor(en ? C_BG : C_EB_GREY);
    { const char* lb = en ? "ON" : "OFF"; int tw = spr.textWidth(lb);
      spr.drawString(lb, PX + (PW - tw) / 2, PY); }
    fEnd();

    // Host, trimmed to fit. Long relay names are common and an overflow would
    // run straight through the pill.
    fSet(F_BODY); spr.setTextColor(sel?C_EB_INK:C_EB_GREY);
    { char nm[32];
      strncpy(nm, relayList[i].url, sizeof(nm)-1); nm[sizeof(nm)-1]=0;
      while(strlen(nm) > 3 && spr.textWidth(nm) > 150) nm[strlen(nm)-1] = 0;
      spr.drawString(nm, 22, y+9); }
    fEnd();
  }

  if(relayCount > ROWS){
    fSet(F_BODY); spr.setTextColor(C_DIM);
    { char pos[16]; snprintf(pos,sizeof(pos),"%d/%d", relaySelIdx+1, relayCount);
      fDrawCentre(pos, 120, 206); }
    fEnd();
  }
  uiFooter();
  dispPush();
}

// ── Waiting / bunker ────────────────────────────────────────────────────────
// Spinner cadence: 60 frames per rotation, ticked every 16ms = 960ms/rotation
// (close enough to the design target of 1.0s).
//
// All call sites should advance via spinTick() which respects the 16ms gate,
// or via dispLoadingFor() which handles ticking + repaint for fake-animation
// contexts. Manual `spinFrame=(spinFrame+1)%N` is deprecated.
static uint8_t spinFrame=0;
static unsigned long lastSpinMs=0;
// Spinner frame advances as a deterministic function of millis(), not
// as a "step on each call". This guarantees the spinner rotates at the
// same visual speed regardless of how often spinTick() is called or how
// long each call site's outer loop takes.
//
// Cadence: 60 frames per rotation, one full rotation per 960ms,
// → frame index = (millis() / 16) % 60.
//
// Returns true if the frame index actually changed since last call (so
// callers that conditionally redraw on tick can avoid wasted SPI
// pushes), false otherwise.
bool spinTick(){
  uint8_t newFrame = (uint8_t)((millis() / 16) % 60);
  if(newFrame == spinFrame) return false;
  spinFrame = newFrame;
  lastSpinMs = millis();
  return true;
}

// Dot-trail spinner: 8 dots distributed across a 180° arc trailing behind
// a leading position. Leading dot is largest and brightest; each trailing
// dot shrinks and dims. Cheap to render — 8× fillCircle per frame, no
// per-pixel arc math. Designed for ST7789 16-bit + 60-frame cadence.
//
// Pre-computed colour ramps avoid per-frame arithmetic. Indices 0..7 where
// 0 = leading (bright) and 7 = tail (dim). Five distinct stops; the dimmest
// trail dots collapse to a single near-black colour the LCD can resolve.
static const uint16_t SPIN_RAMP_AMBER[8] = {
  C_AMBER,   // 0 — leading: #F09000
  0xC480,    // 1
  0x9420,    // 2
  0x6300,    // 3
  0x4200,    // 4
  0x3180,    // 5
  0x2100,    // 6
  0x18C0     // 7 — tail (just above C_VDIM)
};
static const uint16_t SPIN_RAMP_GREEN[8] = {
  C_GREEN,   // 0 — leading: #80CC00
  0x6580,    // 1
  0x4500,    // 2
  0x3460,    // 3
  0x2420,    // 4
  0x1BC0,    // 5
  0x1340,    // 6
  0x0AE0     // 7 — tail
};
static const uint8_t SPIN_DOT_R[8] = {3, 3, 2, 2, 2, 1, 1, 1}; // px radius

void drawDotSpinner(int cx, int cy, int r, const uint16_t* ramp){
  // Leading angle: clockwise from 12 o'clock, one full turn per 60 frames.
  float head = -((float)spinFrame / 60.0f) * 2.0f * PI - PI/2.0f;
  const float arcSpan = PI; // 180° trail
  for(int i = 0; i < 8; i++){
    // Distribute 8 dots evenly across the trailing arc
    float a = head - (i / 7.0f) * arcSpan;
    int dx = cx + (int)(r * cos(a));
    int dy = cy + (int)(r * sin(a));
    spr.fillCircle(dx, dy, SPIN_DOT_R[i], ramp[i]);
  }
}

void drawSpinnerRing(int cx,int cy,int r,int dotR){
  drawDotSpinner(cx, cy, r, SPIN_RAMP_AMBER);
}

void drawSpinnerRingGreen(int cx,int cy,int r,int dotR){
  drawDotSpinner(cx, cy, r, SPIN_RAMP_GREEN);
}

// Animated loading screen — call repeatedly while waiting
// col: C_AMBER for neutral, C_GREEN for crypto ops
void dispLoading(const char* title, const char* line1, const char* line2, uint16_t col){
  g_signWorkingArmed = false;   // a ring screen follows: never animate the ember over it
  spr.fillSprite(C_BG);
  uiHeader(title, col);
  if(col==C_GREEN) drawSpinnerRingGreen(120,106,28,5);
  else drawSpinnerRing(120,106,28,5);
  fSet(F_HEAD); spr.setTextColor(C_MUTED);
  fDrawCentre(line1, 120, 150);
  fEnd();
  if(line2){
    fSet(F_BODY); spr.setTextColor(C_VDIM);
    fDrawCentre(line2, 120, 174);
    fEnd();
  }
  dispPush();
}

// ── Success / failure rendering ────────────────────────────────────────────
// The success tick is rendered using TFT_eSPI's anti-aliased primitives
// (drawSmoothArc, drawWideLine, fillSmoothCircle) which compute sub-pixel
// coverage and blend against the background colour. This costs more per
// frame than the hard-edged drawCircle/drawLine, but for a one-shot success
// screen the visual jump is significant — proper smooth curves and round
// caps instead of stair-stepped diagonals.
//
// Geometry (matches the reference image — bold tick, thin ring frame):
//   Ring:  centre (120, 110), outer r=46, thickness 2px
//   Tick:  shortStart (96, 112) → elbow (113, 130) → longEnd (145, 92)
//          stroke 7px wide, round caps via fillSmoothCircle at endpoints
//   Halo:  matched dim outer band, draws first so bright sits on top

#define SUCC_CX        120
#define SUCC_CY        110
#define SUCC_RING_R    46     // outer radius
#define SUCC_RING_T    2      // ring thickness (px)
#define SUCC_TICK_W    7      // tick stroke width
#define SUCC_TICK_HALO 9      // halo width (1px wider each side)
#define SUCC_TICK_SX   96
#define SUCC_TICK_SY   112
#define SUCC_TICK_EX   113    // elbow
#define SUCC_TICK_EY   130
#define SUCC_TICK_LX   145
#define SUCC_TICK_LY   92

// Halo colour — green ramp 600 (#3B6D11), provides soft outer band against
// the pure-black background. RGB565 = 0x3B68 (approx).
#define C_GREEN_HALO   0x3B68

// Render a single frame of the success animation.
//   ringPct : 0..1 — circle sweep progress (0=invisible, 1=full ring)
//   tickPct : 0..1 — tick stroke progress (0=invisible, 0.5=short leg done,
//                                          1.0=both legs done)
// At ringPct=1, tickPct=1 this is the final static success frame.
__attribute__((unused)) static void paintSuccessFrame(const char* title, const char* msg, uint16_t col,
                              float ringPct, float tickPct){
  spr.fillSprite(C_BG);
  uiHeader(title, col);

  // ── Ring sweep ─────────────────────────────────────────────────────────
  // drawSmoothArc takes degrees, 0 = top (12 o'clock), clockwise.
  // We sweep from 0 to (360 * ringPct).
  if(ringPct > 0.0f){
    int endAngle = (int)(360.0f * ringPct);
    if(endAngle < 1) endAngle = 1;
    if(endAngle > 360) endAngle = 360;
    int outerR = SUCC_RING_R;
    int innerR = SUCC_RING_R - SUCC_RING_T;
    // Halo pass: 1px outside the bright ring
    spr.drawSmoothArc(SUCC_CX, SUCC_CY, outerR + 1, outerR,
                      0, endAngle, C_GREEN_HALO, C_BG, true);
    // Bright core
    spr.drawSmoothArc(SUCC_CX, SUCC_CY, outerR, innerR,
                      0, endAngle, col, C_BG, true);
  }

  // ── Tick stroke ────────────────────────────────────────────────────────
  if(tickPct > 0.0f){
    // Compute the current end of the tick path
    int sx = SUCC_TICK_SX, sy = SUCC_TICK_SY;
    int ex = SUCC_TICK_EX, ey = SUCC_TICK_EY;
    int lx = SUCC_TICK_LX, ly = SUCC_TICK_LY;

    int curX, curY;
    bool drawShortLeg = true;
    bool drawElbow    = false;
    bool drawLongLeg  = false;

    if(tickPct <= 0.5f){
      // Short leg in progress
      float t = tickPct / 0.5f;
      curX = sx + (int)((ex - sx) * t);
      curY = sy + (int)((ey - sy) * t);
    } else {
      // Short leg complete, long leg in progress
      drawElbow   = true;
      drawLongLeg = true;
      float t = (tickPct - 0.5f) / 0.5f;
      curX = ex + (int)((lx - ex) * t);
      curY = ey + (int)((ly - ey) * t);
    }

    // ── Halo pass — wider, dim, drawn first so bright sits on top
    // Round cap at start (always)
    spr.fillSmoothCircle(sx, sy, SUCC_TICK_HALO/2, C_GREEN_HALO, C_BG);

    if(drawShortLeg && tickPct <= 0.5f){
      // Halo line from start to current. Note: bg_color OMITTED so the
      // AA edges read existing pixels and blend correctly. If we passed
      // C_BG explicitly, the AA fringe would paint dark pixels where the
      // line touches anything that's already been drawn — producing a
      // visible seam where the two legs meet.
      spr.drawWideLine(sx, sy, curX, curY, SUCC_TICK_HALO, C_GREEN_HALO);
      spr.fillSmoothCircle(curX, curY, SUCC_TICK_HALO/2, C_GREEN_HALO, C_BG);
    } else {
      // Both legs as separate drawWideLine calls. Critically, bg_color
      // is OMITTED on both — TFT_eSPI reads existing pixels and blends
      // AA against them. Where the long leg's start-cap overlaps the
      // short leg's end-cap, both legs are green so the blend is green
      // on green, no dark seam.
      spr.drawWideLine(sx, sy, ex, ey, SUCC_TICK_HALO, C_GREEN_HALO);
      if(drawLongLeg){
        spr.drawWideLine(ex, ey, curX, curY, SUCC_TICK_HALO, C_GREEN_HALO);
        spr.fillSmoothCircle(curX, curY, SUCC_TICK_HALO/2, C_GREEN_HALO, C_BG);
      }
    }

    // ── Bright pass — narrower, on top
    spr.fillSmoothCircle(sx, sy, SUCC_TICK_W/2, col, C_BG);

    if(drawShortLeg && tickPct <= 0.5f){
      spr.drawWideLine(sx, sy, curX, curY, SUCC_TICK_W, col);
      spr.fillSmoothCircle(curX, curY, SUCC_TICK_W/2, col, C_BG);
    } else {
      // Same trick: bg_color omitted so the AA reads existing pixels.
      // The bright pass blends against the halo where it overlaps,
      // producing a soft green→halo→bg gradient at edges instead of
      // green→bg with a dark fringe in between.
      spr.drawWideLine(sx, sy, ex, ey, SUCC_TICK_W, col);
      if(drawLongLeg){
        spr.drawWideLine(ex, ey, curX, curY, SUCC_TICK_W, col);
        spr.fillSmoothCircle(curX, curY, SUCC_TICK_W/2, col, C_BG);
      }
    }
  }

  // ── Caption + status ───────────────────────────────────────────────────
  fSet(F_HEAD); spr.setTextColor(C_TEXT2);
  fDrawCentre(msg, 120, 176);
  fEnd();
  uiFooter();
  dispPush();
}

// ── Connecting (waiting) frame ───────────────────────────────────────────
// Same ring geometry as paintSuccessFrame, but drawn as a rotating partial
// arc so the ring "spins" while we wait. `phase` 0..1 rotates the arc once per
// cycle. No tick is drawn here — on success the caller hands off to
// dispSuccessFor(), which sweeps the full ring in and animates the tick, so
// the two screens read as one continuous visual.
__attribute__((unused)) static void paintConnectingFrame(const char* title, const char* msg,
                                 uint16_t col, float phase){
  spr.fillSprite(C_BG);
  uiHeader(title, col);

  const int ARC_LEN = 100;                 // degrees of the lit sweep
  int start = (int)(phase * 360.0f) % 360;
  int end   = start + ARC_LEN;
  int outerR = SUCC_RING_R;
  int innerR = SUCC_RING_R - SUCC_RING_T;

  // Dim full-circle track underneath so the spinner reads against a ghost ring.
  spr.drawSmoothArc(SUCC_CX, SUCC_CY, outerR, innerR, 0, 360, C_BORDER2, C_BG, true);

  // Lit arc — split if it wraps past 360.
  auto litArc = [&](int a0, int a1){
    spr.drawSmoothArc(SUCC_CX, SUCC_CY, outerR + 1, outerR, a0, a1, C_GREEN_HALO, C_BG, true);
    spr.drawSmoothArc(SUCC_CX, SUCC_CY, outerR, innerR, a0, a1, col, C_BG, true);
  };
  if(end <= 360){
    litArc(start, end);
  } else {
    litArc(start, 360);
    litArc(0, end - 360);
  }

  fSet(F_BODY); spr.setTextColor(C_TEXT2);
  fDrawCentre(msg, 120, 178);
  fEnd();
  uiFooter();
  dispPush();
}

// Final success frame — used wherever dispSuccess was called before.
// This is a static snapshot; for the animated reveal, use dispSuccessFor()
// which sweeps the ring and draws the tick over ~640ms.
static void ebSignFrame(const char* title, const char* label, const char* msg, float lockP, float flashP, uint8_t alpha, uint16_t labelCol);
void dispSuccess(const char* title, const char* msg, uint16_t col){
  (void)col;   // Entropy Ember: success is the lit ember, never a green tick
  char lab[32];
  ebSignFrame(title, uiUpper(title, lab, sizeof lab), msg, 1.0f, 0.0f, 255, C_EB_INK);
}

// Draw failure X (for wrong PIN etc) — kept simple, hard-edged.
// Failures don't need polish; users want them gone, not dwelt on.
void dispFailure(const char* title, const char* msg){
  spr.fillSprite(C_BG);
  uiHeader(title, C_RED);
  spr.drawSmoothCircle(120, 108, 32, C_RED, C_BG);
  // X using two wide anti-aliased lines
  spr.drawWideLine(100, 88, 140, 128, 5, C_RED, C_BG);
  spr.drawWideLine(140, 88, 100, 128, 5, C_RED, C_BG);
  fSet(F_HEAD); spr.setTextColor(C_TEXT2);
  fDrawCentre(msg, 120, 156);
  fEnd();
  uiFooter();
  dispPush();
}

// ── Animated screen helpers ───────────────────────────────────────────────
// These replace the manual `for(int f=0; f<N; f++){ spinFrame=...; disp...; delay(60); }`
// blocks. Each ticks at 16ms cadence so the spinner stays smooth.
void dispLoadingFor(uint32_t ms, const char* title, const char* line1,
                    const char* line2, uint16_t col){
  uint32_t start = millis();
  // Full paint on first frame so the static UI is in the buffer.
  dispLoading(title, line1, line2, col);
  while(millis() - start < ms){
    if(spinTick()){
      // Subsequent frames: region push only — ~23× less SPI traffic.
      spinnerTickLoading(col);
    }
    delay(2);
  }
}
// Fixed timing for all success/failure animations. Every operation that
// completes successfully feels the same — same reveal cadence, same
// hold time. Callers don't pick a duration; this is the contract.
//
//   Phase 1 (0..350ms):   ring sweeps in (eased)
//   Phase 2 (350..750ms): tick strokes in (linear)
//   Phase 3 (750..1150ms): completion beat — eye registers the success
#define SUCC_RING_MS    200
#define SUCC_TICK_MS    240
#define SUCC_HOLD_MS    160
#define SUCC_TOTAL_MS   (SUCC_RING_MS + SUCC_TICK_MS + SUCC_HOLD_MS)

// Entropy Ember success: the noise resolves into the lit ember, bursts white,
// holds, dissolves (same as the PIN unlock and signing). Replaces the old green
// ring + tick everywhere; the colour argument is ignored by design.
void dispSuccessFor(const char* title, const char* msg, uint16_t col){
  (void)col;
  char lab[32];
  dispEmberResolve(title, uiUpper(title, lab, sizeof lab), msg, true);
}
void dispFailureFor(const char* title, const char* msg){
  // Failure uses the same overall timing as success for consistency.
  // The X is static (not animated) — failure should be readable, not dwelt on.
  dispFailure(title, msg);
  uint32_t start = millis();
  while(millis() - start < SUCC_TOTAL_MS){
    spinTick();
    delay(8);
  }
}

// ── Contextual sign-success ───────────────────────────────────────────────
// For selected Nostr event kinds the success screen shows an icon that
// REPRESENTS the action (zap bolt / heart / note / repost) instead of a
// generic tick, so the confirmation feels recognised. Reveal mirrors the tick:
// the ring sweeps in, then the icon POPS in with a slight overshoot. Unknown
// kinds fall back to the normal tick (dispSuccessFor).
// Kinds with a custom icon: 1 note, 6 repost, 7 reaction/like, 9734 zap.
static bool signKindHasIcon(int k){
  return (k==1 || k==6 || k==7 || k==9734);
}

// Per-kind accent colour. Zaps use AMBER (Lightning/sats belong to the device's
// Bitcoin/amber world — systematic, not decorative). Everything else uses the
// standard success GREEN so the colour system stays coherent. Red is reserved
// for failure, so likes do NOT use it.
static uint16_t signIconColor(int kind){
  return (kind == 9734) ? C_AMBER : C_GREEN;
}

