// Draw the per-kind icon centred at (cx,cy), scaled by s (1.0 = full size),
// in colour col. Shapes are sized for a ~46px ring (matches SUCC_RING_R).
static void drawSignIcon(int kind, int cx, int cy, float s, uint16_t col){
  if(s <= 0.01f) return;
  auto SX=[&](float v){ return cx + (int)lroundf(v*s); };
  auto SY=[&](float v){ return cy + (int)lroundf(v*s); };
  if(kind == 9734){
    // Zap — baked bolt bitmap. blitA4 can't scale, so we FADE it in using s as
    // alpha (clamped 0..1) so it still appears in time with the others' pop.
    float a = s; if(a > 1.0f) a = 1.0f; if(a < 0.0f) a = 0.0f;
    uint16_t zc = blend565(col, C_BG, (uint8_t)(a * 255.0f));
    blitA4(ZAP_ICON_A4, ZAP_ICON_W, ZAP_ICON_H, ZAP_ICON_ROWBYTES, cx, cy, zc, C_BG);
  } else if(kind == 7){
    // Heart — two lobes (filled circles) + a triangle base, like.
    int lobeR = (int)lroundf(9*s);
    spr.fillCircle(SX(-7), SY(-6), lobeR, col);
    spr.fillCircle(SX(7),  SY(-6), lobeR, col);
    spr.fillTriangle(SX(-15),SY(-2), SX(15),SY(-2), SX(0),SY(18), col);
  } else if(kind == 6){
    // Repost — two curved arrows forming a cycle (approximate with arcs + heads).
    int w = (int)lroundf(3*s); if(w<2) w=2;
    spr.drawSmoothArc(cx, cy, (int)lroundf(15*s), (int)lroundf(15*s)-w, 30, 200, col, C_BG, true);
    spr.drawSmoothArc(cx, cy, (int)lroundf(15*s), (int)lroundf(15*s)-w, 210, 380, col, C_BG, true);
    // arrowheads
    spr.fillTriangle(SX(14),SY(-6), SX(8),SY(-10), SX(8),SY(-1), col);
    spr.fillTriangle(SX(-14),SY(6), SX(-8),SY(10), SX(-8),SY(1), col);
  } else {
    // Note (kind 1) — three text lines.
    int w = (int)lroundf(3*s); if(w<2) w=2;
    spr.drawWideLine(SX(-13),SY(-9), SX(13),SY(-9), w, col);
    spr.drawWideLine(SX(-13),SY(0),  SX(13),SY(0),  w, col);
    spr.drawWideLine(SX(-13),SY(9),  SX(4),SY(9),   w, col);
  }
}

// Paint one frame of the contextual sign-success: ring (ringPct) + icon
// (iconScale, with overshoot handled by the caller's easing).
// ── Entropy Ember signing (5 Oct 2026) ───────────────────────────────────────
// Manual and auto signing share one screen built on the brand mark, the same
// grammar as the unlock:
//   WORKING  the ember is noise while the signature is computed (the core-1
//            task keeps it flickering during the blocking schnorr/G0 call)
//   DONE     it resolves outside-in (320 ms), bursts white from the centre
//            (600 ms, buzzerOK at the start), holds, then dissolves
//   zap      a double white strobe before the burst - the strike
// The kind is said in words, not an icon: "NOTE SIGNED", "ZAP SIGNED"...
#define SIGN_MARK_OY 56
static const char* ebSignKindWord(int kind){
  switch(kind){
    case 1:    return "NOTE";
    case 1111: return "COMMENT";
    case 6: case 16: return "REPOST";
    case 7:    return "LIKE";
    case 9734: return "ZAP";
    case 4: case 14: case 1059: return "MESSAGE";
    case 3:    return "FOLLOWS";
    case 0:    return "PROFILE";
    case 5:    return "DELETE";
    case 1984: return "REPORT";
    case 10000:return "MUTE LIST";
    case 10002:return "RELAYS";
    case 30000: case 30003: return "LIST";
    case 30023:return "ARTICLE";
    case 30078:return "APP DATA";    // NIP-78: a client syncing its own settings under your key
    case 22242:return "RELAY AUTH";  // NIP-42
    case 27235:return "HTTP AUTH";   // NIP-98: signed token for an upload / API call
    case 24133:return "CONNECT";     // NIP-46 envelope (never user content)
    default:   return "EVENT";
  }
}
static void ebSignLabel(const char* txt, int y, uint16_t col){ pinDrawLabel(txt, y, col); }
// Full frame. lockP/flashP/alpha drive the mark; label under it; msg in body.
static void ebSignFrame(const char* title, const char* label, const char* msg, float lockP, float flashP, uint8_t alpha, uint16_t labelCol){
  g_ebMarkOX = 96; g_ebMarkOY = SIGN_MARK_OY;
  g_pinMark = { lockP, flashP, alpha, false, 0 };
  spr.fillSprite(C_BG);
  // 29 Oct 2026: the header used to repeat the label ("SIGNED" twice). Only
  // draw it when it says something the label does not.
  { char up[32]; if(title && strcmp(uiUpper(title, up, sizeof up), label ? label : "") != 0) uiHeader(title, ebMix(C_BG, C_EB_BRASS, alpha)); }
  ebMarkDraw(g_pinMark);
  ebSignLabel(label, 120, ebMix(C_BG, labelCol, alpha));
  if(msg && *msg){ fSet(F_BODY); spr.setTextColor(ebMix(C_BG, C_MUTED, alpha)); fDrawCentre(msg, 120, 150); fEnd(); }
  uiFooter();
  dispPush();
  g_ebMarkOX = 96; g_ebMarkOY = 32;   // back to the PIN screen's origin
}
// Arm the next BgSpin to animate ember noise at (96, oy) instead of the ring.
// Whatever is on screen stays; only the 48x48 mark cell is repainted by core 1.
static volatile int g_emberWorkOY = SIGN_MARK_OY;
void emberWorkingArm(int oy){ g_emberWorkOY = oy; g_signWorkingArmed = true; }
// Generic "working" screen on the ember: title header, noise mark, tracked
// caps label, optional body line. Call before a BgSpin around the blocking
// work (signing, G0 wallet derivation, SE door open...).
void dispEmberWorking(const char* title, const char* label, const char* msg){
  ebSignFrame(title, label, msg, 0.0f, 0.0f, 255, C_EB_BRASS);
  emberWorkingArm(SIGN_MARK_OY);
}
void dispSignWorking(const char* msg){ dispEmberWorking("Signing", "SIGNING", msg); }
// The working screen's ending: the noise RESOLVES into the lit ember (320 ms),
// optional burst, short hold, dissolve to black. Call right after the BgSpin
// scope closes so the wait never just cuts to the next page.
void dispEmberResolve(const char* title, const char* label, const char* msg, bool burst){
  if(bgSpinnerRunning) bgSpinnerStop();
  const uint32_t ARC_MS = 320, BURST_MS = 600, HOLD_MS = 320, FADE_MS = 220;
  uint32_t t0 = millis(), el;
  while((el = millis() - t0) < ARC_MS){
    float pr = (float)el / (float)ARC_MS; pr = 1.0f - (1.0f - pr) * (1.0f - pr);
    ebSignFrame(title, label, msg, pr, 0.0f, 255, C_EB_INK);
    esp_task_wdt_reset(); delay(8);
  }
  if(burst){
    buzzerOK();
    uint32_t b0 = millis();
    while((el = millis() - b0) < BURST_MS){
      float tp = (float)el / (float)BURST_MS; if(tp > 1.0f) tp = 1.0f;
      ebSignFrame(title, label, msg, 1.0f, tp, 255, C_EB_INK);
      esp_task_wdt_reset(); delay(8);
    }
  }
  uint32_t h0 = millis();
  while(millis() - h0 < HOLD_MS){ ebSignFrame(title, label, msg, 1.0f, 1.0f, 255, C_EB_INK); esp_task_wdt_reset(); delay(16); }
  uint32_t f0 = millis();
  while((el = millis() - f0) < FADE_MS){
    float p = (float)el / (float)FADE_MS; if(p > 1.0f) p = 1.0f;
    ebSignFrame(title, label, msg, 1.0f, 1.0f, (uint8_t)((1.0f - p * p) * 255.0f), C_EB_INK);
    esp_task_wdt_reset(); delay(8);
  }
  spr.fillSprite(C_BG); dispPush();
}
// The burst half of dispEmberResolve for callers whose mark is ALREADY lit
// (the reconnect hold fills the ember, then this fires it).
void dispEmberBurst(const char* title, const char* label, const char* msg){
  if(bgSpinnerRunning) bgSpinnerStop();
  const uint32_t BURST_MS = 600, HOLD_MS = 320, FADE_MS = 220;
  uint32_t el;
  buzzerOK();
  uint32_t b0 = millis();
  while((el = millis() - b0) < BURST_MS){
    float tp = (float)el / (float)BURST_MS; if(tp > 1.0f) tp = 1.0f;
    ebSignFrame(title, label, msg, 1.0f, tp, 255, C_EB_INK);
    esp_task_wdt_reset(); delay(8);
  }
  uint32_t h0 = millis();
  while(millis() - h0 < HOLD_MS){ ebSignFrame(title, label, msg, 1.0f, 1.0f, 255, C_EB_INK); esp_task_wdt_reset(); delay(16); }
  uint32_t f0 = millis();
  while((el = millis() - f0) < FADE_MS){
    float p = (float)el / (float)FADE_MS; if(p > 1.0f) p = 1.0f;
    ebSignFrame(title, label, msg, 1.0f, 1.0f, (uint8_t)((1.0f - p * p) * 255.0f), C_EB_INK);
    esp_task_wdt_reset(); delay(8);
  }
  spr.fillSprite(C_BG); dispPush();
}
// Failure hold on the ember: red header, the mark extinguished (cells pulled
// to red, core out), red label, body line; buzzerFail once; blocks holdMs.
void dispEmberFail(const char* title, const char* label, const char* msg, uint32_t holdMs){
  if(bgSpinnerRunning) bgSpinnerStop();
  g_ebMarkOX = 96; g_ebMarkOY = SIGN_MARK_OY;
  g_pinMark = { 1.0f, 0.0f, 255, true, 0 };
  spr.fillSprite(C_BG);
  uiHeader(title, C_RED);
  ebMarkDraw(g_pinMark);
  ebSignLabel(label, 120, C_RED);
  if(msg && *msg){ fSet(F_BODY); spr.setTextColor(C_MUTED); fDrawCentre(msg, 120, 150); fEnd(); }
  uiFooter();
  dispPush();
  g_ebMarkOX = 96; g_ebMarkOY = 32;
  buzzerFail();
  uint32_t t0 = millis();
  while(millis() - t0 < holdMs){ esp_task_wdt_reset(); delay(16); }
}
// The lit ember breathing (alpha 170..255 on a ~1.8 s sine): the idle
// "listening" state - alive, not working.
void ebBreatheDraw(int oy){
  float ph = (float)(millis() % 1800) / 1800.0f;
  uint8_t a = (uint8_t)(212.0f + 43.0f * sinf(ph * 2.0f * (float)M_PI));
  g_ebMarkOX = 96; g_ebMarkOY = oy;
  PinMarkState m = { 1.0f, 0.0f, a, false, 0 };
  ebMarkDraw(m);
  g_ebMarkOX = 96; g_ebMarkOY = 32;
}
// Core-1 tick: redraw only the mark's 48x48 cell at the armed origin.
void ebSignWorkingTick(){
  int oy = g_emberWorkOY;
  g_ebMarkOX = 96; g_ebMarkOY = oy;
  PinMarkState m = { 0.0f, 0.0f, 255, false, 0 };
  ebMarkDraw(m);
  dispPushRegion(96, oy, 48, 48);
  g_ebMarkOX = 96; g_ebMarkOY = 32;
}
void bunkerSignFlash(int kind);   // REMOTE page in-place burst (defined with dispBunkerStatus)
void dispSignSuccessFor(const char* title, const char* msg){
  g_signWorkingArmed = false;
  const int kind = g_signKind;
  if(currentState == ST_BUNKER_STATUS && bunkerActive){ bunkerSignFlash(kind); return; }   // 5 Oct 2026: no page change while listening
  char done[24]; snprintf(done, sizeof(done), "%s SIGNED", ebSignKindWord(kind));
  const uint32_t ARC_MS = 320, BURST_MS = 600, HOLD_MS = 450, FADE_MS = 280;
  uint32_t t0 = millis(), el;
  // resolve from noise
  while((el = millis() - t0) < ARC_MS){
    float pr = (float)el / (float)ARC_MS; pr = 1.0f - (1.0f - pr) * (1.0f - pr);
    ebSignFrame(title, "SIGNING", msg, pr, 0.0f, 255, C_EB_BRASS);
    esp_task_wdt_reset(); delay(8);
  }
  // zap: the strike - two white flashes with the mark blinking out between
  if(kind == 9734){
    struct Step { bool white; uint8_t a; uint32_t ms; };
    static const Step STRIKE[] = { {false,0,40}, {true,255,45}, {false,0,55}, {true,255,35}, {false,0,60} };
    for(unsigned i = 0; i < sizeof(STRIKE)/sizeof(STRIKE[0]); i++){
      g_ebMarkWhite = STRIKE[i].white;
      uint32_t st = millis();
      while(millis() - st < STRIKE[i].ms){ ebSignFrame(title, done, msg, 1.0f, 0.0f, STRIKE[i].a ? 255 : 0, C_EB_INK); esp_task_wdt_reset(); delay(8); }
    }
    g_ebMarkWhite = false;
  }
  // burst
  buzzerOK();
  uint32_t b0 = millis();
  while((el = millis() - b0) < BURST_MS){
    float tp = (float)el / (float)BURST_MS; if(tp > 1.0f) tp = 1.0f;
    ebSignFrame(title, done, msg, 1.0f, tp, 255, C_EB_INK);
    esp_task_wdt_reset(); delay(8);
  }
  uint32_t h0 = millis();
  while(millis() - h0 < HOLD_MS){ ebSignFrame(title, done, msg, 1.0f, 1.0f, 255, C_EB_INK); esp_task_wdt_reset(); delay(16); }
  // dissolve
  uint32_t f0 = millis();
  while((el = millis() - f0) < FADE_MS){
    float p = (float)el / (float)FADE_MS; if(p > 1.0f) p = 1.0f;
    uint8_t a = (uint8_t)((1.0f - p * p) * 255.0f);
    ebSignFrame(title, done, msg, 1.0f, 1.0f, a, C_EB_INK);
    esp_task_wdt_reset(); delay(8);
  }
  spr.fillSprite(C_BG); dispPush();
}

// ── Unified unlock screen ────────────────────────────────────────────────
// Collapses the old three screens (PIN-ready → "Decrypting" spinner →
// "Unlocked" tick) into ONE screen whose centre element morphs through the
// unlock lifecycle. The filled dot row (top) and the menu-matched footer
// (WiFi fan + battery) stay fixed throughout; only the ~32px-radius centre
// circle changes. Continuity with the entry screen: the centre sits on the
// same INK_CY the digit occupied, so the last-digit commit visually resolves
// into this element rather than cutting to a different screen.
//
// Phases (driven by the submit handler):
//   UF_READY    — closed padlock in a dim track ring; label "PRESS TO UNLOCK".
//                 NOTE: the padlock stays CLOSED here — the key is not yet
//                 unlocked (SE PIN check hasn't run), so showing it open would
//                 misrepresent state. The "opening" is the tick at the end.
//   UF_WORKING  — padlock fades out; an accent arc sweeps the track while the
//                 real SE pin-session-open / scalar-derive runs; "UNLOCKING".
//   UF_DONE     — arc completes to a full ring; the tick draws inside it;
//                 label "UNLOCKED". Brief hold, then the menu.
enum UnlockPhase { UF_READY, UF_WORKING, UF_DONE };
#define UF_CX     120
#define UF_CY     PIN_INK_CY // matches the entry screen's INK_CY
#define UF_R      36         // track / ring radius
#define UF_T      3          // ring thickness

// Draw the fixed chrome (header, filled dots, footer) shared by every phase.
// ── Ember PIN animation, shared by every PIN screen ──────────────────────
// The Nostr unlock, the BTC door and the BTC per-signature prompt all run the
// same sequence on the same chrome; only the words differ. Set up once per
// use (pinAnimSetup), paint the noise frame before the blocking SE/G0 work
// (pinAnimWorking), then pinAnimSuccess() (resolve + burst + hold, ~1.3 s,
// haptic at the burst) or pinAnimFail() (ember out + shake).
static const char* g_ufLabel        = "Nostr PIN";
static int         g_ufLen          = -1;          // -1 = pinTargetLen
static const char* g_ufWorkingText  = "UNLOCKING";
static const char* g_ufDoneText     = "UNLOCKED";
static bool        g_ufAttemptsLine = true;        // Nostr shows "N attempts left"; the SE counts BTC
static uint8_t     g_ufAlpha        = 255;         // whole-screen fade for the exit dissolve
void pinAnimSetup(const char* label, int len, const char* working, const char* done, bool attemptsLine){
  g_ufLabel = label; g_ufLen = len; g_ufWorkingText = working; g_ufDoneText = done; g_ufAttemptsLine = attemptsLine;
}
static void ufDrawChrome(uint16_t accent){
  // Same chrome as the entry screen, all positions filled (PIN complete).
  pinDrawChrome(g_ufLabel, accent, g_ufLen < 0 ? pinTargetLen : g_ufLen, -1, g_ufLen);
  if(g_ufAlpha < 255){   // exit dissolve: re-draw the grey label at the faded level
    spr.fillRect(0, 92, 240, 14, C_BG);
    pinDrawLabel(uiHeaderCaps(g_ufLabel), 96, ebMix(C_BG, C_EB_GREY, g_ufAlpha));
  }
}

