void drawClosedPadlock(int cx, int cy, uint16_t col){
  blitA4(LOCK_LOGO_A4, LOCK_LOGO_W, LOCK_LOGO_H, LOCK_LOGO_ROWBYTES, cx, cy, col, C_BG);
}


// Render the whole unified screen at a given phase / progress.
//   ringPct : 0..1 arc sweep (WORKING shows a moving partial arc; DONE = 1.0)
//   tickPct : 0..1 tick draw (DONE only)
//   lockA   : padlock alpha 0..255 (READY=255, fading during WORKING start)
void dispUnlockFrame(UnlockPhase phase, float ringPct, float tickPct, uint8_t lockA){
  // Entropy Ember unlock (5 Oct 2026): no padlock, no ring, no tick.
  //   READY    complete ember, armed (dim)
  //   WORKING  ringPct 0..1 -> the ember RESOLVES from noise, outside-in
  //            (the first frame, lockA=80, ringPct=0, is pure noise while the
  //            SE call runs)
  //   DONE     tickPct 0..1 -> white burst rolls out from the centre, then the
  //            ember sits complete. "UNLOCKED".
  (void)lockA;
  const uint16_t accent = ebMix(C_BG, C_EB_BRASS, g_ufAlpha);
  const uint8_t  markA  = (uint8_t)((uint16_t)(phase == UF_READY ? 150 : 255) * g_ufAlpha / 255);
  if(phase == UF_READY)        g_pinMark = { 1.0f,    0.0f,    markA, false, 0 };
  else if(phase == UF_WORKING) g_pinMark = { ringPct, 0.0f,    markA, false, 0 };
  else                         g_pinMark = { 1.0f,    tickPct, markA, false, 0 };
  ufDrawChrome(accent);
  const char* label = (phase == UF_READY)   ? "ENTER TO UNLOCK"
                    : (phase == UF_WORKING)  ? g_ufWorkingText
                                             : g_ufDoneText;
  // 29 Oct 2026: tracked caps, same element as the PIN screen's confirm prompt
  { char up[32]; uiTrackLabel(uiUpper(label, up, sizeof up), 120, 172, phase == UF_DONE ? ebMix(C_BG, C_EB_INK, g_ufAlpha) : accent); }
  dispPush();
}

// ── Wrong-PIN failure (unified visual language) ──────────────────────────
// Same screen as unlock: filled dots, menu footer, the closed padlock in the
// centre ring — but RED, and the padlock + ring do a damped horizontal SHAKE
// (the universal "no" gesture) to read as the lock refusing to open. No jarring
// swap to a different layout, no static red X on the old screen. Self-contained
// + blocking (like dispSuccessFor), then returns so the caller resets PIN entry.
//   xoff : horizontal pixel offset for the shake (applied to ring + lock only;
//          the chrome dots/header/footer stay put).
static void dispUnlockFailFrame(const char* label, int xoff){
  // The ember goes OUT: cells pulled to red, centre extinguished, shaken by xoff.
  g_pinMark = { 1.0f, 0.0f, 255, true, xoff };
  ufDrawChrome(C_RED);   // squares in red
  fSet(F_HEAD); spr.setTextColor(C_RED);
  fDrawCentre(label, 120, 170);
  fEnd();
  // Remaining-attempts line — shown from the first failure. Escalates to a
  // brighter/heavier read in the last 3 (the danger zone before the SE wipe).
  if(!g_ufAttemptsLine){ dispPush(); return; }
  int remain = PIN_SEND_MAX - pinFailCount;
  if(remain < 0) remain = 0;
  char ra[28];
  if(remain == 1) snprintf(ra, sizeof(ra), "1 ATTEMPT LEFT");
  else            snprintf(ra, sizeof(ra), "%d attempts left", remain);
  bool urgent = (remain <= 3);
  fSet(F_BODY);
  spr.setTextColor(urgent ? C_RED : blend565(C_RED, C_BG, 150));
  fDrawCentre(ra, 120, 196);
  fEnd();
  dispPush();
}

void dispUnlockFail(const char* label){
  // Damped horizontal shake: ~3 oscillations decaying to zero over SHAKE_MS,
  // then a brief hold so the red state registers. buzzerFail() fires once at
  // the start (the moment of refusal).
  const uint32_t SHAKE_MS = 420;
  const float    AMP      = 9.0f;     // px, peak shake amplitude
  buzzerFail();
  uint32_t t0 = millis(), el;
  while((el = millis() - t0) < SHAKE_MS){
    float p = (float)el / (float)SHAKE_MS;
    float amp = AMP * (1.0f - p);                 // linear decay
    int xoff = (int)(amp * sinf(p * (float)M_PI * 6.0f));   // ~3 cycles
    dispUnlockFailFrame(label, xoff);
    delay(8);
  }
  dispUnlockFailFrame(label, 0);                  // settle centred
  uint32_t hold = millis();
  while(millis() - hold < 650) delay(8);          // hold so it registers
}
void pinAnimFail(const char* label){ dispUnlockFail(label); }
// Noise frame to show while the blocking SE/G0 work runs (single-threaded, so
// one frame is all we get).
void pinAnimWorking(){ dispUnlockFrame(UF_WORKING, 0.0f, 0.0f, 80); emberWorkingArm(32); }   // a BgSpin around the SE/G0 call keeps the noise moving
// Resolve 0->1 (320 ms, ease-out), burst (600 ms, haptic at its start), then
// hold the lit ember 350 ms by repainting (never a blind delay, so no stray
// repaint can show through). Blocking.
void pinAnimSuccess(){
  const uint32_t ARC_MS  = 320;
  const uint32_t TICK_MS = 600;
  const uint32_t TOTAL   = ARC_MS + TICK_MS;
  uint32_t t0 = millis(), el;
  bool buzzed = false;
  while((el = millis() - t0) < TOTAL){
    if(el < ARC_MS){
      float pr = (float)el / (float)ARC_MS;
      pr = 1.0f - (1.0f - pr) * (1.0f - pr);
      dispUnlockFrame(UF_WORKING, pr, 0.0f, 0);
    } else {
      if(!buzzed){ buzzerOK(); buzzed = true; }
      float tp = (float)(el - ARC_MS) / (float)TICK_MS;
      if(tp > 1.0f) tp = 1.0f;
      dispUnlockFrame(UF_DONE, 1.0f, tp, 0);
    }
    esp_task_wdt_reset();
    delay(8);
  }
  uint32_t hb = millis();
  while(millis() - hb < 350){ dispUnlockFrame(UF_DONE, 1.0f, 1.0f, 0); esp_task_wdt_reset(); delay(16); }
  // Exit dissolve: fade the whole screen to black (~250 ms), then leave the
  // backlight OFF and ramp it back asynchronously (120 ms grace + ~50 ms
  // ramp) so whatever the caller paints next — menu, Bitcoin door, passphrase
  // prompt — fades in rather than cutting in. Any intermediate "working"
  // screens the caller paints in that window are simply never seen.
  for(int a = 255; a >= 0; a -= 24){
    g_ufAlpha = (uint8_t)(a < 0 ? 0 : a);
    dispUnlockFrame(UF_DONE, 1.0f, 1.0f, 0);
    esp_task_wdt_reset(); delay(16);
  }
  g_ufAlpha = 255;
  ledcWrite(TFT_BL_PIN, 0);
  spr.fillSprite(C_BG); dispPush();
  blDimInAsync();
}

// ── Lockout countdown ────────────────────────────────────────────────────
// After enough wrong attempts the device imposes an escalating wait before the
// next try. Same red unified language as the failure: closed padlock in the
// ring, but with a live countdown below. Blocks (refusing entry) until the
// lockout elapses. Format: <1h shows mm:ss; >=1h shows "Nh Mm".
static void fmtLockout(char* out, size_t n, uint32_t secs){
  if(secs >= 3600){
    uint32_t h = secs / 3600, m = (secs % 3600) / 60;
    snprintf(out, n, "%luh %02lum", (unsigned long)h, (unsigned long)m);
  } else {
    uint32_t m = secs / 60, s = secs % 60;
    snprintf(out, n, "%02lu:%02lu", (unsigned long)m, (unsigned long)s);
  }
}
static void dispLockoutFrame(uint32_t remain){
  g_pinMark = { 1.0f, 0.0f, 255, true, 0 };   // extinguished ember, static
  ufDrawChrome(C_RED);
  char cd[16]; fmtLockout(cd, sizeof(cd), remain);
  // Countdown — the focal text, in the red accent.
  fSet(F_TITLE); spr.setTextColor(blend565(C_RED, C_BG, 235));
  fDrawCentre(cd, 120, 162);
  fEnd();
  // Sub-label.
  fSet(F_BODY); spr.setTextColor(blend565(C_RED, C_BG, 150));
  fDrawCentre("LOCKED", 120, 196);
  fEnd();
  dispPush();
}
// Blocks until the active lockout elapses, updating the countdown ~4x/sec.
// Returns when the wait is over (caller then allows a fresh entry).
void dispLockoutWait(){
  uint32_t remain;
  uint32_t lastSave = millis();
  // Persist the remaining time every ~10s while counting down, so a power loss
  // at any point resumes from roughly where it was (never restarts the full
  // wait, never credits offline time).
  while((remain = pinLockoutRemaining()) > 0){
    esp_task_wdt_reset();   // 31 Oct 2026: a lockout can last 24 h with no button polled; waiting, not stuck
    dispLockoutFrame(remain);
    if(millis() - lastSave >= 10000UL){ pinPersistRemaining(); lastSave = millis(); }
    // Poll responsively but cheaply; the countdown only needs ~250ms cadence.
    for(int i=0;i<25;i++){ delay(10); }
  }
  // Lockout elapsed — clear the remaining (count stays) so the next try is live.
  pinLockoutActive = false; pinLockoutSecs = 0; pinSaveFailState();
}

void dispWaiting(){
  spr.fillSprite(C_BG);
  // Header label tracks reality: "Bunker Active" only when bunker mode is
  // actually on (long-lived listener for any client). Without bunker mode
  // we're waiting on a transient nostrconnect session, which is a
  // different thing — calling it "Bunker Active" misleads the user into
  // thinking any client can sign with their key.
  uiHeader(bunkerActive ? "Bunker Active" : "Waiting", C_GREEN);
  ebBreatheDraw(WAIT_MARK_OY);   // 5 Oct 2026: the lit ember breathes while we listen (was a green ring)
  fSet(F_BODY); spr.setTextColor(C_MUTED);
  fDrawCentre(bunkerActive ? "Listening for requests"
                           : "Waiting for connection", 120, 132);
  fEnd();
  spr.drawFastHLine(0,148,240,C_BORDER);
  // Labels were hardcoded to nsec.app / primal, which stopped being true the
  // moment the pool became ordered and failover-capable — ws1 connects to
  // whichever pool entry is ACTIVE, so a fixed label reports the wrong relay
  // and makes this screen actively misleading during a failover.
  const char* activeName = bunkerRelayForIdx(activeRelayIdx);
  if(!activeName) activeName = "relay";
  struct { bool ok; const char* label; } rows[]={
    {wifiConnected,  "WiFi"},
    {wsInitialised,  activeName},
    {ws2Initialised, "share/publish"},
  };
  for(int i=0;i<3;i++){
    int y=156+i*18;
    spr.fillCircle(18,y+6,4,rows[i].ok?C_GREEN:C_VDIM);
    fSet(F_BODY);
    spr.setTextColor(rows[i].ok?C_TEXT2:C_DIM);
    spr.drawString(rows[i].label, 28, y+2);
    spr.setTextColor(rows[i].ok?C_GREEN:C_VDIM);
    fDrawRight(rows[i].ok?"ok":"...", 232, y+2);
    fEnd();
  }
  uiFooter();
  dispPush();
}

// ── Bunker status screen ──────────────────────────────────────────────────
// The bunker home. Replaces the empty post-activate display. Visible state
// for what's happening: connection, recent activity, counters. Refreshes
// every ~250ms while bunker is active, driven by runStateMachine.
// 5 Oct 2026 (Entropy Ember): the ember IS the status element - noise while
// connecting, lit and breathing while listening, extinguished when off. Under
// it the state in tracked caps and the relay in mono. Two black tiles for the
// QR cards (accent on selection), then the three counters on a hairline, no
// box. Battery top-right. No header: the mark is the title.
#define BK_MARK_OY 20
#define BK_LABEL_Y 78
static void bunkerMarkDraw(){
  bool relay = wsInitialised || ws2Initialised;
  if(!bunkerActive){
    g_ebMarkOX = 96; g_ebMarkOY = BK_MARK_OY;
    PinMarkState m = { 1.0f, 0.0f, 90, false, 0 };   // dim, off
    ebMarkDraw(m);
    g_ebMarkOX = 96; g_ebMarkOY = 32;
  } else if(relay && signerEoseReceived){
    ebBreatheDraw(BK_MARK_OY);                        // listening
  } else {
    g_ebMarkOX = 96; g_ebMarkOY = BK_MARK_OY;
    PinMarkState m = { 0.0f, 0.0f, 255, false, 0 };   // connecting: noise
    ebMarkDraw(m);
    g_ebMarkOX = 96; g_ebMarkOY = 32;
  }
}
// Region tick for the state loop between full repaints.
void bunkerMarkTick(){ bunkerMarkDraw(); dispPushRegion(96, BK_MARK_OY, 48, 48); }
// Activity footer: the last signature (kind + how long ago) on the left,
// battery on the right. Replaces the three-counter row (5 Oct 2026).
static void bunkerFooter(){
  const int footY = 220;
  spr.fillRect(0, footY - 2, 240, 22, C_BG);
  fSet(F_SMALL); spr.setTextColor(C_EB_GREY);
  if(g_signHistN){
    char ago[8]; fmtAgo(ago, sizeof(ago), g_signHist[0].atMs);
    char line[40]; snprintf(line, sizeof(line), "%s %s  %s", ebSignKindWord(g_signHist[0].kind), g_signHist[0].manual ? "SIGNED" : "AUTO-SIGNED", ago);
    spr.drawString(line, 12, footY + 3);
  } else {
    spr.drawString(bunkerActive ? "NO SIGNATURES YET" : "", 12, footY + 3);
  }
  fEnd();
  battDrawInline(190, footY);
}
void dispBunkerStatus(){
  spr.fillSprite(C_BG);
  const int MX = 12, MW = 216;
  bool relay = wsInitialised || ws2Initialised;
  bool listening = bunkerActive && relay && signerEoseReceived;

  bunkerMarkDraw();
  pinDrawLabel(!bunkerActive ? "OFF" : listening ? "LISTENING" : "CONNECTING", BK_LABEL_Y,
               listening ? C_EB_BRASS : C_EB_GREY);
  {
    const char* rn = bunkerRelayForIdx(activeRelayIdx);
    if(!rn) rn = "relay";
    fSet(F_SMALL); spr.setTextColor(C_EB_GREY);
    fDrawCentre(rn, 120, 96);
    fEnd();
  }

  // ── Transient remote-pairing banner (slave minted / revoked) ────────────
  int y = 116;
  if(bunkerBannerText[0] && (long)(bunkerBannerUntilMs - millis()) > 0){
    bool isRevoke = (strncmp(bunkerBannerText, "Revoked", 7) == 0);
    uint16_t bcol = isRevoke ? C_RED : C_EB_BRASS;
    spr.drawRoundRect(MX, 112, MW, 20, 6, bcol);
    fSet(F_SMALL); spr.setTextColor(bcol);
    fDrawCentre(bunkerBannerText, 120, 116);
    fEnd();
    y = 138;
  } else if(bunkerBannerText[0]) {
    bunkerBannerText[0] = 0;
  }

  // ── Two QR tiles: FAVILLA | NOSTR APP ───────────────────────────────────
  {
    const int gap = 8;
    const int cw = (MW - gap) / 2;
    const int ch = 208 - y;             // down to the footer
    for(int i=0;i<2;i++){
      int cx = MX + i*(cw+gap);
      bool sel = (bunkerStatusSel == i);
      uint16_t accent = (i==0) ? C_EB_BRASS : C_PURPLE;
      int icx, icy;
      uiGridTile(cx, y, cw, ch, sel, accent, (i==0) ? "FAVILLA" : "NOSTR APP", &icx, &icy);
      uint16_t icol = sel ? accent : C_EB_GREY;
      if(i==0) drawIconPhone(icx, icy + 2, icol);
      else     drawIconQrGlyph(icx, icy + 2, icol);
    }
  }
  bunkerFooter();
  dispPush();
}
// In-place auto-sign (5 Oct 2026): while the REMOTE page is up, a signature
// does NOT open the sign screen - the ember already on screen bursts, the
// label says what was signed, the footer updates, and the page carries on
// listening. Blocking ~1.5 s with region pushes only.
void bunkerSignFlash(int kind){
  char done[24]; snprintf(done, sizeof(done), "%s SIGNED", ebSignKindWord(kind));
  const uint32_t BURST_MS = 600, HOLD_MS = 800;
  buzzerOK();
  auto label = [&](const char* txt, uint16_t col){
    spr.fillRect(0, BK_LABEL_Y - 4, 240, 20, C_BG);
    pinDrawLabel(txt, BK_LABEL_Y, col);
    dispPushRegion(0, BK_LABEL_Y - 4, 240, 20);
  };
  label(done, C_EB_INK);
  bunkerFooter(); dispPushRegion(0, 218, 240, 22);
  uint32_t t0 = millis(), el;
  while((el = millis() - t0) < BURST_MS){
    float tp = (float)el / (float)BURST_MS; if(tp > 1.0f) tp = 1.0f;
    g_ebMarkOX = 96; g_ebMarkOY = BK_MARK_OY;
    PinMarkState m = { 1.0f, tp, 255, false, 0 };
    ebMarkDraw(m);
    g_ebMarkOX = 96; g_ebMarkOY = 32;
    dispPushRegion(96, BK_MARK_OY, 48, 48);
    esp_task_wdt_reset(); delay(8);
  }
  uint32_t h0 = millis();
  while(millis() - h0 < HOLD_MS){ bunkerMarkTick(); esp_task_wdt_reset(); delay(40); }
  label("LISTENING", C_EB_BRASS);
}

// ── Approval ───────────────────────────────────────────────────────────────
// ── Nostr sign-request screen — mirrors the PSBT confirm screen ─────────────
// Same layout language: fixed header + footer bands, a scrolled content window
// in between, a scrollbar when content overflows, and DECLINE/ACCEPT pills at
// the bottom. Button model matches PSBT: BTN1 tap = scroll down, BTN1 hold =
// decline, BTN2 = approve, BTN3 = scroll up (handled in the ST_APPROVAL case).
#define APV_HEADER_H  30
#define APV_FOOTER_H  44
#define APV_VIEW_TOP  APV_HEADER_H
#define APV_VIEW_BOT  (240 - APV_FOOTER_H)
#define APV_VIEW_H    (APV_VIEW_BOT - APV_VIEW_TOP)

// Bunker "Connected" confirmation + dissolve into the live status screen.
// Called once when a client completes the NIP-46 connect/ack. Shows the shared
// animated success reveal (ring sweep + tick draw) with the word "Connected",
// then dissolves into dispBunkerStatus() via the backlight: ramp BL down, swap
// the frame to the live screen while dark (no visible hard cut), ramp BL back
// up. The reveal plays exactly once on connect — afterwards the live screen
// repaints only on real state changes, so there is no idle animation burning
// cycles. Total ~1s, then the device is listening and signable.
void bunkerConnectedReveal(){
  // Animated check + "Connected" (shared success component; on-brand with
  // "Unlocked"/"Saved"). Empty msg keeps it clean per the design choice.
  dispSuccessFor("Connected", "", C_GREEN);

  // Backlight dissolve into the live screen. Ramp down fast, render the live
  // bunker screen into the sprite while dark, push it, then ramp back up.
  for(int d=blTargetDuty(); d>=0; d-=64){ ledcWrite(TFT_BL_PIN, d); delay(6); }
  ledcWrite(TFT_BL_PIN, 0);
  dispBunkerStatus();                         // render the live frame while dark
  for(int d=0; d<=blTargetDuty(); d+=48){ ledcWrite(TFT_BL_PIN, d); delay(6); }
  ledcWrite(TFT_BL_PIN, blTargetDuty());
}

// Word-wrap a string into the content column, drawing each line. Returns the
// y after the last line. Lines that fall outside the view window are still
// advanced (cheap) so total content height is measured correctly for scroll.
static int apvDrawWrapped(const char* text, int x, int y, int maxW, int lineH){
  if(!text || !text[0]) return y;
  String word, line;
  const char* p = text;
  auto flush = [&](){
    if(line.length()){ spr.drawString(line.c_str(), x, y); }
    y += lineH; line = "";
  };
  while(*p){
    char c = *p++;
    if(c=='\n'){
      // hard newline
      if(word.length()){ if(line.length()) line += " "; line += word; word=""; }
      flush();
      continue;
    }
    if(c==' '){
      if(word.length()){
        String trial = line.length() ? line + " " + word : word;
        if(spr.textWidth(trial.c_str()) > maxW){ flush(); line = word; }
        else line = trial;
        word = "";
      }
      continue;
    }
    word += c;
    // very long unbroken token: hard-break it
    if(spr.textWidth(word.c_str()) > maxW){
      if(line.length()) flush();
      // break the token across lines
      while(spr.textWidth(word.c_str()) > maxW && word.length() > 1){
        int cut = word.length();
        while(cut>1 && spr.textWidth(word.substring(0,cut).c_str()) > maxW) cut--;
        spr.drawString(word.substring(0,cut).c_str(), x, y); y += lineH;
        word = word.substring(cut);
      }
    }
  }
  if(word.length()){ if(line.length()) line += " "; line += word; }
  if(line.length()) flush();
  return y;
}

void dispApprovalScroll(int scroll){
  spr.fillSprite(C_BG);

  const int x = 12;
  const int contentW = 240 - x - 14;   // leave room for scrollbar
  const int lineH = 16;
  int y = APV_VIEW_TOP + 8 - scroll;

  // 29 Oct 2026 (board S1): what is being signed, large and centred, then
  // the content. Kind in Archivo Bold 28 when it fits, else tracked caps.
  uiTrackLabel("SIGNING", 120, y, C_EB_GREY);
  y += 20;
  fEndHard(); spr.loadFont(FONT_Archivo_Bold_28_full); spr.setTextColor(C_EB_INK);
  if(spr.textWidth(approvalLine1) <= 216){ spr.drawString(approvalLine1, 120 - spr.textWidth(approvalLine1)/2, y); fEndHard(); y += 40; }
  else { fEndHard(); char up[48]; uiTrackLabel(uiUpper(approvalLine1, up, sizeof up), 120, y + 4, C_EB_BRASS, 2); y += 28; }

  // separator
  spr.drawFastHLine(x, y, contentW, C_EB_LINE); y += 12;

  fSet(F_BODY); spr.setTextColor(C_FG);
  y = apvDrawWrapped(approvalBody, x, y, contentW, lineH);
  fEnd();
  y += 8;

  // record content height for scroll clamping (mirror g_psbt_content_h)
  g_approval_content_h = (y + scroll) - APV_VIEW_TOP;

  // ── Fixed bands on top (mask scrolled content) ──
  spr.fillRect(0, 0, 240, APV_HEADER_H, C_BG);
  uiHeader("SIGN REQUEST", C_EB_BRASS);   // 29 Oct 2026: was red; red is for danger
  spr.fillRect(0, APV_VIEW_BOT, 240, APV_FOOTER_H, C_BG);

  // ── Scrollbar ──
  bool overflow = g_approval_content_h > APV_VIEW_H;
  if(overflow){
    int trackX = 240 - 5, trackY = APV_VIEW_TOP + 2, trackH = APV_VIEW_H - 4;
    spr.fillRoundRect(trackX, trackY, 3, trackH, 1, C_BORDER);
    int maxScroll = g_approval_content_h - APV_VIEW_H;
    if(maxScroll < 1) maxScroll = 1;
    int thumbH = trackH * APV_VIEW_H / g_approval_content_h;
    if(thumbH < 14) thumbH = 14;
    int thumbY = trackY + (trackH - thumbH) * scroll / maxScroll;
    spr.fillRoundRect(trackX, thumbY, 3, thumbH, 1, C_EB_BRASS);
  }

  // ── Footer (29 Oct 2026): HOLD ENTER TO SIGN, BACK declines ──
  // Was DECLINE / ACCEPT pills and a tap of ENTER. Same rule as Bitcoin now.
  uiHoldFooter("HOLD ENTER TO SIGN", overflow ? "BACK declines   DOWN for more" : "BACK declines", 0.0f);

  dispPush();
}

// Hold-to-sign for every Nostr approval screen (29 Oct 2026). `since` is when
// the screen appeared: a press that began before it can't sign. Taps are
// swallowed. Returns true once ENTER has been held 1.5 s.
static unsigned long g_apv_shown_ms = 0;
static bool apvHoldTick(unsigned long since){
  static float last = 0.0f;
  btn2.isPressed();
  float hp = holdSince(btn2, since, 1500);
  if(hp >= 1.0f){ btn2.resetHold(); last = 0.0f; return true; }
  if(hp > 0.0f || last > 0.0f){
    bool more = g_approval_content_h > APV_VIEW_H;
    uiHoldFooter("HOLD ENTER TO SIGN", hp > 0.0f ? "Let go to stop" : (more ? "BACK declines   DOWN for more" : "BACK declines"), hp);
    dispPushRegion(0, 196, 240, 44); last = hp;
  }
  return false;
}
void dispApproval(){
  g_apv_shown_ms = millis();
  dispApprovalScroll(g_approval_scroll);
}

// ── Camera preview ─────────────────────────────────────────────────────────
static volatile bool qrTaskRunning=false;

// V21_2: airgap live-preview hookup. When g_airgapLivePreview is true, qrScanOnce
// draws the frame it grabbed (with a UR progress-bar footer) before returning it,
// so the camera view stays continuous during multipart UR collection. The airgap
// loop sets these each iteration from the UR decoder state.
// (Moved up from beside qrScanOnce so runRestoreFlow — defined earlier in the
// file — can drive the same live preview for its seed/nsec scan loops.)
static bool g_airgapLivePreview=false;
static int  g_airgapUrGot=0, g_airgapUrTotal=0;

// V21.1: QR scan re-trigger interval (ms). Was 800 — set defensively when the
// camera was unstable. The camera is now solid offline and a quirc decode on a
// clean QVGA frame is only ~30–60ms, so 800ms wasted ~12 of every 13 frames.
// 300ms ~triples decode attempts/sec for a snappier "just catches it" feel.
// One knob to sweep on the bench: lower = more attempts (smoother catch, more
// preview-freeze churn), higher = back toward old behaviour.
#define QR_SCAN_INTERVAL_MS 300
// V21_2: airgap multipart-UR needs a faster sample rate than the 300ms Nostr/seed
// gate. Sparrow (and any fast coordinator) cycles UR fragments ~6-10fps; at 300ms
// we only attempt ~3/s, so we keep landing on mid-transition frames (two fragments
// smeared together -> finder patterns survive but data modules mush -> identified=1,
// decode FAIL) or re-catch the same few. 150ms doubles the sample rate while
// leaving enough idle time between scan tasks for dispPreview to render the live
// camera feed and the on-screen diag footer (a 60ms gate starves the preview —
// every main-loop iteration finds qrTaskRunning=true and bails on the render).
// Sweep on the bench if needed: lower = catch faster but preview starves first.
// V22.x: set to 300ms to EXACTLY match the older build that read Blue Wallet.
// At 90ms the grab cadence flooded cam_hal with EV-VSYNC-OVF -> torn frames ->
// quirc unstable grid (cells=[37..53] jitter) -> ECC fail. 200ms helped but may
// not fully clear the tearing on dense QRs; 300 is the known value from the file
// that decoded Blue Wallet. Sweep down only if the preview feels too laggy AND
// dense QRs still decode.
// V22.9: the inter-scan gap is JITTERED (60..150 ms, redrawn after every scan)
// so the KEY's capture cadence cannot phase-lock against a coordinator's
// animation period. The value changes only inside qrScanOnce(), so each
// "millis()-last > QR_AIRGAP_SCAN_INTERVAL_MS" test sees one stable number
// per scan. Was a fixed 90.
static int qrScanGapCur = 90;
#define QR_AIRGAP_SCAN_INTERVAL_MS qrScanGapCur
// ── A/B switch for the 14-16 Sep scan-path changes ───────────────────────
// 1 = behave exactly as before those changes: fixed 90 ms gap, no stale-frame
//     fingerprint, camera left running after a decode / on BACK (the V21_2
//     behaviour). Use it to compare [QRDIAG-SUM] lines on the same QR.
// 0 = the new path (fixes 9, 10, 11-jitter).
#define QR_SCAN_LEGACY 0
// Per-change switches for the new path (ignored when QR_SCAN_LEGACY=1):
#define QR_SCAN_HASH_DRAIN 1   // fix 9: re-fetch when the frame is byte-identical to the last decoded one
#define QR_SCAN_JITTER     1   // fix 11: 60..150 ms gap instead of fixed 90
// Counter for the A/B: how many frames the hash drain rejected this session.
static uint32_t g_qrHashDrained = 0;
// Per-phase timing for the scan loop (microseconds, summed; printed as averages
// in the [QRDIAG-SUM] block). Bench instrumentation, 16 Sep 2026.
static uint32_t g_qrT_fetch=0, g_qrT_stretch=0, g_qrT_close=0, g_qrT_quirc=0, g_qrT_preview=0, g_qrT_decode=0, g_qrT_total=0, g_qrT_n=0;
// V21_2: on-screen scan diagnostic. With USB attached the camera DMA contends
// with serial and scanning breaks, so serial [QRDIAG] is unusable on the bench.
// This renders the last scan outcome (identified count + grid/version or FAIL)
// onto the TFT during the airgap scan instead. Set 0 to strip for ship.
#define QR_ONSCREEN_DIAG 0   // 0 for production UX: scan footer shows only the clean
                             // progress bar / "BTN2 cancel" — no per-frame torn/id=0/
                             // FAIL/recaptured-OK diagnostic spam. Set to 1 on the bench
                             // when you need to diagnose a failing scan by eye (serial is
                             // unusable during scanning due to USB DMA contention).
// V21_2: on-screen scan diagnostic state, written by qrScanTask, read by
// dispPreview's footer. Declared up here (ahead of dispPreview) to avoid a
// forward-reference; qrScanTask is much further down. qrDiagIdentified = how
// many codes quirc located in the last frame; qrDiagCells = grid size of the
// first located code (0 if none); qrDiagOk = true if a located code DECODED,
// false if it only located (FAIL); qrDiagTorn = last attempt got only torn frames.
static volatile int  qrDiagIdentified=0;
// V22.3: set to 1 by the patched read_cell() in identify.c the first time the
// QUIRC_ROBUST_CELL voting path executes. Surfaced on the airgap scan TFT footer
// so the patch can be confirmed LIVE without serial (USB corrupts capture). The
// quirc C file sets this via an extern declaration. Remove with the patch.
volatile int g_robustCellLive=0;
static volatile int  qrDiagCells=0;
static volatile bool qrDiagOk=false;
// V22.x: DEFERRED QRDIAG. Serial during a scan corrupts the camera, so we can't
// watch [QRDIAG] live. Instead, tally decode outcomes here DURING the scan
// (no serial) and flush a summary AFTER it ends (qrDiagFlush, called on scan
// exit when serial is safe). Captures the cell-size spread and the exact decode
// error string — the thing we need to tell "Format data ECC failure" (rounded-
// finder/version-estimation problem) from plain "ECC failure" (data corruption).
static volatile int  qrDiagFrames=0;          // frames attempted
static volatile int  qrDiagIdFrames=0;        // frames where a code was located
static volatile int  qrDiagCellMin=999, qrDiagCellMax=0;  // grid-size spread (jitter = bad estimation)
static char          qrDiagLastErr[40]={0};   // last decode error string
static int           qrDiagErrCounts[8]={0};  // tally by quirc_decode_error_t (0..7)
static void qrDiagReset(){
  qrDiagFrames=0; qrDiagIdFrames=0; qrDiagCellMin=999; qrDiagCellMax=0;
  qrDiagLastErr[0]=0; for(int i=0;i<8;i++) qrDiagErrCounts[i]=0;
}
static void qrDiagFlush(){
  // Safe to call when NOT scanning (serial won't corrupt the camera now).
  Serial.printf("[QRDIAG-SUM] frames=%d located=%d cells=[%d..%d] lastErr=%s\n",
    qrDiagFrames, qrDiagIdFrames,
    (qrDiagCellMin==999?0:qrDiagCellMin), qrDiagCellMax,
    qrDiagLastErr[0]?qrDiagLastErr:"(none)");
  Serial.printf("[QRDIAG-SUM]   hashDrained=%lu\n",(unsigned long)g_qrHashDrained); g_qrHashDrained=0;
  if(g_qrT_n){
    Serial.printf("[QRDIAG-SUM]   per-frame ms: fetch+prep %lu | close %lu | quirc_end %lu | preview %lu | extract+decode %lu | n=%lu\n",
      (unsigned long)(g_qrT_fetch/g_qrT_n/1000), (unsigned long)(g_qrT_close/g_qrT_n/1000), (unsigned long)(g_qrT_quirc/g_qrT_n/1000),
      (unsigned long)(g_qrT_preview/g_qrT_n/1000), (unsigned long)(g_qrT_decode/g_qrT_n/1000), (unsigned long)g_qrT_n);
  }
  g_qrT_fetch=g_qrT_stretch=g_qrT_close=g_qrT_quirc=g_qrT_preview=g_qrT_decode=g_qrT_total=0; g_qrT_n=0;
  const char* enames[8]={"SUCCESS","err1","INVALID_GRID","INVALID_VERSION",
                         "INVALID_ECC","DATA_ECC","UNKNOWN_DATA","DATA_OVERFLOW"};
  for(int i=0;i<8;i++) if(qrDiagErrCounts[i])
    Serial.printf("[QRDIAG-SUM]   err[%s]=%d\n", enames[i], qrDiagErrCounts[i]);
}
static volatile bool qrDiagTorn=false;

#if QR_DUMP_FRAME
// V22.x DE-RISK frame dump. Capture ONE failing grayscale frame DURING a scan
// (silent — no serial, won't corrupt the camera), then base64 it out AFTER the
// scan ends via qrDumpFlush(), riding alongside qrDiagFlush() at the same exit
// points. The buffer is the same QVGA grayscale (W*H bytes) quirc was fed.
// On a laptop: base64 -d the [QRDUMP] payload to a .raw, then ZXing-cpp:
//   ImageView iv(buf, W, H, ImageFormat::Lum); auto r = ReadBarcode(iv, opts);
static uint8_t*       qrDumpBuf=nullptr;      // PSRAM, lazily allocated
static volatile int   qrDumpW=0, qrDumpH=0;   // captured dims
static volatile int   qrDumpLen=0;            // committed byte count (0 = nothing committed)
static volatile bool  qrDumpDone=false;       // true once a frame is committed this scan
static volatile bool  qrDumpHavePending=false;// a snapshot is held, awaiting commit
static int            qrDumpPendW=0, qrDumpPendH=0, qrDumpPendLen=0;
static void qrDumpReset(){ qrDumpLen=0; qrDumpW=0; qrDumpH=0; qrDumpDone=false;
                           qrDumpHavePending=false; qrDumpPendW=qrDumpPendH=qrDumpPendLen=0; }
// Snapshot the EXACT buffer fed to quirc, BEFORE quirc_end() consumes it. Silent.
// Overwrites any prior uncommitted snapshot — only the frame we later commit is kept.
static void qrDumpSnapshot(const uint8_t* fedToQuirc, int W, int H){
  if(qrDumpDone) return;                       // already kept a frame this scan
  int n=W*H;
  if(!qrDumpBuf){ qrDumpBuf=(uint8_t*)ps_malloc(n); if(!qrDumpBuf) return; }
  memcpy(qrDumpBuf, fedToQuirc, n);
  qrDumpPendW=W; qrDumpPendH=H; qrDumpPendLen=n; qrDumpHavePending=true;
}
// Promote the held snapshot to the kept dump. Called on the INVALID_ECC frame. Silent.
static void qrDumpCommit(){
  if(qrDumpDone || !qrDumpHavePending) return;
  qrDumpW=qrDumpPendW; qrDumpH=qrDumpPendH; qrDumpLen=qrDumpPendLen;
  qrDumpDone=true; qrDumpHavePending=false;
}
// Called at scan exit, where serial is safe. Streams base64 in line-wrapped chunks.
static void qrDumpFlush(){
  if(qrDumpLen<=0 || !qrDumpBuf) return;
  static const char b64[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  Serial.printf("[QRDUMP] BEGIN w=%d h=%d len=%d fmt=Lum\n", qrDumpW, qrDumpH, qrDumpLen);
  const uint8_t* p=qrDumpBuf; int n=qrDumpLen, col=0; char line[80]; int li=0;
  for(int i=0;i<n;i+=3){
    uint32_t v=p[i]<<16;
    int rem=n-i;
    if(rem>1) v|=p[i+1]<<8;
    if(rem>2) v|=p[i+2];
    line[li++]=b64[(v>>18)&0x3F];
    line[li++]=b64[(v>>12)&0x3F];
    line[li++]=(rem>1)?b64[(v>>6)&0x3F]:'=';
    line[li++]=(rem>2)?b64[v&0x3F]:'=';
    col+=4;
    if(col>=76 || i+3>=n){ line[li]=0; Serial.printf("[QRDUMP] %s\n", line); li=0; col=0; }
  }
  Serial.printf("[QRDUMP] END\n");
  qrDumpReset();
}
#else
static inline void qrDumpReset(){}
static inline void qrDumpSnapshot(const uint8_t*, int, int){}
static inline void qrDumpCommit(){}
static inline void qrDumpFlush(){}
#endif
// ── Scan viewfinder (23 Sep 2026, mockup A) ─────────────────────────────────
// One geometry for all three preview blitters. Box centred in the camera band
// (x 24..216, y 22..218): 34..206 both ways — the old vy=30 sat 4px high.
// Brackets are 3px, 24px arms, 6px outer radius (the rest of the UI is all
// rounded); the preview OUTSIDE the box is dimmed so the target reads at
// arm's length. vfClass() is per-pixel but branch-cheap: fold the point into
// the top-left corner by symmetry, then a few compares and one ring test.
//   returns 2 = bracket pixel (paint accent), 1 = outside the box (dim), 0 = inside
static const int VF_X = 34, VF_Y = 34, VF_W = 172, VF_H = 172;
static const int VF_ARM = 24, VF_T = 3, VF_R = 6;
static inline uint8_t vfClass(int x, int y){
  int u = x - VF_X; if (u > VF_W - u) u = VF_W - u;   // distance to nearer vertical edge
  int v = y - VF_Y; if (v > VF_H - v) v = VF_H - v;   // distance to nearer horizontal edge
  if (u < 0 || v < 0) return 1;
  if (u < VF_R && v < VF_R) {                        // rounded corner: ring of width VF_T
    int dx = VF_R - u, dy = VF_R - v; int d2 = dx*dx + dy*dy;
    if (d2 > VF_R*VF_R) return 1;                    // the shaved-off corner nub
    return (d2 > (VF_R - VF_T)*(VF_R - VF_T)) ? 2 : 0;
  }
  if (v < VF_T && u <= VF_ARM) return 2;             // horizontal arm
  if (u < VF_T && v <= VF_ARM) return 2;             // vertical arm
  return 0;
}
// Dim a preview grey for the region outside the box (~44%).
static inline uint8_t vfDim(uint8_t g){ return (uint8_t)((g * 7) >> 4); }


void dispPreview(bool airgap=false){
  if(qrTaskRunning) return;            // QR task owns the framebuffer right now
  camera_fb_t* fb=esp_camera_fb_get();
  if(!fb){
    static bool shown=false;
    if(!shown){shown=true;
      spr.fillSprite(C_BG);
      bool _ta = airgap && (effectiveMode==MODE_OFFLINE);
      uiHeader(airgap ? (_ta?"Airgap Sign":"Sign") : "Scan QR",
               _ta ? C_GREEN : C_EB_BRASS);
      // Rounded viewfinder placeholder
      spr.drawRoundRect(14,52,212,156,8,C_BORDER);
      // Corner guides
      int vlen=18; uint16_t vc=airgap?C_GREEN:C_AMBER;
      spr.drawFastHLine(22,60,vlen,vc); spr.drawFastVLine(22,60,vlen,vc);
      spr.drawFastHLine(218-vlen,60,vlen,vc); spr.drawFastVLine(218,60,vlen,vc);
      spr.drawFastHLine(22,200,vlen,vc); spr.drawFastVLine(22,200-vlen,vlen,vc);
      spr.drawFastHLine(218-vlen,200,vlen,vc); spr.drawFastVLine(218,200-vlen,vlen,vc);
      fSet(F_BODY); spr.setTextColor(C_DIM);
      fDrawCentre("Starting camera...", 120, 132);
      fEnd();
      dispPush();
    }
    return;
  }
  // V21.1: skip torn/partial frames — rendering a short buffer shows garbage
  // and reads past valid data. Only render complete frames.
  if(fb->len != (size_t)fb->width*fb->height){ esp_camera_fb_return(fb); return; }

  const int CAM_W=fb->width, CAM_H=fb->height;
  // V21.1: the OV2640 QVGA buffer is 320 wide but only the LEFT portion holds
  // valid image — the right ~columns are sensor padding/garbage (the "dead strip"
  // on the displayed right edge, since the view is rotated 90° so displayed-x
  // maps to sensor-column = srcY). The old centred offset (CAM_W-240)/2 = 40
  // sampled columns 40..279, pulling those dead right columns into view. Sample
  // the LEFT 240 columns (0..239) instead, which are all valid. If a thin dead
  // band still shows, nudge CAM_X_OFF up by a few px; if it over-corrects and a
  // strip appears on the other side, nudge down. Tunable in one place:
  const int CAM_X_OFF = 0;          // was (CAM_W-240)/2 = 40
  const int X_OFF = CAM_X_OFF;
  const int HDR_H=26, FTR_Y=218;
  const int vx=VF_X, vy=VF_Y, vw=VF_W, vh=VF_H; (void)vx; (void)vy; (void)vw; (void)vh;   // geometry now in vfClass()

  static TFT_eSprite hdrSpr(&tft), ftrSpr(&tft);
  static bool spritesInit=false;
  if(!spritesInit){
    hdrSpr.setAttribute(PSRAM_ENABLE, 1); ftrSpr.setAttribute(PSRAM_ENABLE, 1); // reclaim ~23K internal -> PSRAM
    hdrSpr.createSprite(240,HDR_H);
    ftrSpr.createSprite(240,22);
    spritesInit=true;
  }

  uint16_t accentCol=(airgap && effectiveMode==MODE_OFFLINE)?C_GREEN:C_AMBER;
  hdrSpr.fillSprite(C_PANEL);
  hdrSpr.fillRect(0,0,3,HDR_H,accentCol);
  hdrSpr.drawFastHLine(0,HDR_H-1,240,C_VDIM);
  if(fontBufs[F_HEAD]) hdrSpr.loadFont(fontBufs[F_HEAD]);
  hdrSpr.setTextColor(accentCol);
  hdrSpr.drawString(airgap?((effectiveMode==MODE_OFFLINE)?"AIRGAP SIGN":"SIGN"):"SCAN QR", 10, 4);   // caps: header rule
  hdrSpr.setTextColor(C_VDIM);
  hdrSpr.unloadFont();
  if(fontBufs[F_SMALL]) hdrSpr.loadFont(fontBufs[F_SMALL]);
  hdrSpr.drawString("hold steady", 148, 8);
  hdrSpr.unloadFont();

  ftrSpr.fillSprite(C_PANEL);
  ftrSpr.drawFastHLine(0,0,240,C_VDIM);
  if(fontBufs[F_SMALL]) ftrSpr.loadFont(fontBufs[F_SMALL]);
  ftrSpr.setTextColor(C_DIM);
#if QR_ONSCREEN_DIAG
  // V21_2: live scan diagnostic in the footer (serial is unusable on the bench —
  // USB DMA contention breaks scanning). Shows the last attempt's outcome so a
  // failing fast-animation scan can be diagnosed by eye:
  //   torn        = only got partial/short frames (DMA/heap marginal)
  //   id=0        = quirc located NO code (too small/blurry/far/dark)
  //   id=N c=M F  = located N codes, first grid M cells, decode FAILED (smear/limit)
  //   id=N c=M OK = located + decoded (a fragment was read this frame)
  if(airgap){
    char dbg[40];
    if(qrDiagTorn) snprintf(dbg,sizeof(dbg),"torn frame");
    else if(qrDiagIdentified==0) snprintf(dbg,sizeof(dbg),"id=0  (no code)");
    else snprintf(dbg,sizeof(dbg),"id=%d c=%d %s%s",qrDiagIdentified,qrDiagCells,qrDiagOk?"OK":"FAIL",g_robustCellLive?" RC5":"");
    int dw=ftrSpr.textWidth(dbg);
    ftrSpr.drawString(dbg,(240-dw)/2,6);
  }
  // (production) no footer hint text — clean strip only; matches no-hints UI.
#else
  // (production) no footer hint text — clean strip only; matches no-hints UI.
#endif
  ftrSpr.unloadFont();

  static uint16_t lineBuf[240];
  const uint8_t* src=fb->buf;
  auto swap16=[](uint16_t c)->uint16_t{return (c>>8)|(c<<8);};
  uint16_t acSw=swap16(accentCol);

  DISP_LOCK();
  tft.setAddrWindow(0,0,240,240);
  tft.startWrite();
  for(int y=0;y<240;y++){
    if(y<HDR_H){
      for(int x=0;x<240;x++) lineBuf[x]=swap16(hdrSpr.readPixel(x,y));
    } else if(y>=FTR_Y){
      for(int x=0;x<240;x++) lineBuf[x]=swap16(ftrSpr.readPixel(x,y-FTR_Y));
    } else {
      // 90° CCW (axes inverted vs first attempt, which came out 180° off):
      //   srcX = (CAM_H-1) - y
      //   srcY = (x + X_OFF)
      // X_OFF keeps the 240-wide window centred in the 320-wide sensor.
      int srcX=(CAM_H-1)-y; if(srcX<0) srcX=0; else if(srcX>CAM_H-1) srcX=CAM_H-1;
      for(int x=0;x<240;x++){
        int srcY=(x+X_OFF);
        if(srcY<0) srcY=0; else if(srcY>CAM_W-1) srcY=CAM_W-1;
        uint8_t g=src[srcY*CAM_W+srcX];
        uint8_t vf=vfClass(x,y);
        if(vf==1) g=vfDim(g);
        uint16_t px=(vf==2) ? acSw : swap16(((g&0xF8)<<8)|((g&0xFC)<<3)|(g>>3));
        lineBuf[x]=px;
      }
    }
    tft.pushPixels(lineBuf,240);
  }
  tft.endWrite();
  DISP_UNLOCK();
  esp_camera_fb_return(fb);
}

// ── Airgap live preview with UR progress footer ──────────────────────────────
// V21_2: keeps the live camera view up DURING multipart UR collection, with a
// progress bar in the footer instead of swapping to a static "part X of Y"
// screen. Renders a frame the CALLER already grabbed — does NOT grab or return
// the framebuffer (avoids a second esp_camera_fb_get, hence no dual-fb_get
// race). qrScanOnce() calls this with the frame it's about to decode, so one
// grab feeds both display and decode at full scan rate.
//   urGot/urTotal: fountain progress. urTotal<=0 => indeterminate ("scanning").
static void dispAirgapPreviewFrame(camera_fb_t* fb, int urGot, int urTotal){
  // fb may be NULL (caller had no drawable frame this cycle — all grabs torn).
  // We still paint the header + footer (progress bar) and fill the camera band
  // with a neutral colour, so the bar never blanks during capture. fb may also
  // be non-NULL but torn (len != W*H); same handling — strips always draw, only
  // the camera image is gated.
  bool frameOk = (fb != NULL) && (fb->len == (size_t)fb->width*fb->height);
  const int CAM_W = frameOk ? fb->width  : 1;
  const int CAM_H = frameOk ? fb->height : 1;
  const int X_OFF=0;
  const int HDR_H=22, FTR_Y=218;
  const int vx=VF_X, vy=VF_Y, vw=VF_W, vh=VF_H; (void)vx; (void)vy; (void)vw; (void)vh;   // geometry now in vfClass()
  static TFT_eSprite hdrSpr(&tft), ftrSpr(&tft);
  static bool spritesInit=false;
  if(!spritesInit){
    // Pin 16bpp explicitly: readPixel() below assumes RGB565. Without this the
    // sprites use the default depth, and a depth mismatch makes readPixel return
    // values swap16() misinterprets — intermittent garbage/blank in the footer
    // (the progress-bar flicker). The main `spr` sets depth 16; these must match.
    hdrSpr.setColorDepth(16); ftrSpr.setColorDepth(16);
    hdrSpr.setAttribute(PSRAM_ENABLE, 1); ftrSpr.setAttribute(PSRAM_ENABLE, 1); // reclaim ~21K internal -> PSRAM
    hdrSpr.createSprite(240,HDR_H); ftrSpr.createSprite(240,22);
    spritesInit=true;
  }
  // Honest label kept for accent colour only (green offline / amber online),
  // but no text is drawn — clean black frame top.
  bool _trueAirgap = (effectiveMode==MODE_OFFLINE);
  uint16_t accentCol = _trueAirgap ? C_GREEN : C_AMBER;
  // Header — plain black frame (no accent line, no divider, no text).
  hdrSpr.fillSprite(TFT_BLACK);
  // Footer — plain black frame with ONLY the progress bar (no divider line, no
  // N/T count text, no "scanning..." text). Bar shows once total is known.
  ftrSpr.fillSprite(TFT_BLACK);
  if(urTotal>0){
    const int barX=10, barY=7, barH=8;
    int barW=240 - barX*2;            // centred, symmetric margins
    // track
    ftrSpr.drawRoundRect(barX,barY,barW,barH,2,C_VDIM);
    int fillW=(int)((long)(barW-2)*urGot/urTotal);
    if(fillW<0) fillW=0; if(fillW>barW-2) fillW=barW-2;
    if(fillW>0) ftrSpr.fillRoundRect(barX+1,barY+1,fillW,barH-2,1,accentCol);
  }
  // else: empty black footer (no text) until the total is known.
  // Compose in three direct pushes — NO readPixel round-trip (that readback was
  // depth-fragile and the source of the progress-bar flicker). The camera image
  // needs per-pixel rotation so it's still streamed row-by-row, but ONLY for the
  // camera band; the header and footer are pushed straight to the screen with
  // pushSprite (their own correct format path), so the bar always renders.
  static uint16_t lineBuf[240];
  const uint8_t* src = frameOk ? fb->buf : nullptr;   // only deref when drawable
  auto swap16=[](uint16_t c)->uint16_t{return (c>>8)|(c<<8);};
  uint16_t acSw=swap16(accentCol);
  uint16_t blackSw=swap16(TFT_BLACK);
  DISP_LOCK();
  // 1) Header strip (rows 0..HDR_H-1)
  hdrSpr.pushSprite(0, 0);
  // 2) Footer strip (rows FTR_Y..239)
  ftrSpr.pushSprite(0, FTR_Y);
  // 3) Rotated camera band (rows HDR_H..FTR_Y-1) streamed in one window
  tft.setAddrWindow(0, HDR_H, 240, FTR_Y - HDR_H);
  tft.startWrite();
  for(int y=HDR_H; y<FTR_Y; y++){
    // Mirrors dispAirgapPreviewFrameRaw's vertical mapping (transposed draw:
    // display-y = sensor COLUMN, so range/centre over CAM_W with the
    // CAM_PREVIEW_Y_OFF band-centring shift). This twin is currently only
    // called with fb=NULL (strips-only repaint), but keep the mapping
    // identical so the two bodies never diverge if it's revived.
    int srcX=(CAM_H-1)-y + CAM_PREVIEW_Y_OFF;
    srcX = ((srcX % CAM_W) + CAM_W) % CAM_W;
    for(int x=0;x<240;x++){
      uint16_t px;
      uint8_t vf=vfClass(x,y);
      // Left/right black border — same idea as the top/bottom strips, so the
      // live view is framed in black on all 4 sides. SIDE_W matches the visual
      // weight of the top/bottom bands. Columns inside the border are black.
      const int SIDE_W = 24;
      if(x < SIDE_W || x >= 240-SIDE_W){
        px = blackSw;
      } else if(frameOk){
        int srcY=(x+X_OFF);
        if(srcY<0) srcY=0; else if(srcY>CAM_W-1) srcY=CAM_W-1;
        uint8_t g=src[srcY*CAM_W+srcX];
        if(vf==1) g=vfDim(g);
        px=swap16(((g&0xF8)<<8)|((g&0xFC)<<3)|(g>>3));
      } else {
        px=blackSw;   // torn frame — black, not grey
      }
      if(vf==2) px=acSw;
      lineBuf[x]=px;
    }
    tft.pushPixels(lineBuf,240);
  }
  tft.endWrite();
  DISP_UNLOCK();
}

// V22.4: raw-buffer twin of dispAirgapPreviewFrame. Draws from a plain grayscale
// buffer + dimensions instead of a camera_fb_t, so qrScanOnce can return the
// framebuffer to the DVP IMMEDIATELY after the memcpy (closing the fb_count=1
// overrun window that orphaned the GDMA channel) and still render the live view
// from its own snapshot. Body is identical to the fb version; only the source
// changes. rawBuf==NULL => neutral/torn handling (strips still paint).
static void dispAirgapPreviewFrameRaw(const uint8_t* rawBuf, int rawW, int rawH, int urGot, int urTotal){
  bool frameOk = (rawBuf != NULL) && (rawW>0) && (rawH>0);
  const int CAM_W = frameOk ? rawW : 1;
  const int CAM_H = frameOk ? rawH : 1;
  const int X_OFF=0;
  const int HDR_H=22, FTR_Y=218;
  const int vx=VF_X, vy=VF_Y, vw=VF_W, vh=VF_H; (void)vx; (void)vy; (void)vw; (void)vh;   // geometry now in vfClass()
  static TFT_eSprite hdrSpr(&tft), ftrSpr(&tft);
  static bool spritesInit=false;
  if(!spritesInit){
    hdrSpr.setColorDepth(16); ftrSpr.setColorDepth(16);
    hdrSpr.setAttribute(PSRAM_ENABLE, 1); ftrSpr.setAttribute(PSRAM_ENABLE, 1); // reclaim ~21K internal -> PSRAM
    hdrSpr.createSprite(240,HDR_H); ftrSpr.createSprite(240,22);
    spritesInit=true;
  }
  bool _trueAirgap = (effectiveMode==MODE_OFFLINE);
  uint16_t accentCol = _trueAirgap ? C_GREEN : C_AMBER;
  hdrSpr.fillSprite(TFT_BLACK);
  ftrSpr.fillSprite(TFT_BLACK);
  if(urTotal>0){
    const int barX=10, barY=7, barH=8;
    int barW=240 - barX*2;
    ftrSpr.drawRoundRect(barX,barY,barW,barH,2,C_VDIM);
    int fillW=(int)((long)(barW-2)*urGot/urTotal);
    if(fillW<0) fillW=0; if(fillW>barW-2) fillW=barW-2;
    if(fillW>0) ftrSpr.fillRoundRect(barX+1,barY+1,fillW,barH-2,1,accentCol);
  }
  static uint16_t lineBuf[240];
  const uint8_t* src = frameOk ? rawBuf : nullptr;
  auto swap16=[](uint16_t c)->uint16_t{return (c>>8)|(c<<8);};
  uint16_t acSw=swap16(accentCol);
  uint16_t blackSw=swap16(TFT_BLACK);
  DISP_LOCK();
  hdrSpr.pushSprite(0, 0);
  ftrSpr.pushSprite(0, FTR_Y);
  tft.setAddrWindow(0, HDR_H, 240, FTR_Y - HDR_H);
  tft.startWrite();
  for(int y=HDR_H; y<FTR_Y; y++){
#if CAM_PREVIEW_ROT180
    int srcX=y + CAM_PREVIEW_Y_OFF;
#else
    int srcX=(CAM_H-1)-y + CAM_PREVIEW_Y_OFF;
#endif
    // srcX is a sensor COLUMN index (transposed draw), so it legitimately
    // ranges over CAM_W (320), not CAM_H — the old clamp to CAM_H-1 was what
    // pinned the visible band to columns 22..217 and biased the centre. Wrap
    // (not clamp) over CAM_W, matching srcY, so offsets re-centre cleanly.
    srcX = ((srcX % CAM_W) + CAM_W) % CAM_W;
    for(int x=0;x<240;x++){
      uint16_t px;
      uint8_t vf=vfClass(x,y);
      const int SIDE_W = 24;
      if(x < SIDE_W || x >= 240-SIDE_W){
        px = blackSw;
      } else if(frameOk){
#if CAM_PREVIEW_ROT180
        int srcY=(CAM_W-1)-(x+X_OFF)+CAM_PREVIEW_X_OFF;
#else
        int srcY=(x+X_OFF)+CAM_PREVIEW_X_OFF;
#endif
        // Wrap (not clamp) so an alignment shift re-centres the image instead
        // of smearing the edge column. CAM_W is positive so the (%+%)%% form
        // keeps the index in range for negative offsets too.
        srcY = ((srcY % CAM_W) + CAM_W) % CAM_W;
        uint8_t g=src[srcY*CAM_W+srcX];
        if(vf==1) g=vfDim(g);
        px=swap16(((g&0xF8)<<8)|((g&0xFC)<<3)|(g>>3));
      } else {
        px=blackSw;
      }
      if(vf==2) px=acSw;
      lineBuf[x]=px;
    }
    tft.pushPixels(lineBuf,240);
  }
  tft.endWrite();
  DISP_UNLOCK();
}

// ── QR renderer ────────────────────────────────────────────────────────────
class QRTFT {
  TFT_eSprite& s;
public:
  QRTFT(TFT_eSprite& s):s(s){}
  // QR alphanumeric charset per spec: 0-9 A-Z space $ % * + - . / :
  static bool qrIsAlnum(const char* s){
    for(; *s; ++s){
      char c=*s;
      if((c>='0'&&c<='9')||(c>='A'&&c<='Z')) continue;
      if(c==' '||c=='$'||c=='%'||c=='*'||c=='+'||c=='-'||c=='.'||c=='/'||c==':') continue;
      return false;
    }
    return true;
  }
  // ECC_LOW capacities, ALPHANUMERIC mode (uppercase UR frames land here —
  // ~31% more chars/version than the byte-mode table below).
  static int alnumVersionForLen(int len){
    if(len<=25)return 1;if(len<=47)return 2;if(len<=77)return 3;
    if(len<=114)return 4;if(len<=154)return 5;if(len<=195)return 6;
    if(len<=224)return 7;if(len<=279)return 8;if(len<=335)return 9;
    if(len<=395)return 10;if(len<=468)return 11;if(len<=535)return 12;
    if(len<=586)return 13;if(len<=644)return 14;if(len<=718)return 15;
    if(len<=792)return 16;if(len<=858)return 17;if(len<=929)return 18;
    if(len<=1003)return 19;if(len<=1091)return 20;
    return -1;
  }
  static int versionForLen(int len){
    if(len<=17)return 1;if(len<=32)return 2;if(len<=53)return 3;
    if(len<=78)return 4;if(len<=106)return 5;if(len<=134)return 6;
    if(len<=154)return 7;if(len<=192)return 8;if(len<=230)return 9;
    if(len<=271)return 10;if(len<=321)return 11;if(len<=367)return 12;
    if(len<=425)return 13;if(len<=458)return 14;if(len<=520)return 15;
    if(len<=586)return 16;if(len<=644)return 17;if(len<=718)return 18;
    if(len<=792)return 19;if(len<=858)return 20;
    return -1;
  }
  void show(const char* msg, const char* topLabel=nullptr, const char* botLabel=nullptr){
    fEnd(); // unload any active font before drawing QR
    int len=strlen(msg), v=versionForLen(len);
    if(v<0){dispError("QR too large");return;}
    QRCode qr;
    memset(globalQrcodeData,0,QRCODE_DATA_SZ);
    if(qrcode_initText(&qr,globalQrcodeData,v,ECC_LOW,msg)!=0){dispError("QR error");return;}
    s.fillSprite(C_BG);

    // Full-screen QR, centred, with a white quiet-zone border. No header or
    // footer strips — the QR fills the screen cleanly. The white background has
    // slightly rounded outer corners for a softer look; the rounding stays
    // within the quiet zone so it never clips a black module.
    // (topLabel/botLabel are accepted for call-site compatibility but no longer
    // drawn.)
    (void)topLabel; (void)botLabel;
    const int BORDER = 8;
    const int AVAIL  = 240 - BORDER * 2;
    int sc = AVAIL / (int)qr.size;
    if(sc < 1) sc = 1;
    if(sc > 6) sc = 6;
    int dim = (int)qr.size * sc;
    int ox  = (240 - dim) / 2;
    int oy  = (240 - dim) / 2;

    // White background for the QR area + quiet-zone border, rounded corners.
    s.fillRoundRect(ox - BORDER, oy - BORDER, dim + BORDER*2, dim + BORDER*2, 10, C_QR_WHITE);

    // Draw QR modules
    for(int y=0;y<(int)qr.size;y++)
      for(int x=0;x<(int)qr.size;x++)
        if(qrcode_getModule(&qr,x,y))
          s.fillRect(ox+x*sc, oy+y*sc, sc, sc, TFT_BLACK);

    DISP_LOCK(); s.pushSprite(0,0); DISP_UNLOCK();
  }

  // V22: render ONE fragment of an animated UR sequence. Caller cycles `idx`
  // 0..nFrags-1 on a timer. Footer shows frame counter so the user can see it
  // animating and knows the coordinator needs to capture all frames.
  void showUrFrame(const char* fragStr, int idx, int nFrags){
    (void)idx; (void)nFrags;   // count shown once on the pre-display splash
    fEnd();
    // FULL-SCREEN layout (was: header+footer+gaps eating 64 of 240px, leaving
    // a 164px band -> 2px modules on a v10 frame). Uppercase UR fragments are
    // QR-alphanumeric, so use the alnum capacity table: an 80-byte fragment is
    // ~219 chars = v7 = 45 modules = 5px/module = a 225px QR with a 7px white
    // quiet border. Every pixel of the panel is QR.
    int len=strlen(fragStr);
    int v = qrIsAlnum(fragStr) ? alnumVersionForLen(len) : versionForLen(len);
    if(v<0){dispError("UR frag too big");return;}
    QRCode qr;
    memset(globalQrcodeData,0,QRCODE_DATA_SZ);
    if(qrcode_initText(&qr,globalQrcodeData,v,ECC_LOW,fragStr)!=0){dispError("QR error");return;}
    const int BORDER_MIN=6;
    int avail = 240 - BORDER_MIN*2;
    int sc = avail/(int)qr.size; if(sc<1)sc=1; if(sc>8)sc=8;
    int dim=(int)qr.size*sc;
    int ox=(240-dim)/2, oy=(240-dim)/2;
    s.fillSprite(TFT_BLACK);
    s.fillRect(0,0,240,240,C_QR_WHITE);   // full-bleed quiet zone
    for(int y=0;y<(int)qr.size;y++)
      for(int x=0;x<(int)qr.size;x++)
        if(qrcode_getModule(&qr,x,y)) s.fillRect(ox+x*sc,oy+y*sc,sc,sc,TFT_BLACK);
    DISP_LOCK(); s.pushSprite(0,0); DISP_UNLOCK();
  }
};
QRTFT qrDisp(spr);

// Standalone wrapper for forward-declared use in menus
void showQR(const char* msg, const char* topLabel=nullptr, const char* botLabel=nullptr){
  qrDisp.show(msg, topLabel, botLabel);
}

// Two-QR bunker pager. Shows two scannable QRs and lets the user toggle between
// them with BTN1; BTN2/BTN4 exits. Returns true on a normal user exit, false if
// it bailed because a pairing PIN / pair-confirmed splash is pending (caller
// should then let runStateMachine paint that overlay rather than repaint).
//
//   Page 0 (primary): https://favillakey.io/bunker#<bunker://...>
//     "scan with your phone camera" — opens favillakey.io/bunker which reads
//     the fragment and autofills the pair field. Fragment keeps the secret
//     off the server.
//   Page 1: raw bunker://... — "for other Nostr apps" (Coracle, Amethyst etc.
//     scan this directly; they don't understand the https wrapper).
//
// Yields to pairing events the same way the other QR screens do, so a PWA that
// pairs while a QR is on screen can still reveal its PIN.
bool showBunkerQrPager(){
  if(!wallet.exists||!wallet.unlocked){ dispError("Unlock keys first"); errorPause(); return true; }
  String httpsUri = bunkerHttpsURI();
  String rawUri   = bunkerURI();
  int page = 0;  // 0 = https-wrapped (primary), 1 = raw bunker://
  auto paint = [&](){
    if(page==0) qrDisp.show(httpsUri.c_str(), "Bunker - phone", nullptr);
    else        qrDisp.show(rawUri.c_str(),   "Bunker - apps",  nullptr);
  };
  paint();
  while(true){
    pumpInputs();
    btn1.poll(); btn2.poll(); btn4.poll();
    if(btn1.isPressed()){            // toggle between the two QRs
      page ^= 1;
      paint();
    }
    if(btn2.isPressed()||btn4.isPressed()) return true;   // exit
    if(pendingDisplayMsg||pendingReturnToMenu) return false;  // bail for PIN overlay
    delay(10);
  }
}

// Show ONE specific bunker QR full-screen (which: 0 = phone/https-wrapped,
// 1 = app/raw bunker://). Any button exits. Yields to a pairing PIN like the
// pager. Used by the two QR cards on the bunker status screen.
// Small two-item chooser used by the Favilla card: Continue vs Rotate.
// Returns 0=Continue, 1=Rotate, -1=Back/cancel.
static int bunkerFavillaChooser(){
  const char* items[] = {"Continue", "Rotate", "Pairings", "History"};
  const int N = 4;
  int sel = 0;
  auto draw = [&](){
    spr.fillSprite(C_BG);
    uiHeader("Favilla", C_EB_BRASS);
    int yStart = HEADER_H + 10, rowH = 38;
    for(int i=0;i<N;i++){
      int y = yStart + i*rowH;
      bool s = (i==sel);
      uint16_t accent = (i==1) ? C_RED : C_EB_BRASS;   // Rotate is destructive → red
      if(s){ spr.fillRoundRect(12, y-4, 216, rowH-6, 8, ebMix(C_BG, accent, 28)); spr.drawRoundRect(12, y-4, 216, rowH-6, 8, accent); }
      fSet(F_HEAD);
      spr.setTextColor(s ? ((i==1)?C_RED:C_EB_INK) : C_EB_GREY);
      spr.drawString(items[i], 24, y+4);
      fEnd();
    }
    fSet(F_BODY); spr.setTextColor(C_MUTED);
    const char* hint = (sel==1) ? "Rotate revokes ALL paired apps"
                     : (sel==2) ? "View / revoke paired apps"
                     : (sel==3) ? "Recent signatures"
                                : "Show master pairing QR";
    fDrawCentre(hint, 120, 206);
    fEnd();
    dispPush();
  };
  draw();
  drainButtonsAfterTransition();
  while(true){
    pumpInputs();
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    esp_task_wdt_reset();
    if(btn1.isPressed()){ sel=(sel+1)%N; draw(); }
    if(btn3.isPressed()){ sel=(sel-1+N)%N; draw(); }
    if(btn4.isPressed()) return -1;
    if(btn2.isPressed()) return sel;
    if(pendingDisplayMsg||pendingReturnToMenu) return -1;
    delay(10);
  }
}

// ── Favilla > History (5 Oct 2026) ───────────────────────────────────────────
// The last signatures of this power-on life, newest first: kind word, kind
// number, how it was approved, how long ago. Scroll with BTN1/BTN3, BACK exits.
static void bunkerHistoryScreen(){
  int top = 0;
  const int ROWS = 5, rowH = 36, y0 = HEADER_H + 6;
  auto draw = [&](){
    spr.fillSprite(C_BG);
    uiHeader("History", C_EB_BRASS);
    if(!g_signHistN){
      fSet(F_BODY); spr.setTextColor(C_MUTED);
      fDrawCentre("No signatures yet", 120, 110); fEnd();
      dispPush(); return;
    }
    for(int r = 0; r < ROWS && top + r < g_signHistN; r++){
      const SignHist& h = g_signHist[top + r];
      int y = y0 + r * rowH;
      char ago[8]; fmtAgo(ago, sizeof(ago), h.atMs);
      char kindNum[12]; snprintf(kindNum, sizeof(kindNum), "kind %d", h.kind);
      fSet(F_BRAND_B14); spr.setTextColor(C_EB_INK);
      { int x = 12; for(const char* q = ebSignKindWord(h.kind); *q; q++){ char cs[2] = {*q, 0}; spr.drawString(cs, x, y + 2); x += spr.textWidth(cs) + 1; } }
      fEnd();
      fSet(F_SMALL); spr.setTextColor(C_EB_GREY);
      spr.drawString(kindNum, 12, y + 20);
      spr.drawString(h.manual ? "approved on KEY" : "auto-signed", 80, y + 20);
      fEnd();
      fSet(F_MONO); spr.setTextColor(C_EB_GREY);
      int w = spr.textWidth(ago); spr.drawString(ago, 228 - w, y + 4);
      fEnd();
      if(r < ROWS - 1 && top + r + 1 < g_signHistN) spr.drawFastHLine(12, y + rowH - 2, 216, C_EB_LINE);
    }
    if(g_signHistN > ROWS){
      const int TX = 237, TY = y0, TH = ROWS * rowH - 4;
      int th = (TH * ROWS) / g_signHistN; if(th < 8) th = 8;
      int ty = TY + (TH - th) * top / (g_signHistN - ROWS);
      spr.drawFastVLine(TX, TY, TH, C_EB_LINE);
      spr.fillRect(TX - 1, ty, 3, th, C_EB_BRASS);
    }
    dispPush();
  };
  draw();
  drainButtonsAfterTransition();
  uint32_t lastTick = millis();
  while(true){
    pumpInputs();
    btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
    esp_task_wdt_reset();
    if(btn1.isPressed()){ if(top + ROWS < g_signHistN) top++; draw(); }
    if(btn3.isPressed()){ if(top > 0) top--; draw(); }
    if(btn4.isPressed() || btn2.isPressed()) return;
    if(pendingDisplayMsg||pendingReturnToMenu) return;
    if(millis() - lastTick > 5000){ lastTick = millis(); draw(); }   // "ago" column stays honest
    delay(10);
  }
}
