// ── Pairings revocation screen (device-only) ────────────────────────────────
// Lists allowlist entries. Master is display-only (rotate via Favilla>Rotate,
// which cascades). Slaves can be revoked individually; a final row revokes all
// slaves at once. BTN1/BTN3 move, BTN2 acts, BTN4 exits.
void bunkerPairingsScreen(){
  while(true){
    // Build a view list: each slave index, then a synthetic "Revoke ALL" row.
    int slaveIdx[BP_ALLOW_MAX]; int nSlaves=0; int masterIdx=-1;
    for(int i=0;i<BP_ALLOW_MAX;i++){
      if(!bpClients[i].pubHex[0]) continue;
      if(bpClients[i].role==BP_ROLE_MASTER) masterIdx=i;
      else slaveIdx[nSlaves++]=i;
    }
    int rows = nSlaves + (nSlaves>0 ? 1 : 0);   // +1 for "Revoke ALL" if any slaves
    static int sel = 0;
    if(sel >= rows) sel = rows>0 ? rows-1 : 0;

    auto ago = [](uint32_t t)->String{
      if(t==0) return String("--");
      time_t now; time(&now);
      if(now<1700000000L) return String("--");
      long d = (long)now - (long)t;
      if(d<60) return String(d)+"s";
      if(d<3600) return String(d/60)+"m";
      if(d<86400) return String(d/3600)+"h";
      return String(d/86400)+"d";
    };

    spr.fillSprite(C_BG);
    uiHeader("PAIRINGS", C_BLUE);
    int y = HEADER_H + 10;

    // Master row (display-only)
    fSet(F_BODY); spr.setTextColor(C_MUTED);
    if(masterIdx>=0){
      String m = String("master  ")+bpClients[masterIdx].label;
      spr.drawString("MASTER", 12, y);
      spr.setTextColor(C_DIM);
      spr.drawString(bpClients[masterIdx].label, 80, y);
    } else {
      spr.drawString("MASTER  (unpaired)", 12, y);
    }
    fEnd();
    y += 22;
    spr.drawFastHLine(8, y, 224, C_BORDER2); y += 8;

    if(rows==0){
      fSet(F_BODY); spr.setTextColor(C_DIM);
      fDrawCentre("No paired apps", 120, 120); fEnd();
    } else {
      int rowH = 30;
      for(int r=0;r<rows;r++){
        int ry = y + r*rowH;
        bool s = (r==sel);
        bool isAll = (r==nSlaves);
        if(s) spr.drawRoundRect(8, ry-2, 224, rowH-4, 6, isAll?C_RED:C_BLUE);
        if(isAll){
          fSet(F_HEAD); spr.setTextColor(s?C_RED:C_DIM);
          spr.drawString("Revoke ALL slaves", 18, ry+4); fEnd();
        } else {
          int ci = slaveIdx[r];
          fSet(F_BODY); spr.setTextColor(C_MUTED);
          String meta = String(ago(bpClients[ci].pairedAt))+"  "+String(bpClients[ci].pubHex).substring(0,8);
          int mw = spr.textWidth(meta.c_str());
          spr.drawString(meta.c_str(), 232-mw-6, ry+4); fEnd();
          // Label at 12px now: trim it so it never runs into the meta on the right.
          fSet(F_BODY); spr.setTextColor(s?C_FG:C_DIM);
          { char lb[40]; strncpy(lb, bpClients[ci].label, sizeof(lb)-1); lb[sizeof(lb)-1]=0;
            int room = (232-mw-6) - 18 - 8;
            while(strlen(lb) > 3 && spr.textWidth(lb) > room) lb[strlen(lb)-1] = 0;
            spr.drawString(lb, 18, ry+2); } fEnd();
        }
      }
    }
    fSet(F_BODY); spr.setTextColor(C_DIM);
    fDrawCentre("BTN2 revoke   BACK exit", 120, 210); fEnd();
    dispPush();

    drainButtonsAfterTransition();
    // input loop for this paint
    bool repaint=false;
    while(!repaint){
      pumpInputs();
      btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
      esp_task_wdt_reset();
      if(btn4.isPressed()) return;
      if(rows>0 && btn1.isPressed()){ sel=(sel+1)%rows; repaint=true; }
      else if(rows>0 && btn3.isPressed()){ sel=(sel-1+rows)%rows; repaint=true; }
      else if(rows>0 && btn2.isPressed()){
        if(sel==nSlaves){   // Revoke ALL
          if(bunkerConfirm("Revoke ALL", "Revoke all paired apps?", "Master stays paired.")){
            bpRevokeAllSlaves();
          }
        } else {
          int ci = slaveIdx[sel];
          char nm[BP_LABEL_MAX]; strncpy(nm, bpClients[ci].label, BP_LABEL_MAX-1); nm[BP_LABEL_MAX-1]=0;
          if(bunkerConfirm("Revoke", nm, "Revoke this app?")){
            bpRevokeSlave(ci);
          }
        }
        sel=0; repaint=true;   // rebuild list
      }
      if(pendingDisplayMsg||pendingReturnToMenu) return;
      delay(10);
    }
  }
}

bool showSingleBunkerQr(int which){
  if(!wallet.exists||!wallet.unlocked){ dispError("Unlock keys first"); errorPause(); return true; }

  // ── Favilla card: Continue / Rotate chooser ──────────────────────────────
  if(which==0){
    LOG_BOOT("[ROTATE] Favilla card opened — entering chooser\n");
    bpDumpState("before chooser");
    int choice = bunkerFavillaChooser();
    LOG_BOOT("[ROTATE] chooser returned %d (0=Continue 1=Rotate 2=Pairings -1=Back)\n", choice);
    if(choice < 0) return true;                 // back → status screen
    if(choice == 2){                            // Pairings (view/revoke)
      bunkerPairingsScreen();
      drainButtonsAfterTransition();
      return true;                              // back to status screen after
    }
    if(choice == 3){                            // History (recent signatures)
      bunkerHistoryScreen();
      drainButtonsAfterTransition();
      return true;
    }
    if(choice == 1){                            // Rotate
      LOG_BOOT("[ROTATE] Rotate selected — showing confirm\n");
      bool confirmed = bunkerRotateConfirm();
      LOG_BOOT("[ROTATE] confirm result: %s\n", confirmed ? "CONFIRMED" : "cancelled");
      if(!confirmed) return true;               // cancelled
      char fresh[33];
      bpRotateMaster(fresh);                    // kills master+slaves, mints new master token
      bpDumpState("after rotate");
      dispError("");                            // brief clear
      spr.fillSprite(C_BG); uiHeader("ROTATED", C_GREEN);
      fSet(F_BODY); spr.setTextColor(C_FG); fDrawCentre("New master minted", 120, 100); fEnd();
      fSet(F_BODY); spr.setTextColor(C_MUTED); fDrawCentre("Scan to re-pair", 120, 130); fEnd();
      dispPush(); delay(900);
      // fall through to show the new master QR
    }
    String uri = bunkerHttpsURI();
    LOG_BOOT("[ROTATE] QR URI to display: %s\n", uri.c_str());
    if(uri.indexOf("MASTER_PAIRED") >= 0){
      // Master already paired and not rotating — nothing to bootstrap.
      spr.fillSprite(C_BG); uiHeader("Favilla", C_EB_INK);
      fSet(F_BODY); spr.setTextColor(C_FG); fDrawCentre("Master already paired", 120, 88); fEnd();
      fSet(F_BODY); spr.setTextColor(C_MUTED);
      fDrawCentre("Use Rotate to issue a", 120, 124);
      fDrawCentre("fresh master pairing QR.", 120, 142); fEnd();
      dispPush();
      drainButtonsAfterTransition();
      while(true){
        pumpInputs(); btn1.poll(); btn2.poll(); btn4.poll();
        esp_task_wdt_reset();
        if(btn1.isPressed()||btn2.isPressed()||btn4.isPressed()) return true;
        if(pendingDisplayMsg||pendingReturnToMenu) return false;
        delay(10);
      }
    }
    qrDisp.show(uri.c_str(), "Favilla", nullptr);
    while(true){
      pumpInputs();
      btn1.poll(); btn2.poll(); btn4.poll();
      if(btn1.isPressed()||btn2.isPressed()||btn4.isPressed()) return true;
      if(pendingDisplayMsg||pendingReturnToMenu) return false;
      delay(10);
    }
  }

  // ── Nostr App card: raw bunker:// for third-party apps ────────────────────
  // (Same gating: if the master bootstrap token is consumed, the raw URI also
  // returns MASTER_PAIRED. Third-party apps pair as SLAVES via minted tokens
  // from the master client, so a consumed bootstrap here is expected.)
  String uri = bunkerURI();
  if(uri.indexOf("MASTER_PAIRED") >= 0){
    spr.fillSprite(C_BG); uiHeader("NOSTR APP", C_PURPLE);
    fSet(F_BODY); spr.setTextColor(C_FG); fDrawCentre("Master already paired", 120, 80); fEnd();
    fSet(F_BODY); spr.setTextColor(C_MUTED);
    fDrawCentre("Mint a pairing URL from", 120, 116);
    fDrawCentre("the master app (Nostr", 120, 134);
    fDrawCentre("Connect > Generate new).", 120, 152); fEnd();
    dispPush();
    drainButtonsAfterTransition();
    while(true){
      pumpInputs(); btn1.poll(); btn2.poll(); btn4.poll();
      esp_task_wdt_reset();
      if(btn1.isPressed()||btn2.isPressed()||btn4.isPressed()) return true;
      if(pendingDisplayMsg||pendingReturnToMenu) return false;
      delay(10);
    }
  }
  qrDisp.show(uri.c_str(), "Nostr App", nullptr);
  while(true){
    pumpInputs();
    btn1.poll(); btn2.poll(); btn4.poll();
    if(btn1.isPressed()||btn2.isPressed()||btn4.isPressed()) return true;
    if(pendingDisplayMsg||pendingReturnToMenu) return false;
    delay(10);
  }
}

void showCompactSignedQR(const char* signed_json){
  JsonDocument doc;
  if(deserializeJson(doc,signed_json)){dispError("JSON parse");return;}
  const char* id_hex=doc["id"]|"";
  const char* sig_hex=doc["sig"]|"";
  if(strlen(id_hex)!=64||strlen(sig_hex)!=128){
    qrDisp.show(signed_json,"Signed Event","scan with phone"); return;
  }
  static char compact[200];
  snprintf(compact,sizeof(compact),"%s%s",id_hex,sig_hex);
  qrDisp.show(compact,"Signed Event","scan to publish");
}

// ── nostrconnect parser ────────────────────────────────────────────────────
static String urlDecode(const String& s){
  String r=""; int i=0;
  while(i<(int)s.length()){
    if(s[i]=='%'&&i+2<(int)s.length()){char h[3]={s[i+1],s[i+2],0};r+=(char)strtol(h,nullptr,16);i+=3;}
    else if(s[i]=='+'){r+=' ';i++;}
    else{r+=s[i];i++;}
  }
  return r;
}
// Smart-scan: a scanned npub (Nostr public key). We don't have on-device
// contacts storage for V1, so this just displays the key so the user can
// verify/read it (e.g. confirm a counterparty's npub). Pure display, no state
// change. BACK/ENTER dismisses.
void scanShowNpub(const char* npub){
  spr.fillSprite(C_BG);
  uiHeader("NOSTR KEY", C_EB_BRASS);
  fSet(F_BODY); spr.setTextColor(C_TEXT2);
  spr.drawString("Public key (npub):", 10, 40); fEnd();
  // Wrap the npub across lines in mono so it reads cleanly.
  String s = String(npub); s.trim();
  fSet(F_MONO); spr.setTextColor(C_FG);
  int y = 64; const int CPL = 24;
  for(int i=0; i<(int)s.length() && y < 180; i += CPL){
    spr.drawString(s.substring(i, i+CPL).c_str(), 10, y);
    y += 16;
  }
  fEnd();
  fSet(F_BODY); spr.setTextColor(C_MUTED);
  fDrawCentre("BACK to return", 120, 210); fEnd();
  DISP_LOCK(); spr.pushSprite(0,0); DISP_UNLOCK();
  drainButtonsAfterTransition();
  while(true){
    esp_task_wdt_reset(); delay(5);
    if(btn4.isPressed() || btn2.isPressed()) return;
  }
}

bool parseNostrConnect(const char* uri){
  String u=String(uri);
  if(!u.startsWith("nostrconnect://")) return false;
  int qmark=u.indexOf('?'); if(qmark<0) return false;
  String pubkey=u.substring(15,qmark); pubkey.trim();
  if(pubkey.length()!=64) return false;
  pubkey.toCharArray(ncSession.clientPubkey,65);
  String query=u.substring(qmark+1);
  ncSession.relay1[0]=ncSession.relay2[0]=ncSession.relay3[0]=ncSession.secret[0]=0;
  int relayCount=0;
  while(query.length()>0){
    int amp=query.indexOf('&');
    String param=(amp>=0)?query.substring(0,amp):query;
    if(amp>=0) query=query.substring(amp+1); else query="";
    int eq=param.indexOf('='); if(eq<0) continue;
    String key=param.substring(0,eq);
    String val=urlDecode(param.substring(eq+1));
    if(key=="secret") val.toCharArray(ncSession.secret,sizeof(ncSession.secret));
    else if(key=="relay"){
      if(relayCount==0) val.toCharArray(ncSession.relay1,sizeof(ncSession.relay1));
      else if(relayCount==1) val.toCharArray(ncSession.relay2,sizeof(ncSession.relay2));
      else if(relayCount==2) val.toCharArray(ncSession.relay3,sizeof(ncSession.relay3));
      relayCount++;
    }
  }
  ncSession.active=true;
  return true;
}
// All callers pass char[128] buffers. Sources are ≤127-char relay strings
// today (ncSession.relayN filled via bounded toCharArray, or compile-time
// pool constants), but that safety lived in the callers, not here — a future
// caller with a longer source would overflow silently (SEC_1 finding 9
// class: unbounded strncpy/strcpy). Clamp explicitly.
#define WSS_URL_BUF 128
static void parseWssUrl(const char* url,char* host,char* path){
  const char* p=url;
  if(strncmp(p,"wss://",6)==0) p+=6;
  else if(strncmp(p,"ws://",5)==0) p+=5;
  const char* slash=strchr(p,'/');
  if(slash){
    size_t hl=(size_t)(slash-p);
    if(hl>=WSS_URL_BUF) hl=WSS_URL_BUF-1;
    memcpy(host,p,hl); host[hl]=0;
    strncpy(path,slash,WSS_URL_BUF-1); path[WSS_URL_BUF-1]=0;
  }else{
    strncpy(host,p,WSS_URL_BUF-1); host[WSS_URL_BUF-1]=0;
    strcpy(path,"/");
  }
}

// ── WebSocket ──────────────────────────────────────────────────────────────
void subscribeOnConnect(WebSocketsClient& ws,const char* subId){
  if(wallet.exists){
    char h[65]; toHex(wallet.pub,32,h);
    // Use since=now-60 to catch recent requests but ignore old cached ones
    time_t nowT; time(&nowT);
    long since=(nowT>1700000000L)?(long)nowT-60:0;
    char req[256];
    snprintf(req,sizeof(req),"[\"REQ\",\"%s\",{\"kinds\":[24133],\"#p\":[\"%.64s\"],\"since\":%ld}]",subId,h,since);
    ws.sendTXT(req);
    LOG_WS("[WS] Subscribed since=%ld\n",since);
  }
}
void sendConnectRequest(){
  if(!wallet.exists||!wallet.unlocked||!wsInitialised||!ncSession.active) return;
  char ourHex[65]; toHex(wallet.pub,32,ourHex);
  String plain=String("{\"id\":\"1\",\"method\":\"connect\",\"params\":[\"")
    +ourHex+"\",\""+ncSession.secret+"\"]}";
  uint8_t their[32]; if(!fromHex(ncSession.clientPubkey,their,32)) return;
  uint8_t nonce[32]; if(!favillaRandom(nonce,32)) return;
  // ECDH runs on the isolated signer; scalar never enters this processor.
  String enc=nip_encrypt(nullptr,their,plain.c_str(),nonce);
  if(!enc.length()){ LOG_NIP46("[NIP46]\n Encrypt failed in sendConnectRequest"); return; }
  LOG_NIP46("[NIP46] Sending connect request to %s\n", ncSession.clientPubkey);
  time_t now; time(&now); long ts=(long)now;
  String tags_json=String("[[\"p\",\"")+ncSession.clientPubkey+"\"]]";
  String canonical=String("[0,\"")+ourHex+"\","+ts+",24133,"+tags_json+",\""+enc+"\"]";
  uint8_t id_bytes[32];
  mbedtls_sha256_context sctx; mbedtls_sha256_init(&sctx);
  mbedtls_sha256_starts(&sctx,0);
  mbedtls_sha256_update(&sctx,(const uint8_t*)canonical.c_str(),canonical.length());
  mbedtls_sha256_finish(&sctx,id_bytes); mbedtls_sha256_free(&sctx);
  uint8_t sig[64]; if(!favilla::se_schnorr_sign(id_bytes,sig)) { return; }
  char id_hex[65],sig_hex[129];
  toHex(id_bytes,32,id_hex); toHex(sig,64,sig_hex);
  String pub=String("{\"id\":\"")+id_hex+"\",\"pubkey\":\""+ourHex+"\",\"created_at\":"+ts
    +",\"kind\":24133,\"tags\":"+tags_json+",\"content\":\""+enc+"\",\"sig\":\""+sig_hex+"\"}";
  webSocket.sendTXT(("[\"EVENT\","+pub+"]").c_str());
  if(ws2Initialised) webSocket2.sendTXT(("[\"EVENT\","+pub+"]").c_str());
}

void wsEvent(WStype_t type,uint8_t* payload,size_t length){
  switch(type){
    case WStype_CONNECTED:
      wsInitialised=true; subscribeOnConnect(webSocket,"signer");
      _relayReconnectFails=0; _relayConnectedAt=millis();  // healthy — reset failover counter
      LOG_WS("[WS] Connected to relay 1. ncSession.active=%d\n", ncSession.active);
      if(ncSession.active){
        LOG_WS("[WS] Sending connect request...\n");
        sendConnectRequest();
      } else {
        publishBootstrapEvents();  // only publish bootstrap on normal connection, not bunker
      }
      for(int i=0;i<OUTBOX_SIZE;i++)
        if(outbox[i].active&&!outbox[i].ws1ok&&relay1Enabled)
          webSocket.sendTXT(outbox[i].msg);
      break;
    case WStype_TEXT:{
      String msg=String((char*)payload);
      LOG_WS("[WS] RX: %s\n", msg.substring(0,120).c_str());
      if(msg.startsWith("[\"EVENT\"")){
        if(msg.indexOf("\"kind\":24133")>=0||msg.indexOf("\"kind\": 24133")>=0){
          if(!bunkerActive) break; // ignore NIP-46 requests when bunker is off
          wifiHoldAwake();         // a request is in: answer it at full speed
          // A stored request can arrive BEFORE the relay's EOSE, and a 130 KB
          // contact-list sign takes several seconds to receive and answer —
          // long enough for the 8 s "no EOSE" liveness check to declare the
          // relay dead mid-request (seen 7 Oct 2026: false failover to primal,
          // reply published twice). Traffic is proof of life: restart the clock.
          if(!signerEoseReceived && _relayConnectedAt) _relayConnectedAt = millis();
          pendingSocket=0;
          int idIdx=msg.indexOf("\"id\":\"");
          if(idIdx>=0){
            String evid=msg.substring(idIdx+6,idIdx+70);
            evid=evid.substring(0,evid.indexOf('"'));
            if(isDup(evid)) break;   // 23 Nov 2026 (#62 item 4): marked seen only after the signature check (processNip46Request)
          }
          // Process inline. Buttons stay responsive via core-1 polling
          // task; throughput stays good (vs queue's FIFO serialization).
          processNip46Request((char*)payload);
        }
      } else if(msg.startsWith("[\"EOSE\"")){
        // First EOSE = relay processed our REQ — we're really ready
        // for bunker traffic. wsInitialised was just TCP-up.
        signerEoseReceived=true;
        if(currentState==ST_WAITING_CORACLE) dispWaiting();
      } else if(msg.startsWith("[\"OK\"")){
        JsonDocument okDoc; deserializeJson(okDoc,msg);
        if(okDoc.is<JsonArray>()&&okDoc.size()>=3){
          String eid=okDoc[1]|""; bool accepted=okDoc[2]|false;
          String reason=okDoc.size()>=4?(okDoc[3]|""):"";
          // Three outcomes:
          //  1. accepted → drop from outbox (success)
          //  2. rejected with "rate-limited" → drop too (we shouldn't
          //     retry into a rate-limit cliff; better to fail loud)
          //  3. rejected with anything else (invalid, blocked, pow,
          //     duplicate, etc.) → also drop. The relay said no for a
          //     reason that won't change on retry. Retrying is just
          //     log spam and heap pressure.
          // The old code only dropped on accepted+rate-limited, which
          // meant permanent rejections ("invalid: bad event id" from
          // a leaked PWA pre-event-id) retried forever.
          outboxConfirm(eid,false);
          if(!accepted) LOG_WS("[OUTBOX] dropped %s: %s\n",
            eid.substring(0,12).c_str(), reason.c_str());
        }
      }
      break;
    }
    case WStype_DISCONNECTED:
      wsInitialised=false;
      // Single-active-relay failover. The lib will auto-retry the SAME relay on
      // its 5s interval; we only switch to a DIFFERENT relay after a few
      // consecutive failures, so a transient blip doesn't bounce us around.
      if(bunkerActive){
        _relayReconnectFails++;
        LOG_WS("[FAILOVER] relay[%d] disconnected (fail %d/%d)\n",
               activeRelayIdx, _relayReconnectFails, RELAY_FAILOVER_AFTER);
        if(_relayReconnectFails >= RELAY_FAILOVER_AFTER){
          relayFailover();
        }
      }
      break;
    case WStype_ERROR:
      // The patched WebSockets lib drains a frame above WEBSOCKETS_MAX_DATA_SIZE
      // and reports it here instead of dropping the socket (7 Oct 2026).
      LOG_WS("[WS] error: %s\n", payload ? (const char*)payload : "?");
      bunkerSetBanner("Request too large");
      break;
    default: break;
  }
}
// Share-flow publish confirmation: cipherShareRun registers the event id it's
// waiting on here; the OK handler below flips g_shareOkGot when the relay
// acknowledges that exact id. Lets the share wait for real delivery instead of
// a blind drain. Empty id = nothing waiting.
char g_shareWaitId[65] = {0};
volatile bool g_shareOkGot = false;
volatile bool g_shareOkAccepted = false;
// True while CIPHER's ephemeral share link owns ws2. The link exists ONLY to
// publish two events and hear their OKs — it must never become a NIP-46
// delivery channel: the game's blocking loop is pumping the socket, and
// processing a signing request from inside it is reentrancy into a context
// that can't host approval UX (and could auto-sign from mid-game). While set:
// no REQ on connect, and any 24133 that arrives anyway is dropped (clients
// retry; the link lives for seconds).
volatile bool g_cipherShareLink = false;

void wsEvent2(WStype_t type,uint8_t* payload,size_t length){
  switch(type){
    case WStype_CONNECTED:
      ws2Initialised=true;
      if(!g_cipherShareLink) subscribeOnConnect(webSocket2,"signer2");
      for(int i=0;i<OUTBOX_SIZE;i++)
        if(outbox[i].active&&!outbox[i].ws2ok&&relay2Enabled)
          webSocket2.sendTXT(outbox[i].msg);
      break;
    case WStype_TEXT:{
      String msg=String((char*)payload);
      LOG_WS("[WS] RX: %s\n", msg.substring(0,120).c_str());
      if(msg.startsWith("[\"EVENT\"")){
        pendingSocket=1; if(msg.indexOf("\"kind\":24133")>=0||msg.indexOf("\"kind\": 24133")>=0){
          wifiHoldAwake();   // request in on socket 2: answer it at full speed
          if(!bunkerActive || g_cipherShareLink) break;
          int idIdx=msg.indexOf("\"id\":\"");
          if(idIdx>=0){
            String evid=msg.substring(idIdx+6,idIdx+70);
            evid=evid.substring(0,evid.indexOf('"'));
            if(isDup(evid)) break;   // 23 Nov 2026 (#62 item 4): marked seen only after the signature check (processNip46Request)
          }
          // Process inline. See comment in wsEvent (relay 1 handler).
          processNip46Request((char*)payload);
        }
      } else if(msg.startsWith("[\"EOSE\"")){
        // Either relay's EOSE marks us "really ready". See note in wsEvent.
        signerEoseReceived=true;
      } else if(msg.startsWith("[\"OK\"")){
        JsonDocument okDoc; deserializeJson(okDoc,msg);
        if(okDoc.is<JsonArray>()&&okDoc.size()>=3){
          String eid=okDoc[1]|""; bool accepted=okDoc[2]|false;
          String reason=okDoc.size()>=4?(okDoc[3]|""):"";
          // Drop on any OK response — see wsEvent (relay 1) comment.
          outboxConfirm(eid,true);
          if(g_shareWaitId[0] && eid == g_shareWaitId){
            g_shareOkGot = true; g_shareOkAccepted = accepted;
            LOG_WS("[SHARE] relay OK %s accepted=%d\n", eid.substring(0,12).c_str(), accepted);
          }
          if(!accepted) LOG_WS("[OUTBOX] dropped %s: %s\n",
            eid.substring(0,12).c_str(), reason.c_str());
        }
      }
      break;
    }
    case WStype_DISCONNECTED: ws2Initialised=false; break;
    case WStype_ERROR:
      // Includes the patched library's "frame too large" drain (the socket
      // survives; the request inside it is unanswerable because its id is
      // inside the ciphertext we never received).
      LOG_WS("[WS2] error: %s\n", payload ? (const char*)payload : "?");
      break;
    default: break;
  }
}

// Resolve the relay URL for a given pool index. Prefer the session's relay
// list (from the bunker URI the client paired with) when a session is active,
// since those are guaranteed to be relays the client publishes to. Fall back
// to the built-in pool otherwise.
static const char* bunkerRelayForIdx(int idx){
  if(ncSession.active){
    const char* r[3] = { ncSession.relay1, ncSession.relay2, ncSession.relay3 };
    if(idx>=0 && idx<3 && strlen(r[idx])>0) return r[idx];
  }
  return relayEnabledAt(idx);   // enabled entries of the one relay list
  return nullptr;
}
static int bunkerRelayPoolSize(){
  if(ncSession.active){
    int n=0;
    if(strlen(ncSession.relay1)>0) n++;
    if(strlen(ncSession.relay2)>0) n++;
    if(strlen(ncSession.relay3)>0) n++;
    if(n>0) return n;
  }
  return relayEnabledCount();
}

// Connect the single active relay (webSocket only). We hold ONE TLS session at
// a time — webSocket2 is intentionally NOT brought up in bunker mode anymore.
void connectActiveRelay(){
  if(!wifiConnected) return;
  const char* url = bunkerRelayForIdx(activeRelayIdx);
  if(!url){ activeRelayIdx=0; url=bunkerRelayForIdx(0); if(!url) return; }
  char host[128]={0},path[128]={0};
  if(strncmp(url,"ws",2)==0) parseWssUrl(url,host,path);
  else { strncpy(host,url,sizeof(host)-1); strcpy(path,"/"); }
  LOG_WS("[FAILOVER] connecting active relay[%d] = %s\n", activeRelayIdx, host);
  webSocket.onEvent(wsEvent);
  tlsReserveDrop("relay connect");   // 2 Nov 2026: no-op unless the block is held
  webSocket.beginSSL(host,443,path);
  // The lib auto-reconnects to the SAME host on this interval. Failover to a
  // DIFFERENT relay is driven by relayFailover() after RELAY_FAILOVER_AFTER
  // consecutive failures.
  webSocket.setReconnectInterval(5000);
  // Pong timeout raised 3s -> 10s, misses 2 -> 3.
  // processNip46Request runs INLINE from the WStype_TEXT callback, and one
  // webSocket.loop() call dispatches every frame already buffered. A burst of
  // requests therefore runs several 200-500ms decrypts back to back without
  // returning to the library, so an arriving pong sits unread. At a 3s timeout
  // and 2 misses, ~4s of decrypt backlog was enough to drop the relay link.
  // An incoming CALL is exactly that shape: offer plus ICE candidates landing
  // together, each costing a full NIP-44 decrypt. 10s x 3 tolerates the burst.
  // Cost: a genuinely dead link takes ~30s to notice instead of ~6s, which
  // relayFailover() then handles as before.
  // 20 Oct 2026: 10s x 3 -> 15s x 3 (ping every 20s). A Nostrich bulk DM run
  // queues ~4 requests at the relay, each ~2.8 s on the G0, so a pong landed
  // behind them read ~11 s late. Combined with the lib carrying the miss count
  // across reconnects (fixed in WebSocketsClient_Generic-Impl.h), every
  // reconnect died at ~12.7 s. Dead-link detection is now ~45 s worst case.
  webSocket.enableHeartbeat(20000,15000,3);
}

// Advance to the next relay in the pool and reconnect. Called when the active
// relay has failed repeatedly. Fully tears down the current TLS session first
// (frees its internal-SRAM buffers) before opening the next — this is the
// whole point: never hold two sessions at once.
void relayFailover(){
  if(!bunkerActive) return;
  webSocket.disconnect();       // free the current TLS session's buffers
  wsInitialised=false;
  signerEoseReceived=false;     // new relay must re-confirm subscription with its own EOSE
  _relayConnectedAt=0;          // EOSE-liveness window restarts when the new relay connects
  int n = bunkerRelayPoolSize();
  activeRelayIdx = (activeRelayIdx + 1) % n;
  _relayReconnectFails = 0;
  LOG_WS("[FAILOVER] switching to relay[%d] (free heap=%u)\n",
         activeRelayIdx, ESP.getFreeHeap());
  connectActiveRelay();
}

void initWS(){
  if(!wifiConnected) return;
  if(!wsInitialised&&relay1Enabled){
    activeRelayIdx = 0;
    _relayReconnectFails = 0;
    connectActiveRelay();
  }
  wsStarted=true;
}

// Single-active-relay design: relay 2 is NEVER brought up alongside relay 1
// anymore (that dual-TLS setup caused the ~27KB-heap / SE 6D00 / reboot
// cascade). This is now a no-op kept only so existing callers compile.
void connectRelay2IfNeeded(){
  // intentionally empty — failover handles relay redundancy with ONE session.
}

// ── Camera ────────────────────────────────────────────────────────────────
bool cameraRunning=false, cameraHwReady=false;
// ── Camera DMA block reserve (21 Oct 2026) ──────────────────────────────────
// The cold esp_camera_init() needs one contiguous ~34 KB block of internal
// RAM for its DMA buffers. In WiFi mode nothing claims that block until the
// first scan, and by then WiFi's connect-time churn has usually cut the free
// space into pieces: bench 21 Oct, two boots of the same build, 77 KB free on
// both, largest block 36,852 on one and 32,756 on the other ("start blocked").
// So the block is taken at boot, before WiFi starts, while internal RAM is
// still one piece, and handed back to the allocator in cameraStart() just
// before the init that needs it. cameraRelease() re-takes it after deinit so
// a second cold init in the same session is protected too. WiFi never needed
// it: the TLS library is in PSRAM since 20 Oct and the bunker handshake was
// proven at 31.7 KB contiguous before that; ensureContigForTLS() lets the
// reserve go if it ever does.
static void*  g_camReserve = nullptr;
// 2 Nov 2026: the vault link keeps the camera's block. With mbedTLS in PSRAM a
// TLS link does not need it, and releasing it let the link's allocations break
// it up (camera "start blocked" at 26,612). The bunker still releases it: its
// NIP-46 decrypt budget needs that heap for the whole session.
static bool   g_tlsKeepCamReserve = false;
static const size_t CAM_RESERVE_BYTES = 36 * 1024;
static void camReserveTake(const char* why){
  if(g_camReserve) return;
  g_camReserve = heap_caps_malloc(CAM_RESERVE_BYTES, MALLOC_CAP_INTERNAL | MALLOC_CAP_DMA | MALLOC_CAP_8BIT);
  if(!g_camReserve){
    // 2 Nov 2026: after a release the block can come back 12 bytes short of
    // 36 KB (36,852) and was left unheld. Hold what is there if it still meets
    // the camera's 34,000 gate.
    size_t big = heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL | MALLOC_CAP_DMA | MALLOC_CAP_8BIT);
    if(big >= CAM_CONTIG_NEED) g_camReserve = heap_caps_malloc(big, MALLOC_CAP_INTERNAL | MALLOC_CAP_DMA | MALLOC_CAP_8BIT);
  }
  LOG_CAM("[CAM] reserve %s: %s (largest internal now %u)\n", why, g_camReserve ? "held" : "NOT available",
          (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT));
}
static void camReserveRelease(const char* why){
  if(!g_camReserve) return;
  free(g_camReserve); g_camReserve = nullptr;
  LOG_CAM("[CAM] reserve released (%s): largest internal now %u\n", why,
          (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT));
}
// Bench 2 Nov 2026 (vault relay): the comment above was wrong about TLS in
// the builds on the prebuilt core (favilla_key, _fido): the favilla_key_pm core
// (which _release and _rftest extend) is rebuilt with CONFIG_MBEDTLS_EXTERNAL_MEM_ALLOC. On the
// prebuilt core mbedTLS took its 16 KB record buffers from internal RAM and the
// handshake failed with -0x7F00 at ~59 KB internal free and 6 MB PSRAM free.
// tlsAllocInit() (setup) now moves its large allocations to PSRAM at run time.
void tlsReserveDrop(const char* why){ camReserveRelease(why); }
unsigned long lastCameraStopMs=0;   // when cameraStop last ran (re-entry dwell guard)
// V22: when the camera is left RESIDENT (warm) on return to the menu so repeat
// scans don't deinit/realloc (the AUTO/NETWORK fragmentation fix), this marks
// when it went idle. loop() stops the warm camera after CAM_WARM_IDLE_MS so it
// doesn't hold ~35KB internal RAM when the user has navigated away. 0 = not warm-idle.
static unsigned long camWarmIdleStart=0;
#define CAM_WARM_IDLE_MS 8000
static bool scanStoppedWifi=false; // V21.1: true while a device scan has WiFi stopped
static int  scanWifiRestoreMode=-1; // V21.1 FixA: effectiveMode captured at teardown, so the scan-exit restore rebuilds the SAME mode (STA vs AP)
// V21.1: number of live MJPEG streamTask instances using the camera framebuffer
// on a separate FreeRTOS task. cameraStop() must NOT esp_camera_deinit() while
// this is > 0, or the running stream task crashes on a freed driver. The QR
// task and dispPreview run on the main loop (same context as cameraStop) so
// they are never concurrent with it; only streamTask is.
static volatile int streamTaskRunning=0;
// V21.1: tracks whether the OV2640 has been powered up + reset-released via
// the TCA9554 expander. Set true once at boot in cameraPreInit while heap is
// healthy; cameraStart() then skips the expander I2C call (which would fail
// under the low free-heap present after WiFi/WebSocket come up).
static bool cameraPowered=false;
// ── Camera power via TCA9554 expander (V1.1) ────────────────────────────────
// The OV2640 RES/PWDN are on the I2C expander, not GPIOs. Must release the
// camera from reset/power-down BEFORE esp_camera_init(). Uses I2C_LOCK to
// stay clean against battery/haptic/ATECC traffic on the shared main bus.
static bool tca9554Write(uint8_t reg, uint8_t val){
  Wire.beginTransmission(TCA9554_ADDR);
  Wire.write(reg); Wire.write(val);
  return Wire.endTransmission()==0;
}
// V21.1 DIAG ([TCADIAG], strip before ship): read one TCA9554 register.
// Returns true on success; *val holds the register byte. Lets the scan-time
// diagnostic verify the expander's ACTUAL state (input port 0x00 reflects the
// real RES/PWDN pin levels) rather than trusting the boot-latched assumption.
static bool tca9554Read(uint8_t reg, uint8_t* val){
  Wire.beginTransmission(TCA9554_ADDR);
  Wire.write(reg);
  // V21.1 FIX: end the address-write phase with a STOP (true), not a
  // repeated-start (false). The repeated-start form left the ESP32 Wire
  // peripheral (core 3.3.8) in a state that NACK'd the NEXT write to this
  // device — which is exactly why a read-before-write (scan path) failed
  // while a bare write (boot path) succeeded. Proven by [TCADIAG]:
  // boot=LATCHED (no preceding read), scan=NOT-LATCHED (read precedes write).
  if(Wire.endTransmission(true)!=0) return false;
  // 3-arg requestFrom with explicit sendStop=true guarantees a STOP after the
  // read so the bus is fully idle before any following transaction.
  if(Wire.requestFrom((uint16_t)TCA9554_ADDR, (uint8_t)1, true)!=1) return false;
  *val = Wire.read();
  return true;
}
// Bring the OV2640 up in the datasheet-correct order for a GATED power rail:
//   1. Safe state: RES low (in reset), PWDN high (powered down), EN low (rail off).
//   2. Make P0/P1/P2 outputs.
//   3. Enable the rail (EN high). Wait for the 2.8V/1.2V rails to settle.
//   4. PWDN low (wake) — only meaningful now that the rail is up. Datasheet:
//      >1ms after power stable; XVCLK (20MHz) is already free-running here.
//   5. RES high (release reset). Datasheet HW-reset settling <1ms; give ~20ms
//      before any SCCB access.
// Returns false if the expander doesn't ack (camera then fails init defensively).
//
// Why EN-before-PWDN-before-RES: releasing PWDN or RES while the rail is still
// off floats the sensor's I/O against an unpowered core; releasing RES before
// the rail+PWDN are settled can latch the sensor into a bad state that only a
// clean re-reset clears. The rail is the outermost gate, so it comes up first
// and drops last (see cameraPowerDown).
static bool cameraPowerUp(){
  I2C_LOCK();
  // Safe start: RES low (held in reset), PWDN high (down), EN low (rail off).
  // Everything not a camera line stays high (its input-mode default).
  uint8_t out = (uint8_t)(0xFF & ~TCA_P0_CAM_RES & ~TCA_P2_CAM_EN); // RES=0, EN=0, PWDN=1
  bool w0 = tca9554Write(TCA9554_REG_OUTPUT, out);
  // P0,P1,P2 = outputs; rest stay inputs.
  bool wc = tca9554Write(TCA9554_REG_CONFIG, TCA_CFG_CAM_OUT);
  // V21.1 PROBE ([TCADIAG], strip before ship): read CONFIG back IMMEDIATELY,
  // same lock, no intervening bus traffic. cfgWant readback -> chip latches;
  // 0xFF -> chip not holding writes = hardware (reset strap / wiring).
  uint8_t cfgImm = 0xAA; bool rImm = tca9554Read(TCA9554_REG_CONFIG, &cfgImm);
  LOG_CAM("[TCADIAG] powerUp writes: out_ack=%d cfg_ack=%d | immediate cfg readback rd=%d cfg=0x%02X want=0x%02X %s\n",
    (int)w0,(int)wc,(int)rImm,cfgImm,TCA_CFG_CAM_OUT,
    (rImm && cfgImm==TCA_CFG_CAM_OUT) ? "LATCHED" : "NOT-LATCHED");
  bool ok = w0 && wc;

  // 3. Rail on. The OV2640 core (1.2V) + analog (2.8V) come up here; give them
  //    time to settle before releasing PWDN. 10ms is generous for the LDO/switch.
  out |= TCA_P2_CAM_EN;                              // EN high: rail on
  ok = ok && tca9554Write(TCA9554_REG_OUTPUT, out);
  delay(10);                                         // rail settle (was implicit before)

  // 4. Wake: PWDN low. Datasheet requires XVCLK present + >1ms after power stable.
  out &= ~TCA_P1_CAM_PWRDN;
  ok = ok && tca9554Write(TCA9554_REG_OUTPUT, out);
  delay(5);                                          // >1ms after power stable

  // 5. Release reset: RES high. HW-reset settling <1ms; wait ~20ms before SCCB.
  out |= TCA_P0_CAM_RES;
  ok = ok && tca9554Write(TCA9554_REG_OUTPUT, out);
  delay(50);                                         // ~20ms spec; 50ms covers a
                                                     // marginal switched-rail pull-up
                                                     // ramp seen on resume (SCCB
                                                     // reg:0xff timeout). Was 25.
  I2C_UNLOCK();
  if(ok) cameraPowered=true;   // V21.1: remember it's released/powered
  return ok;
}
// Put OV2640 back into power-down AND cut its rail to save current when the
// camera isn't in use. Reverse of the bring-up order: assert PWDN (and hold RES
// low) first so the sensor stops driving the DVP bus while still powered, THEN
// drop the rail. Dropping the rail is the big current win the dedicated CAM_EN
// switch was added for (~40mA idle -> ~0 when the rail is off).
static void camBusRefresh();   // fwd: defined below (main-bus recovery)
static void cameraPowerDown(){
  I2C_LOCK();
  // Step 1: RES low (into reset) + PWDN high (down), rail still ON. This quiesces
  // the DVP outputs before we remove power.
  uint8_t out = (uint8_t)((0xFF & ~TCA_P0_CAM_RES) | TCA_P1_CAM_PWRDN); // RES=0,PWDN=1,EN=1
  bool w1 = tca9554Write(TCA9554_REG_OUTPUT, out);
  delayMicroseconds(200);
  // Step 2: rail OFF (EN low). Keep RES low / PWDN high on the (now unpowered)
  // pins so nothing floats high into the dead core.
  out &= ~TCA_P2_CAM_EN;
  bool w2 = tca9554Write(TCA9554_REG_OUTPUT, out);
  // 18 Sep 2026: VERIFY the rail is actually off. CAM_EN was measured at 1.8V
  // (TCA driving P2 HIGH) during deep sleep with both FPCs unplugged — the
  // SCCB pull-ups on the switched VDD_2.8V rail then burn ~2 mA for the whole
  // sleep. These writes were unchecked, so a failed/ignored write was silent.
  // Read back OUTPUT + CONFIG; if EN is still high or P2 is not an output,
  // re-assert the config, retry the write (with a bus recovery between tries),
  // and log whatever we end with so the sleep path can never leave it dark.
  uint8_t rb_out = 0xFF, rb_cfg = 0xFF; bool r_ok = false;
  for (int attempt = 0; attempt < 3; attempt++) {
    bool ro = tca9554Read(TCA9554_REG_OUTPUT, &rb_out);
    bool rc = tca9554Read(TCA9554_REG_CONFIG, &rb_cfg);
    r_ok = ro && rc;
    bool enHigh   = (rb_out & TCA_P2_CAM_EN) != 0;
    bool p2Input  = (rb_cfg & TCA_P2_CAM_EN) != 0;   // config bit 1 = input
    if (r_ok && !enHigh && !p2Input) break;          // rail genuinely off
    LOG_CAM("[TCADIAG] powerDown attempt %d: w1=%d w2=%d rb_ok=%d out=0x%02X cfg=0x%02X -> %s%s, retrying\n",
            attempt, (int)w1, (int)w2, (int)r_ok, rb_out, rb_cfg,
            enHigh ? "EN-HIGH " : "", p2Input ? "P2-INPUT" : "");
    camBusRefresh();                                  // main-bus recovery (Wire 6/5)
    tca9554Write(TCA9554_REG_CONFIG, TCA_CFG_CAM_OUT);   // P0..P2 outputs again
    w2 = tca9554Write(TCA9554_REG_OUTPUT, out);
    delay(2);
  }
  LOG_CAM("[TCADIAG] powerDown final: out=0x%02X cfg=0x%02X %s\n", rb_out, rb_cfg,
          ((rb_out & TCA_P2_CAM_EN) == 0 && (rb_cfg & TCA_P2_CAM_EN) == 0) ? "RAIL OFF" : "RAIL STILL ON !!");
  I2C_UNLOCK();
  cameraPowered=false;
}
// Force the OV2640 into the off state from a COLD boot (e.g. WiFi-mode boot,
// where cameraPreInit/cameraPowerUp never ran). At the TCA9554 power-on default
// P0/P1/P2 are inputs (high-Z): PWDN floats (reads "awake") AND, on the new
// board, EN floats too — so the rail's enable is undefined. This drives all
// three: EN low (rail off), PWDN high (down), RES low (in reset), and sets them
// as outputs so those levels actually hold. Cheap (two register writes), no full
// camera/driver init, so it does not reintroduce the pre-WiFi cameraPreInit()
// boot regression.
static void cameraHoldOff(){
  I2C_LOCK();
  // EN low (rail off), PWDN high (down), RES low (reset). Non-camera bits high.
  uint8_t out = (uint8_t)((0xFF & ~TCA_P0_CAM_RES & ~TCA_P2_CAM_EN) | TCA_P1_CAM_PWRDN);
  bool w1 = tca9554Write(TCA9554_REG_OUTPUT, out);
  // Make P0,P1,P2 outputs (0=output); rest stay inputs. Without this the OUTPUT
  // write above does nothing because the pins default to inputs.
  bool w2 = tca9554Write(TCA9554_REG_CONFIG, TCA_CFG_CAM_OUT);
  I2C_UNLOCK();
  LOG_CAM("[CAM] holdOff (WiFi mode) — rail OFF + PWDN asserted, out_ack=%d cfg_ack=%d\n",(int)w1,(int)w2);
  cameraPowered=false;
}

// ═══ V22.7: RESIDENT CAMERA — init once, rail-gate the sensor ════════════════
// esp_camera_deinit() on this board is the proven liability: its GDMA teardown
// races (gdma_disconnect errors), it has hung ~8s, and even a "successful"
// deinit can leave a small internal-RAM block behind that BISECTS the big
// contiguous region (observed on the bench: largest stuck at 31732 after one
// init/deinit cycle while TOTAL free returned to ~91K) — after which every
// re-init fails the 34000 gate ("start blocked") even though plenty of RAM is
// free. The per-scan init/deinit churn is the disease; V22.7 removes it.
//
// New model (offline mode): esp_camera_init() runs ONCE at boot while the heap
// is clean, and the driver stays RESIDENT for the whole session.
//   "Camera off" = SUSPEND: quiesce the sensor (PWDN), park the ESP-side pins,
//                  cut the rail via the TCA9554 (SGM2553 CAM_EN switch).
//   "Camera on"  = RESUME:  unpark, rail up, SCCB re-init the sensor (a rail
//                  cycle wipes every register), warm up.
// No heap traffic in either direction, so the fragmentation trap is
// unreachable in normal use. esp_camera_deinit() survives in exactly TWO
// places, both once-per-session events routed through cameraRelease() with the
// sensor already quiesced and pins parked (best-case teardown conditions): the
// cam<->TLS RAM barrier, and the deep-sleep path.
//
// PIN PARKING — mandatory, not an optimisation: with the driver resident the
// S3 keeps driving XCLK (20MHz) into the OV2640's XVCLK pad. If the rail is
// off, that clock BACKFEEDS the sensor through its ESD diodes: it phantom-
// powers the dead rail at ~2.7V, draws mA-scale current from the GPIO, risks
// latch-up when the real rail returns, and defeats the point of the SGM2553.
// So before EN-low we detach the XCLK pad from whatever peripheral feeds it
// (LEDC on classic ESP32/S2, LCD_CAM on S3 — we save/restore the pad's raw
// GPIO-matrix routing register, so this code doesn't care which) and drive it
// LOW. The DVP lines (D0-7/VSYNC/HREF/PCLK) are ESP INPUTS and can't backfeed,
// but an unpowered sensor's outputs FLOAT — floating PCLK/VSYNC noise can
// clock garbage edges into the LCD_CAM peripheral — so they get pulled DOWN
// for the duration. SCCB (SIOD/SIOC, dedicated bus 10/11) needs nothing: the
// ESP side is open-drain (released = high-Z) and the module's 2.8V pull-ups
// hang off the SWITCHED rail, so the lines sit quietly at 0V during suspend.
// (V2-spin board check if sleep current ever reads high: if those SCCB pull-
// ups are in fact fed from an always-on 2.8V, they'd source ~0.5mA into the
// dead sensor — move them to the switched rail.)
static bool     camSuspended = false;      // driver resident, sensor rail OFF, pins parked
static bool     camPinsParked = false;
static uint32_t camXclkOutSelSaved = 0;    // XCLK pad's FUNC_OUT_SEL_CFG before parking

static const gpio_num_t CAM_DVP_INPUTS[] = {
  (gpio_num_t)CAM_PIN_D0,(gpio_num_t)CAM_PIN_D1,(gpio_num_t)CAM_PIN_D2,(gpio_num_t)CAM_PIN_D3,
  (gpio_num_t)CAM_PIN_D4,(gpio_num_t)CAM_PIN_D5,(gpio_num_t)CAM_PIN_D6,(gpio_num_t)CAM_PIN_D7,
  (gpio_num_t)CAM_PIN_VSYNC,(gpio_num_t)CAM_PIN_HREF,(gpio_num_t)CAM_PIN_PCLK,
};

static void camParkPins(){
  if(camPinsParked) return;
  // XCLK: save the exact matrix routing (signal index + inversion + OE-select
  // bits — one raw register), then take the pad over as plain GPIO, output LOW.
  // Restoring the raw register on unpark reconnects whichever peripheral was
  // generating the clock, immune to esp32-camera changing its XCLK source.
  camXclkOutSelSaved = REG_READ(GPIO_FUNC0_OUT_SEL_CFG_REG + 4*CAM_PIN_XCLK);
  esp_rom_gpio_connect_out_signal(CAM_PIN_XCLK, SIG_GPIO_OUT_IDX, false, false);
  gpio_set_direction((gpio_num_t)CAM_PIN_XCLK, GPIO_MODE_OUTPUT);
  gpio_set_level((gpio_num_t)CAM_PIN_XCLK, 0);
  // DVP inputs: pull DOWN so nothing floats against the LCD_CAM input stage
  // while the sensor is unpowered. Pulls are an IO-MUX pad feature — the input
  // matrix routing is untouched, so unparking is just dropping the pulls.
  for(size_t i=0;i<sizeof(CAM_DVP_INPUTS)/sizeof(CAM_DVP_INPUTS[0]);i++){
    gpio_pullup_dis(CAM_DVP_INPUTS[i]);
    gpio_pulldown_en(CAM_DVP_INPUTS[i]);
  }
  camPinsParked = true;
  LOG_CAM("[CAM] pins parked (XCLK matrix saved=0x%08X, DVP pulled down)\n",
          (unsigned)camXclkOutSelSaved);
}

static void camUnparkPins(){
  if(!camPinsParked) return;
  for(size_t i=0;i<sizeof(CAM_DVP_INPUTS)/sizeof(CAM_DVP_INPUTS[0]);i++){
    gpio_pulldown_dis(CAM_DVP_INPUTS[i]);
  }
  REG_WRITE(GPIO_FUNC0_OUT_SEL_CFG_REG + 4*CAM_PIN_XCLK, camXclkOutSelSaved);
  camPinsParked = false;
  LOG_CAM("[CAM] pins unparked (XCLK matrix restored)\n");
}

// Sensor-quiesce = step 1 of cameraPowerDown as a standalone: PWDN high + RES
// low with the RAIL STILL ON, so the OV2640 stops driving PCLK/DVP cleanly
// (OV app note §3.2.4 order: PWDN first, THEN stop the clock) before any
// parking or power removal.
static void camSensorQuiesce(){
  I2C_LOCK();
  uint8_t out = (uint8_t)((0xFF & ~TCA_P0_CAM_RES) | TCA_P1_CAM_PWRDN); // RES=0,PWDN=1,EN=1
  tca9554Write(TCA9554_REG_OUTPUT, out);
  I2C_UNLOCK();
}

// V21.1-proven bus-state refresh before an expander write burst (the scan-path
// write NACK'd when preceded by other traffic; a clean re-begin fixed it).
static void camBusRefresh(){
  I2C_LOCK();
  Wire.end();
  delay(10);
  Wire.begin(6,5);
  delay(10);
  I2C_UNLOCK();
  delayMicroseconds(50);   // let the bus go fully idle before the first write
}

// Sensor tuning — the full exposure/gain baseline + the PCLK /2 DVP-margin fix.
// Factored out of cameraStart so RESUME can re-apply it after every rail cycle
// (a rail cycle returns the sensor factory-fresh). Pure SCCB traffic: no heap.
#define CAM_PCLK_DIV2 1
// ── V22.9 SCAN ZOOM: sensor-side 2x centre crop ─────────────────────────────
// Measured 14 Sep 2026 on a Sparrow PSBT: 111 frames, 17 located, 4 decoded —
// the code is too SMALL in the frame (finder patterns not found; when found,
// modules sub-3px). VGA capture crashed on internal RAM, so instead the OV2640
// delivers the CENTRAL 640x480 of its SVGA (800x600 binned) mode, DSP-scaled to
// the same 320x240 buffer: 2x the pixels per module for the identical 76,800-
// byte framebuffer. quirc, the preview and every buffer are untouched; the
// preview simply shows the crop, so the user aims a smaller box.
// set_res_raw() for the OV2640 maps to set_window(mode, offX, offY, winW, winH,
// outW, outH): startX carries the MODE enum (1 = OV2640_MODE_SVGA).
// Runtime toggle so the A/B is one line (log the [QRDIAG-SUM] with and without).
// 14 Sep 2026 bench: with the crop "applied" the decode rate COLLAPSED (2 feeds
// then nothing for 2 min) and the scan loop slowed ~25% — the SVGA-window path
// is not delivering clean frames on this module. OFF by default; kept for a
// future bench session with the preview watched.
static bool g_camScanZoom = false;
static bool g_camScanZoomApplied = false;   // per camera session; reset in cameraStop
static void camApplyScanZoom(sensor_t* s){
  if(!s) return;
  if(!g_camScanZoom || !s->set_res_raw){ return; }
  // mode=SVGA(1), offset (80,60), window 640x480, output 320x240, scale on, bin on
  int rc = s->set_res_raw(s, 1 /*OV2640_MODE_SVGA*/, 0, 0, 0, 80, 60, 640, 480, 320, 240, true, true);
  LOG_CAM("[CAM] scan zoom 2x (SVGA centre 640x480 -> 320x240): %s\n", rc==0 ? "applied" : "FAILED, full field");
  if(rc!=0 && s->set_framesize) s->set_framesize(s, FRAMESIZE_QVGA);   // restore full field
}
// Exposure dither: while decodes are landing the exposure stays put; after 3
// consecutive frames with no decode it steps 40 -> 28 -> 56 -> 80 -> 40, one
// step per frame, and holds wherever a decode lands. Turns the fixed operating
// point into a self-correcting one without retuning the baseline.
// 14 Sep 2026 bench: stepping exposure EVERY frame once misses start meant only
// 1 frame in 4 ran at the known-good baseline (aec 40); with an already-low hit
// rate that cut the decode rate further. OFF by default. If re-enabled, hold
// each step for several frames rather than one.
static bool g_qrExposureDither = false;
static int g_qrMissStreak = 0, g_qrAecIdx = 0;
static const int g_qrAecTab[4] = { 40, 28, 56, 80 };

static void camApplySensorTuning(sensor_t* s){
  if(!(s && s->set_brightness && s->set_contrast && s->set_saturation)){
    LOG_CAM("[CAM] WARNING: sensor handle/vtable incomplete — skipping sensor config\n");
    return;
  }
  // Let the sensor finish coming up before writing registers. Immediately
  // after init/reset the OV2640's SCCB/clock may not be fully settled; a brief
  // delay before the first set_* avoids a write into a not-ready sensor.
  delay(50);
  s->set_brightness(s, 0);
  s->set_contrast(s, 2);
  s->set_saturation(s, -2);
  if(s->set_sharpness) s->set_sharpness(s, 3);          // V22: crisper module edges off a screen
  // These exposure/gain values are IDENTICAL to the working Arduino-IDE build
  // (nostr_signer_v21_2.ino: aec 40, ae_level -1, gain 0). Known-good baseline;
  // do not re-tune these to chase driver differences.
  if(s->set_exposure_ctrl) s->set_exposure_ctrl(s, 0);  // manual exposure (auto overrides aec_value)
  if(s->set_aec2)          s->set_aec2(s, 0);
  if(s->set_ae_level)      s->set_ae_level(s, -1);
  if(s->set_aec_value)     s->set_aec_value(s, 40);     // known-good Arduino baseline
  if(s->set_gain_ctrl)     s->set_gain_ctrl(s, 0);      // manual gain
  if(s->set_agc_gain)      s->set_agc_gain(s, 0);
  if(s->set_gainceiling)   s->set_gainceiling(s, (gainceiling_t)0);
  if(s->set_bpc)           s->set_bpc(s, 1);
  if(s->set_wpc)           s->set_wpc(s, 1);
  if(s->set_raw_gma)       s->set_raw_gma(s, 1);
  if(s->set_lenc)          s->set_lenc(s, 0);
  // New camera modules are mounted rotated 180° vs the old part: without
  // correction, an object entering from the top appeared from the bottom and
  // left appeared as right. hmirror+vflip together = 180° rotation, done
  // in-sensor (readout scan direction) — zero CPU/framebuffer cost, applies
  // to both the live preview and the frames quirc decodes.
  if(s->set_hmirror)       s->set_hmirror(s, 1);
  if(s->set_vflip)         s->set_vflip(s, 1);
  // ── PCLK /2 (DVP tearing mitigation) ────────────────────────────────────
  // Halve the OUTPUT pixel clock for DVP timing margin while XCLK stays at
  // full rate. OV2640 REG32 (0x32, SENSOR bank) bits [7:6] = PCLK divider:
  // 00=/1, 10=/2, 11=/4. Lower bits are HSYNC config → read-modify-write.
  #if CAM_PCLK_DIV2
  if(s->set_reg && s->get_reg){
    delay(5);
    s->set_reg(s, 0xFF, 0xFF, 0x01);          // ensure SENSOR bank
    delay(2);
    int r32 = s->get_reg(s, 0x32, 0xFF);
    if(r32 >= 0){
      int r32n = (r32 & 0x3F) | 0x80;          // clear [7:6], set 10 = /2
      s->set_reg(s, 0x32, 0xFF, r32n);
      delay(2);
      int rb = s->get_reg(s, 0x32, 0xFF);
      LOG_CAM("[CAM] PCLK /2: REG32 0x%02X -> 0x%02X (readback 0x%02X)\n",
              r32 & 0xFF, r32n & 0xFF, rb & 0xFF);
    } else {
      LOG_CAM("[CAM] PCLK /2: REG32 read failed (%d) — skipped\n", r32);
    }
  }
  #endif
}

// Discard frames until one comes back full-size, so the scan task starts
// against a live pipeline (V21_2 FB-SIZE:0 wall fix). Non-fatal on timeout —
// the scan task has its own retries. Each discarded fb MUST be returned or
// fb_count=1 starves immediately.
static bool camWarmup(){
  const size_t want = 320u*240u;       // QVGA grayscale full frame
  for(int i=0;i<20;i++){                // up to ~20 frames / ~600ms
    camera_fb_t* wf=esp_camera_fb_get();
    if(wf){
      bool full=(wf->len==want);
      esp_camera_fb_return(wf);
      if(full){ LOG_CAM("[CAM] warmup OK after %d frame(s)\n",i+1); return true; }
    }
    vTaskDelay(pdMS_TO_TICKS(30));      // let AEC/AGC + reg set settle
  }
  LOG_CAM("[CAM] warmup: no full frame in 20 tries (continuing)\n");
  return false;
}

// Full resume from suspend: pins back, rail up (expander re-latched from
// scratch — it has been observed to lose its config mid-session), sensor
// re-initialised over SCCB, pipeline warmed. NO driver/heap traffic — the DMA
// descriptors, line buffers and cam_task all sat out the suspend untouched.
static bool cameraResumeHW(){
  LOG_CAM("[CAM] resume: unpark + rail up + sensor re-init (internalLargest=%d — irrelevant, no alloc)\n",
    heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL));
  camBusRefresh();
  camUnparkPins();   // XCLK must be free-running BEFORE PWDN release (datasheet:
                     // XVCLK present + >1ms after power stable). The ~15ms of
                     // clock into the still-dead rail during powerUp's settle is
                     // a normal controlled bring-up, not the sustained backfeed
                     // that parking exists to prevent.
  if(!cameraPowerUp()){
    LOG_CAM("[CAM] resume: expander did not ack — retrying once\n");
    cameraPowered=false;
    delay(5);
    if(!cameraPowerUp()) return false;
  }
  sensor_t* s = esp_camera_sensor_get();
  if(!s || !s->reset){
    LOG_CAM("[CAM] resume: no sensor handle/vtable — driver state bad\n");
    return false;
  }
  // Rail cycle = factory-fresh sensor. reset() reloads the driver's default
  // register tables over SCCB; then re-select the capture format and re-apply
  // the tuning baseline. None of this allocates.
  // s->reset() is the FIRST SCCB traffic after the rail cycle; a marginal
  // sensor wake makes its opening bank-select (reg 0xff) time out. Probe the
  // sensor first with a cheap SCCB read and retry a few times with a short
  // settle, rather than hanging the seed path on one missed reset. Using a
  // register READ as the probe avoids depending on reset()'s return type
  // (which differs across esp32-camera versions). s->id.PID is known
  // (0x26 for the OV2640 on this board, per boot preinit); if the sensor
  // answers, reset() will land.
  {
    bool alive = false;
    for(int attempt=0; attempt<3 && !alive; attempt++){
      if(s->get_reg){
        int v = s->get_reg(s, 0x0A, 0xff);   // 0x0A = PIDH in sensor bank; any ACKing read proves SCCB
        if(v >= 0){ alive = true; break; }
      } else {
        alive = true;   // no probe available on this driver — fall through and try reset
        break;
      }
      LOG_CAM("[CAM] resume: sensor SCCB probe attempt %d silent — retrying\n", attempt+1);
      delay(30);
    }
    if(!alive){
      LOG_CAM("[CAM] resume: sensor did not answer SCCB after 3 tries — camera unavailable\n");
      return false;   // fail closed; the entropy overlay path already fails closed on this
    }
  }
  s->reset(s);
  if(s->set_pixformat) s->set_pixformat(s, PIXFORMAT_GRAYSCALE);
  if(s->set_framesize) s->set_framesize(s, FRAMESIZE_QVGA);
  camApplySensorTuning(s);
  camSuspended = false;
  camWarmup();
  return true;
}

// Counterpart: sensor quiet → in-flight frame drained → pins parked → rail
// off. The driver stays fully resident (cameraHwReady remains true).
static void cameraSuspendHW(){
  if(camSuspended) return;
  camSensorQuiesce();      // PWDN high, rail still on — sensor stops driving DVP
  delay(60);               // > one QVGA frame period: in-flight frame clocks
                           // out fully, DVP/GDMA go idle
  // V22.7b FREEZE FIX: do NOT drain with esp_camera_fb_get() here. The sensor
  // is quiesced, so once the queue is empty the "final" fb_get — the one meant
  // to return NULL — instead BLOCKS inside the driver for its full frame-wait
  // timeout (~4s) on the main loop: buttons dead, UI frozen. That was the
  // multi-second stall 8s after leaving a scan (warm-idle → stop → here).
  // esp_camera_return_all() hands every outstanding framebuffer back to the
  // driver without waiting — with fb_count=1 there is at most one, and any
  // stale queued frame is simply discarded by the next resume's warmup.
  esp_camera_return_all();
  camParkPins();           // XCLK stops (app-note order: PWDN first, then clock)
  cameraPowerDown();       // RES low + PWDN high held on the dead pins, EN low
  camSuspended = true;
  LOG_CAM("[CAM] suspended (driver resident, rail off) internalLargest=%d\n",
    heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL));
}

// FULL teardown — the only remaining esp_camera_deinit() call sites route
// through here: the cam<->TLS RAM barrier and the deep-sleep path. Both are
// once-per-session events, and both arrive with the sensor quiesced and pins
// parked, so the GDMA channel is torn down against a completely idle
// peripheral — the best conditions this driver ever gets. Post-release heap
// fragmentation is acceptable at these sites: the offline-boundary reboot rule
// means the next scan session boots fresh into cameraPreInit's clean heap.
void cameraRelease(){
  LOG_CAM("[CAM] release ENTER: running=%d hwReady=%d suspended=%d internalLargest=%d\n",
    (int)cameraRunning,(int)cameraHwReady,(int)camSuspended,
    heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL));
  cameraRunning=false;
  if(cameraHwReady && !camSuspended){
    camSensorQuiesce();
    delay(60);
    esp_camera_return_all();   // V22.7b: non-blocking — see cameraSuspendHW note
    camParkPins();
  }
  if(cameraHwReady){
    int before=heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL);
    esp_camera_deinit();
    cameraHwReady=false;
    int after=heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL);
    LOG_CAM("[CAM] release: deinited. internalLargest %d -> %d (%+d)\n",
      before, after, after-before);
    camReserveTake("after release");   // 21 Oct 2026: keep the DMA region whole for the next cold init
  }
  // Leave XCLK as GPIO-low and the DVP pulls as-is — a future esp_camera_init
  // reconfigures every pad itself. Do NOT restore the saved matrix routing:
  // it is stale once the driver is gone. Just forget the parked state.
  camPinsParked = false;
  cameraPowerDown();       // rail off (idempotent if already off)
  camSuspended = false;    // no resident driver left to resume
  lastCameraStopMs = millis();
}

// Shared "camera couldn't come up" screen (resume + cold-init failure paths).
static void camShowUnavailable(const char* line1, const char* line2){
  cameraRunning=false; nextState=ST_MENU;
  spr.fillSprite(C_BG);
  uiHeader("CAMERA UNAVAILABLE",C_EB_BRASS);
  fSet(F_BODY); spr.setTextColor(C_DIM);
  fDrawCentre(line1,120,104);
  fDrawCentre(line2,120,124); fEnd();
  dispPush();
  errorPause();
}
// ═══ end V22.7 resident-camera machinery ═════════════════════════════════════

static camera_config_t makeCamCfg(pixformat_t fmt,framesize_t size,int quality,int fb_count){
  camera_config_t cfg={};
  // 10w/10y: the Arduino core hands LEDC timers out first come, first served,
  // so the piezo owns timer 0. On the S3 the camera driver does not clock the
  // sensor from LEDC at all (LCD_CAM makes CAM_CLK), so this timer is unused;
  // it is kept off timer 0 anyway so the two can never meet.
  cfg.ledc_channel=LEDC_CHANNEL_0;cfg.ledc_timer=CAM_LEDC_TIMER;
  cfg.pin_d0=CAM_PIN_D0;cfg.pin_d1=CAM_PIN_D1;cfg.pin_d2=CAM_PIN_D2;cfg.pin_d3=CAM_PIN_D3;
  cfg.pin_d4=CAM_PIN_D4;cfg.pin_d5=CAM_PIN_D5;cfg.pin_d6=CAM_PIN_D6;cfg.pin_d7=CAM_PIN_D7;
  cfg.pin_xclk=CAM_PIN_XCLK;cfg.pin_pclk=CAM_PIN_PCLK;
  cfg.pin_vsync=CAM_PIN_VSYNC;cfg.pin_href=CAM_PIN_HREF;
  cfg.pin_sscb_sda=CAM_PIN_SIOD;cfg.pin_sscb_scl=CAM_PIN_SIOC;
  cfg.pin_pwdn=CAM_PIN_PWDN;cfg.pin_reset=CAM_PIN_RESET;
  // XCLK now from CAM_XCLK_HZ (tunable, see define near camera pins). The old
  // hardcoded 20MHz was the proven value for the previous sensor; the OV2640
  // on this board needs sweeping — start at 16MHz per the board-change note.
  cfg.xclk_freq_hz=CAM_XCLK_HZ;cfg.pixel_format=fmt;
  cfg.frame_size=size;cfg.jpeg_quality=quality;
  cfg.fb_count=fb_count;cfg.fb_location=CAMERA_FB_IN_PSRAM;
  cfg.grab_mode=CAMERA_GRAB_LATEST;
  return cfg;
}
// V1.1/WROOM-N16R8: pre-initialise the camera at BOOT, before WiFi/SSL/
// WebSocket fragment internal RAM. The camera DMA buffers need a large
// contiguous internal-RAM block; at boot that block is clean, so init
// succeeds easily. After this, cameraStart() sees cameraHwReady=true and
// skips re-init, so on-demand scanning works even though internal RAM is
// fragmented by then. (On the old N4R2/2MB board the camera was inited
// on-demand to save RAM; on 8MB PSRAM holding it permanently is fine and
// is what the Seeed Sense reference design does.)
// Returns true if the camera is ready. Boot context: logs only, no UI.
bool cameraPreInit(){
  if(cameraHwReady) return true;
  // V22.7: preinit is now the ONE-AND-ONLY esp_camera_init() of a normal
  // offline session. It runs before WiFi/SSL ever exist (this function is
  // gated to MODE_OFFLINE in setup), so:
  //   • the heap is clean — the driver's DMA descriptors/line buffers land in
  //     a >100K contiguous region, no gate needed;
  //   • the V21.1 objection ("boot-time camera init perturbed WiFi bring-up")
  //     does not apply — WiFi never comes up on this boot path at all.
  // After init + a tuning pass the camera is immediately SUSPENDED (pins
  // parked, rail off): boot cost is the init itself (~200ms), zero idle
  // current, and every subsequent cameraStart() is an allocation-free
  // cameraResumeHW() that CANNOT hit the fragmentation gate.
  if(!cameraPowerUp()){
    LOG_CAM("[CAM] preinit: TCA9554 expander did not ack — deferring to cold-init at scan time\n");
    return false;
  }
  LOG_CAM("[CAM] preinit - Free heap: %d, Largest internal: %d, Free PSRAM: %d\n",
    ESP.getFreeHeap(),
    heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL),
    ESP.getFreePsram());
  // fb_count=1, QVGA grayscale — the pinned known-good scan config (V22 FIX:
  // fb_count=2 drops a DMA line on this OV2640 regardless of heap headroom).
  camera_config_t cfg = makeCamCfg(PIXFORMAT_GRAYSCALE, FRAMESIZE_QVGA, 10, 1);
  if(esp_camera_init(&cfg)!=ESP_OK){
    LOG_CAM("[CAM] preinit: esp_camera_init FAILED — deferring to cold-init at scan time\n");
    cameraHwReady=false;
    cameraPowerDown();               // don't leave the sensor powered on a dead init
    return false;
  }
  sensor_t* s=esp_camera_sensor_get();
  LOG_CAM("[CAM] preinit sensor handle s=%p\n",(void*)s);
  if(s){
    LOG_CAM("[CAM] preinit sensor id: PID=0x%02X VER=0x%02X MIDH=0x%02X MIDL=0x%02X\n",
            (unsigned)s->id.PID, (unsigned)s->id.VER,
            (unsigned)s->id.MIDH, (unsigned)s->id.MIDL);
    Serial.flush();
  }
  camApplySensorTuning(s);           // re-applied on every resume anyway, but a
                                     // boot-time pass validates SCCB right now
  cameraHwReady=true;
  LOG_CAM("[CAM] preinit: driver RESIDENT (largest internal now %d) — suspending until first scan\n",
    heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL));
  // Straight into suspend: no warmup here (resume warms up per-scan after its
  // own rail cycle — frames warmed now would be thrown away), pins parked,
  // rail off. Zero camera current until the first scan.
  cameraSuspendHW();
  return true;
}

// 11da (bench 22 Nov: BTC Wallets > Import and NOSTR Device > Overlay seed
// could not use the camera; the BTC sign scan could). Since 10q/11b every
// scan that works takes the scan's own hold first (camHoldWake: no light
// sleep, the CPU and APB frequency locks, the clock safety net standing
// aside); the multisig and address-book scans, Sign with address, the entropy
// overlay, grid, quad and capture pages never did, so on the light-sleep
// build the clock could drop to 80 MHz and the chip nap mid-capture (scans
// 20-40x slower, frames timing out). The hold now belongs to cameraStart()
// itself, so every camera user has it; cameraStop() already releases it, and
// a start that fails releases it here.
static void cameraStartInner();
void cameraStart(){
  if(cameraRunning) return;
  camHoldWake();                       // idempotent: a caller that took it first keeps one hold
  cameraStartInner();
  if(!cameraRunning) camReleaseWake("start failed");
}
static void cameraStartInner(){

  // ── V22.7 RESIDENT FAST PATHS ──────────────────────────────────────────
  // Normal offline life lives entirely in these two branches: the driver was
  // inited once at boot (cameraPreInit) and never deinits, so starting the
  // camera is pin/rail/SCCB work only. NO allocation happens here, which is
  // why neither branch consults the 34000 contiguous gate — a fragmented heap
  // is irrelevant to a resume, and blocking on it was exactly the old bug
  // ("start blocked — only 31732 contiguous" with 90K genuinely free).
  if(cameraHwReady && camSuspended){
    // Suspended (rail off, pins parked) — the normal "camera off" state.
    if(!cameraResumeHW()){
      camShowUnavailable("Sensor did not wake —","try again");
      return;
    }
    esp_task_wdt_reset();
    cameraRunning=true;
    return;
  }
  if(cameraHwReady && !camSuspended){
    // Paused-resident (cameraPause: sensor deliberately left powered so a
    // confirm-screen round trip resumes instantly). Verify the expander
    // hasn't drifted; if it has, the sensor's power state is unknown —
    // recover with a full rail-cycle resume (suspend then cameraResumeHW),
    // NOT the old esp_camera_deinit()+reinit: the DRIVER is fine, only the
    // SENSOR is stale, and deinit is the fragmentation/GDMA-race hazard this
    // whole architecture exists to avoid.
    uint8_t cfgEntry=0xFF;
    I2C_LOCK(); bool rdEntry=tca9554Read(TCA9554_REG_CONFIG,&cfgEntry); I2C_UNLOCK();
    bool okCfg = rdEntry && ((cfgEntry & TCA_CAM_OUTPUTS)==0);
    if(!okCfg){
      LOG_CAM("[CAM] resume-from-pause: expander drifted (rd=%d cfg=0x%02X) — full rail-cycle resume\n",
        (int)rdEntry,cfgEntry);
      camSensorQuiesce();
      delay(20);
      camParkPins();
      cameraPowerDown();
      camSuspended=true;
      if(!cameraResumeHW()){
        camShowUnavailable("Sensor did not wake —","try again");
        return;
      }
    }
    esp_task_wdt_reset();
    cameraRunning=true;
    return;
  }
  // ── end fast paths ───────────────────────────────────────────────────────

  // ── LEGACY COLD-INIT PATH ────────────────────────────────────────────────
  // Reached only when no driver is resident: a WiFi-mode boot (preinit is
  // gated to MODE_OFFLINE), a preinit failure, or a scan after cameraRelease()
  // (post-TLS in the same session). Behaviour below is unchanged: dwell
  // guard, contiguous gate, expander dance, esp_camera_init.
  // RE-ENTRY DWELL GUARD: rapid stop→start cycling at the tight contiguous-RAM
  // margin (scan-in-place) was crashing — the GDMA/DVP teardown from the last
  // cameraStop hadn't fully settled and the heap hadn't coalesced before reinit,
  // so a DMA buffer landed badly and EV-VSYNC-OVF corrupted the stack (Double
  // exception in ROM memcpy). Enforce a minimum gap since the last stop so the
  // peripheral is idle and the contiguous block is clean before we init again.
  {
    const unsigned long CAM_REENTRY_MIN_MS = 150;
    unsigned long since = millis() - lastCameraStopMs;
    if(lastCameraStopMs != 0 && since < CAM_REENTRY_MIN_MS){
      unsigned long waitMs = CAM_REENTRY_MIN_MS - since;
      LOG_CAM("[CAM] re-entry dwell: waiting %lums for GDMA/heap to settle\n", waitMs);
      delay(waitMs);
    }
  }
  // Scanning is allowed in ALL modes. On good hardware the framebuffer and quirc
  // live in PSRAM; only the camera's small DMA line buffers need contiguous
  // internal RAM (~40KB). The ST_SCANNING dispatch tears down WiFi BEFORE calling
  // us IF contiguous internal RAM is too low, so by the time we run there should
  // be enough. As a final safety net, refuse the init (gracefully) only if the
  // contiguous internal block is genuinely below what esp_camera_init needs —
  // attempting a doomed init is what left GDMA half-torn-down and tripped the WDT.
  camReserveRelease("cold init");   // 21 Oct 2026: the block we kept for exactly this
#ifdef FAVILLA_BLE_KBD
  // 8t: Bluetooth breaks up the block the cold start needs; it comes back after
  // the scan. 11ai (11 Nov 2026): only when it has to. 11c halved the DMA
  // buffer to 16 KB on the rebuilt core, and the bench shows 20 KB contiguous
  // with Bluetooth up, so a scan can run with the phone still connected (the
  // pairing QR, a setup key or recovery codes scanned without dropping the
  // link). The stop stays as the fallback when the block is not there.
  if(g_btLife && blek::s_up){
    const size_t have = heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);
    if(have >= CAM_CONTIG_NEED + 2048) LOG_CAM("[CAM] Bluetooth stays up for this scan: %u contiguous internal, need %u\n", (unsigned)have, (unsigned)CAM_CONTIG_NEED);
    else blek::pauseForCamera();
  }
#endif
  {
    size_t contig = heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL|MALLOC_CAP_8BIT);
    const size_t CAM_MIN_CONTIG = CAM_CONTIG_NEED;   // 11c
    if(contig < CAM_MIN_CONTIG){
      LOG_CAM("[CAM] start blocked — only %u contiguous internal (need %u)\n",
              (unsigned)contig, (unsigned)CAM_MIN_CONTIG);
      cameraHwReady=false;
      cameraRunning=false;
      nextState=ST_MENU;
      spr.fillSprite(C_BG);
      uiHeader("CAMERA UNAVAILABLE",C_EB_BRASS);
      fSet(F_BODY); spr.setTextColor(C_DIM);
      fDrawCentre("Low memory —",120,104);
      fDrawCentre("try again",120,124); fEnd();
      dispPush();
      errorPause();
      return;
    }
  }
  esp_task_wdt_reset();
  // V21.1: only touch the expander if not already released from boot pre-init.
  // After WiFi/WebSocket are up, free heap is low and an I2C write to the
  // expander can fail simply because the I2C driver can't allocate a buffer.
  // Pre-init released the camera while heap was healthy (cameraPowered=true),
  // so normally we skip this.
  // V21.1 FIX: the boot "latch once, skip at scan time" assumption is FALSE on
  // this hardware — [TCADIAG] proved the TCA9554 reads back 0xFF (power-on
  // default: P0/P1 = INPUTS, so PWDN floats high = OV2640 held in power-down)
  // by scan time, even with cameraPowered==1. The expander loses its config
  // between boot and scan (most likely a brownout/glitch on a WiFi TX current
  // spike). So we RE-ASSERT every scan. Wire was begun once at boot and stays
  // up all session (battery gauge + haptic use it continuously), so this 2-byte
  // transaction needs NO heap allocation — the old "I2C write fails under low
  // heap" fear was a misdiagnosis of THIS same expander problem.
  {
    // Read the expander state ON ENTRY, before we touch it. If it's already
    // wrong here AND a driver was previously inited, that driver was brought up
    // against a held-in-power-down sensor and is poisoned — it must be torn
    // down and re-inited after we fix the expander below.
    uint8_t cfgEntry = 0xFF;
    I2C_LOCK(); bool rdEntry = tca9554Read(TCA9554_REG_CONFIG, &cfgEntry); I2C_UNLOCK();
    // "Configured" now means all three camera lines (RES/PWDN/EN) are outputs.
    bool wasConfigured = rdEntry && ((cfgEntry & TCA_CAM_OUTPUTS)==0);

    // V21.1 FIX: the ATECC sign path (getUnmaskedKey -> ateccReinit) runs
    // Wire.end()+Wire.begin()+ECCX08.begin() right before a scan, which leaves
    // the shared I2C bus (SDA6/SCL5) in a state where the NEXT write NACKs
    // (proven: scan write = NOT-LATCHED, boot write = LATCHED; the only
    // difference is an ATECC op precedes the scan). Reads tolerate it; the
    // expander WRITE does not. Give the expander the same clean bus the ATECC
    // gives itself: re-begin Wire immediately before powering the camera.
    {
      I2C_LOCK();
      Wire.end();
      delay(10);
      Wire.begin(6,5);
      delay(10);
      I2C_UNLOCK();
    }
    delayMicroseconds(50);  // V21.1: let the I2C bus go fully idle after the
                            // entry read before cameraPowerUp's first write.
    bool puOk = cameraPowerUp();
    // Verify the config actually took (write may ack but not retain). Read the
    // CONFIG reg: P0/P1 must read as outputs (their bits = 0).
    uint8_t cfgChk = 0xFF;
    I2C_LOCK(); bool rd = tca9554Read(TCA9554_REG_CONFIG, &cfgChk); I2C_UNLOCK();
    bool configured = rd && ((cfgChk & TCA_CAM_OUTPUTS)==0);
    if(!puOk || !configured){
      LOG_CAM("[CAM] expander re-assert weak (puOk=%d rd=%d cfg=0x%02X) — retrying once\n",
        (int)puOk,(int)rd,cfgChk);
      cameraPowered=false;            // clear stale hint
      delay(5);
      cameraPowerUp();                // one retry
    }
    // V22.7: the old "expander drifted on entry with driver up → deinit+reinit"
    // branch is gone. On this path cameraHwReady is false by construction (the
    // resident-driver cases returned in the fast paths above); drift with a
    // resident driver is now handled up there with a rail-cycle resume, never
    // a deinit. Keep the entry read for the [TCADIAG] picture only.
    (void)wasConfigured;
  }
  if(!cameraHwReady){
    HEAPCK(scanApiPending ? "cam-init PWA-scan" : "cam-init local-scan");
    heapIntegrity("pre-camera-init");   // DIAG: last check before the camera DMA alloc that crashes
    LOG_CAM("[CAM] Before init - Free heap: %d, Max alloc: %d, Free PSRAM: %d, Largest internal: %d, DMA free: %d\n",
      ESP.getFreeHeap(), ESP.getMaxAllocHeap(), ESP.getFreePsram(),
      heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL),
      heap_caps_get_free_size(MALLOC_CAP_DMA));
    Serial.flush();
    delay(200);
    // V21.1 FIX: fb_count=1 (was 2), matching v20 — which produced clean frames
    // in network mode. The handover marked fb_count a dead end ("buffers are in
    // PSRAM"), but that conflates two different allocations: the FRAMEBUFFERS are
    // in PSRAM (free to double), but the driver's DMA descriptors / line buffers
    // are in INTERNAL RAM and scale with the number of in-flight frames. With
    // WiFi+webserver already carving internal RAM down to a fragmented ~51KB,
    // fb_count=2's extra DMA infrastructure pushed the contiguous demand past
    // what fits -> the driver ran short of line-buffer space -> one DMA line
    // dropped -> FB-SIZE 69120 != 76800. v20 fit because fb_count=1 needed less.
    // Tradeoff: single buffer can be contended between driver/preview/QR (the
    // original reason it was raised to 2) -> watch for FB-OVF; if that returns
    // worse than the short-frame, the real fix is reclaiming internal RAM (Fix
    // A WiFi deinit-refresh), not buffer count.
    // V21.1: ADAPTIVE fb_count. fb_count=2 (double-buffer) gives a smoother
    // preview (sensor fills one buffer while we read the other), but its DMA
    // line buffers need more CONTIGUOUS INTERNAL RAM. In a fragmented heap
    // (~49KB, e.g. WiFi up) that overflows and drops a DMA line -> FB-SIZE
    // 69120!=76800 torn frames. In a clean heap (offline/fresh boot, ~118KB)
    // it fits fine. So choose by the contiguous block available right now:
    //   >= 70KB  -> 2 (smooth, safe — the normal offline-scan case)
    //   <  70KB  -> 1 (safety fallback, never tears)
    // This gives smooth double-buffering in the offline airgap scan flow while
    // making it impossible to reintroduce the torn-frame regression.
    // V22 FIX: the adaptive >=70KB threshold was wrong. It measures contig BEFORE
    // init, so a clean offline-scan heap (~90KB) picks fb_count=2 — but the OV2640
    // on this board drops a DMA line at fb_count=2 regardless of headroom (the
    // line-buffer alloc happens DURING init, after the check). Result: FB-SIZE
    // 69120!=76800 torn frames + quirc garbage grid estimates (cells=69). v21.1
    // already proved fb_count=1 never tears. Pin it to 1 for the scan path.
    size_t contigNow = heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL|MALLOC_CAP_8BIT);
    int fbCount = 1;
    // VGA was tried here to get more px/module for dense QRs — but on this OV2640
    // + DVP timing it made decoding WORSE (torn/dropped frames at the larger frame
    // size, lower effective frame rate on animated QRs). Reverted to QVGA baseline.
    framesize_t scanSize = FRAMESIZE_QVGA; const char* scanSizeName = "QVGA"; size_t ramGuard = CAM_CONTIG_NEED;   // 11c
    LOG_CAM("[CAM] fb_count=%d size=%s (contig internal=%u)\n",
      fbCount, scanSizeName, (unsigned)contigNow);
    camera_config_t cfg=makeCamCfg(PIXFORMAT_GRAYSCALE,scanSize,10,fbCount);
    // QVGA grayscale — matches v20 (which produced clean frames) and the boot
    // pre-init that reserved the DMA region. QQVGA gave torn frames on this
    // OV2640 + DVP timing. Framebuffer is in PSRAM; only small line/DMA buffers
    // sit in internal RAM. Guard catches a genuinely starved heap (normally we
    // never reach here — pre-init already reserved the region at boot).
    // ── V21.1 DIAG ([TCADIAG], strip before ship) ──────────────────────────
    // Read the expander's ACTUAL state immediately before esp_camera_init, so a
    // single torn-frame scan tells us WHICH hardware variable is biting:
    //   • heap  → see the [HEAPCK]/[CAM] Before-init numbers logged just above
    //   • expander drift → if RES/PWDN here are NOT in the released state, the
    //     boot latch did not hold and the camera is being inited while held in
    //     reset / powered down (v20 hardwired these, so it never had this risk).
    // Expected released state: input port P0(RES)=1 run, P1(PWDN)=0 awake,
    // P2(EN)=1 rail on; config P0/P1/P2 = 0 (outputs). Anything else = drift.
    {
      I2C_LOCK();
      uint8_t inp=0, outp=0, cfgp=0;
      bool ri = tca9554Read(0x00, &inp);   // input port = real pin levels
      bool ro = tca9554Read(TCA9554_REG_OUTPUT, &outp);
      bool rc = tca9554Read(TCA9554_REG_CONFIG, &cfgp);
      I2C_UNLOCK();
      if(ri && ro && rc){
        bool resRun   = (inp & TCA_P0_CAM_RES);      // 1 = running (good)
        bool pwdnDown = (inp & TCA_P1_CAM_PWRDN);     // 1 = powered down (bad)
        bool railOn   = (inp & TCA_P2_CAM_EN);        // 1 = rail on (good)
        bool p0Out    = !(cfgp & TCA_P0_CAM_RES);     // config 0 = output
        bool p1Out    = !(cfgp & TCA_P1_CAM_PWRDN);
        bool p2Out    = !(cfgp & TCA_P2_CAM_EN);
        LOG_CAM("[TCADIAG] in=0x%02X out=0x%02X cfg=0x%02X | RES=%s PWDN=%s RAIL=%s | P0out=%d P1out=%d P2out=%d | cameraPowered=%d | %s\n",
          inp, outp, cfgp,
          resRun?"RUN":"RESET", pwdnDown?"DOWN":"AWAKE", railOn?"ON":"OFF",
          p0Out, p1Out, p2Out, (int)cameraPowered,
          (resRun && !pwdnDown && railOn && p0Out && p1Out && p2Out) ? "OK-released" : "DRIFT!");
      } else {
        LOG_CAM("[TCADIAG] expander read FAILED (ri=%d ro=%d rc=%d) — bus contended / no ack\n",
          (int)ri,(int)ro,(int)rc);
      }
    }
    // ── end TCADIAG ─────────────────────────────────────────────────────────
    size_t largestInternal = heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL|MALLOC_CAP_8BIT);
    if(largestInternal < ramGuard){
      LOG_CAM("[CAM] Insufficient RAM: %d bytes contiguous internal (need %u for %s)\n",
        largestInternal, (unsigned)ramGuard, scanSizeName);
      // VGA was requested but the heap shrank between the check and here — retry
      // once at QVGA rather than failing the scan outright.
      if(scanSize==FRAMESIZE_VGA && largestInternal >= 40000){
        LOG_CAM("[CAM] falling back VGA->QVGA\n");
        scanSize=FRAMESIZE_QVGA; scanSizeName="QVGA"; ramGuard=40000;
        cfg=makeCamCfg(PIXFORMAT_GRAYSCALE,scanSize,10,fbCount);
      } else {
        cameraHwReady=false; cameraRunning=false; nextState=ST_MENU;
        spr.fillSprite(C_BG); uiHeader("CAMERA ERROR",C_EB_BRASS);
        fSet(F_BODY); spr.setTextColor(C_DIM);
        fDrawCentre("Insufficient RAM",120,112); fEnd();
        dispPush(); errorPause(); return;
      }
    }
    if(esp_camera_init(&cfg)!=ESP_OK){
      LOG_CAM("[CAM] FAILED\n");
      cameraHwReady=false;
      cameraRunning=false;
      nextState=ST_MENU;
      spr.fillSprite(C_BG);
      uiHeader("CAMERA ERROR",C_EB_BRASS);
      fSet(F_BODY); spr.setTextColor(C_DIM);
      fDrawCentre("Camera unavailable",120,112); fEnd();
      dispPush();
      errorPause();
      return;
    }
    sensor_t* s=esp_camera_sensor_get();
    HEAPCK("post cam-init");
    // DIAG + GUARD: SE051 build crashes here (null deref, EXCVADDR=0) configuring
    // the sensor, where the ATECC build does not. Log the sensor handle + a couple
    // of its function pointers so we can see whether `s` is null or its vtable is
    // unpopulated, and guard the calls so a null pointer logs instead of crashing.
    LOG_CAM("[CAM] sensor handle s=%p set_brightness=%p set_reg=%p\n",
            (void*)s,
            (void*)(s?(void*)s->set_brightness:nullptr),
            (void*)(s?(void*)s->set_reg:nullptr));
    // KEY DIAG: the detected sensor PID. If esp_camera_init mis-detected the
    // sensor (PID=0 or not 0x26/0x42 for OV2640), the driver hands back a vtable
    // whose set_* internally deref NULL state — exactly the crash we see. Logged
    // with an explicit flush so it survives even if the next call faults.
    if(s){
      LOG_CAM("[CAM] sensor id: PID=0x%02X VER=0x%02X MIDH=0x%02X MIDL=0x%02X\n",
              (unsigned)s->id.PID, (unsigned)s->id.VER,
              (unsigned)s->id.MIDH, (unsigned)s->id.MIDL);
      Serial.flush();
    }
    // V22.7: sensor tuning (exposure/gain baseline + PCLK /2 DVP-margin fix)
    // factored into camApplySensorTuning() so the resident-driver resume path
    // re-applies the identical configuration after every rail cycle. Same
    // register writes, same order, same delays as the inline block it replaced.
    camApplySensorTuning(s);
#if QR_REGDUMP
    // OV2640 register dump — to diff the working Arduino (IDF 4.4) build against
    // the PlatformIO (IDF 5.1) build and find which regs the new driver sets
    // differently (the suspected Blue Wallet image-quality regression). The
    // OV2640 is BANKED: reg 0xFF selects DSP bank (0x00) or SENSOR bank (0x01).
    // Dump both. Run on BOTH builds, diff the [REGDUMP] lines. Strip after.
    if(s && s->set_reg && s->get_reg){
      delay(50);  // let the settings above settle into the sensor
      for(int bank=0; bank<=1; bank++){
        s->set_reg(s, 0xFF, 0xFF, bank);   // select bank
        delay(2);
        Serial.printf("[REGDUMP] === bank %d ===\n", bank);
        for(int r=0x00; r<=0xFF; r+=8){
          int v0=s->get_reg(s,r+0,0xFF), v1=s->get_reg(s,r+1,0xFF);
          int v2=s->get_reg(s,r+2,0xFF), v3=s->get_reg(s,r+3,0xFF);
          int v4=s->get_reg(s,r+4,0xFF), v5=s->get_reg(s,r+5,0xFF);
          int v6=s->get_reg(s,r+6,0xFF), v7=s->get_reg(s,r+7,0xFF);
          Serial.printf("[REGDUMP] b%d %02X: %02X %02X %02X %02X %02X %02X %02X %02X\n",
            bank, r,
            v0&0xFF,v1&0xFF,v2&0xFF,v3&0xFF,v4&0xFF,v5&0xFF,v6&0xFF,v7&0xFF);
        }
      }
      s->set_reg(s, 0xFF, 0xFF, 0x01);   // leave sensor bank selected (driver default)
      Serial.printf("[REGDUMP] done\n");
    }
#endif
    cameraHwReady=true;
    // V21_2 FIX (FB-SIZE: 0 wall): after esp_camera_init + the manual exposure/
    // gain register writes above, the OV sensor needs several frame periods to
    // apply the new config and start clocking valid pixels into DMA. With no
    // warmup, qrScanTask's first fb_get hits this cold window and gets 0-length
    // frames for all its retries (cam_hal: FB-SIZE: 0 != 76800), exits, and
    // re-triggers forever. Discard frames here until one comes back full-size
    // (or we time out), so the scan task starts against a live pipeline. Each
    // discarded fb MUST be returned or fb_count=1 starves immediately.
    // 19 Oct 2026: a cold init that went straight into streaming gave a frozen
    // first scan on the bench (one frame, then esp_camera_fb_get timing out
    // ~5 s per frame), in BOTH doors, even with a clean heap; closing and
    // reopening always worked, and that second open is the resume path (rail
    // cycle + sensor re-init + warmup). So a cold init now ends exactly like a
    // boot pre-init: suspend at once, then take the proven resume path. Costs a
    // rail cycle (a few hundred ms) on the first scan of a session only.
    cameraSuspendHW();
    if(!cameraResumeHW()){
      LOG_CAM("[CAM] cold init: resume after suspend FAILED\n");
      camShowUnavailable("Sensor did not wake —","try again");
      return;
    }
    LOG_CAM("[CAM] init OK (cold path, then suspend+resume)\n");
  }
  cameraRunning=true;
}
void cameraStop(){
  g_camScanZoomApplied=false;   // V22.9: next session re-applies the scan crop (resume resets the sensor)
  camReleaseWake("stopped");   // 10q: scan over - only the hold a scan took
  qrDiagFlush();     // V22.x: dump the deferred scan diagnostics now (serial safe — scan ended)
  qrDumpFlush();     // V22.x: base64 the captured failing frame now (serial safe — scan ended)
  LOG_CAM("[CAM] stop ENTER: running=%d hwReady=%d suspended=%d internalLargest=%d\n",
    (int)cameraRunning,(int)cameraHwReady,(int)camSuspended,
    heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL));
  // ── V22.7: stop = SUSPEND, never deinit ──────────────────────────────────
  // The per-scan esp_camera_deinit() this function used to do was the whole
  // disease: GDMA teardown races, the ~8s hang variant, and the fragmentation
  // bomb (a deinit leaving one small block that bisects the contiguous region
  // → every later init fails the 34000 gate with 90K genuinely free). The
  // driver now stays RESIDENT for the session; this function just quiesces the
  // sensor, parks the pins, and cuts the rail (cameraSuspendHW). The DMA
  // descriptors/line buffers are deliberately KEPT — they were allocated into
  // the clean boot heap and holding them is what guarantees the next scan.
  // Internal-RAM reclaim for TLS/bunker goes through cameraRelease() instead
  // (the cam<->TLS barrier), the one place a real deinit still happens.
  //
  // We still do NOT use SCCB software-standby (COM2/0x09): on the OV2640 it
  // holds SIO_D low until a power cycle (OmniVision app note; esp32-camera
  // issue #101). The rail cut makes it moot anyway.
  if(cameraRunning){
    cameraRunning=false;
    quircScanFree();   // V21_2: release the persistent scan quirc (~150KB PSRAM)
  }
  if(streamTaskRunning>0){
    // Live MJPEG stream on its own task — don't yank the sensor/pins under it.
    // The stream's exit path stops polling; a later stop/release finishes up.
    LOG_CAM("[CAM] stop: %d stream task(s) live — deferring suspend\n", streamTaskRunning);
    lastCameraStopMs = millis();
    return;
  }
  if(cameraHwReady && !camSuspended){
    // Covers both the normal scan exit AND stop-after-cameraPause (running
    // already false but the sensor was left powered for the fast resume).
    cameraSuspendHW();
  } else if(!cameraHwReady){
    // No resident driver (cold-init path was used and released, or preinit
    // failed) — just make sure the sensor isn't left burning the rail.
    cameraPowerDown();
  }
  // (cameraHwReady && camSuspended → already exactly where we want to be.)
  lastCameraStopMs = millis();   // for the cold-path re-entry dwell guard
}

// V22.x: LIGHT stop for screens that don't use the camera but where a full
// cameraStop() is wrong. esp_camera_deinit() on this board hangs ~8s trying to
// tear down the GDMA channel while XCLK is still clocking (gdma_disconnect: no
// peripheral connected), and reclaims 0 — so the Nostr confirm path stalled 8s
// and the next scan hit "Insufficient RAM". Instead, keep the driver RESIDENT
// (cameraHwReady stays true, like the NETWORK-mode scan path already does) and
// just (a) stop the main loop from grabbing frames (cameraRunning=false) and
// (b) power the sensor down so the EV-VSYNC-OVF flood stops jamming the loop.
// cameraStart() resumes instantly (it early-returns on !cameraRunning re-init,
// and skips hardware init because cameraHwReady is still true). No deinit, no
// GDMA teardown, no 8s hang, no RAM reclaim needed (the block was never freed).
void cameraPause(){
  camReleaseWake("paused");   // 10q
  if(!cameraRunning) return;
  cameraRunning=false;
  quircScanFree();                 // release the PSRAM scan quirc
  // V22.7b: non-blocking buffer handback (see cameraSuspendHW note). The old
  // fb_get drain loop here was worse than useless with the sensor still LIVE:
  // it never saw NULL (fresh frames kept arriving) and spun until the 20-frame
  // cap — up to ~1.3s of pointless grabbing on a path that exists for speed.
  esp_camera_return_all();
  // IMPORTANT: do NOT cameraPowerDown() here — pause's entire purpose is the
  // instant resume. With the sensor left powered (and the expander config
  // intact), the next cameraStart() takes the paused-resident fast path: one
  // expander CONFIG read, then cameraRunning=true — no rail cycle, no SCCB
  // re-init, no warmup. If the sensor should actually go dark (leaving the
  // scan flow, warm-idle timeout), that's cameraStop() → suspend instead. The
  // EV-VSYNC-OVF lines that continue are harmless driver-ISR logging (no reader,
  // single fb in PSRAM); they do not jam the loop now that we've stopped grabbing
  // and stopped the live-preview redraw (g_airgapLivePreview=false on this path).
  LOG_CAM("[CAM] paused (resident, no deinit, sensor left powered) internalLargest=%d\n",
    heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL));
}

// ── cam <-> bunker RAM barrier ───────────────────────────────────────────────
// The camera DMA and the TLS handshake both need a large CONTIGUOUS internal-RAM
// block, and this chip does not have enough for both at once with WiFi up. They
// each work alone; the failure mode is starting one while the other still holds
// the block (observed: camera deinit racing bunker bring-up left contiguous
// stranded at 31732, so every relay TLS handshake then failed). This barrier is
// called before bunker activates: if the camera is resident it is fully stopped
// (esp_camera_deinit reclaims its DMA RAM), then we wait briefly and verify the
// contiguous block actually came back above the TLS need. Returns false if it
// could not be reclaimed, so the caller refuses cleanly instead of limping into
// a relay-handshake-fails loop.
#ifndef TLS_MIN_CONTIG
#define TLS_MIN_CONTIG 34000   // contiguous internal block for the TLS handshake.
                               // Lowered from 40000: with CONFIG_MBEDTLS_DYNAMIC_BUFFER
                               // active the handshake allocates incrementally (PSRAM-
                               // capable), so the persistent contiguous-internal need is
                               // lower than the old conservative 40K. The first connect
                               // succeeded; WS disconnect frees ~43KB but fragments it, so
                               // re-activations see ~38900 contiguous — above this floor.
                               // If a connect fails at this level, raise it; if it works,
                               // the 40K was simply too cautious.
#endif
bool ensureContigForTLS(){
  // PROVEN BY MEASUREMENT (see boot log analysis): the relay TLS handshake
  // connects fine at internalLargest=31732 — the framework's precompiled
  // ssl_client/mbedtls allocates its 16K content buffers with dynamic buffering,
  // so the real contiguous-internal need is BELOW 31732. The old secureRestart
  // was NOT a real allocation failure — it was this barrier's own 34000 gate
  // refusing preemptively and rebooting. Removing that gate lets the handshake
  // proceed, and it succeeds.
  //
  // We also DROPPED the boot-time TLS arena: it reserved ~44K of internal DRAM
  // permanently, which starved the camera below its 34000 scan gate ("Low memory
  // — try again" / "Insufficient RAM"). The arena was catching only ~280 bytes of
  // mbedtls bookkeeping (the big buffers never routed through it), so it cost the
  // camera ~44K to buy TLS almost nothing. Net: remove the arena, give that RAM
  // back to the camera, and make this barrier non-fatal.

  // Stop a resident camera before opening the relay: frees its DMA descriptors,
  // stops the DVP, and keeps the camera task from competing with the TLS task.
  // (The framebuffer is in PSRAM; this is about not running both at once.)
  // 2 Nov 2026: a vault link leaves a suspended camera resident (the bench ran
  // two backups at 11,252 largest internal with the driver resident; TLS is in
  // PSRAM), so the next scan stays warm. A running camera is still released.
  if(cameraRunning || (cameraHwReady && !g_tlsKeepCamReserve)){
    // V22.7: full release, not just suspend — TLS needs the driver's internal
    // DMA RAM back. This is one of the two sanctioned esp_camera_deinit()
    // sites; cameraRelease() quiesces + parks first so the GDMA teardown runs
    // against a completely idle peripheral (kills the gdma_disconnect race).
    LOG_CAM("[BARRIER] camera resident — RELEASING it before TLS/bunker\n");
    cameraRelease();
    esp_task_wdt_reset();
  }

  size_t contig = heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL|MALLOC_CAP_8BIT);
  // 21 Oct 2026: the camera's boot-time reserve is never needed by TLS (mbedTLS
  // is in PSRAM; the handshake was proven at 31.7 KB contiguous before that),
  // but if a future core change ever leaves TLS short, the camera yields.
  // 26 Oct 2026: release it UNCONDITIONALLY when the bunker comes up. On the
  // bench the contig<32000 test was true on every bunker start anyway (pre-TLS
  // internalLargest 22516), so this changes nothing today; it just stops the
  // behaviour depending on a fragmentation number. The camera and the bunker
  // are mutually exclusive already (a scan with the bunker up closes the WS
  // first and cold-inits from whatever is free; proven at 34804 on 26 Oct),
  // and after the first barrier the re-take never lands, so holding the block
  // through a bunker session buys the camera nothing. NOTE: releasing it did
  // NOT lift the NIP-46 heap floor — bunker-only free heap was 22.4 KB with
  // the reserve already released. See SAFETY_MARGIN in handleNip46Request.
  if(g_camReserve && !g_tlsKeepCamReserve){
    camReserveRelease(contig < 32000 ? "TLS short of contiguous internal"
                                     : "bunker up: heap back to NIP-46");
    contig = heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL|MALLOC_CAP_8BIT);
  }
  LOG_WS("[BARRIER] proceeding to TLS (contig internal=%u) — no gate, no reboot\n",
         (unsigned)contig);
  // Always proceed. If a future relay/handshake genuinely needs more contiguous
  // than is available, beginSSL() will fail its connect and the failover logic
  // rotates relays / retries — a recoverable soft failure, NOT a reboot. That is
  // strictly better UX than the old crash-looking ROM dump.
  return true;
}


// ── RF diagnostic ───────────────────────────────────────────────────────────
// Boot-time radio health check, serial only. Runs a passive scan (measures the
// RX path independent of connection logic) and reports TX power. Compare the
// SAME build on WROOM vs MINI in the SAME spot vs the SAME AP: a consistent
// RSSI gap > ~6-8 dB on a common network indicates an antenna/layout problem,
// not firmware. Rotate each board 90/180 deg — a large RSSI swing means the
// PCB antenna is detuned or shadowed (e.g. by the EMI shield or ground pour).
// Call after wifiLoadCredentials() and before any connect attempt.
void wifiRadioDiag(){
  g0DoorRadioGuard();   // 24 Sep 2026: commit NOSTR to the G0 before any radio
  WiFi.mode(WIFI_STA);
  WiFi.disconnect(true);
  delay(200);

  int8_t txq = 0;
  esp_wifi_get_max_tx_power(&txq);
  Serial.printf("[RFDIAG] === radio diagnostic ===\n");
  Serial.printf("[RFDIAG] max_tx_power: %d (%.2f dBm)\n", txq, txq * 0.25f);

  unsigned long t0 = millis();
  int n = WiFi.scanNetworks();   // blocking passive scan
  Serial.printf("[RFDIAG] scan: %d networks in %lu ms\n", n, millis()-t0);
  for(int i=0;i<n && i<20;i++){
    Serial.printf("[RFDIAG]  %2d  %4d dBm  ch%2d  %s\n",
      i, WiFi.RSSI(i), WiFi.channel(i),
      WiFi.SSID(i).length()? WiFi.SSID(i).c_str() : "(hidden)");
  }
  WiFi.scanDelete();
  Serial.printf("[RFDIAG] === end ===\n");
  Serial.flush();
}

// V21_2: DEPRECATED / UNUSED. Airgap scanning is now offline-only and the device
// never auto-transitions offline->online, so the airgap path no longer restores
// WiFi anywhere — every call site was removed. Going online is a manual menu
// action only. Function retained (uncalled) for reference; safe to delete in the
// pre-ship cleanup pass. Was: restart WiFi after an airgap scan (STA reconnect /
// AP bring-up; OFFLINE left WiFi off).
void airgapRestoreWifi(){
  if(effectiveMode==MODE_OFFLINE) return;  // never had WiFi up
  // V21.1 FIX A: the scan did WiFi.mode(WIFI_OFF) (full deinit), so esp_wifi_start
  // alone won't bring it back — re-init through the Arduino layer with WiFi.mode.
  if(effectiveMode==MODE_HOTSPOT){
    apBringUp();          // self-contained: AP + cam server + mDNS
  } else {
    g0DoorRadioGuard();   // 24 Sep 2026: commit NOSTR to the G0 before any radio
    WiFi.mode(WIFI_STA);
    delay(150);
    if(wifiConnectBest(6000)){
      strncpy(currentIP, WiFi.localIP().toString().c_str(), 19);
      mdnsEnd();
      char mdnsName[32]; makeMdnsHostname(mdnsName,sizeof(mdnsName));
      if(mdnsBegin(mdnsName)){ MDNS.addService("http","tcp",80);
        strncpy(currentMdnsName,mdnsName,sizeof(currentMdnsName)-1);
        currentMdnsName[sizeof(currentMdnsName)-1]=0;
        LOG_NET("[mDNS] airgap restore: http://%s.local\n", mdnsName); }
      wifiConnected=true;
    } else {
      LOG_NET("[CAM] airgap restore: reconnect failed, will retry via maintenance loop\n");
      wifiConnected=false; reconnecting=true;
    }
  }
}
// Histogram contrast-stretch. ON alongside the squaring close: the close fixed
// the grid geometry (cells now lock at 53 = correct v9) but ECC still fails —
// modules sampled slightly wrong. The stretch widens contrast so each module's
// centre sample lands decisively black/white, cutting bit errors. Close = geometry,
// stretch = contrast; stacked they cover both halves of the rounded-QR problem.
#define QR_HIST_STRETCH 0
// Morphological squaring of rounded "designer" QR modules (see qrScanOnce).
// ON: confirmed fix — the same Blue Wallet UR data regenerated with square corners
// scans fine, proving the rounded rendering is the cause. Now a proper close
// (min then max) that fills corner notches without merging dense neighbours.
#define QR_SQUARE_MODULES 0
// OV2640 register dump (both banks) — was for diffing drivers, no longer needed
// (old Arduino build failed Blue Wallet too, so there is no driver regression).
#define QR_REGDUMP 0
// V22.x DE-RISK: capture ONE failing (INVALID_ECC) grayscale frame during a scan
// and base64-dump it over serial AFTER the scan ends (serial-during-scan corrupts
// the camera, so capture is silent + deferred, exactly like QRDIAG). Purpose: feed
// the EXACT pixels quirc choked on to desktop ZXing-cpp's ZXingReader on a laptop
// (no laptop camera needed) to decide whether the V2 ZXing port is justified.
// OFF for ship. The decoder side wraps the bytes as ImageView(Lum,W,H).
#define QR_DUMP_FRAME 0
static volatile bool qrFound=false;
static volatile bool qrReady=false;
#define QR_RESULT_SZ 1024
static char* qrResultBuf = nullptr;   // (PSRAM, ps_malloc at boot)
static void qrScanTask(void* arg){
  Serial.printf("[AIRDIAG] qrScanTask: enter\n");
  qrFound=false;
  // V21.1: grab a COMPLETE frame. The OV2640 + DMA can deliver torn/partial
  // frames (len < width*height) under bus contention; feeding a short buffer
  // to quirc wastes a whole scan cycle on garbage. Retry a few times until we
  // get a full frame, returning the torn ones immediately. Expected full size
  // = width*height for grayscale (QVGA = 76800).
  camera_fb_t* fb=NULL;
  for(int tries=0; tries<8; tries++){
    fb=esp_camera_fb_get();
    if(!fb) { vTaskDelay(pdMS_TO_TICKS(10)); continue; }
    if(fb->format==PIXFORMAT_GRAYSCALE && fb->len==(size_t)fb->width*fb->height) break; // full frame
    esp_camera_fb_return(fb); fb=NULL;            // torn/partial — discard, retry
    vTaskDelay(pdMS_TO_TICKS(10));
  }
  if(!fb){
    Serial.printf("[AIRDIAG] qrScanTask: no full frame after 8 tries — torn/null\n");
    qrDiagTorn=true; qrDiagIdentified=0; qrDiagCells=0; qrDiagOk=false; qrTaskRunning=false;vTaskDelete(NULL);return;
  }
  Serial.printf("[AIRDIAG] qrScanTask: got frame %ux%u len=%u\n",(unsigned)fb->width,(unsigned)fb->height,(unsigned)fb->len);
  qrDiagTorn=false;
  struct quirc* qr=quirc_new();
  if(!qr||quirc_resize(qr,fb->width,fb->height)<0){if(qr)quirc_destroy(qr);esp_camera_fb_return(fb);qrTaskRunning=false;vTaskDelete(NULL);return;}
  uint8_t* buf=quirc_begin(qr,NULL,NULL);
  // CRASH GUARD: quirc_begin can return NULL under heap pressure (see the other
  // scan path). Bail this frame cleanly rather than memcpy to NULL.
  if(!buf){
    LOG_CAM("[QMEM] quirc_begin NULL (qrTask) — skipping frame\n");
    quirc_destroy(qr); esp_camera_fb_return(fb); qrTaskRunning=false; vTaskDelete(NULL); return;
  }
#if QR_HIST_STRETCH
  {
    const uint8_t* src=fb->buf; int n=(int)fb->len;
    uint32_t hist[256]={}; for(int i=0;i<n;i++) hist[src[i]]++;
    int lo_cut=n/50,hi_cut=n/50,lo=0,hi=255,acc=0;  // 2% clip — more aggressive stretch for screen QRs
    for(int v=0;v<256;v++){acc+=hist[v];if(acc>=lo_cut){lo=v;break;}} acc=0;
    for(int v=255;v>=0;v--){acc+=hist[v];if(acc>=hi_cut){hi=v;break;}}
    if(hi-lo<20){lo=0;hi=255;}  // lower threshold — apply stretch even on low-contrast frames
    if(lo==0&&hi==255) memcpy(buf,src,n);
    else{float scale=255.0f/(float)(hi-lo);for(int i=0;i<n;i++){int v=(int)((src[i]-lo)*scale);buf[i]=(uint8_t)(v<0?0:v>255?255:v);}}
  }
#else
  // Raw passthrough — let quirc's own adaptive threshold handle a clean,
  // already-high-contrast screen image without our clip corrupting modules.
  memcpy(buf, fb->buf, (size_t)fb->len);
#endif
  quirc_end(qr); esp_camera_fb_return(fb);
  int count=quirc_count(qr);
  // V21_2: record diagnostic state for the on-screen readout (USB serial is
  // unusable on the bench — it contends with camera DMA and breaks scanning).
  qrDiagIdentified=count; qrDiagCells=0; qrDiagOk=false;
  // ── V21.1 DIAG ([QRDIAG], strip before ship) ───────────────────────────────
  // Measures the device's READABLE ceiling for multi-part QR fragment sizing.
  // For each code quirc IDENTIFIES (locates the finder pattern + grid), log its
  // grid size (px → version) and whether the DECODE step then succeeds. Hold
  // progressively denser codes at the camera; the last version that logs OK is
  // the per-fragment ceiling. cells = code.size (pixels of the sampled grid);
  // version derives from a successful decode only (FAIL = grid found, data not
  // recovered, i.e. just past the readable limit). 'identified=0' = quirc could
  // not even find a code (too small/blurry/far). Grep-removable before ship.
  LOG_CAM("[QRDIAG] identified=%d\n", count);
  // ── end QRDIAG ──────────────────────────────────────────────────────────────
  for(int i=0;i<count&&!qrFound;i++){
    struct quirc_code code; struct quirc_data data;
    quirc_extract(qr,i,&code);
    if(i==0) qrDiagCells=code.size;   // V21_2: first located grid size for on-screen diag
    quirc_decode_error_t derr=quirc_decode(&code,&data);
    if(derr==QUIRC_SUCCESS){
      qrDiagOk=true; qrDiagCells=code.size;   // V21_2: a code decoded
      // ── V21.1 DIAG ([QRDIAG], strip before ship) ─────────────────────────────
      { const char* eccs="MLHQ"; char ec=(data.ecc_level>=0&&data.ecc_level<4)?eccs[data.ecc_level]:'?';
        LOG_CAM("[QRDIAG] OK   ver=%d ecc=%c bytes=%d cells=%d\n",
          data.version, ec, (int)data.payload_len, code.size); }
      // ── end QRDIAG ────────────────────────────────────────────────────────────
      size_t len=data.payload_len<QR_RESULT_SZ-1?data.payload_len:QR_RESULT_SZ-1;
      memcpy(qrResultBuf,data.payload,len);qrResultBuf[len]=0;qrFound=true;
    } else {
      // ── V21.1 DIAG ([QRDIAG], strip before ship) ─────────────────────────────
      // Grid located but data not recovered → at/just past the readable limit.
      // cells→version: version ≈ (cells-17)/4. quirc_strerror gives the stage.
      LOG_CAM("[QRDIAG] FAIL cells=%d (~ver=%d) err=%s\n",
        code.size, (code.size>=21)?((code.size-17)/4):0, quirc_strerror(derr));
      // ── end QRDIAG ────────────────────────────────────────────────────────────
    }
  }
  // V21_2: inversion retry DISABLED for the scan path. Screen QRs are always
  // dark-on-light (never colour-inverted), so the inverted re-decode never helps
  // here — but it re-runs a full quirc_count()+decode on exactly the frames that
  // already failed (the smeared mid-transition frames a fast animator produces),
  // roughly doubling decode time and lowering the effective sample rate. Dropping
  // it lets the next clean frame come round sooner. Flip to 1 only if a genuinely
  // inverted source ever needs supporting (paper white-on-black, etc.).
#define QR_INVERT_RETRY 0
#if QR_INVERT_RETRY
  if(!qrFound&&count>0){
    int w2,h2; uint8_t* ibuf=quirc_begin(qr,&w2,&h2);
    for(int i=0;i<w2*h2;i++) ibuf[i]^=0xFF;
    quirc_end(qr); int count2=quirc_count(qr);
    for(int i=0;i<count2&&!qrFound;i++){
      struct quirc_code code; struct quirc_data data;
      quirc_extract(qr,i,&code);
      if(quirc_decode(&code,&data)==QUIRC_SUCCESS){
        size_t len=data.payload_len<QR_RESULT_SZ-1?data.payload_len:QR_RESULT_SZ-1;
        memcpy(qrResultBuf,data.payload,len);qrResultBuf[len]=0;qrFound=true;
      }
    }
  }
#endif
  // V21_2: HWM = words of stack left UNUSED at peak. x4 = bytes. If this stays
  // comfortably >512 words at stack=8192, the shrink has margin. If it dips low,
  // bump the stack in triggerQRScan. Strip before ship.
  Serial.printf("[AIRDIAG] qrscan stack HWM=%u words (~%u bytes free)\n",
    (unsigned)uxTaskGetStackHighWaterMark(NULL),
    (unsigned)(uxTaskGetStackHighWaterMark(NULL)*4));
  quirc_destroy(qr); qrTaskRunning=false; vTaskDelete(NULL);
}

// ── Seed restore functions ────────────────────────────────────────────────
// All placed here: after dispPreview, qrResultBuf, dispLoading are defined

int bip39FindPrefix(const char* prefix, int skip){
  int found=0;
  for(int i=0;i<2048;i++){
    if(strncmp(BIP39_WORDS[i],prefix,strlen(prefix))==0){
      if(found==skip) return i;
      found++;
    }
  }
  return -1;
}

int bip39CountPrefix(const char* prefix){
  int n=0;
  for(int i=0;i<2048;i++)
    if(strncmp(BIP39_WORDS[i],prefix,strlen(prefix))==0) n++;
  return n;
}

// Enter one word using BTN1=next letter, BTN2=confirm/cycle
// Returns true and sets word_out on success, false to cancel
bool enterOneWord(int word_num, int total_words, char* word_out){
  char confirmedPrefix[9]={0};
  int confirmedLen=0;
  char currentLetter='a';
  bool letterStarted=false;
  int wordCursor=0;
  const int WORD_MODE_THRESHOLD=10;

  // Flush buttons on entry so a leaked press from the method screen or the
  // previous word doesn't immediately act here.
  delay(250);
  btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
  btn1.resetHold(); btn2.resetHold(); btn3.resetHold(); btn4.resetHold();
  clearButtonPending();

  while(true){
    char prefix[9]={0};
    strncpy(prefix, confirmedPrefix, 8);
    if(letterStarted && confirmedLen<8){
      prefix[confirmedLen]=currentLetter;
      prefix[confirmedLen+1]=0;
    }

    int confirmedMatches=bip39CountPrefix(confirmedPrefix);
    int displayMatches=letterStarted ? bip39CountPrefix(prefix) : confirmedMatches;
    bool wordMode=(confirmedMatches>0 && confirmedMatches<=WORD_MODE_THRESHOLD && !letterStarted);

    // ── Draw ─────────────────────────────────────────────────────
    spr.fillSprite(C_BG);
    uiHeader("RESTORE SEED",C_GREEN);
    char wc[16]; snprintf(wc,16,"Word %d / %d",word_num,total_words);
    fSet(F_BODY); spr.setTextColor(C_DIM); fDrawCentre(wc,120,34); fEnd();
    uiRule(48,C_VDIM);

    // The thing you're building — confirmed prefix + the letter under the
    // cursor — is the hero of this screen. Render it large in F_TITLE (24px
    // mono): monospace keeps each character distinct for letter-by-letter
    // scanning and makes the trailing cursor line up cleanly.
    { char dispC[10]={0}; strncpy(dispC,confirmedPrefix,8);
      char dispL[3]={0};
      if(letterStarted){ dispL[0]=currentLetter; dispL[1]='_'; }
      else strcpy(dispL,"_");
      fSet(F_TITLE);
      int cw=confirmedLen>0?spr.textWidth(dispC):0;
      int lw=spr.textWidth(dispL);
      int sx=120-(cw+lw)/2;
      if(confirmedLen>0){ spr.setTextColor(C_FG); spr.drawString(dispC,sx,66); }
      spr.setTextColor(C_AMBER); spr.drawString(dispL,sx+cw,66);
      fEnd();
    }

    if(wordMode){
      if(wordCursor>=confirmedMatches) wordCursor=0;
      int idx=bip39FindPrefix(confirmedPrefix,wordCursor);
      if(idx>=0){
        // Candidate word — second-most-important, bumped to F_HEAD (16px).
        fSet(F_HEAD); spr.setTextColor(C_GREEN);
        fDrawCentre(BIP39_WORDS[idx],120,108); fEnd();
        char mc[24]; snprintf(mc,24,"%d of %d",wordCursor+1,confirmedMatches);
        fSet(F_BODY); spr.setTextColor(C_VDIM); fDrawCentre(mc,120,134); fEnd();
      }
    } else if(letterStarted){
      if(displayMatches==0){
        fSet(F_HEAD); spr.setTextColor(C_RED); fDrawCentre("no match",120,108); fEnd();
      } else {
        int idx=bip39FindPrefix(prefix,0);
        if(idx>=0){
          fSet(F_HEAD); spr.setTextColor(displayMatches==1?C_GREEN:C_DIM);
          fDrawCentre(BIP39_WORDS[idx],120,108); fEnd();
        }
        char mc[16]; snprintf(mc,16,"%d matches",displayMatches);
        fSet(F_BODY); spr.setTextColor(C_VDIM); fDrawCentre(mc,120,134); fEnd();
      }
    } else {
      if(confirmedLen>0){
        char mc[16]; snprintf(mc,16,"%d matches",confirmedMatches);
        fSet(F_BODY); spr.setTextColor(C_VDIM); fDrawCentre(mc,120,112); fEnd();
      }
    }
    uiFooter(); dispPush();

    // ── Input — four-button scheme ──────────────────────────────────────
    //   SCROLL DOWN (btn1) = next letter / next word  (forward)
    //   SCROLL UP   (btn3) = prev letter / prev word  (backward)
    //   ENTER (btn2)       = accept letter / confirm word
    //   BACK  (btn4)       = delete last letter; if none, return to prev word
    // btn3/btn1 auto-repeat while held so long scans aren't tedious.
    bool redraw=false;
    unsigned long loopStart=millis();

    // Advance currentLetter to the next valid first-extension letter, in the
    // given direction (+1 forward, -1 backward), wrapping a..z. Only lands on
    // letters that still yield at least one BIP-39 match for the prefix.
    auto cycleLetter=[&](int dir){
      char test[9]; strncpy(test,confirmedPrefix,8);
      for(int step=0; step<26; step++){
        char c = currentLetter + dir*(step+1);
        while(c<'a') c+=26; while(c>'z') c-=26;
        test[confirmedLen]=c; test[confirmedLen+1]=0;
        if(bip39CountPrefix(test)>0){ currentLetter=c; return; }
      }
    };
    // Pick the first valid letter (used when starting letter entry).
    auto firstValidLetter=[&]()->bool{
      char test[9]; strncpy(test,confirmedPrefix,8); test[confirmedLen+1]=0;
      for(char c='a';c<='z';c++){
        test[confirmedLen]=c;
        if(bip39CountPrefix(test)>0){ currentLetter=c; letterStarted=true; return true; }
      }
      return false;
    };
    // Acknowledge an accepted word so the user registers it landed, instead of
    // the screen jumping straight to the next word. Shows the word large in
    // green with a tick, a short success beat, then a brief hold.
    auto confirmWordFlash=[&](const char* w){
      buzzerOK();
      spr.fillSprite(C_BG);
      uiHeader("RESTORE SEED",C_GREEN);
      char wcf[16]; snprintf(wcf,16,"Word %d / %d",word_num,total_words);
      fSet(F_BODY); spr.setTextColor(C_DIM); fDrawCentre(wcf,120,34); fEnd();
      uiRule(48,C_VDIM);
      // Centred green tick above the accepted word.
      int cx=120, cy=82;
      spr.drawWideLine(cx-9,cy, cx-2,cy+8, 5, C_GREEN);
      spr.drawWideLine(cx-2,cy+8, cx+12,cy-9, 5, C_GREEN);
      fSet(F_TITLE); spr.setTextColor(C_GREEN);
      fDrawCentre(w,120,116); fEnd();
      fSet(F_BODY); spr.setTextColor(C_MUTED); fDrawCentre("Saved",120,150); fEnd();
      uiFooter(); dispPush();
      delay(750);
      clearButtonPending();
    };

    while(!redraw && millis()-loopStart<30000){
      btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();

      // Auto-repeat for scroll buttons when held (smooth fast scanning).
      float hDown=btn1.holdProgress(500);
      float hUp  =btn3.holdProgress(500);

      // ── SCROLL DOWN (forward) ──
      if(btn1.isPressed() || hDown>=1.0f){
        if(wordMode){
          wordCursor=(wordCursor+1)%confirmedMatches;
        } else if(!letterStarted){
          firstValidLetter();          // begin letter entry at first valid
        } else {
          cycleLetter(+1);
        }
        redraw=true; delay(hDown>=1.0f?45:120); continue;
      }
      // ── SCROLL UP (backward) ──
      if(btn3.isPressed() || hUp>=1.0f){
        if(wordMode){
          wordCursor=(wordCursor-1+confirmedMatches)%confirmedMatches;
        } else if(!letterStarted){
          // Start letter entry on the LAST valid letter when scrolling up.
          if(firstValidLetter()) cycleLetter(-1);
        } else {
          cycleLetter(-1);
        }
        redraw=true; delay(hUp>=1.0f?45:120); continue;
      }

      // ── ENTER (accept letter / confirm word) ──
      if(btn2.isPressed()){
        if(wordMode){
          if(wordCursor>=confirmedMatches) wordCursor=0;
          int idx=bip39FindPrefix(confirmedPrefix,wordCursor);
          if(idx>=0){
            strncpy(word_out,BIP39_WORDS[idx],11); word_out[11]=0;
            confirmWordFlash(word_out);
            return true;
          }
        } else if(letterStarted){
          char test[9]; strncpy(test,confirmedPrefix,8);
          test[confirmedLen]=currentLetter; test[confirmedLen+1]=0;
          if(bip39CountPrefix(test)>0){
            confirmedPrefix[confirmedLen++]=currentLetter;
            confirmedPrefix[confirmedLen]=0;
            letterStarted=false; wordCursor=0;
            clearButtonPending();
            redraw=true; continue;
          }
        } else if(confirmedMatches==1){
          int idx=bip39FindPrefix(confirmedPrefix,0);
          if(idx>=0){
            strncpy(word_out,BIP39_WORDS[idx],11); word_out[11]=0;
            confirmWordFlash(word_out);
            return true;
          }
        }
        delay(120); redraw=true; continue;
      }

      // ── BACK (delete last letter; if none, go to previous word) ──
      if(btn4.isPressed()){
        if(letterStarted){
          // Abandon the in-progress letter without deleting a confirmed one.
          letterStarted=false; wordCursor=0;
          clearButtonPending();
          redraw=true; continue;
        } else if(confirmedLen>0){
          confirmedPrefix[--confirmedLen]=0;
          wordCursor=0;
          clearButtonPending();
          redraw=true; continue;
        } else {
          // Nothing entered for this word → step back to the previous word.
          clearButtonPending();
          return false;
        }
      }

      delay(10);
    }
  }
}

// BIP-39 passphrase: picker, QR path, validation, fingerprint confirm. Lives
// in its own file; it is a slice of this one (needs every helper above).
#include "passphrase.h"

// 29 Oct 2026 (board N2): onboarding asks "24 words / 12 words / seed QR /
// nsec" in ONE list and presets the method here (0 words, 1 seed QR, 2 nsec),
// so the restore flow skips its own method screen. -1 = ask (other callers).
static int g_restoreMethodPreset = -1;
bool runRestoreFlow(int word_count, uint8_t* priv_out, uint8_t* pub_out){
  // Method selection as a proper highlighted-pill selector (scroll to choose,
  // ENTER to select, BACK to cancel). Replaces the old hold-BTN1-for-nsec
  // mechanic, which was undiscoverable.
  // Three cards rather than uiPillSelect, to match the rest of onboarding.
  // Three at 84px would not fit under a question block, so they run at 62px —
  // still taller than the Nostr menu's 68px cards feel, because these carry a
  // description line each and Nostr's carry an icon instead.
  int m = 0;
  if(g_restoreMethodPreset >= 0){ m = g_restoreMethodPreset; g_restoreMethodPreset = -1; }
  else { bool mdone = false, mback = false;
    while(!mdone && !mback){
      spr.fillSprite(C_BG);
      uiAsk("Restore wallet", "How do you have your key?");
      ppCard(46, 62, "SEED WORDS", "Type them in",        m==0, C_EB_BRASS, ppIconWords);
      ppCard(114,62, "SEED QR",    "Scan a backup QR",    m==1, C_EB_BRASS, ppIconQr);
      ppCard(182,56, "NSEC",       "Nostr key only",      m==2, C_EB_BRASS,  ppIconKey);
      dispPush();
      while(true){
        btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
        if(btn1.isPressed()){ m = (m + 1) % 3; break; }
        if(btn3.isPressed()){ m = (m + 2) % 3; break; }
        if(btn2.isPressed()){ mdone = true; break; }
        if(btn4.isPressed()){ mback = true; break; }
        esp_task_wdt_reset(); delay(10);
      }
      delay(200);
    }
    if(mback) return false;   // BACK = cancel restore
  }
  bool useQR   = (m==1);
  bool useNsec = (m==2);
  // Flush any queued press before the next screen takes input.
  clearButtonPending();

  char mnemonic_in[300]={0};

  // SEC_1 finding 6: this function handles raw key material — the scanned
  // nsec or mnemonic lands in qrResultBuf (PSRAM) and mnemonic_in (stack).
  // Previously only the success path zeroed mnemonic_in, and qrResultBuf was
  // never wiped at all (it kept the full nsec/mnemonic until the NEXT scan
  // truncated it). RAII guard: destructor runs on every return, success or
  // error, so no exit path can forget.
  struct RestoreWipe {
    char* mn; size_t mnLen;
    ~RestoreWipe(){
      mbedtls_platform_zeroize(mn, mnLen);
      if(qrResultBuf) mbedtls_platform_zeroize(qrResultBuf, QR_RESULT_SZ);
    }
  } _restoreWipe{ mnemonic_in, sizeof(mnemonic_in) };

  if(useNsec){
    // nsec import via QR scan
    spr.fillSprite(C_BG);
    uiAsk("Import nsec", "Nostr key only - no Bitcoin");
    fSet(F_HEAD); spr.setTextColor(C_FG);
    fDrawCentre("Scan your nsec QR",120,84); fEnd();
    fSet(F_BODY); spr.setTextColor(C_TEXT2);
    fDrawCentre("Show it on your phone",120,118); fEnd();
    fSet(F_BODY); spr.setTextColor(C_VDIM);
    fDrawCentre("Back to cancel",120,204); fEnd();
    dispPush(); delay(800);
    // V22.x: mirror the ST_SCANNING / ST_AIRGAP_SIGN entry sequence exactly —
    // this loop previously skipped it and inherited whatever clock was current.
    // At 80MHz (pwrIdle inherited from a static screen) the grab + 5x5 morpho
    // close + quirc full-image scan + per-pixel preview push runs at ~1/3 speed,
    // so the live view updates at ~1fps and reads as a FROZEN screen. Known
    // regression pattern — see the smart-scan pwrBoost note in ST_SCANNING.
    pwrBoost();       // grab+decode+preview MUST run at 240MHz
    camHoldWake();    // camera DMA capture can't tolerate light sleep (10q: the scan's own hold)
    cameraStart(); qrFound=false;
    if(!cameraRunning) return false;   // start failed — error screen already shown
    // Stale-frame flush (matches ST_SCANNING): with fb_count=1 + resident camera
    // the buffer can still hold the LAST frame from a previous scan session.
    for(int _f=0; _f<4; _f++){
      camera_fb_t* _sf=esp_camera_fb_get();
      if(_sf) esp_camera_fb_return(_sf);
      vTaskDelay(pdMS_TO_TICKS(25));
    }
    qrResultBuf[0]=0;   // clear any leftover decode result
    qrDiagReset(); qrDumpReset();
    // V22.x FIX (no live view on restore scans): this loop still used the OLD
    // background-task scanner (triggerQRScan/qrScanTask) + dispPreview. With the
    // resident camera (fb_count=1 + GRAB_LATEST) the main-loop dispPreview and the
    // cross-core task race each other on esp_camera_fb_get — the preview gets
    // NULL/torn frames only, so the screen froze on the "Starting camera..."
    // placeholder. Migrated to the proven synchronous qrScanOnce() pattern used by
    // ST_SCANNING / ST_AIRGAP_SIGN: one context owns the camera, and qrScanOnce
    // draws the live feed itself (g_airgapLivePreview).
    g_airgapLivePreview=true; g_airgapUrGot=0; g_airgapUrTotal=0;
    unsigned long ns=millis();
    LOG_CAM("[RESTORE] nsec sync-scan loop ENTER (qrScanOnce path) running=%d hwReady=%d\n",
            (int)cameraRunning,(int)cameraHwReady);
    unsigned long lastNsecQR=0;
    while(millis()-ns<30000){
      btn4.poll();
      if(btn4.isPressed()){ g_airgapLivePreview=false; cameraStop(); return false; }   // BACK = cancel
      if(!qrFound&&(millis()-lastNsecQR>QR_AIRGAP_SCAN_INTERVAL_MS)){
        qrScanOnce();          // grabs, draws the live preview, decodes; sets qrFound
        lastNsecQR=millis();   // stamp AFTER the scan (V22.2: true inter-scan gap)
        delay(5);              // brief yield so the camera ISR/DMA can quiesce
      }
      if(qrFound){
        qrFound=false; g_airgapLivePreview=false; cameraStop();
        clearButtonPending();  // drop presses queued during the blocking scan
        // NEVER log the QR content here — on this path it IS the user's
        // Nostr private key (nsec/hex). Length only. (SEC_1 finding 1 class,
        // worst instance: full key material to serial.)
        LOG_CAM("[NSEC] QR scanned (%d chars)\n", strlen(qrResultBuf));
        // Parse nsec - bech32 (nsec1...) or raw 64-char hex
        String raw=String(qrResultBuf);
        raw.trim();
        LOG_CAM("[NSEC] trimmed length: %d (need 63 for nsec1 or 64 for hex)\n", raw.length());
        String data;                 // hoisted from the bech32 branch so the wipe guard covers it
        uint8_t privBytes[32]={0};
        uint8_t bits5[64]={0};       // hoisted for the same reason
        bool parsed=false;
        // SEC_1 finding 6: raw/data are heap String copies of the user's
        // private key; privBytes/bits5 hold it decoded. Wipe on EVERY exit —
        // the destructor runs on success and on each early error return.
        struct NsecWipe {
          String &r, &d; uint8_t *pb, *b5;
          ~NsecWipe(){
            wipeString(r); wipeString(d);
            mbedtls_platform_zeroize(pb, 32);
            mbedtls_platform_zeroize(b5, 64);
          }
        } _nsecWipe{ raw, data, privBytes, bits5 };

        if(raw.startsWith("nsec1")||raw.startsWith("NSEC1")){
          // Bech32 decode
          // Bech32 charset
          const char* CHARSET="qpzry9x8gf2tvdw0s3jn54khce6mua7l";
          // Convert bech32 string to 5-bit values, then to 8-bit bytes
          data=raw.substring(5); // skip "nsec1"
          data.toLowerCase();
          // Remove checksum (last 6 chars)
          if(data.length()<40){ dispError("nsec too short");errorPause(); return false; }
          data=data.substring(0,data.length()-6);
          // Decode each char to 5-bit value
          int n5=0;
          bool ok=true;
          for(int i=0;i<(int)data.length()&&n5<64;i++){
            const char* p=strchr(CHARSET,data[i]);
            if(!p){ ok=false; break; }
            bits5[n5++]=(uint8_t)(p-CHARSET);
          }
          if(!ok){ dispError("Bad nsec chars");errorPause(); return false; }
          // Convert 5-bit groups to 8-bit bytes
          uint32_t acc=0; int bits=0; int outLen=0;
          for(int i=0;i<n5;i++){
            acc=(acc<<5)|bits5[i]; bits+=5;
            while(bits>=8&&outLen<32){
              privBytes[outLen++]=(acc>>(bits-8))&0xFF;
              bits-=8;
            }
          }
          if(outLen==32) parsed=true;
          else{ dispError("nsec decode failed");errorPause(); return false; }
        } else if(raw.length()==64){
          // Raw hex private key
          if(fromHex(raw.c_str(),privBytes,32)) parsed=true;
        }
        LOG_CAM("[NSEC] parsed=%d\n", parsed);  // never log key bytes, even one
        if(!parsed){ dispError("Invalid nsec format");errorPause(); return false; }
        // Derive public key
        if(!bip340_make_key(privBytes,pub_out)){ dispError("Key derive failed");errorPause(); return false; }
        memcpy(priv_out,privBytes,32);
        keyIsNsecImport=true;
        return true;
      }
      delay(10);
    }
    g_airgapLivePreview=false; cameraStop(); return false;   // timeout
  } else if(useQR){
    // Seed phrase QR scan path
    spr.fillSprite(C_BG);
    uiHeader("SCAN SEED QR",C_EB_BRASS);
    fSet(F_BODY); spr.setTextColor(C_DIM);
    fDrawCentre("Scan your seed phrase QR",120,80); fEnd();
    fSet(F_BODY); spr.setTextColor(C_VDIM); fDrawCentre("BACK  cancel",120,200); fEnd();
    uiFooter(); dispPush(); delay(800);
    // V22.x: same entry sequence as the nsec path above — pwrBoost is the fix
    // for the frozen-preview symptom (80MHz cut the scan+preview rate to ~1/3).
    pwrBoost();
    camHoldWake();    // 10q
    cameraStart(); qrFound=false;
    if(!cameraRunning) return false;   // start failed — error screen already shown
    for(int _f=0; _f<4; _f++){          // stale-frame flush (fb_count=1 resident)
      camera_fb_t* _sf=esp_camera_fb_get();
      if(_sf) esp_camera_fb_return(_sf);
      vTaskDelay(pdMS_TO_TICKS(25));
    }
    qrResultBuf[0]=0;
    qrDiagReset(); qrDumpReset();
    // V22.x FIX: same no-live-view bug as the nsec path above — migrated from the
    // dead triggerQRScan/dispPreview background-task pattern to synchronous
    // qrScanOnce(), which draws the live feed itself. See the nsec loop comment.
    g_airgapLivePreview=true; g_airgapUrGot=0; g_airgapUrTotal=0;
    LOG_CAM("[RESTORE] seed sync-scan loop ENTER (qrScanOnce path) running=%d hwReady=%d\n",
            (int)cameraRunning,(int)cameraHwReady);
    unsigned long qs=millis();
    unsigned long lastSeedQR=0;
    while(millis()-qs<30000){
      btn4.poll();
      if(btn4.isPressed()){ g_airgapLivePreview=false; cameraStop(); return false; }   // BACK = cancel
      if(!qrFound&&(millis()-lastSeedQR>QR_AIRGAP_SCAN_INTERVAL_MS)){
        qrScanOnce();          // grabs, draws the live preview, decodes; sets qrFound
        lastSeedQR=millis();   // stamp AFTER the scan (V22.2: true inter-scan gap)
        delay(5);
      }
      if(qrFound){
        qrFound=false; g_airgapLivePreview=false; cameraStop();
        clearButtonPending();  // drop presses queued during the blocking scan
        strncpy(mnemonic_in,qrResultBuf,sizeof(mnemonic_in)-1); break;
      }
      delay(10);
    }
    if(!mnemonic_in[0]){ g_airgapLivePreview=false; cameraStop(); return false; }   // timeout
  } else {
    // Word entry path
    char words[24][12]={};
    // Guard rather than trailing memset: the cancel path below returns
    // mid-entry with words[] partially filled (SEC_1 finding 6).
    struct WordsWipe { void* w; size_t n; ~WordsWipe(){ mbedtls_platform_zeroize(w,n); } }
      _wordsWipe{ words, sizeof(words) };
    for(int w=0;w<word_count;w++){
      if(!enterOneWord(w+1,word_count,words[w])){
        if(w>0){ w-=2; continue; }
        return false;
      }
    }
    for(int w=0;w<word_count;w++){ if(w>0) strcat(mnemonic_in," "); strcat(mnemonic_in,words[w]); }
  }

  // F4: VALIDATE THE BIP-39 CHECKSUM BEFORE DERIVING. This path previously
  // went straight from words to PBKDF2, so a mistyped word that happens to
  // exist in the wordlist restored a DIFFERENT, PERFECTLY VALID WALLET with
  // no error. The user then sees an empty balance and cannot tell a typo
  // from a theft. Catch it here, while they can still fix it.
  {
    // Validate mnemonic_in, NOT the word-entry array: `words` is scoped to the
    // manual-entry branch, and the QR-scan path populates mnemonic_in without
    // ever touching it. Both paths converge here.
    char _mtmp[300]; strncpy(_mtmp, mnemonic_in, sizeof(_mtmp)-1);
    _mtmp[sizeof(_mtmp)-1] = 0;
    const char* _wp[24]; int _wc = 0;
    for(char* t = strtok(_mtmp, " "); t && _wc < 24; t = strtok(NULL, " "))
      _wp[_wc++] = t;
    bool _mok = (_wc == 12 || _wc == 24) && bip39_validate_mnemonic(_wp, _wc);
    mbedtls_platform_zeroize(_mtmp, sizeof(_mtmp));
    if(!_mok){
      dispError("Checksum failed - check words");
      errorPause();
      return false;
    }
  }

  uint8_t seed[64]={0};
  // SEC_1 finding 6: the three error returns inside the derive block below
  // previously left a (possibly fully derived) seed on the stack. Guard
  // wipes it on every exit; the success path's explicit memset stays as
  // belt-and-braces.
  struct SeedWipe { uint8_t* s; ~SeedWipe(){ mbedtls_platform_zeroize(s,64); } }
    _seedWipe{ seed };

  // ── BIP-39 passphrase (optional) + fingerprint confirm ─────────────────
  // Words checksum-valid; now ask whether the wallet used a passphrase, then
  // derive and show the master fingerprint BEFORE anything is sealed. A
  // wrong passphrase (or wrong words that still pass the checksum) is
  // caught here by the owner comparing the number, not by an empty balance
  // later. BACK on the fingerprint screen returns to the passphrase choice
  // with the words kept; BACK on the choice abandons the restore.
  {
    char pass[PP_MAX+1]={0};
    uint8_t seedWords[64]={0}, fpW[4]={0}, fpF[4]={0};
    struct PassWipe { char* p; uint8_t* sw; ~PassWipe(){
      mbedtls_platform_zeroize(p,PP_MAX+1); mbedtls_platform_zeroize(sw,64); } }
      _passWipe{ pass, seedWords };
    int ppMode = PP_MODE_NONE;
    while(true){
      bool rehearsed=false;
      int m = ppCollectMode(pass, sizeof pass, true, &rehearsed);
      if(m<0) return false;                        // abandon restore
      ppMode = m;
      bool hasPass = (ppMode==PP_MODE_BAKED) || (ppMode==PP_MODE_SESSION && rehearsed);
      dispEmberWorking("Restoring","DERIVING KEY",nullptr);
      {
        BgSpin _spin(C_EB_BRASS);
        // Words-only seed first: it is the final seed when there is no
        // passphrase, and the "words only" fingerprint when there is one.
        if(!bip39_mnemonic_to_seed(mnemonic_in,"",seedWords)){ dispError("Seed failed");errorPause(); return false; }
#ifdef FAVILLA_PK_RESTORABLE
        pkrPendingFromSeed(seedWords);   // restorable passkeys follow the words, never the passphrase
#endif
        if(!ppMasterFingerprint(seedWords,fpW)){ dispError("Fingerprint failed");errorPause(); return false; }
        if(hasPass){
          if(!bip39_mnemonic_to_seed(mnemonic_in,pass,seed)){ dispError("Seed failed");errorPause(); return false; }
          if(!ppMasterFingerprint(seed,fpF)){ dispError("Fingerprint failed");errorPause(); return false; }
        } else {
          memcpy(seed, seedWords, 64); memcpy(fpF, fpW, 4);
        }
      }
      LOG_KEY("[PASS] restore: passphrase=%s fp=%02x%02x%02x%02x\n",
              hasPass?"yes":"no", fpF[0],fpF[1],fpF[2],fpF[3]);
      if(ppFingerprintConfirm(fpW, fpF, hasPass, true)) break;
      // Back to the passphrase choice: forget this derivation.
      mbedtls_platform_zeroize(seed,64);
      mbedtls_platform_zeroize(pass,sizeof pass);
    }
    // v4: per-session wallet. What gets sealed is the ENTROPY; the Nostr
    // identity derives from the words alone; the rehearsal passphrase (if
    // any) was only for the fingerprint screen and is forgotten here.
    pendingRestoreMode = (uint8_t)ppMode;
    mbedtls_platform_zeroize(pendingRestoreEntropy, sizeof(pendingRestoreEntropy)); pendingRestoreWc=0;
    if(ppMode==PP_MODE_SESSION){
      memcpy(seed, seedWords, 64);
      char _mt[300]; strncpy(_mt, mnemonic_in, sizeof(_mt)-1); _mt[sizeof(_mt)-1]=0;
      const char* _wp[24]; int _wc=0;
      for(char* t=strtok(_mt," "); t && _wc<24; t=strtok(NULL," ")) _wp[_wc++]=t;
      int elen=0;
      bool eok = bip39_words_to_entropy(_wp, _wc, pendingRestoreEntropy, &elen);
      mbedtls_platform_zeroize(_mt, sizeof(_mt));
      if(!eok || !(elen==16 || elen==32)){ dispError("Entropy failed");errorPause(); return false; }
      pendingRestoreWc=_wc;
    }
  }

  dispEmberWorking("Restoring","DERIVING KEY",nullptr);
  {
    // Live spinner during NIP-06 derive. return false on any failure
    // unwinds this scope (stopping the spinner) before returning from the fn.
    BgSpin _spin(C_EB_BRASS);
    if(!nip06_derive(seed,priv_out)){ dispError("Derive failed");errorPause(); return false; }
    if(!bip340_make_key(priv_out,pub_out)){ dispError("Key setup failed (E3)");errorPause(); return false; }
  }
  keyIsNsecImport=false;
  // Stash the seed for the ST_PIN_ENTRY save step. We can't save now
  // because the new PIN (needed to encrypt) hasn't been chosen yet. The
  // pending buffer is zeroised on save, on sleep, and on any restore-
  // abort path (see calls to memset(pendingRestoreSeed,...)).
  memcpy(pendingRestoreSeed, seed, 64);
  pendingRestoreSeedValid = true;
  memset(seed,0,sizeof(seed)); memset(mnemonic_in,0,sizeof(mnemonic_in));
  return true;
}


// ── First-run onboarding ────────────────────────────────────────────────────
// Shown once at boot when no key is stored. Two clean choices that route into
// the existing flows. Sets nextState and returns. No BACK target (there's
// nothing behind first-run), so the selector is drawn without a back action.
// ── First impression ────────────────────────────────────────────────────────
// The wordmark alone (Archivo lockup), on black. No header, no footer,
// no chrome of any kind — this is the first thing an owner ever sees and the
// product's whole argument is restraint. Everything else on this screen exists
// only to say "press this".
// 29 Oct 2026 (page language): the end-of-setup page. Tracked label, the lit
// ember, one headline (Archivo Bold 28), up to two grey lines, and the action
// as a tracked footer. No pill, no status footer. Waits for ENTER.
static void obFinishPage(const char* label, const char* head, const char* l1, const char* l2,
                         const char* action, uint16_t l1col = C_EB_GREY){
  spr.fillSprite(C_BG);
  uiTrackLabel(label, 120, 14, C_EB_GREY);
  ebMarkSmall(101, 40, 6, 2);
  fEndHard(); spr.loadFont(FONT_Archivo_Bold_28_full); spr.setTextColor(C_EB_INK);
  spr.drawString(head, 120 - spr.textWidth(head)/2, 94);
  fEndHard(); spr.loadFont(FONT_Archivo_Regular_13);
  if(l1){ spr.setTextColor(l1col);    spr.drawString(l1, 120 - spr.textWidth(l1)/2, 136); }
  if(l2){ spr.setTextColor(C_EB_GREY); spr.drawString(l2, 120 - spr.textWidth(l2)/2, 154); }
  fEndHard();
  uiTrackLabel(action, 120, 204, C_EB_BRASS);
  dispPush();
  clearButtonPending();
  bool d=false; while(!d){ btn1.poll();btn2.poll();btn3.poll();btn4.poll();
    if(btn2.isPressed()) d=true; esp_task_wdt_reset(); delay(20); }
  buzzerOK();
}
static void obWelcome(){
  while(true){
    spr.fillSprite(C_BG);
    int wTotal = ebDrawWordmark(78, 255);   // brand lockup (4 Oct 2026)
    int x0     = (240 - wTotal) / 2;
    // Hairline under the wordmark, inset to its width — a rule the full width
    // of the screen would frame the text; this one underlines it.
    spr.drawFastHLine(x0, 122, wTotal, C_BORDER2);
    // A FACT, not a slogan. "Your keys, your device" is the most recycled line
    // in Bitcoin and says nothing this device does not share with every other
    // one. The radios are genuinely down for the whole of setup, so say that
    // instead — it is checkable, it is the actual behaviour, and no competitor's
    // first screen can claim it.
    //
    // Rendered as a STATUS, in the device's own vocabulary: accent dot plus a
    // small caps label, the same pattern uiHeader uses for mode everywhere else.
    // A sentence here would read as marketing; a status reads as instrumentation.
    {
      fSet(F_HEAD_SM); spr.setTextColor(C_EB_BRASS);
      const char* st = "AIR-GAPPED SETUP";
      int tw = spr.textWidth(st);
      int x0 = (240 - (tw + 14)) / 2;
      spr.drawString(st, x0 + 14, 138);
      fEnd();
      spr.fillSmoothCircle(x0 + 4, 143, 3, C_EB_BRASS, C_BG);
    }
    ebMarkSmall(101, 28, 6, 2);   // 29 Oct 2026 (board O1): the ember above the lockup
    uiTrackLabel("PRESS ANY BUTTON", 120, 204, C_EB_BRASS);   // any button does begin
    dispPush();
    while(true){
      btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
      if(btn1.isPressed()||btn2.isPressed()||btn3.isPressed()||btn4.isPressed()) return;
      esp_task_wdt_reset(); delay(10);
    }
  }
}

// ── The four buttons, drawn where they physically are ───────────────────────
// A KEY has no labels on the case. Rather than explain the buttons in prose on
// every screen, show them once, in plan view, with each label sitting at the
// corner its button occupies. Physical map (see BTN*_GPIO): BTN4 top-left =
// scroll up, BTN3 top-right = scroll down, BTN2 bottom-left = back, BTN1
// bottom-right = enter.
static void obButtons(){
  const int BX = 80, BY = 80, BW = 80, BH = 80;   // device body — SQUARE, centred
  while(true){
    spr.fillSprite(C_BG);
    uiAsk("Four buttons", "One at each corner");   // 29 Oct 2026: page language

    // The device, in plan view: body, screen, and a dot at each corner where a
    // button actually is.
    spr.drawRoundRect(BX, BY, BW, BH, 10, C_BORDER2);
    spr.fillRoundRect(BX + 12, BY + 12, BW - 24, BH - 24, 4, C_PANEL);
    const int dx1 = BX + 6,  dx2 = BX + BW - 6;
    const int dy1 = BY + 6,  dy2 = BY + BH - 6;
    spr.fillSmoothCircle(dx1, dy1, 3, C_EB_BRASS, C_BG);
    spr.fillSmoothCircle(dx2, dy1, 3, C_EB_BRASS, C_BG);
    spr.fillSmoothCircle(dx1, dy2, 3, C_EB_BRASS, C_BG);
    spr.fillSmoothCircle(dx2, dy2, 3, C_EB_BRASS, C_BG);

    // Leaders from each dot out to its label, so the mapping is unambiguous.
    spr.drawFastHLine(40, dy1, dx1 - 43, C_BORDER2);
    spr.drawFastHLine(dx2 + 3, dy1, 200 - dx2 - 3, C_BORDER2);
    spr.drawFastHLine(40, dy2, dx1 - 43, C_BORDER2);
    spr.drawFastHLine(dx2 + 3, dy2, 200 - dx2 - 3, C_BORDER2);

    fSet(F_HEAD_SM);
    spr.setTextColor(C_EB_BRASS);
    spr.drawString("SCROLL", 10, dy1 - 18);
    { const char* r = "SCROLL"; int w = spr.textWidth(r); spr.drawString(r, 230 - w, dy1 - 18); }
    spr.setTextColor(C_EB_GREY);
    spr.drawString("BACK", 10, dy2 + 6);
    { const char* r = "ENTER"; int w = spr.textWidth(r); spr.drawString(r, 230 - w, dy2 + 6); }
    fEnd();

    fSet(F_BODY); spr.setTextColor(C_TEXT2);
    fDrawCentre("Enter accepts. Back undoes.", 120, 190); fEnd();
    uiTrackLabel("ENTER TO CONTINUE", 120, 208, C_EB_BRASS);
    dispPush();
    while(true){
      btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
      if(btn2.isPressed()) return;      // engine btn2 = physical ENTER
      esp_task_wdt_reset(); delay(10);
    }
  }
}

void runOnboarding(){
  obWelcome();
  obButtons();
  while(true){
    // Same card language as every other choice in the flow. uiPillSelect is
    // still used elsewhere in the product; this screen no longer needs it.
    int choice = 0;
    { bool done=false;
      while(!done){
        // 29 Oct 2026 (board N1): label, one question, two cards.
        spr.fillSprite(C_BG);
        uiTrackLabel("SET UP", 120, 14, C_EB_GREY);
        fEndHard(); spr.loadFont(FONT_Archivo_Bold_28_full); spr.setTextColor(C_EB_INK);
        spr.drawString("New or restore?", 120 - spr.textWidth("New or restore?")/2, 38);
        fEndHard();
        ppCard32(88, 64, "NEW WALLET", "Fresh recovery words",   choice==0, C_EB_BRASS, ppIconNewWallet32);
        ppCard32(160,64, "RESTORE",    "Words, QR or nsec", choice==1, C_EB_BRASS, ppIconRestore32);
        dispPush();
        while(true){
          btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
          if(btn1.isPressed()||btn3.isPressed()){ choice = choice ? 0 : 1; break; }
          if(btn2.isPressed()){ done=true; break; }
          esp_task_wdt_reset(); delay(10);
        }
        delay(200);
      }
    }

    if(choice==0){
      // Create new wallet → fresh BIP-39 seed. Routes through ST_PIN_ENTRY with
      // pinModeNew=true (the new-key generation runs after the PIN is set).
      // ── Two-PIN explainer ───────────────────────────────────────────────
      // The spend explainer used to appear AFTER the daily PIN was already
      // set, so the first code was chosen by someone who did not yet know a
      // second one existed. State the model once, here, before either.
      {
        bool tp=false;
        while(!tp){
          // 29 Oct 2026 (board O2): an explainer, so no cards (two cards
          // read as a choice). Label, two named PINs with what each opens.
          spr.fillSprite(C_BG);
#ifdef FAVILLA_PASSKEY_DOOR
          // 30 Oct 2026: three PINs. Same label + headline pair per PIN, the
          // descriptions dropped so three fit above the footer (rows 54 px).
          uiTrackLabel("THREE PINS", 120, 14, C_EB_GREY);
          const char* nm[3] = {"NOSTR PIN", "BTC PIN", "VAULT PIN"};
          const char* hd[3] = {"Opens Nostr", "Moves Bitcoin", "Signs you in"};
          for(int i = 0; i < 3; i++){
            int y = 40 + i * 54;
            uiTrackLabel(nm[i], 120, y, C_EB_BRASS);
            fEndHard(); spr.loadFont(FONT_Archivo_Bold_28_full); spr.setTextColor(C_EB_INK);
            spr.drawString(hd[i], 120 - spr.textWidth(hd[i])/2, y + 16); fEndHard();
          }
#else
          uiTrackLabel("TWO PINS", 120, 14, C_EB_GREY);
          const char* nm[2] = {"NOSTR PIN", "BTC PIN"};
          const char* hd[2] = {"Opens Nostr", "Moves Bitcoin"};
          const char* ds[2] = {"Every day. Notes and messages.", "Only for sending. Kept different."};
          for(int i = 0; i < 2; i++){
            int y = 44 + i * 74;
            uiTrackLabel(nm[i], 120, y, C_EB_BRASS);
            fEndHard(); spr.loadFont(FONT_Archivo_Bold_28_full); spr.setTextColor(C_EB_INK);
            spr.drawString(hd[i], 120 - spr.textWidth(hd[i])/2, y + 16);
            fEndHard(); spr.loadFont(FONT_Archivo_Regular_13); spr.setTextColor(C_EB_GREY);
            spr.drawString(ds[i], 120 - spr.textWidth(ds[i])/2, y + 50); fEndHard();
          }
#endif
          uiTrackLabel("ENTER TO SET THEM", 120, 204, C_EB_BRASS);

          dispPush();
          while(true){ btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
            if(btn2.isPressed()){ tp=true; break; }
            esp_task_wdt_reset(); delay(10); }
          delay(200);
        }
      }
      memset(pinBuf,0,sizeof(pinBuf)); pinDigit=0; pinConfirm=false;
      pinModeNew=true; restoringKey=false; prefer24Words=true;
      // Two-door: begin the 4-phase PIN capture (daily set/confirm, spend
      // set/confirm). Clear captured-PIN buffers so a re-entered onboarding
      // never inherits stale digits.
      pinPhase=PINPHASE_DAILY_SET; spendExplainerShown=false;
      memset(dailyPinBuf,0,sizeof(dailyPinBuf)); memset(spendPinBuf,0,sizeof(spendPinBuf)); memset(passkeyPinBuf,0,sizeof(passkeyPinBuf));
      clearButtonPending();
      nextState=ST_PIN_ENTRY;
      return;
    }

    // Restore wallet → pick word count, run the restore flow, then set the PIN
    // (mirrors the Key-menu restore path exactly).
    // Same card language as the create path. This screen is the ONLY thing a
    // restoring owner sees before typing 24 words, so it should not be the one
    // screen in the flow that looks like the old product.
    //
    // Unlike the create path, 24 is NOT preselected here: the user already HAS
    // a phrase and is telling us its length, not choosing a strength. Starting
    // on 12 would be equally arbitrary, so the order matches the create screen
    // (24 on top) but the highlight is simply where the cursor starts, and
    // getting it wrong costs a press, not a weaker key.
    // 29 Oct 2026 (board N2): one list - 24 WORDS, 12 WORDS, SEED QR, NSEC -
    // instead of "how many words" then "how do you have your key". Three
    // cards show at a time; NSEC is one press below. Cursor starts on 24.
    int rwc = 24;
    { int rsel = 0; bool rdone = false, rback = false;
      static const char* rN[4] = {"24 WORDS", "12 WORDS", "SEED QR", "NSEC"};
      static const char* rD[4] = {"Type them in", "Type them in", "Scan a backup QR", "Nostr key only"};
      while(!rdone && !rback){
        spr.fillSprite(C_BG);
        uiTrackLabel("RESTORE", 120, 14, C_EB_GREY);
        int top = (rsel == 3) ? 1 : 0;   // scroll the window by one for NSEC
        for(int k = 0; k < 3; k++){
          int i = top + k;
          void (*ic)(int,int,uint16_t,uint16_t) = (i < 2) ? ppIconWords : (i == 2 ? ppIconQr : ppIconKey);
          ppCard(40 + k * 60, 54, rN[i], rD[i], rsel == i, C_EB_BRASS, ic);
        }
        if(top == 0){ fSet(F_SMALL); spr.setTextColor(C_EB_GREY); fDrawCentre("1 more below: NSEC", 120, 222); }
        dispPush();
        while(true){
          btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
          if(btn1.isPressed()){ rsel = (rsel + 1) % 4; break; }
          if(btn3.isPressed()){ rsel = (rsel + 3) % 4; break; }
          if(btn2.isPressed()){ rdone = true; break; }
          if(btn4.isPressed()){ rback = true; break; }   // BACK → top-level choice
          esp_task_wdt_reset(); delay(10);
        }
        delay(200);
      }
      if(rback) continue;
      rwc = (rsel == 1) ? 12 : 24;
      g_restoreMethodPreset = (rsel <= 1) ? 0 : (rsel == 2 ? 1 : 2);
    }
    uint8_t rpriv[32]={0},rpub[32]={0};
    if(runRestoreFlow(rwc,rpriv,rpub)){
      memcpy(pendingRestoreKey,rpriv,32);
      memcpy(wallet.pub,rpub,32);
      memset(wallet.priv,0,32);
      wallet.exists=false; wallet.unlocked=false; UV_FORGET();
      memset(pinBuf,0,sizeof(pinBuf)); pinDigit=0; pinConfirm=false; pinModeNew=true; restoringKey=true;
      pinPhase=PINPHASE_DAILY_SET; spendExplainerShown=false;
      memset(dailyPinBuf,0,sizeof(dailyPinBuf)); memset(spendPinBuf,0,sizeof(spendPinBuf)); memset(passkeyPinBuf,0,sizeof(passkeyPinBuf));
      clearButtonPending();
      nextState=ST_PIN_ENTRY;
      return;
    }
    // Restore cancelled or failed (runRestoreFlow paints its own errors) →
    // loop back to the onboarding choice so the user can try again.
  }
}

// ── V21_2: SYNCHRONOUS scan (main-loop, no task) ───────────────────────────
// Root-cause history: driving the camera from a pinned task (core 1) produced a
// persistent "cam_hal: FB-SIZE: 0" wall — fb_get never completed a frame from
// that context, then the heap corrupted. The warmup grab from the MAIN context
// always returns a full frame first try, so the camera + fb_get path is healthy
// from the main loop. This function runs the exact same grab+quirc decode as
// qrScanTask, synchronously, on the main loop's (large, proven) stack. One
// camera owner, one context, deterministic — the solid path for airgap signing.
// Returns true if a QR payload was decoded into qrResultBuf (qrFound also set).
// qrScanTask is retained below but unused (reversible).
//
// V21_2: persistent quirc instance, reused across frames within a scan session.
// Created lazily in qrScanOnce(), freed by quircScanFree() from cameraStop().
static struct quirc* g_scanQuirc=NULL;
static int g_scanQuircW=0, g_scanQuircH=0;
// (g_airgapLivePreview / g_airgapUrGot / g_airgapUrTotal moved up beside
//  qrTaskRunning — see "Camera preview" section — so runRestoreFlow can use them.)
static void quircScanFree(){
  // V22.3 FIX (contiguous-RAM erosion across scan restarts -> camera starved ->
  // id=0 flood): do NOT destroy the persistent scan quirc here anymore. Creating
  // and destroying its ~128KB PSRAM working buffer on every scan session was
  // fragmenting PSRAM (free returned the block to a non-contiguous gap, so the
  // largest contiguous block shrank each cycle) and the camera driver's matching
  // alloc/free churn eroded contiguous INTERNAL RAM the same way (86KB->61KB->...
  // observed), dropping below the OV2640 DMA floor (~40KB) so the sensor produced
  // torn/garbage frames and quirc could no longer even locate the finder patterns.
  // Fix: allocate g_scanQuirc EXACTLY ONCE (lazily in qrScanOnce) and keep it for
  // the life of the process. 128KB held permanently out of 8MB PSRAM is free in
  // practice, and the big block is now allocated once ever -> zero per-scan
  // fragmentation. This is what gets capture back to a clean state (id=1 c=53),
  // which is the prerequisite for the rounded-module read to be testable at all.
  // (Kept as a function, now a no-op, so all existing call sites stay valid.)
}
// V22.3: explicit teardown for the rare cases that truly need the PSRAM back
// (none in the normal scan path). Not called from cameraStop anymore.
static void quircScanDestroy(void) __attribute__((unused));
static void quircScanDestroy(){
  if(g_scanQuirc){
    quirc_destroy(g_scanQuirc); g_scanQuirc=NULL; g_scanQuircW=0; g_scanQuircH=0;
  }
}
#ifdef FAVILLA_DICE_ROLL
#include "dice_roll.h"
#endif
#ifdef FAVILLA_ENTROPY_CAPTURE
#include "entropy_capture.h"
#endif
#ifdef FAVILLA_ENTROPY_RESTART
#include "entropy_restart.h" // needs cameraPowerUp/Down + cameraSuspendHW/ResumeHW
#endif
#ifdef FAVILLA_ENTROPY_OVERLAY
#include "entropy_overlay.h" // needs showQR, camera, se_random
#endif
#ifdef FAVILLA_BENCH_PROBES
#include "rce_sim.h"         // 19 Oct 2026: Settings > Device > RCE sim (bench env only)
#include "ram_test.h"        // 19 Oct 2026: Settings > Device > RAM test (bench env only)
#endif
bool qrScanOnce(){
  // 10q: the scan record. One call = one grab (+ decode + preview).
  // 10y: on the first grab of each scan, measure what the sensor really sends.
  // (10w/10x were wrong: on the S3 the sensor clock is not an LEDC timer, it
  // is the LCD_CAM peripheral's own CAM_CLK, routed to the XCLK pin.)
  if(g_scanRec.on && g_scanRec.calls == 0 && cameraRunning){
    const uint32_t t0 = micros(); int v = gpio_get_level((gpio_num_t)CAM_PIN_VSYNC), edges = 0, pclkToggles = 0, pc = gpio_get_level((gpio_num_t)CAM_PIN_PCLK);
    while(micros() - t0 < 500000){
      const int nv = gpio_get_level((gpio_num_t)CAM_PIN_VSYNC); if(nv && !v) edges++; v = nv;
      const int np = gpio_get_level((gpio_num_t)CAM_PIN_PCLK); if(np != pc) pclkToggles++; pc = np;
    }
    g_scanRec.vsyncPerSec = edges * 2; g_scanRec.pclkSeen = pclkToggles;
    g_scanRec.camClkSel = LCD_CAM.cam_ctrl.cam_clk_sel; g_scanRec.camClkDiv = LCD_CAM.cam_ctrl.cam_clkm_div_num;
  }
  struct ScanCall { uint32_t t0 = micros(); ~ScanCall(){
    if(!g_scanRec.on) return;
    const uint32_t now = millis(), us = micros() - t0;
    g_scanRec.calls++; g_scanRec.callUs += us;
    if(us / 1000 > g_scanRec.maxCallMs) g_scanRec.maxCallMs = us / 1000;
    if(g_scanRec.lastEnd){ const int32_t gap = (int32_t)(now - us / 1000 - g_scanRec.lastEnd); if(gap > (int32_t)g_scanRec.maxGapMs) g_scanRec.maxGapMs = (uint32_t)gap; }
    g_scanRec.lastEnd = now;
    const int mhz = (int)getCpuFrequencyMhz(); if(mhz < g_scanRec.minMhz) g_scanRec.minMhz = mhz; if(mhz > g_scanRec.maxMhz) g_scanRec.maxMhz = mhz;
    const uint32_t fi = heap_caps_get_free_size(MALLOC_CAP_INTERNAL); if(fi < g_scanRec.minInt) g_scanRec.minInt = fi;
  } } _scanCall;
  qrFound=false;
  esp_task_wdt_reset();   // V21_2: scan loop can be long; keep loopTask WDT fed
  // V22.x: CONDITIONAL stale-frame drain. With fb_count=1 + GRAB_LATEST, fb_get
  // can hand back the SAME buffer as last cycle (the frame still showing the
  // PREVIOUS UR part) — so on a static aim the collection wouldn't advance until
  // the user moved the camera. BUT draining EVERY cycle halves the capture rate
  // and made animated collection choppy / drop parts. Compromise: only drain when
  // the LAST cycle found nothing (qrScanLastFound==false) — i.e. we're genuinely
  // stuck on a stale/blank frame and need to force a fresh capture. When parts are
  // actively flowing (last cycle decoded a QR), skip the drain and keep full rate.
  static bool qrScanLastFound=false;
  if(g_camScanZoom && !g_camScanZoomApplied){
    // First scan of this camera session: crop the sensor. QR paths only — the
    // entropy captures never come through qrScanOnce, so the full field the
    // NIST campaign characterised is untouched for them. Drain two frames so
    // the first decode attempt is on a cropped capture, not a mid-switch one.
    camApplyScanZoom(esp_camera_sensor_get());
    g_camScanZoomApplied=true; g_qrMissStreak=0; g_qrAecIdx=0;
    for(int _z=0;_z<2;_z++){ camera_fb_t* zf=esp_camera_fb_get(); if(zf) esp_camera_fb_return(zf); vTaskDelay(pdMS_TO_TICKS(30)); }
  }
  if(!qrScanLastFound){
    camera_fb_t* stale=esp_camera_fb_get();
    if(stale) esp_camera_fb_return(stale);
  }
  // V22.9 (14 Sep 2026) STALE-FRAME FINGERPRINT. The conditional drain above
  // only fires when the LAST cycle decoded nothing — so after a SUCCESSFUL
  // decode the next fb_get could hand back the very same buffer, we decoded the
  // same UR part again (rc=0 duplicate), that still counted as "found", and the
  // drain was skipped again. On an animated QR from Sparrow the collection then
  // advanced only when the user's hand made a decode FAIL. Log signature:
  // "[UR] feed got=1/4" three times in a row, then 2/4 three times...
  // Fix: fingerprint each frame with a sparse hash (every 61st byte, ~1.3K
  // reads at QVGA, microseconds) and if the buffer we just fetched is
  // byte-identical to the one we last decoded, hand it back and fetch again.
  // This drains ONLY when the frame is genuinely stale, so a moving stream
  // keeps full capture rate.
  static uint32_t qrLastFrameHash=0; static bool qrLastFrameHashValid=false;
  auto frameHash=[](const camera_fb_t* f)->uint32_t{
    uint32_t h=2166136261u; for(size_t i=0;i<f->len;i+=61){ h^=f->buf[i]; h*=16777619u; }
    return h ^ (uint32_t)f->len;
  };
  uint32_t _t0=micros(), _tA;
  camera_fb_t* fb=NULL;
  for(int tries=0; tries<8; tries++){
    fb=esp_camera_fb_get();
    if(!fb){ esp_task_wdt_reset(); delay(10); continue; }
    if(fb->format==PIXFORMAT_GRAYSCALE && fb->len==(size_t)fb->width*fb->height){
      if(!QR_SCAN_LEGACY && QR_SCAN_HASH_DRAIN && qrLastFrameHashValid && frameHash(fb)==qrLastFrameHash){
        g_qrHashDrained++;
        // same pixels we already decoded: stale buffer, not a new capture
        esp_camera_fb_return(fb); fb=NULL; esp_task_wdt_reset(); delay(15); continue;
      }
      break; // full, fresh frame
    }
    esp_camera_fb_return(fb); fb=NULL;            // torn/partial — discard, retry
    esp_task_wdt_reset(); delay(10);
  }
  if(g_scanRec.on) g_scanRec.grabUs += micros() - _t0;   // 10t: time spent waiting for the camera
  if(g_scanRec.on){ if(fb){ if(!g_scanRec.frames) g_scanRec.firstFrameMs = millis() - g_scanRec.t0; g_scanRec.frames++; } else g_scanRec.noFrame++; }   // 10q; 10s: time to the first frame
  if(!fb){
    qrDiagTorn=true; qrDiagIdentified=0; qrDiagCells=0; qrDiagOk=false;
    qrScanLastFound=false;   // no frame -> drain next cycle to force a fresh capture
    // BAR FLICKER FIX: all 8 grab attempts were torn, so we never reach the
    // dispAirgapPreviewFrame() call at the end of this function — meaning the
    // header/footer (progress bar) are not redrawn this cycle. With intermittent
    // DVP tearing, good cycles draw the bar and all-torn cycles don't, which read
    // as the bar flashing on/off during capture. Repaint the header+footer here
    // (frame-independent) so the bar is steady regardless of capture success.
    // Pass a NULL fb: dispAirgapPreviewFrame now renders a neutral camera band
    // when the frame isn't drawable, but still paints the strips.
    if(g_airgapLivePreview) dispAirgapPreviewFrame(NULL, g_airgapUrGot, g_airgapUrTotal);
    return false;
  }
  qrDiagTorn=false;
  // V21_2/V22.3: reuse ONE persistent quirc across frames AND across scan
  // sessions. Originally quirc_new()+resize()+destroy() ran EVERY frame (~150KB
  // PSRAM churn every 150ms) — fixed in V21_2 to once-per-session. V22.3 goes
  // further: it is now allocated ONCE for the life of the process and never
  // destroyed (quircScanFree is a no-op), because even once-per-session churn
  // fragmented PSRAM + internal RAM across scan restarts and starved the camera.
  if(!g_scanQuirc){
    g_scanQuirc=quirc_new();
    if(!g_scanQuirc){ esp_camera_fb_return(fb); return false; }
    g_scanQuircW=0; g_scanQuircH=0;
  }
  // 16 Sep 2026 SCAN CROP: quirc analyses the CENTRAL QR_SCAN_CROP x QR_SCAN_CROP
  // window of the frame, not all 320x240. The viewfinder box maps to roughly
  // sensor rows 34..206 / cols 70..250, well inside a centred 224 window, and
  // quirc_end() scales with pixel count (measured 280 ms full-frame from PSRAM).
  // A 224x224 image (50 KB) also lets quirc.c place it in INTERNAL RAM. The
  // live preview still shows the full frame (copied from fb, not from quirc).
  // 16 Sep 2026 bench: 224 crop + internal RAM took quirc_end only 280 -> 215
  // (quirc is CPU-bound, not PSRAM-bound) and CLIPPED the code as naturally
  // held (INVALID_ECC 16 -> 37, false grids at cells=29, nudging needed again).
  // 0 = full frame, as before. Kept for a future session that first maps the
  // viewfinder box to sensor coordinates properly.
  #ifndef QR_SCAN_CROP
  #define QR_SCAN_CROP 0
  #endif
  const int fbW=(int)fb->width, fbH=(int)fb->height;
  const int cw = (QR_SCAN_CROP>0 && QR_SCAN_CROP<fbW) ? QR_SCAN_CROP : fbW;
  const int ch = (QR_SCAN_CROP>0 && QR_SCAN_CROP<fbH) ? QR_SCAN_CROP : fbH;
  const int cox=(fbW-cw)/2, coy=(fbH-ch)/2;
  if(g_scanQuircW!=cw || g_scanQuircH!=ch){
    int iB=heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL);
    int pB=(int)heap_caps_get_largest_free_block(MALLOC_CAP_SPIRAM);
    if(quirc_resize(g_scanQuirc,cw,ch)<0){ esp_camera_fb_return(fb); return false; }
    g_scanQuircW=cw; g_scanQuircH=ch;
    int iA=heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL);
    int pA=(int)heap_caps_get_largest_free_block(MALLOC_CAP_SPIRAM);
    LOG_CAM("[QMEM] quircAlloc(%dx%d crop of %dx%d): internal %d->%d (%d)  psram %d->%d (%d)\n",
      cw,ch,fbW,fbH, iB,iA,iA-iB, pB,pA,pA-pB);
  }
  struct quirc* qr=g_scanQuirc;
  qrLastFrameHash=frameHash(fb); qrLastFrameHashValid=true;   // this frame is now "seen"
  uint8_t* buf=quirc_begin(qr,NULL,NULL);
  // CRASH GUARD: under heap pressure quirc's image buffer can fail to allocate
  // and quirc_begin() returns NULL (observed when the camera leaves internal RAM
  // fragmented down to ~31KB). The memcpy below would then write to address 0 —
  // a double-exception. Skip this frame cleanly instead; the next frame retries
  // once the heap settles.
  if(!buf){
    LOG_CAM("[QMEM] quirc_begin returned NULL — skipping frame (internalLargest=%d)\n",
            (int)heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL));
    // Reset the cached quirc so the NEXT frame rebuilds it from scratch — by then
    // the post-camera-init heap churn may have settled and the alloc can succeed.
    // Without this, g_scanQuirc stays cached in its bad state and every frame
    // returns NULL forever (scan silently never decodes).
    if(g_scanQuirc){ quirc_destroy(g_scanQuirc); g_scanQuirc=NULL; g_scanQuircW=0; g_scanQuircH=0; }
    esp_camera_fb_return(fb);
    return false;
  }
#if QR_HIST_STRETCH
  {
    // crop-aware (16 Sep 2026): quirc's buffer is cw x ch, not the full frame
    const uint8_t* src=fb->buf; int n=cw*ch;
    uint32_t hist[256]={}; for(int y=0;y<ch;y++){ const uint8_t* r=src+(y+coy)*fbW+cox; for(int x=0;x<cw;x++) hist[r[x]]++; }
    int lo_cut=n/50,hi_cut=n/50,lo=0,hi=255,acc=0;
    for(int v=0;v<256;v++){acc+=hist[v];if(acc>=lo_cut){lo=v;break;}} acc=0;
    for(int v=255;v>=0;v--){acc+=hist[v];if(acc>=hi_cut){hi=v;break;}}
    if(hi-lo<20){lo=0;hi=255;}
    (void)n;
    float scale=(hi>lo)?255.0f/(float)(hi-lo):1.0f;
    for(int y=0;y<ch;y++){ const uint8_t* r=src+(y+coy)*fbW+cox; uint8_t* o=buf+y*cw;
      if(lo==0&&hi==255) memcpy(o,r,(size_t)cw);
      else for(int x=0;x<cw;x++){int v=(int)((r[x]-lo)*scale);o[x]=(uint8_t)(v<0?0:v>255?255:v);} }
  }
#else
  if(cw==fbW && ch==fbH) memcpy(buf, fb->buf, (size_t)fbW*fbH);                      // full frame: one copy
  else for(int y=0;y<ch;y++) memcpy(buf + y*cw, fb->buf + (y+coy)*fbW + cox, (size_t)cw);   // central crop
#endif
  // V22.4 GDMA-OVF FIX: the framebuffer is now fully copied into `buf` (quirc's
  // own PSRAM image). Everything below (morphology, quirc_end Otsu+scan) operates
  // ONLY on `buf` — fb's pixels are no longer needed. With fb_count=1, holding fb
  // across that ~tens-of-ms pipeline left the DVP with nowhere to land the next
  // frame -> EV-VSYNC-OVF -> the driver's ISR resets/orphans the GDMA channel
  // (the "gdma_disconnect: no peripheral connected" + zero-reclaim deinit). Return
  // the single DMA buffer NOW so the DVP has it back within ~1ms and can't overrun.
  // Snapshot the dimensions we still need; the live preview is drawn from `buf`
  // (pre-morphology snapshot below) instead of fb so we don't touch fb after this.
  const int qrFrameW = cw;   // quirc works on the crop
  const int qrFrameH = ch;
  // V22.4 DIAG (strip before ship): log the ACTUAL frame geometry the module
  // reports, ONCE. A 3-way split preview means the real width differs from what
  // we sample with — this tells us the true width/height/len. If len != W*H the
  // pixel format isn't 1 byte/px as assumed; if W != 320 the new module runs a
  // different active-array width and CAM_W must follow fb->width (it does) — so
  // a persistent split points at len/stride, not width.
  {
    static bool dimLogged=false;
    if(!dimLogged){
      dimLogged=true;
      LOG_CAM("[CAMDIM] new-module frame: width=%d height=%d len=%u W*H=%d fmt=%d\n",
        (int)fb->width,(int)fb->height,(unsigned)fb->len,
        (int)fb->width*(int)fb->height,(int)fb->format);
    }
  }
  // Snapshot the clean (pre-morphology) frame for the live preview before the
  // morphological close mutates `buf`. Reuses a persistent PSRAM buffer.
  static uint8_t* g_previewBuf=nullptr; static int g_previewCap=0;
  bool previewReady=false;
  static uint8_t previewSkip=0;   // push the live preview every SECOND frame (~24 ms saved per frame)
  if(g_airgapLivePreview && ((previewSkip++)&1)==0){
    int pn=fbW*fbH;   // the preview shows the FULL frame, copied from fb before it is returned
    if(g_previewCap<pn){ if(g_previewBuf) free(g_previewBuf);
                         g_previewBuf=(uint8_t*)ps_malloc(pn);
                         g_previewCap=(g_previewBuf?pn:0); }
    if(g_previewBuf){ memcpy(g_previewBuf, fb->buf, pn); previewReady=true; }
  }
  esp_camera_fb_return(fb); fb=NULL;   // DVP gets its buffer back immediately
  esp_task_wdt_reset();
  _tA=micros(); g_qrT_fetch+=_tA-_t0; _t0=_tA;   // (fetch + copy + stretch counted here; stretch split below if enabled)
#if QR_SQUARE_MODULES
  // Square up ROUNDED FINDER corners before quirc sees them. Per device testing the
  // data modules are square; Blue Wallet rounds the three finder patterns. Rounded
  // finder corners shift quirc's finder-centroid estimate frame-to-frame, so version/
  // grid estimation JITTERS (cells=[37..53]) and even when it locks 53 the whole grid
  // is registered with a sub-module offset -> every sample biased -> id=1 ECC fail.
  // Fix: a morphological CLOSE (dilate-dark=min, then erode-dark=max) with a structuring
  // element big enough to actually FILL the finder corner notches. A 3x3 barely reached
  // them; the finders are the largest black features in the code, so a 5x5 close fills
  // their rounded notches decisively while a 1-module-wide data cell is grown then eroded
  // back to ~itself (size + inter-module gaps preserved). Separable (1D H then 1D V) so a
  // (2R+1)x(2R+1) element costs 2*(2R+1) compares/pixel, not (2R+1)^2.
  // QR_CLOSE_RADIUS: 2 => 5x5 (try first). Bump to 3 => 7x7 if finders still under-filled.
  #ifndef QR_CLOSE_RADIUS
  #define QR_CLOSE_RADIUS 2
  #endif
  // Operates on GRAYSCALE (no pre-threshold — quirc's own Otsu runs in quirc_end).
  {
    const int R=QR_CLOSE_RADIUS;
    int W=qrFrameW, H=qrFrameH, N=W*H;
    static uint8_t* t1=nullptr; static uint8_t* t2=nullptr; static int tCap=0;
    if(tCap<N){ if(t1)free(t1); if(t2)free(t2);
                t1=(uint8_t*)ps_malloc(N); t2=(uint8_t*)ps_malloc(N);
                tCap=((t1&&t2)?N:0); }
    if(t1&&t2){
      // ---- CLOSE = MIN (dilate dark) then MAX (erode dark), each done separably ----
      // MIN pass: horizontal min (buf->t1), then vertical min (t1->t2)
      for(int y=0;y<H;y++){
        const uint8_t* r=&buf[y*W]; uint8_t* o=&t1[y*W];
        for(int x=0;x<W;x++){
          int x0=x-R<0?0:x-R, x1=x+R>=W?W-1:x+R; uint8_t m=255;
          for(int k=x0;k<=x1;k++) if(r[k]<m) m=r[k];
          o[x]=m;
        }
      }
      for(int x=0;x<W;x++){
        for(int y=0;y<H;y++){
          int y0=y-R<0?0:y-R, y1=y+R>=H?H-1:y+R; uint8_t m=255;
          for(int k=y0;k<=y1;k++){ uint8_t v=t1[k*W+x]; if(v<m) m=v; }
          t2[y*W+x]=m;
        }
      }
      // MAX pass: horizontal max (t2->t1), then vertical max (t1->buf) — completes CLOSE
      for(int y=0;y<H;y++){
        const uint8_t* r=&t2[y*W]; uint8_t* o=&t1[y*W];
        for(int x=0;x<W;x++){
          int x0=x-R<0?0:x-R, x1=x+R>=W?W-1:x+R; uint8_t m=0;
          for(int k=x0;k<=x1;k++) if(r[k]>m) m=r[k];
          o[x]=m;
        }
      }
      for(int x=0;x<W;x++){
        for(int y=0;y<H;y++){
          int y0=y-R<0?0:y-R, y1=y+R>=H?H-1:y+R; uint8_t m=0;
          for(int k=y0;k<=y1;k++){ uint8_t v=t1[k*W+x]; if(v>m) m=v; }
          buf[y*W+x]=m;
        }
      }
    }
  }
#endif
  _tA=micros(); g_qrT_close+=_tA-_t0; _t0=_tA;
  qrDumpSnapshot(buf, qrFrameW, qrFrameH);  // V22.x: hold pre-quirc_end pixels
  quirc_end(qr);
  _tA=micros(); g_qrT_quirc+=_tA-_t0; _t0=_tA;
  // V22.4: preview is drawn from the pre-morphology snapshot taken right after
  // the memcpy (g_previewBuf), NOT from fb — fb was already returned above to
  // keep the DVP fed. dispAirgapPreviewFrameRaw draws from a plain buffer+dims.
  if(g_airgapLivePreview && previewReady)
    dispAirgapPreviewFrameRaw(g_previewBuf, fbW, fbH, g_airgapUrGot, g_airgapUrTotal);
  else if(g_airgapLivePreview && !g_previewBuf)   // never had a frame: draw the empty viewfinder once
    dispAirgapPreviewFrameRaw(NULL, 0, 0, g_airgapUrGot, g_airgapUrTotal);
  esp_task_wdt_reset();   // V21_2: quirc_end (full-image threshold+scan) is the heavy step
  _tA=micros(); g_qrT_preview+=_tA-_t0; _t0=_tA;
  int count=quirc_count(qr);
  qrDiagIdentified=count; qrDiagCells=0; qrDiagOk=false;
  // V22.x: record into the deferred accumulator instead of printing live (serial
  // during scan corrupts the camera). Flushed by qrDiagFlush() on scan exit.
  qrDiagFrames++;
  if(count>0) qrDiagIdFrames++;
  // 2 Nov 2026: 12.9 KB moved from internal RAM to PSRAM, taken on the first
  // scan and kept (CPU-only work, no DMA). The decoded payload is wiped after
  // it is copied out, since a scan can carry a SeedQR.
  static struct quirc_code* s_qcode = nullptr; static struct quirc_data* s_qdata = nullptr;
  if(!s_qcode) s_qcode = (struct quirc_code*)psBootCalloc(sizeof(struct quirc_code));
  if(!s_qdata) s_qdata = (struct quirc_data*)psBootCalloc(sizeof(struct quirc_data));
  if(!s_qcode || !s_qdata) count = 0;
  struct quirc_code& code = *s_qcode; struct quirc_data& data = *s_qdata;
  for(int i=0;i<count&&!qrFound;i++){
    quirc_extract(qr,i,&code);
    if(i==0){
      qrDiagCells=code.size;
      if(code.size>0){
        if(code.size<qrDiagCellMin) qrDiagCellMin=code.size;
        if(code.size>qrDiagCellMax) qrDiagCellMax=code.size;
      }
    }
    quirc_decode_error_t derr=quirc_decode(&code,&data);
    if((int)derr>=0 && (int)derr<8) qrDiagErrCounts[(int)derr]++;
    // V22.x DE-RISK: capture a LOCATED-but-FAILED frame for the desktop ZXing test.
    // quirc jitters between error codes (INVALID_ECC / INVALID_GRID / INVALID_VERSION)
    // on the rounded code, so commit on ANY non-success decode of a located code —
    // not just index 4 — to guarantee we grab a frame. qrDumpCommit() keeps only the
    // first, so an early grid-fail frame is fine; the snapshot above is this frame.
    if(derr!=QUIRC_SUCCESS) qrDumpCommit();
    if(derr!=QUIRC_SUCCESS){
      const char* es=quirc_strerror(derr);
      strncpy(qrDiagLastErr, es?es:"?", sizeof(qrDiagLastErr)-1);
      qrDiagLastErr[sizeof(qrDiagLastErr)-1]=0;
    }
    if(derr==QUIRC_SUCCESS){
      qrDiagOk=true; qrDiagCells=code.size;
      size_t len=data.payload_len<QR_RESULT_SZ-1?data.payload_len:QR_RESULT_SZ-1;
      memcpy(qrResultBuf,data.payload,len);qrResultBuf[len]=0;qrFound=true;
    }
  }
  if(s_qdata) memset(s_qdata, 0, sizeof(struct quirc_data));   // 2 Nov 2026: never leave a decoded payload behind
  if(s_qcode) memset(s_qcode, 0, sizeof(struct quirc_code));
  // NOTE: do NOT quirc_destroy(qr) here — g_scanQuirc persists across frames
  // and is freed by quircScanFree() from cameraStop() when the scan ends.
  _tA=micros(); g_qrT_decode+=_tA-_t0; g_qrT_n++;
  qrScanLastFound = qrFound;   // drive next cycle's conditional drain
  // V22.9: exposure dither on miss streaks + jittered gap for the next scan.
  if(qrFound){ g_qrMissStreak = 0; }
  else if(g_qrExposureDither && ++g_qrMissStreak >= 3){
    g_qrAecIdx = (g_qrAecIdx + 1) & 3;
    sensor_t* sd = esp_camera_sensor_get();
    if(sd && sd->set_aec_value) sd->set_aec_value(sd, g_qrAecTab[g_qrAecIdx]);
  }
  // 16 Sep 2026: gap cut from 60..150 to 20..40 ms. Measured: the loop was
  // ~550 ms/frame and the gap was a fifth of it; button polling is fine at 20.
  qrScanGapCur = QR_SCAN_LEGACY ? 90 : (QR_SCAN_JITTER ? 20 + (int)(esp_random() % 21) : 30);
  return qrFound;
}

// ── DEPRECATED (V22.x): no callers left. The restore-flow seed/nsec loops were
// the last users of this background-task scanner and have been migrated to the
// synchronous qrScanOnce() pattern. Do NOT re-adopt this path: with the resident
// camera (fb_count=1 + GRAB_LATEST) the cross-core fb_get race starves the
// main-loop preview (FB-SIZE:0 wall) and corrupts the heap when internal RAM is
// tight — see the ST_SCANNING comment. Kept temporarily for reference; safe to
// delete along with qrScanTask and dispPreview in the pre-ship strip pass.
void triggerQRScan(){
  if(qrTaskRunning) return;
  qrTaskRunning=true;
  // V21_2 FIX: stack was 32768. After camera init the largest CONTIGUOUS
  // internal block falls to ~26KB (camera fb is in internal RAM), so a 32KB
  // task stack can't be allocated -> xTaskCreate returns -1 forever. quirc's
  // image buffers live on the heap (quirc_new/quirc_resize), NOT this stack,
  // so 8KB is ample for the task's call frames + locals. Log the contiguous
  // block at create-time so a future starve is obvious in one line.
  Serial.printf("[AIRDIAG] qrscan create: largestInternal=%u\n",
    (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL));
  BaseType_t r=xTaskCreatePinnedToCore(qrScanTask,"qrscan",8192,NULL,1,NULL,1);
  Serial.printf("[AIRDIAG] xTaskCreatePinnedToCore -> %d (pdPASS=%d)\n",(int)r,(int)pdPASS);
  if(r!=pdPASS){ qrTaskRunning=false; Serial.printf("[AIRDIAG] task create FAILED — qrTaskRunning reset\n"); }
}

// ── HTTP API ───────────────────────────────────────────────────────────────
// iosSignEvent (EVENT_JSON_SZ, PSRAM, ps_malloc at boot) is declared next to iosPreEventId above: signNostrEvent needs it (11an)
static char* iosSignResult = nullptr;  // EVENT_JSON_SZ — PSRAM, ps_malloc at boot
WebServer camServer(80);
// ── 9k (7 Nov 2026, issue #7): the HTTP API without Wi-Fi ───────────────────
// Every /api handler reaches the request and the reply through httpIo, which
// is camServer itself, except while a request tunnelled over the Bluetooth app
// channel runs (apiTunnelRun, NOSTR Bluetooth life): then the method, path,
// query, the three X-Favilla headers and the body come from that request, and
// the status, type and body are kept for the answer. Headers the handlers add
// (CORS, caching) mean nothing over Bluetooth and are dropped. The routes are
// the ones apiServerBegin_register gives camServer (apiOn keeps a copy).
struct ApiRoute { String path; HTTPMethod m; std::function<void(void)> fn; };
static std::vector<ApiRoute> g_apiRoutes;
static std::function<void(void)> g_apiNotFound;
struct HttpIo {
  bool tun = false;
  HTTPMethod tm = HTTP_GET; String tpath, tquery, tbody, tSess, tAuth, tCtr;
  // 9l (issue #8): the paired app client the call came from (its MAC verified on the app channel)
  bool tAppSet = false; uint8_t tApp[8] = {0};
  int rcode = 0; String rtype, rbody; bool rsent = false;
  String queryArg(const String& n) const {
    int i = 0; const int L = tquery.length();
    while(i < L){ int a = tquery.indexOf('&', i); if(a < 0) a = L; int e = tquery.indexOf('=', i); if(e < 0 || e > a) e = a;
      if(tquery.substring(i, e) == n) return urlDecodeQ(tquery.substring(e < a ? e + 1 : a, a)); i = a + 1; }
    return String();
  }
  static String urlDecodeQ(const String& v){ String o; o.reserve(v.length()); for(unsigned i = 0; i < v.length(); i++){ char c = v[i];
      if(c == '+') c = ' '; else if(c == '%' && i + 2 < v.length()){ char h[3] = { v[i+1], v[i+2], 0 }; c = (char)strtol(h, nullptr, 16); i += 2; } o += c; } return o; }
  String arg(const String& n){ if(!tun) return camServer.arg(n); return n == "plain" ? tbody : queryArg(n); }
  bool hasArg(const String& n){ if(!tun) return camServer.hasArg(n); return n == "plain" ? tbody.length() > 0 : tquery.indexOf(n + "=") >= 0 || tquery == n; }
  String header(const String& n){ if(!tun) return camServer.header(n);
    if(n.equalsIgnoreCase("X-Favilla-Session")) return tSess; if(n.equalsIgnoreCase("X-Favilla-Auth")) return tAuth; if(n.equalsIgnoreCase("X-Favilla-Ctr")) return tCtr; return String(); }
  bool hasHeader(const String& n){ if(!tun) return camServer.hasHeader(n); return header(n).length() > 0; }
  HTTPMethod method(){ return tun ? tm : camServer.method(); }
  String uri(){ return tun ? tpath : camServer.uri(); }
  // 11bv (issue #47 item 3): the query in canonical form for the sealed AAD:
  // "k=v&k=v", decoded, in the order sent ("" when none). The PWA builds the
  // same from URLSearchParams (FSEC._aad), so a changed ?id= breaks the MAC.
  String canonQuery(){
    String o;
    if(tun){
      int i = 0; const int L = tquery.length();
      while(i < L){ int a = tquery.indexOf('&', i); if(a < 0) a = L; int e = tquery.indexOf('=', i); if(e < 0 || e > a) e = a;
        if(a > i){ if(o.length()) o += '&'; o += urlDecodeQ(tquery.substring(i, e)); o += '='; if(e < a) o += urlDecodeQ(tquery.substring(e + 1, a)); }
        i = a + 1; }
      return o;
    }
    for(int k = 0; k < camServer.args(); k++){ const String n = camServer.argName(k); if(n == "plain") continue;
      if(o.length()) o += '&'; o += n; o += '='; o += camServer.arg(k); }
    return o;
  }
  void sendHeader(const String& n, const String& v, bool first = false){ if(!tun) camServer.sendHeader(n, v, first); }
  void setContentLength(size_t n){ if(!tun) camServer.setContentLength(n); }
  void keep(int c, const char* t, const char* b, size_t n){ if(rsent) return; rcode = c; rtype = t ? t : ""; rbody = String(); if(b && n) rbody.concat(b, n); rsent = true; }
  void send(int c){ if(!tun){ camServer.send(c); return; } keep(c, nullptr, nullptr, 0); }
  void send(int c, const char* t, const String& b){ if(!tun){ camServer.send(c, t, b); return; } keep(c, t, b.c_str(), b.length()); }
  void send(int c, const String& t, const String& b){ if(!tun){ camServer.send(c, t, b); return; } keep(c, t.c_str(), b.c_str(), b.length()); }
  void send(int c, const char* t, const char* b){ if(!tun){ camServer.send(c, t, b); return; } keep(c, t, b, b ? strlen(b) : 0); }
  void send_P(int c, PGM_P t, PGM_P b){ if(!tun){ camServer.send_P(c, t, b); return; } keep(c, t, b, b ? strlen(b) : 0); }
};
static HttpIo httpIo;
static void apiOn(const char* path, HTTPMethod m, std::function<void(void)> fn){ g_apiRoutes.push_back({ String(path), m, fn }); camServer.on(path, m, fn); }
static void apiOnAny(const char* path, std::function<void(void)> fn){ g_apiRoutes.push_back({ String(path), HTTP_ANY, fn }); camServer.on(path, fn); }
static void apiOnNotFound(std::function<void(void)> fn){ g_apiNotFound = fn; camServer.onNotFound(fn); }


// Origin check — request must be from the device itself, a private network
// (RFC1918), or have no Origin header at all (some clients omit it). This
// prevents random websites that the user visits from being able to invoke
// the API even if they somehow learn the session key. Returns true if the
// origin is acceptable.
//
// Allowed:
//   - No Origin header (curl, native apps, same-origin GETs)
//   - 192.168.x.x, 10.x.x.x, 172.16-31.x.x (RFC1918 private networks)
//   - 169.254.x.x (link-local, used during AP setup)
//   - localhost / 127.0.0.1
//   - .local (mDNS)
// Blocked:
//   - Public-internet origins like https://example.com
//   - Anything else
bool apiCheckOrigin(){
  String origin = httpIo.header("Origin");
  if(origin.length() == 0) return true;  // no Origin = not from a browser, allow

  // Strip scheme
  int schemeEnd = origin.indexOf("://");
  if(schemeEnd < 0) return false;  // malformed Origin
  String host = origin.substring(schemeEnd + 3);
  // Strip port if present
  int colonIdx = host.indexOf(':');
  if(colonIdx >= 0) host = host.substring(0, colonIdx);

  // Allowed host patterns
  if(host == "localhost") return true;
  if(host.endsWith(".local")) return true;
  // 11bl (issue #47 item 4): a private address only as a dotted IPv4 literal.
  // The prefix test passed names like 10.attacker.com and 192.168.attacker.com,
  // which could then read /api/info from a page on the open internet.
  int o[4]; int n = 0; const char* p = host.c_str();
  while(n < 4){
    if(*p < '0' || *p > '9') return false;
    int v = 0, d = 0;
    while(*p >= '0' && *p <= '9' && d < 4){ v = v * 10 + (*p - '0'); p++; d++; }
    if(d > 3 || v > 255) return false;
    o[n++] = v;
    if(n < 4){ if(*p != '.') return false; p++; }
  }
  if(*p) return false;
  if(o[0] == 127) return true;
  if(o[0] == 10) return true;
  if(o[0] == 192 && o[1] == 168) return true;
  if(o[0] == 169 && o[1] == 254) return true;
  if(o[0] == 172 && o[1] >= 16 && o[1] <= 31) return true;   // 172.16.0.0 - 172.31.255.255
  return false;
}

void apiAddCORS(){
  httpReqMark(httpIo.uri().c_str());   // [HTTP] request timing marker
  { String ip = httpIo.tun ? String("bluetooth") : camServer.client().remoteIP().toString(); strncpy(g_httpLastIp, ip.c_str(), sizeof(g_httpLastIp)-1); g_httpLastIp[sizeof(g_httpLastIp)-1]=0; }

  // Echo the Origin header back when present and allowed, instead of "*".
  // "*" disables CORS protections like cookie/credential propagation
  // and means we can't use Allow-Credentials. Echoing the specific origin
  // preserves the browser's same-origin sanity checks while permitting
  // the legitimate cross-origin calls (PWA on different IP, captive
  // portal flow). If origin check fails, we don't add the header at all
  // and the browser blocks the response.
  String origin = httpIo.header("Origin");
  if(origin.length() > 0 && apiCheckOrigin()){
    httpIo.sendHeader("Access-Control-Allow-Origin", origin);
    httpIo.sendHeader("Vary", "Origin");
  } else if(origin.length() == 0){
    // No Origin = not a CORS request, no header needed
  }
  // If origin is set but not allowed, omit Allow-Origin entirely — the
  // browser will block the response, which is what we want.
  httpIo.sendHeader("Access-Control-Allow-Methods","GET,POST,OPTIONS");
  httpIo.sendHeader("Access-Control-Allow-Headers","Content-Type,Authorization,X-Favilla-Session,X-Favilla-Auth,X-Favilla-Ctr");
  httpIo.sendHeader("Access-Control-Allow-Private-Network","true");
}

