// User presence: one press of ENTER approves, BACK refuses.
// Step 3a (30 Oct 2026): an OVERLAY, not a blocking loop. The step 2 version
// held loop() until the press (a 3 s [STALL] was logged); now loop() keeps
// running underneath with the state machine, footers and Emberwill held off
// (fidoPromptActive), and this tick draws the prompt once per request and
// checks ENTER / BACK on every pass.
static bool     g_fidoShown = false;
static uint32_t g_fidoShownSeq = 0;
static unsigned long g_fidoShownAt = 0;
// Kind 3 (2 Nov 2026): the account picker for a sign-in with no username. The
// prompt's own chrome and type scale (tracked brass PASSKEY label, the site in
// the 13 px body face, the two tracked footer labels) around the house list
// cards (uiListCard: 14 px name, 12 px second line), three visible.
static int g_pickSel = 0;
// Cut s (a buffer of cap bytes) to fit maxW px in the current font, with "..."
// when cut. Measures whole UTF-8 characters, never writes past cap (review
// 2 Nov 2026: the old version could write two bytes past a 48-byte buffer).
static void pkFitText(char* s, size_t cap, int maxW, bool tracked){
  auto w = [&](const char* t){ int x = 0; for(const char* q = t; *q; ){ size_t l = 1; while(q[l] && (((uint8_t)q[l]) & 0xC0) == 0x80 && l < 4) l++; char c[5] = {0}; memcpy(c, q, l); x += spr.textWidth(c) + (tracked ? 1 : 0); q += l; } return x; };
  if(cap < 4 || cap > 100 || w(s) <= maxW) return;
  size_t n = strlen(s); if(n > cap - 4) n = cap - 4;   // room for "..." and the NUL
  while(n > 0 && (((uint8_t)s[n]) & 0xC0) == 0x80) n--;
  for(;;){
    char t[104]; memcpy(t, s, n); memcpy(t + n, "...", 4);   // n <= cap - 4 <= 96
    if(n == 0 || w(t) <= maxW){ memcpy(s, t, n + 4); return; }
    n--; while(n > 0 && (((uint8_t)s[n]) & 0xC0) == 0x80) n--;
  }
}

static void fidoDrawPicker(){
  const int n = fido::g_pick.n, VIS = 3, CH = 42, PITCH = 46, Y0 = 52;
  if(g_pickSel >= n) g_pickSel = n - 1;
  if(g_pickSel < 0) g_pickSel = 0;
  int off = 0; if(n > VIS){ off = g_pickSel - 1; if(off < 0) off = 0; if(off > n - VIS) off = n - VIS; }
  fEnd(); spr.fillSprite(C_BG);
  uiTrackLabel("VAULT", 120, 14, C_EB_BRASS);
  fEndHard(); spr.loadFont(FONT_Archivo_Regular_13); spr.setTextColor(C_EB_GREY);
  { char t[96]; snprintf(t, sizeof t, "Sign in to %s", fido::g_up.rp); pkFitText(t, sizeof t, 216, false); spr.drawString(t, 120 - spr.textWidth(t) / 2, 32); }
  fEndHard();
  for(int r = 0; r < VIS && off + r < n; r++){
    int i = off + r, y = Y0 + r * PITCH;
    char nm[48], sb[48];
    strncpy(nm, fido::g_pick.name[i], sizeof nm); nm[sizeof nm - 1] = 0;
    strncpy(sb, fido::g_pick.sub[i], sizeof sb);  sb[sizeof sb - 1] = 0;
    fSet(F_BRAND_B14); pkFitText(nm, sizeof nm, 216 - 24 - 14, true); fEnd();
    fSet(F_BODY);      pkFitText(sb, sizeof sb, 216 - 24 - 14, false); fEnd();
    uiListCard(12, y, 216, CH, i == g_pickSel, C_EB_BRASS, nm, sb[0] ? sb : nullptr, 24);
  }
  if(n > VIS){
    const int TX = 237, TY = Y0 + 2, TH = VIS * PITCH - 8;
    int thumb = TH * VIS / n; if(thumb < 8) thumb = 8;
    int ty = TY + (TH - thumb) * off / (n - VIS);
    spr.drawFastVLine(TX, TY, TH, C_EB_LINE); spr.fillRect(TX - 1, ty, 3, thumb, C_EB_BRASS);
  }
  uiCornerAnswers("DECLINE", "SIGN IN");   // 11cw
  dispPush();
}
// Settings > Device > Passkeys (2 Nov 2026, ruling P4). One record per screen,
// opened only when shown: each open costs one of the G0's 32 per power-on life
// and stays cached until the KEY locks, so paging back and forth is free.
// SCROLL moves, a held ENTER (2 s, a brass bar fills) deletes, BACK leaves.
// Deleting the record does not remove the passkey from the site: the screen
// says so. Same chrome as the passkey prompt.
static void pkPageMsg(const char* label, const char* l1, const char* l2){
  wp::stop();   // 11cg: a moving wait page ends here too
  fEnd(); spr.fillSprite(C_BG);
  uiTrackLabel(label, 120, 14, C_EB_BRASS);
  fEndHard(); spr.loadFont(FONT_Archivo_Regular_13); spr.setTextColor(C_EB_INK);
  int y = uiWrapCentre(l1, 92, 210, 18, 3);
  if(l2){ spr.setTextColor(C_EB_GREY); uiWrapCentre(l2, y + 8, 210, 18, 3); }
  fEndHard();
  uiTrackLabel("BACK TO LEAVE", 120, 216, C_EB_GREY);
  dispPush();
}
static void runPasskeysPage(){
  auto waitBack = [](){ clearButtonPending(); for(;;){ btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll(); tickStatusBarInMenu(false); if(subMenuShouldYieldForApi()) return; if(btn4.isPressed() || btn2.isPressed()) return; delay(10); } };
  // 2b: the page works in the PASSKEY life too (each record open runs in a passkey window).
  const bool open = g_passkeyLife ? g_pkPinHeld : wallet.unlocked;
  if(!open || !favilla::rk_ready() || !g0_pk2b_present()){
    pkPageMsg("PASSKEYS", !favilla::rk_ready() ? "No-username passkeys are off on this KEY." : !g0_pk2b_present() ? "The signer chip needs the v13 firmware." : "Unlock the KEY to see them.",
              !favilla::rk_ready() ? "The G0 needs VAULT and the partition table needs nvs_vault." : nullptr);
    waitBack(); return;
  }
  int idx = 0;
  for(;;){
    int n = favilla::rk_count();
    if(n == 0){ pkPageMsg("PASSKEYS", "No no-username passkeys on this KEY.", "A site saves one when you register with a passkey and no username."); waitBack(); return; }
    if(idx >= n) idx = n - 1;
    // Review 2 Nov 2026: in a PASSKEY life the FIDO task takes the bus (window
    // batch) before the record lock; take them in the same order here, or the
    // two tasks deadlock. A no-op in other lives.
    favilla::RkAcct a; int e; { g0_window_batch_begin(); e = favilla::rk_at(idx, &a); g0_window_batch_end(); }
    // Review 2 Nov 2026: a record that can never be opened (sealed under another
    // wallet's words, or altered in flash) can still be deleted, by slot.
    const bool bad = (e == favilla::RK_E_FORMAT) || (e == favilla::RK_E_G0 && favilla::rk_last_res() == 0xE6);
    if(e != 0) { memset(&a, 0, sizeof a); a.slot = favilla::rk_slot_at(idx); a.site[0] = 0; }
    char count[24]; snprintf(count, sizeof count, "%d OF %d", idx + 1, n);
    auto draw = [&](float hold){
      fEnd(); spr.fillSprite(C_BG);
      uiTrackLabel("PASSKEYS", 120, 14, C_EB_BRASS);
      uiTrackLabel(count, 120, 34, C_EB_GREY);
      if(e == 0){
        fEndHard(); spr.loadFont(FONT_Archivo_Bold_28_full); spr.setTextColor(C_EB_INK);
        if(spr.textWidth(a.site) <= 216) spr.drawString(a.site, 120 - spr.textWidth(a.site) / 2, 70);
        else { fEndHard(); spr.loadFont(FONT_Archivo_Regular_13); spr.setTextColor(C_EB_INK); uiWrapCentre(a.site, 74, 210, 18, 2); }
        fEndHard(); spr.loadFont(FONT_Archivo_Regular_13);
        char l[72];
        snprintf(l, sizeof l, "%s", a.name[0] ? a.name : "(no name)"); pkFitText(l, sizeof l, 210, false);
        spr.setTextColor(C_EB_INK); spr.drawString(l, 120 - spr.textWidth(l) / 2, 118);
        if(a.disp[0] && strcmp(a.disp, a.name)){ snprintf(l, sizeof l, "%s", a.disp); pkFitText(l, sizeof l, 210, false); spr.setTextColor(C_EB_GREY); spr.drawString(l, 120 - spr.textWidth(l) / 2, 138); }
        fEndHard();
        uiTrackLabel("HOLD ENTER TO DELETE", 120, 196, C_EB_BRASS);
        if(hold > 0){ int w = (int)(176 * (hold > 1 ? 1 : hold)); spr.fillRect(32, 210, 176, 2, C_EB_LINE); spr.fillRect(32, 210, w, 2, C_EB_BRASS); }
        else uiTrackLabel("BACK TO LEAVE", 120, 216, C_EB_GREY);
      } else {
        fEndHard(); spr.loadFont(FONT_Archivo_Regular_13); spr.setTextColor(C_EB_INK);
        uiWrapCentre(e == favilla::RK_E_BUDGET ? "The vault limit needs your PIN. Lock and unlock the KEY to see more."
                     : bad ? "This record cannot be opened: another wallet sealed it, or it was altered. It only takes a place."
                           : "This record could not be opened.", 82, 210, 18, 4);
        fEndHard();
        if(bad){
          uiTrackLabel("HOLD ENTER TO DELETE", 120, 196, C_EB_BRASS);
          if(hold > 0){ int w = (int)(176 * (hold > 1 ? 1 : hold)); spr.fillRect(32, 210, 176, 2, C_EB_LINE); spr.fillRect(32, 210, w, 2, C_EB_BRASS); }
          else uiTrackLabel("BACK TO LEAVE", 120, 216, C_EB_GREY);
        } else uiTrackLabel("BACK TO LEAVE", 120, 216, C_EB_GREY);
      }
      dispPush();
    };
    draw(0);
    clearButtonPending();
    bool moved = false, deleted = false; float lastHold = 0;
    while(!moved && !deleted){
      btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll();
      tickStatusBarInMenu(false);
      if(subMenuShouldYieldForApi()){ mbedtls_platform_zeroize(&a, sizeof a); return; }
      if(btn4.isPressed()){ mbedtls_platform_zeroize(&a, sizeof a); return; }
      if(n > 1 && btn1.isPressed()){ idx = (idx + 1) % n; moved = true; }
      else if(n > 1 && btn3.isPressed()){ idx = (idx + n - 1) % n; moved = true; }
      else if(e == 0 || (bad && a.slot >= 0)){
        float h = btn2.holdProgress(2000);
        if(h >= 1.0f){
          int slot = a.slot; char site[favilla::RK_SITE_MAX + 1]; strcpy(site, a.site);
          int de; { g0_window_batch_begin(); de = favilla::rk_delete(slot); g0_window_batch_end(); }   // same lock order as rk_at above
          char msg[300]; snprintf(msg, sizeof msg, site[0] ? "Also remove it in your %s account settings: the site still accepts it." : "%sThe record was unreadable, so the site is unknown.", site);
          pkPageMsg("PASSKEYS", de == 0 ? "Deleted from this KEY." : "Could not delete it.", de == 0 ? msg : favilla::rk_err_name(de));
          LOG_BOOT("[RK] Settings: delete slot %d: %s\n", slot, favilla::rk_err_name(de));
          while(btn2.stable == LOW){ btn2.poll(); delay(5); }
          waitBack(); deleted = true;
        } else if((h > 0) != (lastHold > 0) || (h - lastHold) > 0.04f){ lastHold = h; draw(h); }
        btn2.isPressed();   // a tap is not a delete: drop it
      }
      delay(10);
    }
    mbedtls_platform_zeroize(&a, sizeof a);
    if(subMenuShouldYieldForApi()) return;
  }
}
// ── Vault phase 3 (2 Nov 2026): relay backup of the passkey records ───────────
// Vault spec section 4. One kind 30078 event per vault on the vault relay
// (favilla::VB_RELAY, its own name, never in the Nostr relay list), signed by
// k_pub on the G0 (VSIGN_INIT, anti-exfil). Publishing first fetches the
// relay's copy and merges it, so a KEY that missed a change never publishes
// over it. Nothing is opened at any step. The link is webSocket2, brought up
// for the one exchange and dropped (the CIPHER share pattern), with its own
// event handler.
enum { VBR_OK = 0, VBR_NOKEYS, VBR_NOVPUB, VBR_NOG0, VBR_LOCKED, VBR_NOWIFI, VBR_NOCLOCK, VBR_EXPORT, VBR_SIGN,
       VBR_RELAY, VBR_REFUSED, VBR_NOTFOUND, VBR_BADEVENT, VBR_OTHERVAULT, VBR_PASS, VBR_MERGE, VBR_MEM, VBR_BUSY, VBR_PARTIAL, VBR_OLDER, VBR_TOOBIG };   // v19: 19 = older than the last backup this KEY published; 11dr: 20 = too big for one event
static volatile bool g_vbClosing = false;   // 8z3: our own close is not a drop
static volatile bool g_vbConn = false, g_vbOkGot = false, g_vbOkAcc = false, g_vbEose = false;
// Review 2 Nov 2026: CLOSED or a dropped frame means the fetch is incomplete,
// never "no backup" (a publish or a cleared restore flag would follow).
static volatile bool g_vbClosed = false, g_vbDropped = false, g_vbFetching = false;
static char g_vbWantId[65] = {0}; static char g_vbOkMsg[96] = {0};
static char* g_vbEvt = nullptr; static size_t g_vbEvtN = 0; static uint32_t g_vbEvtAt = 0;   // newest event object from the relay (PSRAM)
static void* vbAlloc(size_t n){
#ifdef MALLOC_CAP_SPIRAM
  void* p = heap_caps_malloc(n, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT); if(p) return p;
#endif
  return malloc(n);
}
static void vbEvtFree(){ if(g_vbEvt){ free(g_vbEvt); g_vbEvt = nullptr; } g_vbEvtN = 0; g_vbEvtAt = 0; }
static void wsEventVault(WStype_t type, uint8_t* payload, size_t length){
  switch(type){
    case WStype_CONNECTED: g_vbConn = true; break;
    case WStype_DISCONNECTED:
      if(!g_vbConn) LOG_BOOT("[VAULT] link: connect attempt failed, TLS %d (%s), wifi %d rssi %d, internal free %u largest %u, psram largest %u\n",
                             webSocket2.lastConnectErr, webSocket2.lastConnectErrText[0] ? webSocket2.lastConnectErrText : "no TLS error: DNS or TCP",
                             (int)WiFi.status(), (int)WiFi.RSSI(),
                             (unsigned)heap_caps_get_free_size(MALLOC_CAP_INTERNAL), (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT),
                             (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_SPIRAM));
      else if(!g_vbClosing) LOG_BOOT("[VAULT] link dropped while open (relay or TLS closed it), wifi %d rssi %d, internal free %u largest %u\n",   // 8z3
                    (int)WiFi.status(), (int)WiFi.RSSI(), (unsigned)heap_caps_get_free_size(MALLOC_CAP_INTERNAL), (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT));
      g_vbConn = false; break;
    case WStype_ERROR: LOG_BOOT("[VAULT] link error: %.*s\n", (int)(length > 80 ? 80 : length), payload ? (const char*)payload : ""); break;
    case WStype_TEXT: {
      const char* m = (const char*)payload;
      if(length > 8 && !strncmp(m, "[\"OK\",\"", 7)){
        if(length >= 7 + 64 && !strncmp(m + 7, g_vbWantId, 64)){
          // 23 Nov 2026 (#62 item 2): bounded by the frame. A 71-byte frame put r
          // on the NUL and strchr(r + 6) started past the end of the buffer.
          const char* r = m + 7 + 64; size_t avail = length - (7 + 64);
          g_vbOkAcc = avail >= 6 && !strncmp(r, "\",true", 6);
          const char* q = avail > 6 ? (const char*)memchr(r + 6, '"', avail - 6) : nullptr; g_vbOkMsg[0] = 0;
          if(q){ size_t i = 0; q++; while(q < m + length && *q != '"' && i < sizeof(g_vbOkMsg) - 1) g_vbOkMsg[i++] = *q++; g_vbOkMsg[i] = 0; }
          g_vbOkGot = true;
        }
      } else if(length > 10 && !strncmp(m, "[\"EVENT\",", 9)){
        const char* a = (const char*)memchr(m, '{', length); const char* z = m + length;
        while(z > a && *(z - 1) != '}') z--;
        if(!g_vbFetching) break;   // review: nothing kept outside a fetch
        if(!a || z <= a){ g_vbDropped = true; break; }
        if(a && z > a){
          size_t n = (size_t)(z - a);
          const char* ca = strstr(a, "\"created_at\":"); uint32_t at = ca ? (uint32_t)strtoul(ca + 13, nullptr, 10) : 0;
          if(n >= 200000) g_vbDropped = true;
          else if(at >= g_vbEvtAt){
            char* b = (char*)vbAlloc(n + 1);
            if(b){ memcpy(b, a, n); b[n] = 0; vbEvtFree(); g_vbEvt = b; g_vbEvtN = n; g_vbEvtAt = at; }
            else g_vbDropped = true;
          }
        }
      } else if(length > 7 && !strncmp(m, "[\"EOSE\"", 7)){
        g_vbEose = true;
      } else if(length > 9 && !strncmp(m, "[\"CLOSED\"", 9)){
        g_vbClosed = true; LOG_BOOT("[VAULT] relay closed the request: %.*s\n", (int)(length > 120 ? 120 : length), m);
      } else if(length > 9 && !strncmp(m, "[\"NOTICE\"", 9)){
        LOG_BOOT("[VAULT] relay notice: %.*s\n", (int)(length > 120 ? 120 : length), m);
      }
      break; }
    default: break;
  }
}
static void vbLinkClose(){
  g_vbClosing = true;
  unsigned long t0 = millis();
  while(millis() - t0 < 300){ webSocket2.loop(); esp_task_wdt_reset(); delay(20); }
  webSocket2.setReconnectInterval(0xFFFFFFFFUL);
  webSocket2.disconnect();
  webSocket2.freeClient();   // bench 2 Nov: the library kept the TLS client (~1.9 KB) in the middle of the largest internal block, so every later handshake failed
  g_vbConn = false;
  webSocket2.onEvent(wsEvent2);   // the socket is the bunker / share socket again
  g_vbClosing = false;
  LOG_BOOT("[VAULT] link closed, internal largest %u\n", (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT));
}
static bool vbLinkOpen(const char* host){
  if(!wifiConnected) return false;
  if(ws2Initialised) { LOG_BOOT("[VAULT] the second socket is busy (a share is running) - later\n"); return false; }
  g_tlsKeepCamReserve = true; ensureContigForTLS(); g_tlsKeepCamReserve = false;   // keeps the camera's block (see g_tlsKeepCamReserve)
  g_vbConn = false;
  LOG_BOOT("[VAULT] link: wss://%s, internal free %u largest %u\n", host, (unsigned)heap_caps_get_free_size(MALLOC_CAP_INTERNAL), (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT));
  webSocket2.onEvent(wsEventVault);
  webSocket2.beginSSL(host, 443, "/");
  webSocket2.setReconnectInterval(3000);
  unsigned long t0 = millis();
  while(millis() - t0 < 12000){ webSocket2.loop(); esp_task_wdt_reset(); if(g_vbConn){ LOG_BOOT("[VAULT] link up in %lu ms\n", (unsigned long)(millis() - t0)); return true; } delay(20); }
  LOG_BOOT("[VAULT] wss://%s did not answer in 12 s (last TLS error %d %s, internal largest %u)\n", host, webSocket2.lastConnectErr,
           webSocket2.lastConnectErrText[0] ? webSocket2.lastConnectErrText : "none", (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT));
  vbLinkClose();
  return false;
}
// On an open link: the newest backup event by our key. true when the relay
// answered (EOSE), whether or not it had one (g_vbEvt).
static bool vbFetchOnLink(const char pubHex[65]){
  vbEvtFree(); g_vbEose = false; g_vbClosed = false; g_vbDropped = false;
  char req[220];
  snprintf(req, sizeof req, "[\"REQ\",\"fv\",{\"kinds\":[30078],\"authors\":[\"%s\"],\"#d\":[\"%s\"],\"limit\":1}]", pubHex, favilla::VB_D_TAG);
  g_vbFetching = true;
  if(!webSocket2.sendTXT(req)){ g_vbFetching = false; return false; }
  unsigned long t0 = millis();
  while(millis() - t0 < 8000 && !g_vbEose && !g_vbClosed && g_vbConn){ webSocket2.loop(); esp_task_wdt_reset(); delay(10); }
  g_vbFetching = false;
  webSocket2.sendTXT("[\"CLOSE\",\"fv\"]");
  if(g_vbClosed || g_vbDropped) LOG_BOOT("[VAULT] fetch incomplete (%s) - treated as no answer\n", g_vbClosed ? "relay closed it" : "a frame was dropped");
  return g_vbEose && !g_vbClosed && !g_vbDropped;
}
// Check and merge the event in g_vbEvt. VBR_OK / VBR_BADEVENT / VBR_OTHERVAULT / VBR_PASS / VBR_MERGE / VBR_MEM.
static int vbMergeEvt(const uint8_t pub[32], const uint8_t chk[8], favilla::RkImport* st){
  const char* ct = nullptr; size_t cn = 0; uint32_t at = 0;
  int e = favilla::vb_event_check(g_vbEvt, g_vbEvtN, pub, &ct, &cn, &at);
  if(e){ LOG_BOOT("[VAULT] the relay's backup event failed its checks (%d) - ignored\n", e); return VBR_BADEVENT; }
  // v19 rollback guard (docs/DOOR_KEY_RULE.md section 4): a copy older than the
  // last backup a relay accepted from this KEY is a replay or a stale relay. It
  // is never merged; a publish then goes ahead over it.
  { uint32_t lt = 0; uint16_t ln = 0;
    if(vbLastLoad(&lt, &ln) && at < lt){ LOG_BOOT("[VAULT] the relay's backup (%lu) is older than this KEY's last one (%lu, %u records) - not merged\n", (unsigned long)at, (unsigned long)lt, (unsigned)ln); return VBR_OLDER; } }
  size_t cap = cn / 4 * 3 + 4, rn = 0;
  uint8_t* raw = (uint8_t*)vbAlloc(cap); if(!raw) return VBR_MEM;
  int r = VBR_OK;
  if(mbedtls_base64_decode(raw, cap, &rn, (const uint8_t*)ct, cn)) r = VBR_BADEVENT;
  else {
    const uint8_t* body; size_t bn;
    int pe = favilla::vb_blob_parse(raw, rn, chk, &body, &bn);
    if(pe == favilla::VB_E_PASS) r = VBR_PASS;
    else if(pe == favilla::VB_E_CHECK) r = VBR_OTHERVAULT;
    else if(pe) r = VBR_BADEVENT;
    else if(favilla::rk_import(body, bn, st)) r = VBR_MERGE;
    else LOG_BOOT("[VAULT] relay backup of %lu merged\n", (unsigned long)at);
  }
  mbedtls_platform_zeroize(raw, cap); free(raw);
  return r;
}
static bool vpLinkUp();   // 11q: the phone is connected over Bluetooth in the NOSTR BT life
volatile int g_hbWant = 0;   // 11s: "Check all": opens the loops should spend on health now (the G0's 32 per sitting is the hard limit; 8 kept back for sign-ins)
volatile int g_hbDoneNow = 0;
volatile int g_hbOneSlot = -1;   // 11ax (issue #30): ASSESS_ONE: this slot first, then the usual backfill
// 11ax: run a pending ASSESS_ONE (one OPEN, on the loop that owns the G0). Both
// lives' backfill blocks call this first. True if it ran.
static bool hbAssessOneTick(){
  const int s = g_hbOneSlot; if(s < 0) return false;
  g_hbOneSlot = -1;
  int r; { g0_window_batch_begin(); r = favilla::rk_health_assess_slot(s); g0_window_batch_end(); }
  LOG_BOOT("[PW] assess one (app): slot %d %s\n", s, r == 1 ? "assessed" : r == 0 ? "already known" : r == -1 ? "is not a password" : favilla::rk_err_name(r));
  return true;
}
// 11ad: the NOSTR life mounts the records 5 s after the PIN with no button
// pressed (rkMountTick). A backup asked for before that landed answered
// VBR_NOG0 ("signer chip too old"), which it is not: mount now instead.
static void vbMountNow(){ if(g_rkMountPending && wallet.unlocked){ g_rkMountPending = false; const uint32_t t0 = millis(); if(favilla::rk_mount()) LOG_BOOT("[RK] nvs_vault mounted on demand in %lu ms\n", (unsigned long)(millis() - t0)); } }
// v19 (13 Nov 2026, docs/DOOR_KEY_RULE.md section 4): the NOSTR life writes the
// publishing key copy from the sealed bytes the PASSKEY life left ("vseal"),
// under the daily key, inside the daily session. The vseal bytes stay until the
// SE confirms the object, so a failure is tried again at the next unlock.
static uint32_t g_vpubTriedEpoch = 0xFFFFFFFFu;
static bool vpubPendingWrite(){
  if(g_passkeyLife || !wallet.unlocked || !g0_doorpin_present()) return false;
  uint8_t sealed[32];
  if(!vpubSealLoad(sealed)) return false;
  bool ok = false;
  I2C_LOCK();
  if(favilla::se_pin_session_is_open()) ok = favilla::se_vpub_write(sealed);
  I2C_UNLOCK();
  mbedtls_platform_zeroize(sealed, 32);
  if(ok) vpubSealErase();
  LOG_BOOT("[VAULT] publishing key copy (daily layer): %s\n", ok ? "written" : "NOT written (tried again at the next unlock)");
  return ok;
}
static void vpubPendingTick(){
  const uint32_t epoch = favilla::rk_lock_epoch();
  if(epoch == g_vpubTriedEpoch || !wallet.unlocked || g_passkeyLife) return;
  g_vpubTriedEpoch = epoch;
  if(vpubPendingWrite() || !g0_doorpin_present()) return;
  // 11bf (bench 16 Nov 2026): say what happened when there was nothing to write,
  // so a silent skip can never pass for "written".
  if(vpubSealPending()) return;   // there was something, and vpubPendingWrite logged why it failed
  bool have; { I2C_LOCK(); have = favilla::se_vpub_present(); I2C_UNLOCK(); }
  LOG_BOOT("[VAULT] publishing key copy (daily layer): %s\n", have ? "already stored" : "missing - start in VAULT mode once, then unlock here again");
}
static int vbCommonChecks(uint8_t pub[32], uint8_t chk[8], char pubHex[65], bool needSign){
  vbMountNow();
  if(!favilla::rk_ready()) return VBR_NOG0;
  if(!vbKeysLoad(pub, chk)) return VBR_NOKEYS;
  if(!wifiConnected && !vpLinkUp()) return VBR_NOWIFI;   // 11q: or the phone over Bluetooth
  if(needSign){
    if(!g0_vpub_present()) return VBR_NOG0;
    bool v; { I2C_LOCK(); v = favilla::se_vpub_present(); I2C_UNLOCK(); }
    if(!v && wallet.unlocked) v = vpubPendingWrite();   // v19: the copy the PASSKEY life prepared
    if(!v) return VBR_NOVPUB;
    if(!wallet.unlocked) return VBR_LOCKED;
    time_t now = time(nullptr);
    if(now < 1700000000 || now > 4102444800L) return VBR_NOCLOCK;   // review: never publish with a clock that is unset or absurd
  }
  for(int i = 0; i < 32; i++) sprintf(pubHex + 2 * i, "%02x", pub[i]);
  return VBR_OK;
}
// =============================================================================
// 11q (10 Nov 2026, Josh): vault backup and restore over Bluetooth, the phone
// as the relay courier. Same blob, same signature, same checks as the Wi-Fi
// path; only the socket is gone. The app channel carries 40 KB per answer and
// a vault event can be 140 KB, so the frame travels in chunks:
//   KEY -> app  R_NUDGE third byte: bit0 "back up now", bit1 "restore now"
//   app -> KEY  VAULT_PUT 0x42 [total u32][offset u32][bytes]  the relay's newest
//               event (JSON object), total 0 = the relay has none; the KEY
//               checks and merges it on the main loop and answers the result
//   app -> KEY  VAULT_GET 0x40 [offset u32]  offset 0 stages (exports, signs)
//               the ["EVENT",...] frame; each answer carries one chunk
//   app -> KEY  VAULT_DONE 0x41 [ok][relay message]  the relay's OK; only then
//               does the KEY record "last backup" and clear dirty
// A backup = PUT (merge the relay's copy first, as the Wi-Fi path does), GET
// until the end, publish, DONE. A restore = PUT alone. Jobs that touch the
// records or the G0 (stage, merge) run on the main loop (vpPump), never on
// the Bluetooth task; the handlers wait on them briefly and otherwise say busy.
#if defined(FAVILLA_BLE_KBD) && defined(FAVILLA_PK_RESTORABLE)
namespace ag { static bool nudgeNow(); static bool appLinkUp(); }
static bool vpLinkUp(){ return g_nostrBtLife && ag::appLinkUp(); }
static bool vpNudge(){ return ag::nudgeNow(); }
#else
static bool vpLinkUp(){ return false; }
static bool vpNudge(){ return false; }
#endif
static SemaphoreHandle_t g_vpMx = nullptr;
static char* g_vpFrame = nullptr; static size_t g_vpFrameN = 0; static uint32_t g_vpFrameAt = 0;   // staged frame (PSRAM)
static uint32_t g_vpCreated = 0, g_vpGen = 0; static int g_vpNrec = 0;
static char* g_vpIn = nullptr; static size_t g_vpInN = 0, g_vpInTotal = 0; static uint32_t g_vpInAt = 0;   // event being put (PSRAM)
static volatile uint8_t g_vpWant = 0;        // nudge bits: 1 back up, 2 restore
static volatile int g_vpJob = 0;             // 1 stage, 2 merge (set by the handler, run by vpPump)
static volatile int g_vpStageR = -1;         // result of the last stage job (VBR_*), -1 = none
static volatile int g_vpMergeR = -1;         // result of the last merge job (VBR_*), -1 = none
static favilla::RkImport g_vpMergeSt = {};
static volatile int g_vpDone = -1;           // VAULT_DONE: 0 ok, 1 refused, 2 the app could not reach the relay; -1 none
static volatile uint32_t g_vpSentTo = 0;     // 11cg: bytes of the staged frame the app has collected (VAULT_GET off + n), for the KEY's bar
// 11cg: the Wi-Fi backup and restore report their stages here (the Backup
// page's step rows); null when nothing is watching. 1 relay copy, 2 sign, 3 send.
static void (*g_vbStage)(int) = nullptr;
static inline void vbStage(int k){ if(g_vbStage) g_vbStage(k); }
static char g_vpDoneMsg[96] = {0};
static uint32_t g_vpAskedAt = 0;             // when the page or the tick asked the phone
static void vpLock(){ if(!g_vpMx) g_vpMx = xSemaphoreCreateMutex(); xSemaphoreTake(g_vpMx, portMAX_DELAY); }
static void vpUnlock(){ xSemaphoreGive(g_vpMx); }
static void vpFrameFree(){ vpLock(); if(g_vpFrame){ mbedtls_platform_zeroize(g_vpFrame, g_vpFrameN); free(g_vpFrame); g_vpFrame = nullptr; } g_vpFrameN = 0; vpUnlock(); }
static void vpInFree(){ vpLock(); if(g_vpIn){ free(g_vpIn); g_vpIn = nullptr; } g_vpInN = g_vpInTotal = 0; vpUnlock(); }
// Export, sign, keep the frame for the app. Main loop only.
static int vpStage(){
  uint8_t pub[32], chk[8]; char ph[65];
  int r = vbCommonChecks(pub, chk, ph, true); if(r) return r;
  if(vbRestorePending()) return VBR_BUSY;
  uint32_t t0 = millis();
  uint8_t* body = (uint8_t*)vbAlloc(favilla::VB_BLOB_MAX); uint8_t* blob = (uint8_t*)vbAlloc(favilla::VB_BLOB_MAX);
  size_t b64cap = favilla::VB_BLOB_MAX / 3 * 4 + 8; char* b64 = (char*)vbAlloc(b64cap);
  size_t jcap = b64cap + 600; char* frame = (char*)vbAlloc(jcap + 16);
  if(!body || !blob || !b64 || !frame){ free(body); free(blob); free(b64); free(frame); return VBR_MEM; }
  size_t bn = 0, bl = 0; int nrec = 0, ntomb = 0; uint32_t gen = 0;
  r = VBR_OK;
  { const int xe = favilla::rk_export(body, favilla::VB_BLOB_MAX - favilla::VB_HDR, &bn, &nrec, &ntomb, &gen); if(xe) r = xe == favilla::RK_E_SIZE ? VBR_TOOBIG : VBR_EXPORT; }   // 11dr
  if(!r){ size_t blobN = favilla::vb_blob(chk, body, bn, blob); if(mbedtls_base64_encode((unsigned char*)b64, b64cap, &bl, blob, blobN)) r = VBR_EXPORT; }
  size_t jn = 0; uint32_t created = 0;
  if(!r){
    created = (uint32_t)time(nullptr); uint8_t id[32], sig[64];
    favilla::vb_event_id(ph, created, b64, bl, id);
    if(!g0_vault_sign(id, pub, sig)){ r = VBR_SIGN; vbFixSet(true); }
    else {
      memcpy(frame, "[\"EVENT\",", 9);
      jn = favilla::vb_event_json(frame + 9, jcap, id, ph, created, b64, bl, sig);
      if(!jn) r = VBR_EXPORT; else if(10 + jn > favilla::VB_EVENT_MAX) r = VBR_TOOBIG; else { frame[9 + jn] = ']'; frame[10 + jn] = 0; }   // 11dr
    }
    mbedtls_platform_zeroize(sig, 64);
  }
  mbedtls_platform_zeroize(body, favilla::VB_BLOB_MAX); free(body); free(blob); free(b64);
  if(r){ free(frame); return r; }
  vpLock();
  if(g_vpFrame){ mbedtls_platform_zeroize(g_vpFrame, g_vpFrameN); free(g_vpFrame); }
  g_vpFrame = frame; g_vpFrameN = 10 + jn; g_vpFrameAt = millis(); g_vpCreated = created; g_vpGen = gen; g_vpNrec = nrec;
  vpUnlock();
  LOG_BOOT("[VAULT] staged for the phone: %d records + %d tombstones, %u bytes (%lu ms)\n", nrec, ntomb, (unsigned)g_vpFrameN, (unsigned long)(millis() - t0));
  return VBR_OK;
}
// Check and merge the event the app put. Main loop only.
static int vpMerge(favilla::RkImport* st){
  uint8_t pub[32], chk[8]; char ph[65];
  int r = vbCommonChecks(pub, chk, ph, false); if(r) return r;
  vpLock(); char* ev = g_vpIn; size_t n = g_vpInN; g_vpIn = nullptr; g_vpInN = g_vpInTotal = 0; vpUnlock();
  if(!ev) return VBR_NOTFOUND;   // total 0: the relay holds no backup by this key
  // the same checks as a relay fetch: author, kind, tags, id, signature, then the blob
  const char* a = (const char*)memchr(ev, '{', n); const char* z = ev + n; while(z > a && *(z - 1) != '}') z--;
  if(!a || z <= a){ free(ev); return VBR_BADEVENT; }
  vbEvtFree(); g_vbEvt = ev; g_vbEvtN = (size_t)(z - a); memmove(ev, a, g_vbEvtN); ev[g_vbEvtN] = 0;
  r = vbMergeEvt(pub, chk, st);
  vbEvtFree();
  LOG_BOOT("[VAULT] the phone's copy of the relay backup: %d (%d added, %d removed)\n", r, st->added, st->removed);
  return r;
}
// One job per call, from loop() and from the menu tick.
static void vpPump(){
  if(!g_nostrBtLife) return;
  const int job = g_vpJob; if(!job) return;
  if(job == 1){ g_vpStageR = vpStage(); }
  else if(job == 2){ favilla::RkImport st{}; g_vpMergeR = vpMerge(&st); g_vpMergeSt = st; if(g_vpMergeR == VBR_OK || g_vpMergeR == VBR_NOTFOUND) vbRestorePendingSet(false); }
  g_vpJob = 0;
}
// Ask the phone. want: 1 back up, 2 restore.
static bool vpAsk(uint8_t want){
  if(!vpLinkUp()) return false;
  g_vpWant = want; g_vpDone = -1; g_vpMergeR = -1; g_vpStageR = -1; g_vpAskedAt = millis(); g_vpSentTo = 0;
  const bool sent = vpNudge();
  LOG_BOOT("[VAULT] asked the phone: %s (nudge %s)\n", want == 2 ? "restore" : "back up", sent ? "sent" : "NOT sent");
  return sent;
}
// A frame the app never collected, or a put the app never finished, is dropped after 2 minutes.
static void vpTidy(){
  const uint32_t now = millis();
  if(g_vpFrame && now - g_vpFrameAt > 120000UL) vpFrameFree();
  if(g_vpIn && now - g_vpInAt > 120000UL) vpInFree();
  if(g_vpWant && now - g_vpAskedAt > 120000UL) g_vpWant = 0;
}
// Restore: fetch, check, merge. Never publishes.
static int vaultRestoreNow(favilla::RkImport* st){
  uint8_t pub[32], chk[8]; char ph[65];
  int r = vbCommonChecks(pub, chk, ph, false); if(r) return r;
  uint32_t t0 = millis();
  vbStage(1);   // 11cg
  if(!vbLinkOpen(favilla::VB_RELAY)) return VBR_RELAY;
  bool answered = vbFetchOnLink(ph);
  vbLinkClose();
  if(!answered){ vbEvtFree(); return VBR_RELAY; }
  vbStage(2);   // 11cg: checking and merging
  if(!g_vbEvt){ LOG_BOOT("[VAULT] restore: no backup on %s for this key (%lu ms)\n", favilla::VB_RELAY, (unsigned long)(millis() - t0)); return VBR_NOTFOUND; }
  r = vbMergeEvt(pub, chk, st);
  vbEvtFree();
  LOG_BOOT("[VAULT] restore: %d, %lu ms\n", r, (unsigned long)(millis() - t0));
  return r;
}
// Publish: fetch and merge the relay's copy first, then sign and send ours.
static int vaultPublishNow(int* nrecOut){
  uint8_t pub[32], chk[8]; char ph[65];
  int r = vbCommonChecks(pub, chk, ph, true); if(r) return r;
  if(vbRestorePending()) return VBR_BUSY;   // never publish over a backup this KEY has not fetched yet
  uint32_t t0 = millis();
  vbStage(1);   // 11cg: the relay's copy first
  if(!vbLinkOpen(favilla::VB_RELAY)) return VBR_RELAY;
  if(!vbFetchOnLink(ph)){ vbLinkClose(); vbEvtFree(); return VBR_RELAY; }
  if(g_vbEvt){
    favilla::RkImport st{}; int m = vbMergeEvt(pub, chk, &st); vbEvtFree();
    if(m == VBR_OLDER) m = VBR_OK;   // v19: ours is newer; publish over the stale copy
    if(m != VBR_OK){ vbLinkClose(); return m; }   // never overwrite what we could not read or merge (review: BADEVENT too)
    if(st.foreign || st.full){ vbLinkClose(); LOG_BOOT("[VAULT] the relay backup holds %d record(s) this KEY cannot keep - not publishing over it\n", st.foreign + st.full); return VBR_PARTIAL; }
  }
  uint8_t* body = (uint8_t*)vbAlloc(favilla::VB_BLOB_MAX); uint8_t* blob = (uint8_t*)vbAlloc(favilla::VB_BLOB_MAX);
  size_t b64cap = favilla::VB_BLOB_MAX / 3 * 4 + 8; char* b64 = (char*)vbAlloc(b64cap);
  size_t jcap = b64cap + 600; char* frame = (char*)vbAlloc(jcap + 16);
  if(!body || !blob || !b64 || !frame){ free(body); free(blob); free(b64); free(frame); vbLinkClose(); return VBR_MEM; }
  size_t bn = 0, bl = 0; int nrec = 0, ntomb = 0; uint32_t gen = 0;
  r = VBR_OK;
  { const int xe = favilla::rk_export(body, favilla::VB_BLOB_MAX - favilla::VB_HDR, &bn, &nrec, &ntomb, &gen); if(xe) r = xe == favilla::RK_E_SIZE ? VBR_TOOBIG : VBR_EXPORT; }   // 11dr
  if(!r){
    size_t blobN = favilla::vb_blob(chk, body, bn, blob);
    if(mbedtls_base64_encode((unsigned char*)b64, b64cap, &bl, blob, blobN)) r = VBR_EXPORT;
  }
  if(!r){
    uint32_t created = (uint32_t)time(nullptr); uint8_t id[32], sig[64];
    favilla::vb_event_id(ph, created, b64, bl, id);
    vbStage(2);   // 11cg: signing on the G0
    uint32_t ts = millis();
    if(!g0_vault_sign(id, pub, sig)){ r = VBR_SIGN; vbFixSet(true); }   // review: the next PASSKEY login re-makes the key copy
    else {
      memcpy(frame, "[\"EVENT\",", 9);
      size_t jn = favilla::vb_event_json(frame + 9, jcap, id, ph, created, b64, bl, sig);
      if(!jn) r = VBR_EXPORT;
      else if(10 + jn > favilla::VB_EVENT_MAX) r = VBR_TOOBIG;   // 11dr: the KEY could not read it back
      else {
        frame[9 + jn] = ']'; frame[10 + jn] = 0;
        for(int i = 0; i < 32; i++) sprintf(g_vbWantId + 2 * i, "%02x", id[i]);
        g_vbOkGot = false; g_vbOkAcc = false;
        LOG_BOOT("[VAULT] publishing %d records + %d tombstones, %u bytes (sign %lu ms)\n", nrec, ntomb, (unsigned)(10 + jn), (unsigned long)(millis() - ts));
        // 8z3 (bench 6 Nov: "backup NOT published" 320 ms after publishing 33,676 bytes):
        // say which step failed - the send itself, the link, or no answer.
        vbStage(3);   // 11cg: sending, then the relay's answer
        const unsigned long tsend = millis();
        webSocket2.lastWriteErr = 0; webSocket2.lastWriteErrText[0] = 0;
        const bool sent = webSocket2.sendTXT((uint8_t*)frame, 10 + jn);
        if(!sent) LOG_BOOT("[VAULT] TLS write failed after %u of %u bytes (any failed allocation is logged above as [ALLOC])\n",
                           (unsigned)webSocket2.lastWriteDone, (unsigned)webSocket2.lastWriteWant);
        LOG_BOOT("[VAULT] send %s in %lu ms, link %s, internal free %u largest %u\n", sent ? "done" : "FAILED", (unsigned long)(millis() - tsend),
                 g_vbConn ? "up" : "down", (unsigned)heap_caps_get_free_size(MALLOC_CAP_INTERNAL), (unsigned)heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT));
        if(!sent) r = VBR_RELAY;
        else {
          unsigned long tw = millis();
          while(millis() - tw < 10000 && !g_vbOkGot && g_vbConn){ webSocket2.loop(); esp_task_wdt_reset(); delay(10); }
          if(!g_vbOkGot){ r = VBR_RELAY; LOG_BOOT("[VAULT] no answer from the relay after %lu ms (link %s)\n", (unsigned long)(millis() - tw), g_vbConn ? "still up" : "dropped"); }
          else if(!g_vbOkAcc){ r = VBR_REFUSED; LOG_BOOT("[VAULT] relay refused the backup: %s\n", g_vbOkMsg); }
          else {
            vbLastSave(created, (uint16_t)nrec);
            if(!favilla::rk_set_clean(gen)) LOG_BOOT("[VAULT] a change landed during the backup - another backup will follow\n");
          }
        }
        g_vbWantId[0] = 0;
      }
    }
    mbedtls_platform_zeroize(sig, 64);
  }
  vbLinkClose();
  free(body); free(blob); free(b64); free(frame);
  if(nrecOut) *nrecOut = nrec;
  LOG_BOOT("[VAULT] backup %s, %lu ms in all\n", r == VBR_OK ? "accepted by the relay" : "NOT published", (unsigned long)(millis() - t0));
  return r;
}
static void vbResultText(int r, bool restore, const favilla::RkImport* st, int nrec, char* l1, size_t n1, char* l2, size_t n2){
  l2[0] = 0;
  switch(r){
    case VBR_OK:
      if(restore){ snprintf(l1, n1, "Restored."); snprintf(l2, n2, "%d added or updated, %d removed. %d passkeys and %d passwords on this KEY.", st ? st->added : 0, st ? st->removed : 0, favilla::rk_count(), favilla::rk_pw_count()); }
      else { snprintf(l1, n1, "Backed up."); snprintf(l2, n2, "%d passkeys on %s.", nrec, favilla::VB_RELAY); }
      break;
    case VBR_NOKEYS:     snprintf(l1, n1, "Backups are not set up on this KEY."); snprintf(l2, n2, "Set the KEY up again on this firmware."); break;
    case VBR_NOVPUB:     snprintf(l1, n1, "Open VAULT mode once to finish setting up backups."); break;
    case VBR_NOG0:       snprintf(l1, n1, g0_caps_known() ? "The signer chip needs the v14 firmware." : "The signer chip's version was not read at boot. Try again, or restart the KEY."); break;
    case VBR_LOCKED:     snprintf(l1, n1, "Unlock the KEY first."); break;
    case VBR_NOWIFI:     snprintf(l1, n1, "Connect to Wi-Fi first."); break;
    case VBR_NOCLOCK:    snprintf(l1, n1, "The KEY does not know the time yet."); snprintf(l2, n2, "Try again in a minute."); break;
    case VBR_SIGN:       snprintf(l1, n1, "The signer did not sign the backup."); break;
    case VBR_RELAY:      snprintf(l1, n1, "Could not reach %s.", favilla::VB_RELAY); break;
    case VBR_REFUSED:    snprintf(l1, n1, "The relay refused the backup."); snprintf(l2, n2, "%s", g_vbOkMsg); break;
    case VBR_NOTFOUND:   snprintf(l1, n1, "No backup found for these words."); break;
    case VBR_BADEVENT:   snprintf(l1, n1, "The backup on the relay failed its checks."); snprintf(l2, n2, "Nothing was changed."); break;
    case VBR_OTHERVAULT: snprintf(l1, n1, "That backup belongs to other words."); snprintf(l2, n2, "Nothing was imported."); break;
    case VBR_PASS:       snprintf(l1, n1, "That backup needs a vault passphrase."); snprintf(l2, n2, "This firmware cannot ask for one yet. Nothing was imported."); break;
    case VBR_BUSY:       snprintf(l1, n1, "Restore first."); snprintf(l2, n2, "This KEY has not fetched its backup yet."); break;
    case VBR_OLDER:      snprintf(l1, n1, "That backup is older than this KEY's last one."); snprintf(l2, n2, "Nothing was imported. Back up again to replace it."); break;
    case VBR_TOOBIG:     snprintf(l1, n1, "Not backed up."); snprintf(l2, n2, "Too much for one backup (%d entries). They are all safe on this KEY.", favilla::rk_count_all()); break;   // 11dr
    case VBR_PARTIAL:    snprintf(l1, n1, "Not backed up."); snprintf(l2, n2, "The relay backup holds entries this KEY cannot keep (newer firmware, or more than %d). Nothing was overwritten.", favilla::RK_MAX); break;
    default:             snprintf(l1, n1, "Something went wrong (%d).", r); snprintf(l2, n2, "Nothing was changed."); break;
  }
}
// 11cg (22 Nov 2026, UX drop 1): the Wi-Fi backup and restore as three (or
// two) steps; the running one turns (wp, work_page.inc). vbStage() moves it on.
static bool g_vbStageRestore = false;
static void vbStagePaint(int k){
  if(g_vbStageRestore){
    wp::setStep(0, k >= 2 ? wp::DONE : wp::NOW);
    wp::setStep(1, k >= 2 ? wp::NOW : wp::TODO);
  } else {
    for(int i = 0; i < 3; i++) wp::setStep(i, i + 1 < k ? wp::DONE : i + 1 == k ? wp::NOW : wp::TODO);
  }
  wp::show();
}
static void vbStepsBegin(bool restore, const char* foot){
  g_vbStageRestore = restore;
  if(restore){
    wp::steps("BACKUP", "Restoring");
    wp::step(0, wp::NOW,  "Fetching", favilla::VB_RELAY);
    wp::step(1, wp::TODO, "Checked and merged", "on this KEY");
  } else {
    wp::steps("BACKUP", "Backing up");
    wp::step(0, wp::NOW,  "Checking the relay", "for a newer copy first");
    wp::step(1, wp::TODO, "Signing", "on the signer chip");
    wp::step(2, wp::TODO, "Sending", favilla::VB_RELAY);
  }
  snprintf(wp::P.foot, sizeof wp::P.foot, "%s", foot ? foot : "");
  wp::show();
  g_vbStage = vbStagePaint;
}
static void vbStepsEnd(){ g_vbStage = nullptr; wp::stop(); }
// Automatic: a pending restore (after a restore from the words) first, then a
// backup of any change, after a random 1 to 30 minutes (D2), on a quiet screen.
static uint32_t g_vbDueAt = 0, g_vbCheckAt = 0; static bool g_vbDirty = false, g_vbPend = false;
static void vaultAutoTick(){
  if(g_passkeyLife) return;
  uint32_t now = millis();
  vpPump(); vpTidy();
  { // 11s: health backfill in the NOSTR lives too (Wi-Fi or Bluetooth): a few OPENs per
    // sitting on a quiet home screen, for entries the KEY has never assessed
    static uint32_t hbAt = 0, hbEpoch = 0; static int hbN = 0;
    if(hbEpoch != favilla::rk_lock_epoch()){ hbEpoch = favilla::rk_lock_epoch(); hbN = 0; }
    if(wallet.unlocked && favilla::rk_ready() && g0_v15_present() && fidoBePkrOpen() && !fidoPromptActive() && hbAssessOneTick()){ }   // 11ax: ASSESS_ONE first
    const bool asked = g_hbWant > 0;   // Check all from the PWA: no idle wait, one per 200 ms
    if(wallet.unlocked && (asked || hbN < 6) && favilla::rk_ready() && g0_v15_present() && fidoBePkrOpen() && currentState == ST_MENU && nextState == currentState &&
       !fidoPromptActive() && (asked || (uint32_t)(now - lastActivity) > 20000UL) && now - hbAt > (asked ? 200UL : 5000UL)){
      hbAt = now; bool did; { g0_window_batch_begin(); did = favilla::rk_health_backfill_one(); g0_window_batch_end(); }
      if(did){ hbN++; if(asked){ g_hbWant--; g_hbDoneNow++; } LOG_BOOT("[PW] health backfill: one entry assessed (%d this sitting)\n", hbN); }
      else { hbN = 6; g_hbWant = 0; } } }
  if((!wifiConnected && !vpLinkUp()) || !wallet.unlocked || !favilla::rk_ready()){ g_vbDueAt = 0; return; }
  if(!g_vbCheckAt || now - g_vbCheckAt > 30000){ g_vbCheckAt = now ? now : 1; g_vbDirty = favilla::rk_dirty(); g_vbPend = vbRestorePending(); }
  if(!(g_vbPend || (g_vbDirty && g0_vpub_present()))){ g_vbDueAt = 0; return; }
  if(!g_vbDueAt){
    uint32_t d = g_vbPend ? 5000 : 60000 + (esp_random() % 1740000UL);
    g_vbDueAt = (now + d) | 1;
    LOG_BOOT("[VAULT] %s in %lu s\n", g_vbPend ? "relay restore" : "backup", (unsigned long)(d / 1000));
    return;
  }
  if((int32_t)(now - g_vbDueAt) < 0) return;
  // A quiet screen only. Bench 2 Nov 2026: this used to exclude ST_MENU, but
  // ST_MENU (0) IS the home screen, so the automatic backup and the automatic
  // relay restore never ran (a backup sat "due" for 4 minutes on the home
  // screen). Submenus run as blocking loops inside ST_MENU and never reach this
  // tick. Now: home screen allowed, but only after 20 s with no button press.
  if(fidoPromptActive() || stateIsSecurityUx(currentState) || nextState != currentState) return;
  if((uint32_t)(millis() - lastActivity) < 20000UL) return;
  if(!wifiConnected){   // 11q: over Bluetooth the phone does the relay work; results land in the handlers
    if(g_vpWant){ return; }   // one ask at a time (vpTidy drops a stale one)
    const bool asked = vpAsk(g_vbPend ? 2 : 1);
    LOG_BOOT("[VAULT] %s over Bluetooth: %s\n", g_vbPend ? "restore" : "backup", asked ? "asked the phone" : "the phone is not here");
    g_vbDueAt = (now + 600000UL) | 1; g_vbCheckAt = 0;   // again in 10 minutes unless the phone finishes it (dirty clears, rpend clears)
    return;
  }
  // Review 2 Nov 2026 (finding 5, kept on purpose): with the bunker up, a
  // backup holds off the bunker socket and NIP-46 for the link's 4 to 5 s
  // (12 s worst case, a relay that never answers). Requests wait on the relay
  // and are served after; bench check 9 proved the bunker carries on. Skipping
  // backups while the bunker is active would mean an always-on desk signer is
  // never backed up.
  // 11cg: the steps, the running one turning (no footer: no button works while the link runs)
  if(dimActive) idleDimWake();
  vbStepsBegin(g_vbPend, nullptr);
  if(g_vbPend){
    favilla::RkImport st{}; int r = vaultRestoreNow(&st);
    if(r == VBR_OK || r == VBR_NOTFOUND || r == VBR_OTHERVAULT){ vbRestorePendingSet(false); g_vbPend = false; g_vbDueAt = 0; }   // review: a backup we could not read keeps the KEY from publishing
    else g_vbDueAt = (now + 300000UL) | 1;   // no relay yet: try again in 5 minutes
  } else {
    int n = 0; int r = vaultPublishNow(&n);
    g_vbDueAt = (r == VBR_OK) ? 0 : ((now + 600000UL) | 1);   // failed: again in 10 minutes
  }
  vbStepsEnd();
  g_vbCheckAt = 0;
  if(currentState != (DeviceState)99){ nextState = currentState; currentState = (DeviceState)99; }   // redraw whatever the link paused (bench 2 Nov: never 99 -> 99, which froze the KEY)
}
// Settings > Device > Passkeys > Backup (NOSTR life).
static void runVaultBackupPage(){
  int sel = 0;
  auto msgWait = [](const char* l1, const char* l2){
    pkPageMsg("BACKUP", l1, l2); clearButtonPending();
    for(;;){ btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll(); tickStatusBarInMenu(false); if(subMenuShouldYieldForApi()) return; if(btn4.isPressed() || btn2.isPressed()) return; delay(10); } };
  for(;;){
    char st1[64], st2[64]; uint32_t lt = 0; uint16_t ln = 0;
    bool dirty = favilla::rk_dirty();
    if(vbLastLoad(&lt, &ln)){ time_t tt = (time_t)lt; struct tm tmv; localtime_r(&tt, &tmv); char mon[8]; strftime(mon, sizeof mon, "%b", &tmv);
      snprintf(st1, sizeof st1, "Last backup %d %s %d", tmv.tm_mday, mon, tmv.tm_year + 1900); snprintf(st2, sizeof st2, "%u passkeys%s", (unsigned)ln, dirty ? ", changes since" : ""); }
    else { snprintf(st1, sizeof st1, "Not backed up yet"); snprintf(st2, sizeof st2, "%s", favilla::VB_RELAY); }
    const bool viaPhone = !wifiConnected;   // 11q
    auto draw = [&](){
      fEnd(); spr.fillSprite(C_BG);
      uiTrackLabel("BACKUP", 120, 14, C_EB_BRASS);
      fEndHard(); spr.loadFont(FONT_Archivo_Regular_13);
      spr.setTextColor(C_EB_INK);  spr.drawString(st1, 120 - spr.textWidth(st1) / 2, 40);
      spr.setTextColor(C_EB_GREY); spr.drawString(st2, 120 - spr.textWidth(st2) / 2, 60);
      fEndHard();
      uiListCard(12, 98, 216, 42, sel == 0, C_EB_BRASS, "Back up now", viaPhone ? "Through the Favilla app" : "Send to the vault relay", 24);
      uiListCard(12, 144, 216, 42, sel == 1, C_EB_BRASS, "Restore", viaPhone ? "The app fetches it" : "Fetch and merge the backup", 24);
      uiTrackLabel("ENTER TO RUN", 120, 196, C_EB_BRASS);
      uiTrackLabel("BACK TO LEAVE", 120, 216, C_EB_GREY);
      dispPush();
    };
    draw(); clearButtonPending();
    int choice = -1;
    while(choice < 0){
      btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll(); tickStatusBarInMenu(false);
      if(subMenuShouldYieldForApi() || btn4.isPressed()) return;
      if(btn1.isPressed() || btn3.isPressed()){ sel ^= 1; draw(); }
      if(btn2.isPressed()) choice = sel;
      delay(10);
    }
    // 11cg (22 Nov 2026, UX drop 1): steps that move instead of one still line.
    // Bluetooth: the KEY follows the app's courier work (the relay copy it PUTs,
    // each chunk it collects with VAULT_GET, the relay's answer in VAULT_DONE).
    // Wi-Fi: vaultPublishNow / vaultRestoreNow report their stages (vbStage).
    const bool restore = choice == 1;
    char l1[96], l2[128]; favilla::RkImport st{}; int nrec = 0; int r;
    if(!wifiConnected){   // 11q: the phone is the courier
      if(restore){
        wp::steps("BACKUP", "Restoring");
        wp::step(0, wp::NOW,  "The app fetches it", favilla::VB_RELAY);
        wp::step(1, wp::TODO, "Checked and merged", "on this KEY");
      } else {
        wp::steps("BACKUP", "Backing up");
        wp::step(0, wp::NOW,  "Checking the relay", "the app fetches its copy");
        wp::step(1, wp::TODO, "Sealed and sent", "through the Favilla app");
        wp::step(2, wp::TODO, "Relay keeps it", favilla::VB_RELAY);
      }
      snprintf(wp::P.foot, sizeof wp::P.foot, "BACK TO STOP");
      wp::show();
      if(!vpLinkUp()){ r = VBR_NOWIFI; }
      else if(!vpAsk(restore ? 2 : 1)){ r = VBR_RELAY; }
      else {
        r = VBR_RELAY; const uint32_t t0 = millis(); uint32_t shown = 0xFFFFFFFF;
        while(millis() - t0 < 90000UL){
          btn1.poll(); btn2.poll(); btn3.poll(); btn4.poll(); tickStatusBarInMenu(false); vpPump();
          if(btn4.isPressed()){ g_vpWant = 0; wp::stop(); return; }
          if(restore){ if(g_vpMergeR >= 0){ r = g_vpMergeR; st = g_vpMergeSt; break; } }
          else {
            if(g_vpMergeR > 0 && g_vpMergeR != VBR_NOTFOUND){ r = g_vpMergeR; st = g_vpMergeSt; break; }   // could not merge the relay's copy: not publishing over it
            if(g_vpStageR > 0){ r = g_vpStageR; break; }
            if(g_vpDone >= 0){ r = g_vpDone == 0 ? VBR_OK : g_vpDone == 1 ? VBR_REFUSED : VBR_RELAY; nrec = g_vpNrec; if(g_vpDone == 1) strlcpy(g_vbOkMsg, g_vpDoneMsg, sizeof g_vbOkMsg); break; }
          }
          // where the courier is, repainted only when it changes
          const size_t inT = g_vpInTotal, inN = g_vpInN, fN = g_vpFrameN; const uint32_t to = g_vpSentTo;
          uint32_t key; char sub[34] = "";
          if(restore){
            const int pc = inT ? (int)(inN * 100 / inT) : 0;
            key = (uint32_t)pc;
            if(inT) snprintf(sub, sizeof sub, "%d%%  of %u KB", pc, (unsigned)((inT + 1023) / 1024));
            if(key != shown){ shown = key; if(sub[0]) wp::setStep(0, wp::NOW, sub); wp::P.bar = inT ? pc / 100.0f : -1.0f; wp::show(); }
          } else {
            const int stage = (fN && to >= fN) ? 3 : (g_vpStageR == 0 && fN) ? 2 : (g_vpMergeR >= 0) ? 2 : 1;
            const int pc = fN ? (int)((uint64_t)to * 100 / fN) : 0;
            key = (uint32_t)(stage * 1000 + pc);
            if(key != shown){
              shown = key;
              for(int i = 0; i < 3; i++) wp::setStep(i, i + 1 < stage ? wp::DONE : i + 1 == stage ? wp::NOW : wp::TODO);
              if(stage == 2 && fN){ snprintf(sub, sizeof sub, "%d%%  of %u KB", pc, (unsigned)((fN + 1023) / 1024)); wp::setStep(1, wp::NOW, sub); wp::P.bar = pc / 100.0f; }
              else if(stage == 2){ wp::setStep(1, wp::NOW, "sealing on the KEY"); wp::P.bar = -1.0f; }
              else if(stage == 3){ wp::setStep(1, wp::DONE, "through the Favilla app"); wp::setStep(2, wp::NOW, "waiting for its answer"); wp::P.bar = -1.0f; }
              wp::show();
            }
          }
          delay(10);
        }
        g_vpWant = 0;
      }
      vbResultText(r, restore, &st, nrec, l1, sizeof l1, l2, sizeof l2);
      if(r == VBR_NOWIFI){ snprintf(l1, sizeof l1, "Connect to Wi-Fi, or open the Favilla app."); l2[0] = 0; }
      else if(r == VBR_RELAY && !wifiConnected){ snprintf(l1, sizeof l1, "The Favilla app did not finish it."); snprintf(l2, sizeof l2, "Open the app on the phone and try again."); }
    }
    else if(!restore){
      vbStepsBegin(false, nullptr);
      if(vbRestorePending()){ r = vaultRestoreNow(&st); if(r == VBR_OK || r == VBR_NOTFOUND) vbRestorePendingSet(false); }
      r = vaultPublishNow(&nrec);
      vbStepsEnd();
      vbResultText(r, false, nullptr, nrec, l1, sizeof l1, l2, sizeof l2);
    } else {
      vbStepsBegin(true, nullptr);
      r = vaultRestoreNow(&st);
      vbStepsEnd();
      if(r == VBR_OK || r == VBR_NOTFOUND) vbRestorePendingSet(false);
      vbResultText(r, true, &st, 0, l1, sizeof l1, l2, sizeof l2);
    }
    wp::stop();
    // 11cg: good news closes by itself; anything else waits for a press.
    if(r == VBR_OK){
      char line[44];
      if(restore) snprintf(line, sizeof line, "%d added, %d removed", st.added, st.removed);
      else snprintf(line, sizeof line, "%d passkeys on the relay", nrec);
      g_vbCheckAt = 0;
      wp::done("BACKUP", restore ? "Restored" : "Backed up", line);
      if(subMenuShouldYieldForApi()) return;
      continue;
    }
    g_vbCheckAt = 0;
    msgWait(l1, l2[0] ? l2 : nullptr);
    if(subMenuShouldYieldForApi()) return;
  }
}

// 2 Nov 2026 (Vault phase 2b): Settings > Device > Passkeys in the NOSTR life.
