// 2 Nov 2026: why a passkey request was refused. Up to 5 s, or until a button.
static unsigned long g_fidoNoticeAt = 0;
static void fidoNoticeClose(){
  g_fidoNoticeOn = false;
  clearButtonPending();
  if(nextState != currentState) { }
  else if(currentState == ST_MENU) dispMenu();
  else if(currentState != (DeviceState)99) { nextState = currentState; currentState = (DeviceState)99; }
}
static unsigned long g_fidoNoticeLast = 0;
static bool fidoNoticeTick(){
  if(g_fidoRefusedReq && fido::g_up.state != 1){
    g_fidoRefusedReq = false;
    // Review 2 Nov 2026: never over a PIN pad, onboarding, an approval or a
    // pending screen change (re-entering those resets them), and at most once
    // per 30 s, so a page cannot keep pushing the owner off the screen.
    if(millis() - g_fidoRefusedAt > 10000UL || stateIsSecurityUx(currentState) || currentState == ST_ONBOARD || nextState != currentState || !wallet.exists
       || (g_fidoNoticeLast && millis() - g_fidoNoticeLast < 30000UL)){
      LOG_BOOT("[FIDO] refusal not shown on screen (state %d)\n", (int)currentState);
      return false;
    }
    g_fidoNoticeLast = millis();
    if(dimActive) idleDimWake();
    lastActivity = millis();
    const char* l1; const char* l2 = nullptr;
    bool keys = false;
#ifdef FAVILLA_PK_RESTORABLE
    if(g0_pk2b_present()){ I2C_LOCK(); keys = favilla::se_pk2b_keys_present(); I2C_UNLOCK(); }
#endif
    if(g_doorChoice == DOOR_BTC){ l1 = "Passkeys are not open in BTC mode."; l2 = "Restart to switch."; }
    else if(!wallet.unlocked){ l1 = "Unlock the KEY to use passkeys."; }
    else if(keys){ l1 = "Passkeys are in VAULT mode. Restart to switch."; l2 = "To use them here too, allow them in NOSTR mode from the VAULT menu."; }
    else { l1 = "Passkeys are not open in this mode."; l2 = "Restart and choose VAULT."; }
    pkPageMsg("PASSKEYS", l1, l2);
    g_fidoNoticeOn = true; g_fidoNoticeAt = millis();
    clearButtonPending();
    LOG_BOOT("[FIDO] refusal shown: %s\n", l1);
    return true;
  }
  if(!g_fidoNoticeOn) return false;
  if(fido::g_up.state == 1){ g_fidoNoticeOn = false; return false; }   // a real prompt takes the screen
  lastActivity = millis();
  if(millis() - g_fidoNoticeAt > 5000 || btn1.isPressed() || btn2.isPressed() || btn3.isPressed() || btn4.isPressed()) fidoNoticeClose();
  return true;
}
static void fidoUiTick(){
  if(fidoNoticeTick()) return;
  uint8_t st = fido::g_up.state;
  uint32_t seq = fido::g_up.seq;
  if(st == 1 && fido::g_up.kind == 2 && (!g_fidoShown || seq != g_fidoShownSeq)){
    if(dimActive) idleDimWake();
    lastActivity = millis();
    g_fidoShown = true; g_fidoShownSeq = seq; g_fidoShownAt = millis();
    LOG_BOOT("[FIDO] PIN asked over state %d for %s\n", (int)currentState, fido::g_up.rp);
    uint8_t r = uvPinPrompt(seq);
    if(r && fido::g_up.state == 1 && fido::g_up.seq == seq) fido::g_up.state = r;
    st = fido::g_up.state;   // falls through to the close-out below
  }
  if(st == 1 && (!g_fidoShown || seq != g_fidoShownSeq)){
    if(dimActive) idleDimWake();       // a request lights the screen
    lastActivity = millis();
    g_fidoShown = true; g_fidoShownSeq = seq; g_fidoShownAt = millis();
    clearButtonPending();              // a press made before the prompt never counts
    g_pickSel = 0;
    fidoDrawPrompt();
    LOG_BOOT("[FIDO] prompt shown over state %d: %s %s\n", (int)currentState, fido::g_up.what, fido::g_up.rp);
    return;
  }
  if(!g_fidoShown) return;
  if(st == 1){
    lastActivity = millis();           // keep the screen lit while asking
    if(fido::g_up.seq != g_fidoShownSeq) return;   // a newer request replaced the one on screen: redraw first
    if(fido::g_up.kind == 3){
      if(!wallet.unlocked){ fido::g_up.state = 3; st = 3; }   // locked while the picker was up: refuse, the names leave the screen now
      else { const int pn = fido::g_pick.n;                     // one read (review: no divide by a zeroed count)
        if(pn > 1 && btn1.isPressed()){ g_pickSel = (g_pickSel + 1) % pn; fidoDrawPicker(); return; }
        if(pn > 1 && btn3.isPressed()){ g_pickSel = (g_pickSel + pn - 1) % pn; fidoDrawPicker(); return; } }
    }
    if(st == 3){ /* refused above */ }
    else if(btn2.isPressedFresh(g_fidoShownAt))      { if(fido::g_up.kind == 3) fido::g_pick.sel = (uint8_t)g_pickSel; fido::g_up.state = 2; st = 2; }
    else if(btn4.isPressedFresh(g_fidoShownAt)) { fido::g_up.state = 3; st = 3; }
    else return;
  }
  g_fidoShown = false;
  LOG_BOOT("[FIDO] prompt closed: %s\n", st == 2 ? "approved" : st == 3 ? "refused" : st == 5 ? "UV blocked (the site gets 0x3C)" : "withdrawn by the host / timeout");
  clearButtonPending();
  if(nextState != currentState) { /* a screen change is already pending (a menu that yielded): it draws itself */ }
  else if(currentState == ST_MENU) dispMenu();
  else { nextState = currentState; currentState = (DeviceState)99; }   // re-enter the screen we covered
}
